INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24826, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每个人都一样重要，有一样的权利。", "primary_collocate": null, "pronunciation": "píng děng", "ipa": "pʰiŋ˧˥ tɤŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "大家都在争取平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直在追求平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家很重视平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有平等，就没有和平。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们需要爱，也需要平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在书里写了自由和平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要为平等一起努力。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "平等对每个人都很重要。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们讲平等，也讲尊重。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在一所好的学校里，每个学生都能得到平等。", "target_word": "平等", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "不平等", "label": "复合"}, {"form": "平等权", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：人人同样重要、权利相同的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba8c8f5f-fc8f-4d44-9255-da7efb81def0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24826, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "平等", "is_correct": true, "explanation": "正确：“争取”的对象是权利、机会等抽象事物，“平等”符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“争取”的对象应是权利或机会，不能说“争取体重”。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：“垃圾”不是可以争取的对象，与句意不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不能被争取，与句意不合。"}], "explanations": {"平等": "正确：“争取”的对象是权利、机会等抽象事物，“平等”符合句意。", "体重": "搭配：“争取”的对象应是权利或机会，不能说“争取体重”。", "垃圾": "语义：“垃圾”不是可以争取的对象，与句意不合。", "天气": "语义：“天气”不能被争取，与句意不合。"}, "sentence_index": 0, "correct_answer": "平等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两根绳子的长短很平等。", "explanation": "这里应该用〈相等〉。平等指人在地位、权利上相同；两物长短相同要说相等。"}, {"text": "走钢丝需要保持平等。", "explanation": "这里应该用〈平衡〉。平衡指物体或身体的稳定状态；平等说的是人的地位和权利。"}, {"text": "大家的看法要平等。", "explanation": "这里应该用〈一致〉。看法、意见相符要说一致，平等不用于观点的相符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24826, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平等", "is_correct": true, "explanation": "正确：“为……努力”的宾语是理想或目标，“平等”符合句意。"}, {"text": "牙膏", "is_correct": false, "explanation": "语义：“牙膏”不是值得为之努力的目标，与句意不合。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“为……努力”的宾语应是理想或目标，“地铁”不能这样搭配。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：“雨水”不能作为为之努力的对象，与句意不合。"}], "explanations": {"平等": "正确：“为……努力”的宾语是理想或目标，“平等”符合句意。", "牙膏": "语义：“牙膏”不是值得为之努力的目标，与句意不合。", "地铁": "搭配：“为……努力”的宾语应是理想或目标，“地铁”不能这样搭配。", "雨水": "语义：“雨水”不能作为为之努力的对象，与句意不合。"}, "sentence_index": 6, "correct_answer": "平等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的特点是构图平等。", "explanation": "这里应该用〈对称〉。平等指人在地位、权利上相同；图形、布局左右相配要说对称。"}, {"text": "饮食要注意营养平等。", "explanation": "这里应该用〈均衡〉。营养讲各类成分比例适当要说均衡；平等不用于营养搭配。"}, {"text": "做研究要保证数据平等。", "explanation": "这里应该用〈准确〉。数据要说准确；平等不用来描述数据。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该重视很平等。", "corrected_sentence": "我们应该重视平等。", "error_description": "错误：「重视」的宾语须是名词性成分，「很平等」是形容词短语，不能作宾语。正确：去掉「很」，说「重视平等」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校应当保障平等地。", "corrected_sentence": "学校应当保障平等。", "error_description": "错误：「平等地」是副词，须放在动词前修饰动词，如「平等地保障」；「保障平等地」句末副词悬空。正确：去掉「地」，说「保障平等」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
