INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24828, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把脏东西弄掉，让东西变干净。", "primary_collocate": null, "pronunciation": "qīng lǐ", "ipa": "tɕʰiŋ˥ li˨˩", "syllable_count": 2, "sentences": [{"text": "工人在清理街上的垃圾。", "target_word": "清理", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雪后，大家一起清理路上的雪。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天早上清理一下鱼缸。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把河里的脏东西清理干净了。", "target_word": "清理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在清理厨房里的油烟机。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨以后，工人清理了地上的泥。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你清理一下杯子里的茶叶。", "target_word": "清理", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我花了一个小时把脏鞋子清理干净了。", "target_word": "清理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清理厨房里的油污很麻烦。", "target_word": "清理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们帮着清理院子里的落叶。", "target_word": "清理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "清理了", "label": "完成体标"}, {"form": "清理过", "label": "经历体标"}, {"form": "清理清理", "label": "重叠"}], "register": "中性", "sense_fingerprint": "清理：除去垃圾、泥、落叶等脏东西，使地方或物品干净", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bb68faa-3174-49c6-8b97-9428afdeed62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24828, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "清理", "is_correct": true, "explanation": "清理：除去垃圾、泥等脏东西，即本词。"}, {"text": "情理", "is_correct": false, "explanation": "「情理」第一音节 qíng（第二声）与 qīng（第一声）只差声调，意思是道理。"}, {"text": "倾力", "is_correct": false, "explanation": "「倾力」第二音节 lì（第四声）与 lǐ（第三声）只差声调，意思是全力以赴。"}, {"text": "经理", "is_correct": false, "explanation": "「经理」声母 j 与 q 不同，意思是负责管理的人。"}, {"text": "清丽", "is_correct": false, "explanation": "「清丽」第二音节 lì（第四声）与 lǐ（第三声）声调不同，意思是清秀美丽。"}], "explanations": {"清理": "清理：除去垃圾、泥等脏东西，即本词。", "情理": "「情理」第一音节 qíng（第二声）与 qīng（第一声）只差声调，意思是道理。", "倾力": "「倾力」第二音节 lì（第四声）与 lǐ（第三声）只差声调，意思是全力以赴。", "经理": "「经理」声母 j 与 q 不同，意思是负责管理的人。", "清丽": "「清丽」第二音节 lì（第四声）与 lǐ（第三声）声调不同，意思是清秀美丽。"}, "sentence_index": null, "correct_answer": "清理"}, "level_3": {"options": [{"text": "清理", "is_correct": true, "explanation": "「清理」与“街上的垃圾”搭配，指清除垃圾，符合句意。"}, {"text": "观看", "is_correct": false, "explanation": "语义：垃圾不是可以观看的对象，句意是清除垃圾。"}, {"text": "欢迎", "is_correct": false, "explanation": "配价：「欢迎」的对象应是人或客人，不能以“垃圾”为宾语。"}, {"text": "种植", "is_correct": false, "explanation": "语义：垃圾不能被种植，与句意不符。"}], "explanations": {"清理": "「清理」与“街上的垃圾”搭配，指清除垃圾，符合句意。", "观看": "语义：垃圾不是可以观看的对象，句意是清除垃圾。", "欢迎": "配价：「欢迎」的对象应是人或客人，不能以“垃圾”为宾语。", "种植": "语义：垃圾不能被种植，与句意不符。"}, "sentence_index": 0, "correct_answer": "清理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于清理了激动的心情。", "explanation": "这里应该用〈平复〉。清理用于具体的脏东西，心情要用平复。"}, {"text": "这部电影我已经清理完了。", "explanation": "这里应该用〈看完〉。清理指清除脏东西使干净，看电影要用看完。"}, {"text": "我每天晚上清理一首歌再睡觉。", "explanation": "这里应该用〈听〉。清理指清除脏东西使干净，歌不能清理，要用听。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24828, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "清理", "is_correct": true, "explanation": "「清理」指清除杯子里多余的茶叶，符合句意。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：「翻译」是转换语言，不能用于茶叶。"}, {"text": "通知", "is_correct": false, "explanation": "配价：「通知」的对象应是人，不能以“茶叶”为接受对象。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：「拥抱」指人与人之间的动作，不能用于杯子里的茶叶。"}], "explanations": {"清理": "「清理」指清除杯子里多余的茶叶，符合句意。", "翻译": "语义：「翻译」是转换语言，不能用于茶叶。", "通知": "配价：「通知」的对象应是人，不能以“茶叶”为接受对象。", "拥抱": "搭配：「拥抱」指人与人之间的动作，不能用于杯子里的茶叶。"}, "sentence_index": 6, "correct_answer": "清理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都清理自己的生日。", "explanation": "这里应该用〈庆祝〉。清理指清除脏东西使干净，过生日要用庆祝。"}, {"text": "妈妈正在清理孩子的脾气。", "explanation": "这里应该用〈改正〉。清理指清除脏东西使干净，性格上的毛病要用改正。"}, {"text": "他很会清理朋友的笑声。", "explanation": "这里应该用〈欣赏〉。清理指清除脏东西使干净，笑声不是要清除的东西，应当用欣赏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天把桌子被清理干净了。", "corrected_sentence": "我昨天把桌子清理干净了。", "error_description": "“把”字句与“被”字句不能同时使用：句中已用“把”，多加的“被”是错误的，应去掉，说“我昨天把桌子清理干净了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天晚上把鱼缸清理着。", "corrected_sentence": "他昨天晚上把鱼缸清理了。", "error_description": "表示已经完成的具体动作，应用“了”，不能用“着”。“着”表示动作或状态的持续，与“昨天晚上”这种已结束的时间不搭，应说“清理了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
