INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24830, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24830, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示事情分成不同的部分或时期，一个一个地到来。", "primary_collocate": null, "pronunciation": "jiē duàn xìng", "ipa": "tɕjɛ˥ twan˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这项工作是阶段性进行的。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学习是阶段性的，要慢慢来。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工程分三步，是阶段性完成的。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的变化是阶段性出现的。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨水是阶段性到来的，不是一直下。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的成长是阶段性的。", "target_word": "阶段性", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司的计划是阶段性推进的。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阶段性的任务一个接着一个。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新功能会阶段性地上线，先面向部分用户。", "target_word": "阶段性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目会阶段性地开放。", "target_word": "阶段性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "阶段性：事情分成几个阶段，一个接一个地出现或进行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e01db3e0-aba5-44e5-92e3-89627e0736ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24830, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "阶段性", "is_correct": true, "explanation": "正确：阶段性说明工作分段进行，与“进行”的语境相符。"}, {"text": "突发性", "is_correct": false, "explanation": "语义：突发性指突然发生，与工作有计划地持续推进的含义冲突。"}, {"text": "随机性", "is_correct": false, "explanation": "语义：随机性指没有规律地发生，与“进行”的有序推进相反。"}, {"text": "偶发性", "is_correct": false, "explanation": "搭配：偶发性多用于偶然发生的事件，不用于修饰有组织的工作进行。"}], "explanations": {"阶段性": "正确：阶段性说明工作分段进行，与“进行”的语境相符。", "突发性": "语义：突发性指突然发生，与工作有计划地持续推进的含义冲突。", "随机性": "语义：随机性指没有规律地发生，与“进行”的有序推进相反。", "偶发性": "搭配：偶发性多用于偶然发生的事件，不用于修饰有组织的工作进行。"}, "sentence_index": 0, "correct_answer": "阶段性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头是阶段性出现的。", "explanation": "这里应该用〈一次性〉。阶段性指事情分成几段一个接一个地出现，石头一次出现不分段。"}, {"text": "好消息是阶段性传来的，所有消息在同一刻到达。", "explanation": "这里应该用〈同时〉。阶段性强调分段先后出现，同一刻到达的消息没有先后之分。"}, {"text": "这个问题是阶段性地解决的，一次就全部解决了。", "explanation": "这里应该用〈整体〉。阶段性强调分段完成，一次全部解决就不属于分段的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24830, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阶段性", "is_correct": true, "explanation": "正确：阶段性修饰“推进”，说明计划分段进行，符合句意。"}, {"text": "停滞性", "is_correct": false, "explanation": "语义：停滞性指停止不前，与“推进”的含义相反。"}, {"text": "倒退性", "is_correct": false, "explanation": "语义：倒退性指向后退，与“推进”的方向相反。"}, {"text": "个体性", "is_correct": false, "explanation": "搭配：个体性指单个人的特征，与“公司的计划”这种集体层面的主语不相符。"}], "explanations": {"阶段性": "正确：阶段性修饰“推进”，说明计划分段进行，符合句意。", "停滞性": "语义：停滞性指停止不前，与“推进”的含义相反。", "倒退性": "语义：倒退性指向后退，与“推进”的方向相反。", "个体性": "搭配：个体性指单个人的特征，与“公司的计划”这种集体层面的主语不相符。"}, "sentence_index": 6, "correct_answer": "阶段性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个项目会阶段性地开放，各地一起开放。", "explanation": "这里应该用〈同步〉。阶段性指分段一个接一个地进行，各地一起开放应用〈同步〉。"}, {"text": "他是阶段性出生的。", "explanation": "这里不能用阶段性：出生只发生一次，没有分段先后的过程，阶段性无法修饰它。"}, {"text": "这些资料是阶段性地整理完成的，一次就全都整理好了。", "explanation": "这里应该用〈整体〉。阶段性强调分段进行，一次全部整理完毕不属于分段的过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些数据是阶段性收集地。", "corrected_sentence": "这些数据是阶段性收集的。", "error_description": "错误在于结构助词：“是……的”句式的句末应用“的”，此处误用“地”。“地”用于状语之后修饰动词，不能在句末充当结尾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新的版本是阶段性上线地。", "corrected_sentence": "新的版本是阶段性上线的。", "error_description": "错误在于结构助词：“是……的”句式的句末应用“的”，此处误用“地”。“地”用于状语之后修饰动词，不能在句末充当结尾。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
