INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24833, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指限制在某个范围或地方内，不能超出。", "primary_collocate": null, "pronunciation": "jú xiàn", "ipa": "tɕy˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我们的讨论不要局限在这个问题上。", "target_word": "局限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动只局限于本校学生。", "target_word": "局限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的生活局限在一个小村子里。", "target_word": "局限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学习不应该只局限于课本。", "target_word": "局限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲的内容不局限于数学。", "target_word": "局限", "complexity_tier": "T3", "furigana": "lǎo shī jiǎng de nèi róng bù jú xiàn yú shù xué", "sentence_source": "generated"}, {"text": "别把自己局限在家里。", "target_word": "局限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种做法只局限在小城市。", "target_word": "局限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的兴趣不局限于音乐。", "target_word": "局限", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不想把工作局限在办公室里。", "target_word": "局限", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的看法不能局限于眼前的事。", "target_word": "局限", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "局限了", "label": "体标"}, {"form": "局限于", "label": "搭配"}], "register": "书面", "sense_fingerprint": "限制在某个范围内，不能超出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fb7fbe2-03dc-4c00-8c7e-e16f093b9f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24833, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩大", "is_correct": false, "explanation": "搭配：“扩大”要带直接宾语（扩大范围），不能说“扩大在这个问题上”。"}, {"text": "局限", "is_correct": true, "explanation": "正确：“局限在这个问题上”表示讨论被限定在这个问题的范围内，符合语境。"}, {"text": "转移", "is_correct": false, "explanation": "配价：“转移”表示去向要用“到”，不能说“转移在这个问题上”。"}, {"text": "放弃", "is_correct": false, "explanation": "配价：“放弃”直接带宾语（放弃这个问题），不用“在……上”引出范围。"}], "explanations": {"扩大": "搭配：“扩大”要带直接宾语（扩大范围），不能说“扩大在这个问题上”。", "局限": "正确：“局限在这个问题上”表示讨论被限定在这个问题的范围内，符合语境。", "转移": "配价：“转移”表示去向要用“到”，不能说“转移在这个问题上”。", "放弃": "配价：“放弃”直接带宾语（放弃这个问题），不用“在……上”引出范围。"}, "sentence_index": 0, "correct_answer": "局限"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次比赛局限了他的名气，现在很多人都认识他。", "explanation": "这里应该用〈提高〉。局限表示限定在某个范围之内，不用来表示使名气变大。"}, {"text": "他的失误局限了团队的士气，大家都没有精神。", "explanation": "这里应该用〈挫伤〉。局限表示限定在某个范围之内，不用来表示使士气受损。"}, {"text": "这部电影局限了观众的情绪。", "explanation": "这里应该用〈影响〉。局限指把事物限定在某个范围内，不用来表示作用于观众的情绪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24833, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摆脱", "is_correct": false, "explanation": "配价：“摆脱”要直接带宾语（摆脱困境），不能说“摆脱在小城市”。"}, {"text": "远离", "is_correct": false, "explanation": "搭配：“远离”要带宾语（远离小城市），“远离在”的结构不成立。"}, {"text": "局限", "is_correct": true, "explanation": "正确：“只局限在小城市”表示这种做法的范围仅限于小城市，符合语境。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”是躲开，与“这种做法只在小城市”的推广范围不合。"}], "explanations": {"摆脱": "配价：“摆脱”要直接带宾语（摆脱困境），不能说“摆脱在小城市”。", "远离": "搭配：“远离”要带宾语（远离小城市），“远离在”的结构不成立。", "局限": "正确：“只局限在小城市”表示这种做法的范围仅限于小城市，符合语境。", "逃避": "语义：“逃避”是躲开，与“这种做法只在小城市”的推广范围不合。"}, "sentence_index": 6, "correct_answer": "局限"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次改革局限了工人的待遇。", "explanation": "这里应该用〈改善〉。局限是限定在某范围之内，不能用来表示使待遇变好。"}, {"text": "这场大雨局限了空气，现在空气很清新。", "explanation": "这里应该用〈净化〉。局限表示限定在某个范围之内，不用来表示使空气变干净。"}, {"text": "这次手术局限了他的视力，他看东西很模糊。", "explanation": "这里应该用〈损伤〉。局限表示限定在某个范围之内，不用来表示使视力受损。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24833, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的研究局限医学领域。", "corrected_sentence": "他的研究局限在医学领域。", "error_description": "错误形式：“局限”后漏掉介词“在”；正确形式：“局限在医学领域”。原因：“局限”后面要用“在”或“于”引出被限定的范围。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24833, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些问题局限到一个小范围内。", "corrected_sentence": "这些问题局限在一个小范围内。", "error_description": "介词错误：“局限”后引出范围要用“在”或“于”，不能用“到”；应说“局限在一个小范围内”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
