INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24834, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一个人喊，另一个人回答。", "primary_collocate": null, "pronunciation": "hū yìng", "ipa": "xu˥ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "山上的人大喊，山下的人立刻呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山这边喊，朋友在山那边呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在河两岸喊话，互相呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喊了几声，没有人呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牧羊人一声长喊，远处有人呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，远处的鸟叫一声，另一边的鸟立刻呼应。", "target_word": "呼应", "complexity_tier": "T3", "furigana": "yè lǐ, yuǎn chù de niǎo jiào yì shēng, lìng yì biān de niǎo lì kè hū yìng.", "sentence_source": "generated"}, {"text": "队长喊口号，队员们大声呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在门外叫了一声，里面有人呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在前面喊，学生在后面呼应。", "target_word": "呼应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在院子里叫了几声，远处的狗也跟着呼应。", "target_word": "呼应", "complexity_tier": "T3", "furigana": "xiǎo gǒu zài yuànzi lǐ jiào le jǐ shēng, yuǎn chù de gǒu yě gēn zhe hū yìng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "互相呼应", "label": "复合"}], "register": "中性", "sense_fingerprint": "呼应|动词|一方喊、另一方回答", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba8c8f5f-fc8f-4d44-9255-da7efb81def0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24834, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "呼应", "is_correct": true, "explanation": "呼应：动词，表示一方喊、另一方回答，此处说山下的人立刻回应山上的喊声。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：「沉默」表示不出声，与「立刻」所说的及时回答相悖。"}, {"text": "破坏", "is_correct": false, "explanation": "配价：「破坏」需要带宾语，「山下的人立刻破坏」结构不完整。"}, {"text": "逃跑", "is_correct": false, "explanation": "语义：「逃跑」表示躲避离开，与「大喊」之后的应答关系不合。"}], "explanations": {"呼应": "呼应：动词，表示一方喊、另一方回答，此处说山下的人立刻回应山上的喊声。", "沉默": "语义：「沉默」表示不出声，与「立刻」所说的及时回答相悖。", "破坏": "配价：「破坏」需要带宾语，「山下的人立刻破坏」结构不完整。", "逃跑": "语义：「逃跑」表示躲避离开，与「大喊」之后的应答关系不合。"}, "sentence_index": 0, "correct_answer": "呼应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈呼应我去医院。", "explanation": "这里应该用〈陪同〉。呼应指一方喊、另一方回答，不指陪伴同行；“陪我去医院”才对。"}, {"text": "那双鞋呼应了我的脚。", "explanation": "这里应该用〈合〉。呼应指一方喊、另一方回答，不指大小合适；“那双鞋合我的脚”才对。"}, {"text": "孩子只呼应父母的脾气，从不反驳。", "explanation": "这里应该用〈顺从〉。呼应指一方喊、另一方回答，不指依从别人的性情；“顺从父母的脾气”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24834, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "呼应", "is_correct": true, "explanation": "呼应：动词，表示一方喊、另一方回答，此处说队员们对队长的口号大声回应。"}, {"text": "默读", "is_correct": false, "explanation": "语义：「默读」是不出声地阅读，与「大声」矛盾。"}, {"text": "搬运", "is_correct": false, "explanation": "语义：「搬运」是把物品从一处运到另一处，与「大声」所表示的应答意义不合。"}, {"text": "静坐", "is_correct": false, "explanation": "语义：「静坐」表示安静地坐着，与「大声」矛盾。"}], "explanations": {"呼应": "呼应：动词，表示一方喊、另一方回答，此处说队员们对队长的口号大声回应。", "默读": "语义：「默读」是不出声地阅读，与「大声」矛盾。", "搬运": "语义：「搬运」是把物品从一处运到另一处，与「大声」所表示的应答意义不合。", "静坐": "语义：「静坐」表示安静地坐着，与「大声」矛盾。"}, "sentence_index": 6, "correct_answer": "呼应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打了我一下，我立刻呼应了他。", "explanation": "这里应该用〈回击〉。呼应指回答对方的呼喊，不指以攻击还击。"}, {"text": "他随手把书呼应到桌上。", "explanation": "这里应该用〈放〉。呼应指一方喊、另一方回答，不指放置物品；“他随手把书放到桌上”才对。"}, {"text": "这个人只呼应领导的指示，从不反驳。", "explanation": "这里应该用〈顺从〉。呼应指一方喊、另一方回答，不指依从别人的意见；“顺从领导的指示”才对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24834, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山下的人立刻呼应着了。", "corrected_sentence": "山下的人立刻呼应了。", "error_description": "错误：「呼应」是一次性的应答，与「立刻」相配，应用「了」表示完成，说「立刻呼应了」；「着」表示持续，与「立刻」的瞬时含义冲突，「呼应着了」不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24834, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "队员们大声呼应得。", "corrected_sentence": "队员们大声呼应。", "error_description": "错误：「呼应得」后面没有补语，「得」多余，句子不完整。正确：去掉「得」，说「大声呼应」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a384423-1ab5-4cce-9e02-76eae3132d8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
