INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24836, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "开会时要讨论的事情的清单。", "primary_collocate": null, "pronunciation": "yì chéng", "ipa": "i˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "开会以前，秘书把议程发给每个人。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议程上第一件事是选新的班长。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在会上说：“先看议程，再说别的。”", "target_word": "议程", "complexity_tier": "T3", "furigana": "jīng lǐ zài huì shàng shuō xiān kàn yì chéng zài shuō bié de", "sentence_source": "generated"}, {"text": "今天开会的议程只有两件事。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没带议程，所以不知道下一项是什么。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个议程写得很清楚，大家都能看懂。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在黑板上写着今天班会的议程。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们没有按议程开会，会开得很乱。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把明天的议程打印十份。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "议程里有一项是讨论学校的新规定。", "target_word": "议程", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "議程", "label": "繁体"}, {"form": "议程表", "label": "复合"}], "register": "书面", "sense_fingerprint": "开会时要讨论的事情清单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c9b1ce-420a-4bbc-97dd-366c624344ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24836, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "议程", "is_correct": true, "explanation": "正确：“议程”指开会时要讨论的事情清单，读作 yì chéng。"}, {"text": "一城", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是一座城市。"}, {"text": "已成", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经形成。"}, {"text": "以诚", "is_correct": false, "explanation": "yǐ（第三声）与 yì（第四声）声调不同，意思是用真诚（如“以诚待人”）。"}], "explanations": {"议程": "正确：“议程”指开会时要讨论的事情清单，读作 yì chéng。", "一城": "yī（第一声）与 yì（第四声）声调不同，意思是一座城市。", "已成": "yǐ（第三声）与 yì（第四声）声调不同，意思是已经形成。", "以诚": "yǐ（第三声）与 yì（第四声）声调不同，意思是用真诚（如“以诚待人”）。"}, "sentence_index": null, "correct_answer": "议程"}, "level_3": {"options": [{"text": "议程", "is_correct": true, "explanation": "正确：秘书在开会前发的是会议的事项清单，“把议程发给每个人”合理。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是大型设备，不能在开会前发给每个人，与句意不合。"}, {"text": "眼药水", "is_correct": false, "explanation": "搭配：“发”一般用于文件、资料，不说“把眼药水发给每个人”，二者不搭配。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车不能发给每个人，与“开会以前”的语境不符。"}], "explanations": {"议程": "正确：秘书在开会前发的是会议的事项清单，“把议程发给每个人”合理。", "空调": "语义：空调是大型设备，不能在开会前发给每个人，与句意不合。", "眼药水": "搭配：“发”一般用于文件、资料，不说“把眼药水发给每个人”，二者不搭配。", "公交车": "语义：公交车不能发给每个人，与“开会以前”的语境不符。"}, "sentence_index": 0, "correct_answer": "议程"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭店的议程上有很多好吃的菜。", "explanation": "这里应该用〈菜单〉。菜单是列出菜品的清单，议程是会议讨论事项的清单，不能用来点菜。"}, {"text": "这部小说的议程很感人。", "explanation": "这里应该用〈情节〉。议程指会议事项，不能用来形容小说的故事感人。"}, {"text": "我买了一台新议程，看电视很清楚。", "explanation": "这里应该用〈电视机〉。议程是会议讨论事项的清单，不是可以看节目的电器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24836, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "议程", "is_correct": true, "explanation": "正确：“议程”指开会时要讨论的事情清单，读作 yì chéng。"}, {"text": "一成", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是十分之一。"}, {"text": "一程", "is_correct": false, "explanation": "yī（第一声）与 yì（第四声）声调不同，意思是一段路程。"}, {"text": "议政", "is_correct": false, "explanation": "zhèng 与 chéng 声母不同（zh 与 ch），意思是讨论国家政事。"}], "explanations": {"议程": "正确：“议程”指开会时要讨论的事情清单，读作 yì chéng。", "一成": "yī（第一声）与 yì（第四声）声调不同，意思是十分之一。", "一程": "yī（第一声）与 yì（第四声）声调不同，意思是一段路程。", "议政": "zhèng 与 chéng 声母不同（zh 与 ch），意思是讨论国家政事。"}, "sentence_index": null, "correct_answer": "议程"}, "level_3": {"options": [{"text": "议程", "is_correct": true, "explanation": "正确：“班会的议程”指班会要讨论的事项，写在黑板上合理。"}, {"text": "病历", "is_correct": false, "explanation": "语义：“病历”是病人的医疗记录，与班会无关。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“班会”不能与“体温”搭配，说“班会的体温”不通。"}, {"text": "药方", "is_correct": false, "explanation": "语义：“药方”是医生开的药单，与班会的内容无关。"}], "explanations": {"议程": "正确：“班会的议程”指班会要讨论的事项，写在黑板上合理。", "病历": "语义：“病历”是病人的医疗记录，与班会无关。", "体温": "搭配：“班会”不能与“体温”搭配，说“班会的体温”不通。", "药方": "语义：“药方”是医生开的药单，与班会的内容无关。"}, "sentence_index": 6, "correct_answer": "议程"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的议程很感人。", "explanation": "这里应该用〈歌词〉。议程是会议事项清单，不能用来形容歌曲感人。"}, {"text": "我每天坐议程去上班。", "explanation": "这里应该用〈公交车〉。议程是会议事项清单，不是交通工具，不能“坐”。"}, {"text": "这道菜的议程很简单。", "explanation": "这里应该用〈做法〉。议程指会议事项，菜的做法不能说成议程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "秘书印了一把议程。", "corrected_sentence": "秘书印了一份议程。", "error_description": "量词错误：纸质的议程用“份”，“把”用于有柄的东西，不能用来数议程。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秘书把议程的发给了所有人。", "corrected_sentence": "秘书把议程发给了所有人。", "error_description": "结构错误：在“把”字句中，“议程”后不能直接加“的”，应说“把议程发给了所有人”；多出的“的”破坏了“把”字句的结构。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
