INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24838, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一个地方一下子变到另一个地方。", "primary_collocate": null, "pronunciation": "yuè qiān", "ipa": "ɥe˥˩ tɕʰjɛn˥", "syllable_count": 2, "sentences": [{"text": "飞船启动引擎，一瞬间跃迁到了另一个星系。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏里的角色一按键，就能跃迁到地图另一边。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在小说里，主人公一下子跃迁到了千里之外的京城。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞船准备好了，下一秒就要跃迁到火星轨道。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "魔法师念完咒语，一眨眼就跃迁到了山顶。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一按按钮，就跃迁到了几百公里外的海边。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个传送门能让人立刻跃迁到另一座城市。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，战士打开光门，跃迁到了敌人后方。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器人按下按钮，从房间这头跃迁到了那头。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船长下令，全船立刻跃迁离开危险的海域。", "target_word": "跃迁", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "跃迁了", "label": "完成体"}, {"form": "跃迁过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "瞬间从一个地点转移到另一个地点（空间上的突然位移）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e01db3e0-aba5-44e5-92e3-89627e0736ec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24838, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "跃迁", "is_correct": true, "explanation": "跃迁：指一瞬间从一地转到另一地，与“一瞬间”相合。"}, {"text": "漫游", "is_correct": false, "explanation": "语义：“漫游”指悠闲地到处走，与“一瞬间”的急速位移相矛盾。"}, {"text": "爬行", "is_correct": false, "explanation": "语义：“爬行”速度很慢，与“一瞬间”相矛盾。"}, {"text": "散步", "is_correct": false, "explanation": "搭配：“散步”是人悠闲地行走，不能用于飞船。"}], "explanations": {"跃迁": "跃迁：指一瞬间从一地转到另一地，与“一瞬间”相合。", "漫游": "语义：“漫游”指悠闲地到处走，与“一瞬间”的急速位移相矛盾。", "爬行": "语义：“爬行”速度很慢，与“一瞬间”相矛盾。", "散步": "搭配：“散步”是人悠闲地行走，不能用于飞船。"}, "sentence_index": 0, "correct_answer": "跃迁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这辆货车在山路上缓慢跃迁。", "explanation": "这里应该用〈移动〉。跃迁是一瞬间的位移，不能用于缓慢行进。"}, {"text": "他沿着河岸跃迁了一个小时。", "explanation": "这里应该用〈步行〉。跃迁是瞬间完成的位移，不能持续一段时间。"}, {"text": "他把水跃迁到了桌上。", "explanation": "这里应该用〈倒〉。跃迁是不及物的瞬间位移，不能带宾语表示搬动他物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "跃迁", "is_correct": true, "explanation": "跃迁：指瞬间从一地转到另一地，与“立刻”和“传送门”相合。"}, {"text": "漫步", "is_correct": false, "explanation": "语义：“漫步”指悠闲缓行，与“立刻”相矛盾。"}, {"text": "爬行", "is_correct": false, "explanation": "语义：“爬行”速度很慢，与“立刻”相矛盾。"}, {"text": "行驶", "is_correct": false, "explanation": "搭配：“行驶”用于车船等交通工具，不能用于描述让人完成的位移。"}], "explanations": {"跃迁": "跃迁：指瞬间从一地转到另一地，与“立刻”和“传送门”相合。", "漫步": "语义：“漫步”指悠闲缓行，与“立刻”相矛盾。", "爬行": "语义：“爬行”速度很慢，与“立刻”相矛盾。", "行驶": "搭配：“行驶”用于车船等交通工具，不能用于描述让人完成的位移。"}, "sentence_index": 6, "correct_answer": "跃迁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆公交车在早高峰时慢慢跃迁，穿过了老城区。", "explanation": "这里应该用〈行驶〉。跃迁是瞬间完成的位移，不能用于慢慢穿过一个区域。"}, {"text": "木筏在河面上跃迁了三天。", "explanation": "这里应该用〈漂流〉。跃迁是瞬间完成的位移，不能持续三天。"}, {"text": "他低头认真跃迁，没有说话。", "explanation": "这里应该用〈思考〉。跃迁是瞬间的空间位移，不能用于安静的思维活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "飞船穿过虫洞，瞬间跃迁了到另一片星空。", "corrected_sentence": "飞船穿过虫洞，瞬间跃迁到了另一片星空。", "error_description": "错误：“跃迁了到”。正确：“跃迁到了”。“到”是补语，应紧接动词，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他跳进光门，一下子跃迁地到了敌人后方。", "corrected_sentence": "他跳进光门，一下子跃迁到了敌人后方。", "error_description": "错误：“跃迁地到”。正确：“跃迁到了”。“地”是状语标记，不能放在动词与补语“到”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea69a300-08e8-4927-8974-98338482547b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
