INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24840, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "意思是“作为最重要的”。", "primary_collocate": null, "pronunciation": "wéi zhǔ", "ipa": "weɪ˧˥ ʈʂu˨˩", "syllable_count": 2, "sentences": [{"text": "周末的活动以运动为主。", "target_word": "为主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这次旅行以看风景为主。", "target_word": "为主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生的作业以练习为主，考试为辅。", "target_word": "为主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家的饭菜以清淡为主。", "target_word": "为主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的产品以手机为主。", "target_word": "为主", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个城市的天气以晴天为主。", "target_word": "为主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的教育应当以鼓励为主。", "target_word": "为主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的音乐会以老歌为主。", "target_word": "为主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街的商店以吃的东西为主。", "target_word": "为主", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的会议以讨论为主。", "target_word": "为主", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "以……为主", "label": "固定格式"}], "register": "中性", "sense_fingerprint": "为主：把某部分作为最重要的，常与“为辅”对举（以……为主）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bb68faa-3174-49c6-8b97-9428afdeed62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "为主", "is_correct": true, "explanation": "「为主」与“以运动”构成“以……为主”，表示运动是周末活动的重点，符合句意。"}, {"text": "为期", "is_correct": false, "explanation": "配价：「为期」后须接时间段，不能接“运动”。"}, {"text": "为难", "is_correct": false, "explanation": "语义：「为难」表示使人感到困难，与句意不符。"}, {"text": "为止", "is_correct": false, "explanation": "语义：「以……为止」表示以某事为终点，不能说明活动的重点。"}], "explanations": {"为主": "「为主」与“以运动”构成“以……为主”，表示运动是周末活动的重点，符合句意。", "为期": "配价：「为期」后须接时间段，不能接“运动”。", "为难": "语义：「为难」表示使人感到困难，与句意不符。", "为止": "语义：「以……为止」表示以某事为终点，不能说明活动的重点。"}, "sentence_index": 0, "correct_answer": "为主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "考试时间以学校的通知为主。", "explanation": "这里应该用〈为准〉。按通知确定时间是“以……为准”；“为主”指最重要的部分。"}, {"text": "今天的课上到下午四点为主。", "explanation": "这里应该用〈为止〉。表示到某个时间结束用“到……为止”；“为主”指最重要的部分。"}, {"text": "这次培训为主三天。", "explanation": "这里应该用〈为期〉。说明持续时间用“为期”；“为主”指最重要的部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "为主", "is_correct": true, "explanation": "「为主」表示以鼓励为主要方式，符合句意。"}, {"text": "为敌", "is_correct": false, "explanation": "语义：「为敌」表示把某事当作敌人，与教育的描述不符。"}, {"text": "为祸", "is_correct": false, "explanation": "语义：「为祸」指造成灾害，不能用来说明教育的方式。"}, {"text": "为仇", "is_correct": false, "explanation": "语义：「为仇」表示视为仇敌，与教育的正常方式不符。"}], "explanations": {"为主": "「为主」表示以鼓励为主要方式，符合句意。", "为敌": "语义：「为敌」表示把某事当作敌人，与教育的描述不符。", "为祸": "语义：「为祸」指造成灾害，不能用来说明教育的方式。", "为仇": "语义：「为仇」表示视为仇敌，与教育的正常方式不符。"}, "sentence_index": 6, "correct_answer": "为主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛结果以裁判的决定为主。", "explanation": "这里应该用〈为准〉。以某决定作为标准用“以……为准”；“为主”指最重要的部分。"}, {"text": "报名到明天中午为主。", "explanation": "这里应该用〈为止〉。表示截止时间用“到……为止”；“为主”指最重要的部分。"}, {"text": "这个展览为主一个月。", "explanation": "这里应该用〈为期〉。说明持续时间用“为期”；“为主”指最重要的部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个周末的安排用休息为主。", "corrected_sentence": "这个周末的安排以休息为主。", "error_description": "介词错误：固定格式是“以……为主”，前面的介词应该用“以”，不能用“用”，应说“以休息为主”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这个学期的课程用听力为主。", "corrected_sentence": "我们这个学期的课程以听力为主。", "error_description": "“以……为主”中的介词应为“以”，不能用“用”代替，应说“以听力为主”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
