INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24842, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种黑白格子的小方块，用手机扫一下就能看到信息。", "primary_collocate": null, "pronunciation": "èr wéi mǎ", "ipa": "ɚ˥˩ weɪ˧˥ ma˨˩˦", "syllable_count": 3, "sentences": [{"text": "朋友给我看了他的二维码。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小方块就是二维码。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扫一下二维码，就能看到信息。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海报右下角有一个二维码。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先扫描二维码，再进门。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书的封面上印着一个二维码。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的二维码在手机里。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子好奇地看着那个二维码。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二维码太小了，手机扫不到。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们扫二维码看作业。", "target_word": "二维码", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个二维码", "label": "量词"}, {"form": "一张二维码", "label": "量词"}, {"form": "二維碼", "label": "繁体"}], "register": "中性", "sense_fingerprint": "黑白格子的小方块，手机一扫就能看到信息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bb68faa-3174-49c6-8b97-9428afdeed62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24842, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "歌声", "is_correct": false, "explanation": "搭配：“看”的对象是可见的东西，“歌声”要用“听”。"}, {"text": "脚步声", "is_correct": false, "explanation": "语义：脚步声是听得见的，不能用“看”给别人看。"}, {"text": "二维码", "is_correct": true, "explanation": "正确：“看”的对象是图形码，句意是朋友给我看他的码。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”要用“闻”或“尝”，不能说给别人看。"}], "explanations": {"歌声": "搭配：“看”的对象是可见的东西，“歌声”要用“听”。", "脚步声": "语义：脚步声是听得见的，不能用“看”给别人看。", "二维码": "正确：“看”的对象是图形码，句意是朋友给我看他的码。", "味道": "搭配：“味道”要用“闻”或“尝”，不能说给别人看。"}, "sentence_index": 0, "correct_answer": "二维码"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "收银员在超市里扫的是一排粗细不同的黑线，那就是这件商品的二维码。", "explanation": "这里应该用〈条形码〉。条形码是一排粗细不同的线条，二维码是黑白方块组成的图形。"}, {"text": "他一口气吃掉了三个二维码。", "explanation": "这里应该用〈饼干〉。饼干能吃，二维码是图形，不能吃。"}, {"text": "在地址栏输入二维码，就能打开网页。", "explanation": "这里应该用〈网址〉。网址是文字，可以输入地址栏；二维码是图形，要用手机扫描。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24842, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的数值，不会存在手机里。"}, {"text": "嗓音", "is_correct": false, "explanation": "搭配：“在手机里”说的是可存放的内容，“嗓音”不说存在手机里。"}, {"text": "二维码", "is_correct": true, "explanation": "正确：二维码可以存在手机里，需要时拿出来扫。"}, {"text": "性格", "is_correct": false, "explanation": "语义：性格是人的特点，不存在于手机里。"}], "explanations": {"体重": "语义：体重是身体的数值，不会存在手机里。", "嗓音": "搭配：“在手机里”说的是可存放的内容，“嗓音”不说存在手机里。", "二维码": "正确：二维码可以存在手机里，需要时拿出来扫。", "性格": "语义：性格是人的特点，不存在于手机里。"}, "sentence_index": 6, "correct_answer": "二维码"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "登录网站时要输入二维码。", "explanation": "这里应该用〈验证码〉。验证码要输入，二维码要用手机扫描，不能输入。"}, {"text": "他的二维码一按，门就开了。", "explanation": "这里应该用〈指纹〉。指纹要按压，二维码要用手机扫描，不能按。"}, {"text": "入住酒店时，要报出二维码。", "explanation": "这里应该用〈身份证号码〉。身份证号码要说出来，二维码要出示给别人扫描，不能报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24842, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "包装盒上有一只二维码。", "corrected_sentence": "包装盒上有一个二维码。", "error_description": "量词错误：“二维码”的量词应为“个”，不用“只”。正确说法是“包装盒上有一个二维码”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24842, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我手机里有一颗二维码。", "corrected_sentence": "我手机里有一个二维码。", "error_description": "量词错误：“颗”用于圆粒状的东西，二维码是方形图案，应说“一个二维码”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
