INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24846, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "进入并成为一部分。", "primary_collocate": null, "pronunciation": "róng rù", "ipa": "ɻʊŋ˧˥ ɻu˥˩", "syllable_count": 2, "sentences": [{"text": "刚到北京时，我很难融入当地生活。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们很快融入了游戏中。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "留学生需要时间融入新环境。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他慢慢融入了这个大家庭。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑着融入人群，不见了。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想融入一个集体，要先学会听别人说话。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很快融入了新的班级。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的学生很想融入大家。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老城已经融入了现代生活。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小在国外长大，现在要融入这里的文化。", "target_word": "融入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "融入了", "label": "体标"}, {"form": "融入过", "label": "体标"}], "register": "中性", "sense_fingerprint": "进入某个环境或集体，并成为其中一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bb68faa-3174-49c6-8b97-9428afdeed62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "融入", "is_correct": true, "explanation": "正确。“很难融入当地生活”表示难以进入当地的生活并成为其中一部分，句意通顺。"}, {"text": "烧", "is_correct": false, "explanation": "语义：“烧”指用火加热或燃烧，与“当地生活”的语义不相容。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：“挖”一般接具体的坑或土方，不能接“生活”。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指把具体物体拆散，不能用于拆开一种生活。"}], "explanations": {"融入": "正确。“很难融入当地生活”表示难以进入当地的生活并成为其中一部分，句意通顺。", "烧": "语义：“烧”指用火加热或燃烧，与“当地生活”的语义不相容。", "挖": "搭配：“挖”一般接具体的坑或土方，不能接“生活”。", "拆": "语义：“拆”指把具体物体拆散，不能用于拆开一种生活。"}, "sentence_index": 0, "correct_answer": "融入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她把照片融入了相册。", "explanation": "这里应该用〈放入〉。融入指进入某个整体并成为其中一部分，不用于把照片放进相册。"}, {"text": "客厅里融入了一盏灯。", "explanation": "这里应该用〈挂〉。挂灯是把灯悬挂起来，融入不表示悬挂。"}, {"text": "他给朋友融入了一封信。", "explanation": "这里应该用〈寄〉。寄信是把信送出去，融入表示进入整体，不表示寄送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "融入", "is_correct": true, "explanation": "正确。“融入了新的班级”表示进入新班级并成为其中一员，句意通顺。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”是用脚击打，不能“踢了新的班级”。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指用刀把东西分开，不能用于班级。"}, {"text": "扛", "is_correct": false, "explanation": "配价：“扛”要求能承托的物体作宾语，班级不能被扛起。"}], "explanations": {"融入": "正确。“融入了新的班级”表示进入新班级并成为其中一员，句意通顺。", "踢": "语义：“踢”是用脚击打，不能“踢了新的班级”。", "切": "语义：“切”指用刀把东西分开，不能用于班级。", "扛": "配价：“扛”要求能承托的物体作宾语，班级不能被扛起。"}, "sentence_index": 6, "correct_answer": "融入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在花园里融入了一朵花。", "explanation": "这里应该用〈摘〉。摘是从植物上取下，融入表示进入整体，不能用于取花。"}, {"text": "他把垃圾融入了箱子。", "explanation": "这里应该用〈扔〉。扔是丢弃，融入表示成为整体的一部分，不表示丢弃。"}, {"text": "她很快融入了新衣服。", "explanation": "这里应该用〈穿〉。穿是把衣服穿在身上，融入表示进入某个整体，不表示穿衣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很快融入在这个社团。", "corrected_sentence": "他很快融入了这个社团。", "error_description": "“在”误用：“融入”后直接接宾语，“在”不能插在“融入”与宾语之间，应说“他很快融入了这个社团”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她很快被融入了当地的文化。", "corrected_sentence": "她很快融入了当地的文化。", "error_description": "“被”误用：“融入”表示主动进入并成为一部分，不能用于被动句，多加“被”是错误的。应说“她很快融入了当地的文化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
