INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24848, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示什么事情快要发生。", "primary_collocate": null, "pronunciation": "yù shì", "ipa": "y˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "天上的黑云预示着大雨快要来了。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早开的花预示着春天快到了。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸色越来越难看，预示着他要发火了。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人说，这股冷风预示着冬天快到了。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚂蚁搬家预示着要下雨。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处的雷声预示着暴风雨快来了。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿飞回来，预示着春天到了。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天边的红光预示着明天是晴天。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种味道预示着饭快做好了。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水变黄预示着洪水就要来了。", "target_word": "预示", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "預示", "label": "繁体"}, {"form": "预示着", "label": "体标"}, {"form": "预示了", "label": "体标"}], "register": "书面", "sense_fingerprint": "某种迹象表明事情快要发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f3c9b1ce-420a-4bbc-97dd-366c624344ba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24848, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "预示", "is_correct": true, "explanation": "正确答案。预示（yù shì）表示迹象显示事情快要发生。"}, {"text": "玉石", "is_correct": false, "explanation": "第二个音节声调不同（shí 第二声，shì 第四声），意思是玉石。"}, {"text": "鱼市", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是鱼市。"}, {"text": "雨势", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨势。"}, {"text": "预设", "is_correct": false, "explanation": "shè 与 shì 韵母不同（e 与 i），意思是预先设定。"}], "explanations": {"预示": "正确答案。预示（yù shì）表示迹象显示事情快要发生。", "玉石": "第二个音节声调不同（shí 第二声，shì 第四声），意思是玉石。", "鱼市": "yú（第二声）与 yù（第四声）声调不同，意思是鱼市。", "雨势": "yǔ（第三声）与 yù（第四声）声调不同，意思是雨势。", "预设": "shè 与 shì 韵母不同（e 与 i），意思是预先设定。"}, "sentence_index": null, "correct_answer": "预示"}, "level_3": {"options": [{"text": "预示", "is_correct": true, "explanation": "正确答案。“预示着”表示迹象显示大雨快要来了，符合句意。"}, {"text": "抱怨", "is_correct": false, "explanation": "语义：“抱怨”的主语须是有意识的人，黑云不能抱怨。"}, {"text": "发出", "is_correct": false, "explanation": "搭配：“发出”的宾语多为声音、光、信号，不能说“发出大雨”。"}, {"text": "散布", "is_correct": false, "explanation": "搭配：“散布”的宾语多为消息、谣言，不能说“散布大雨”。"}], "explanations": {"预示": "正确答案。“预示着”表示迹象显示大雨快要来了，符合句意。", "抱怨": "语义：“抱怨”的主语须是有意识的人，黑云不能抱怨。", "发出": "搭配：“发出”的宾语多为声音、光、信号，不能说“发出大雨”。", "散布": "搭配：“散布”的宾语多为消息、谣言，不能说“散布大雨”。"}, "sentence_index": 0, "correct_answer": "预示"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "电视台预示下周播出新剧。", "explanation": "这里应该用〈预告〉。预示指迹象表明事情快要发生，有意向大众发布消息时应该用〈预告〉。"}, {"text": "老师预示我们要注意时间。", "explanation": "这里应该用〈提醒〉。预示指迹象表明将要发生的事，提醒别人注意某事时应该用〈提醒〉。"}, {"text": "这张照片预示他去过北京。", "explanation": "这里应该用〈证明〉。预示多指迹象表明将要发生的事，确认“他去过北京”这类已发生的事实应该用〈证明〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24848, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "预示", "is_correct": true, "explanation": "正确答案。预示（yù shì）表示迹象显示事情快要发生。"}, {"text": "误事", "is_correct": false, "explanation": "wù 与 yù 的元音不同（u 与 ü），意思是耽误事情。"}, {"text": "叙事", "is_correct": false, "explanation": "xù 与 yù 声母不同（x 与 y），意思是叙述事情。"}, {"text": "入世", "is_correct": false, "explanation": "rù 与 yù 声母不同（r 与 y），意思是加入世界性组织。"}, {"text": "预制", "is_correct": false, "explanation": "zhì 与 shì 声母不同（zh 与 sh），意思是预先制作。"}], "explanations": {"预示": "正确答案。预示（yù shì）表示迹象显示事情快要发生。", "误事": "wù 与 yù 的元音不同（u 与 ü），意思是耽误事情。", "叙事": "xù 与 yù 声母不同（x 与 y），意思是叙述事情。", "入世": "rù 与 yù 声母不同（r 与 y），意思是加入世界性组织。", "预制": "zhì 与 shì 声母不同（zh 与 sh），意思是预先制作。"}, "sentence_index": null, "correct_answer": "预示"}, "level_3": {"options": [{"text": "预示", "is_correct": true, "explanation": "正确答案。“预示着”表示迹象显示春天快要到了，符合句意。"}, {"text": "吞没", "is_correct": false, "explanation": "搭配：“吞没”的宾语多为河水、大海等实体，不能接“春天到了”这样的事件，句子不通。"}, {"text": "通知", "is_correct": false, "explanation": "配价：“通知”需要接收者（通知某人某事），句中没有接收者。"}, {"text": "散发", "is_correct": false, "explanation": "搭配：“散发”的宾语多为气味、热量，不能接“春天到了”这样的事件。"}], "explanations": {"预示": "正确答案。“预示着”表示迹象显示春天快要到了，符合句意。", "吞没": "搭配：“吞没”的宾语多为河水、大海等实体，不能接“春天到了”这样的事件，句子不通。", "通知": "配价：“通知”需要接收者（通知某人某事），句中没有接收者。", "散发": "搭配：“散发”的宾语多为气味、热量，不能接“春天到了”这样的事件。"}, "sentence_index": 6, "correct_answer": "预示"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校预示周五放假。", "explanation": "这里应该用〈通知〉。预示说的是迹象表明将要发生的事，学校把放假安排告诉大家应该用〈通知〉。"}, {"text": "他预示自己撒了谎。", "explanation": "这里应该用〈承认〉。“预示”的主语须是迹象（如乌云、花开），人不能用它来说自己做过的事，表达认错应说“承认”。"}, {"text": "市长预示明天放假。", "explanation": "这里应该用〈宣布〉。预示强调迹象，官方正式发布决定时应该用〈宣布〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这几天的闷热预示过台风快要来了。", "corrected_sentence": "这几天的闷热预示着台风快要来了。", "error_description": "体标用错。“过”表示经历过的动作，台风还没有来，不能用“预示过”；这里应该用“预示着”，表示迹象显示台风快要来了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "院子里的积水预示得夜里要下雨。", "corrected_sentence": "院子里的积水预示着夜里要下雨。", "error_description": "“着”误用为结构助词“得”。“预示”后应接时态助词“着”，不能接“得”；“得”需要带补语（如“预示得很准”），而句子中没有补语。正确说法是“院子里的积水预示着夜里要下雨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '65de5bc4-b62f-4ec2-9482-df726991680b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
