INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24850, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24850, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "树叶、垃圾等被细菌和小虫子分解，慢慢变成泥土的过程。", "primary_collocate": null, "pronunciation": "shēng wù jiàng jiě", "ipa": "ʂəŋ˥ u˥˩ tɕjaŋ˥˩ tɕjɛ˨˩˦", "syllable_count": 4, "sentences": [{"text": "树叶掉在地上，通过生物降解变成泥土。", "target_word": "生物降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物降解需要小虫子和细菌的帮助。", "target_word": "生物降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种塑料袋可以生物降解。", "target_word": "生物降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾的生物降解要很长时间。", "target_word": "生物降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "温度高的时候，生物降解会快一点。", "target_word": "生物降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用可以生物降解的杯子喝咖啡。", "target_word": "生物降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的落叶会慢慢发生生物降解。", "target_word": "生物降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物降解对保护环境很有用。", "target_word": "生物降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纸盒的生物降解只要几个月。", "target_word": "生物降解", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了生物降解是怎么进行的。", "target_word": "生物降解", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "可生物降解", "label": "复合"}, {"form": "生物降解塑料", "label": "复合"}], "register": "书面", "sense_fingerprint": "有机物被微生物或小动物分解成泥土的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172f7e52-d98b-43ac-869e-8829631459cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24850, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生物降解", "is_correct": true, "explanation": "正确：树叶被微生物和小动物分解成泥土，正是“通过生物降解”的过程。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头变成泥土要靠风化，与句中“小虫子”的分解语境不合。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光是能量，不会让树叶变成泥土，与句意不符。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“通过……变成泥土”后面要接过程，“钢铁”是材料，不能这样搭配。"}], "explanations": {"生物降解": "正确：树叶被微生物和小动物分解成泥土，正是“通过生物降解”的过程。", "石头": "语义：石头变成泥土要靠风化，与句中“小虫子”的分解语境不合。", "阳光": "语义：阳光是能量，不会让树叶变成泥土，与句意不符。", "钢铁": "搭配：“通过……变成泥土”后面要接过程，“钢铁”是材料，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "生物降解"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "金属的生物降解要很长时间。", "explanation": "这里应该用〈锈蚀〉。生物降解只指有机物被微生物分解，金属的损坏应说“锈蚀”。"}, {"text": "地球上的生物降解是一种动物。", "explanation": "这里是把〈生物降解〉误当成〈动物〉的意思。生物降解是有机物被分解的过程，不是生物个体，不能说“一种动物”。"}, {"text": "他每天都进行生物降解，身体很健康。", "explanation": "这里是把〈生物降解〉误当成〈锻炼〉的意思。生物降解是有机物被微生物分解的过程，不是人自己进行的活动，不能用来说明锻炼身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24850, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生物降解", "is_correct": true, "explanation": "正确：“会慢慢发生生物降解”指落叶被分解的变化，与句意相符。"}, {"text": "晚餐", "is_correct": false, "explanation": "语义：晚餐是人吃的饭，与落叶慢慢变化的语境无关。"}, {"text": "兴趣", "is_correct": false, "explanation": "搭配：“发生”不与“兴趣”搭配，应说“产生兴趣”。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“发生”一般接变化或事件，“比赛”是活动，不说“发生比赛”。"}], "explanations": {"生物降解": "正确：“会慢慢发生生物降解”指落叶被分解的变化，与句意相符。", "晚餐": "语义：晚餐是人吃的饭，与落叶慢慢变化的语境无关。", "兴趣": "搭配：“发生”不与“兴趣”搭配，应说“产生兴趣”。", "比赛": "搭配：“发生”一般接变化或事件，“比赛”是活动，不说“发生比赛”。"}, "sentence_index": 6, "correct_answer": "生物降解"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "花园里有一台生物降解。", "explanation": "量词误用：“台”用于机器，生物降解是过程，应说“一个过程”或“一种现象”。"}, {"text": "这种饮料的生物降解很好喝。", "explanation": "这里是把〈生物降解〉误当成〈饮料〉的意思。生物降解指有机物被分解的过程，不能说它“好喝”。"}, {"text": "这场足球比赛的生物降解很激烈。", "explanation": "这里是把〈生物降解〉误当成〈比赛〉的意思。生物降解是分解过程，不能用“激烈”来形容，比赛才能说很激烈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24850, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "树叶掉在地上，会把慢慢生物降解。", "corrected_sentence": "树叶掉在地上，会慢慢生物降解。", "error_description": "错误形式：“会把慢慢生物降解”；正确形式：“会慢慢生物降解”。“把”字句要求“把＋受事＋动词”，“生物降解”不带宾语，不能用“把”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24850, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公园里的树叶会慢慢做生物降解。", "corrected_sentence": "公园里的树叶会慢慢发生生物降解。", "error_description": "错误形式：“做生物降解”；正确形式：“发生生物降解”。“生物降解”是自然过程，常与“发生”“进行”搭配，不说“做生物降解”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
