INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24854, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多人一起想的事情，比如大家都有一样的想法。", "primary_collocate": null, "pronunciation": "sī cháo", "ipa": "sɨ˥ ʈʂʰaʊ˧˥", "syllable_count": 2, "sentences": [{"text": "现在年轻人中有一种新思潮。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都想环保，这股思潮越来越流行。", "target_word": "思潮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个思潮让很多人开始少用塑料。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校里流行一种读书的思潮。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种思潮在网上传得很快。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们想改变这种旧思潮。", "target_word": "思潮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "城市里出现了回乡生活的思潮。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这股思潮让大家更爱运动。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不太明白这种新思潮。", "target_word": "思潮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他想知道这股思潮从哪里来。", "target_word": "思潮", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股思潮", "label": "量词"}, {"form": "一种思潮", "label": "量词"}, {"form": "新思潮", "label": "复合"}], "register": "中性", "sense_fingerprint": "思潮：许多人共同拥有、一起流行的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bb68faa-3174-49c6-8b97-9428afdeed62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24854, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "思潮", "is_correct": true, "explanation": "正确。“一种新思潮”指年轻人中流行的一种共同想法，与“年轻人中有”搭配自然，句意通顺。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，年轻人中不会有一种新体温。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是燃料，与年轻人中流行的想法毫无关系。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身体数值，不能作为年轻人中流行的东西。"}], "explanations": {"思潮": "正确。“一种新思潮”指年轻人中流行的一种共同想法，与“年轻人中有”搭配自然，句意通顺。", "体温": "语义：体温是身体的温度，年轻人中不会有一种新体温。", "汽油": "语义：汽油是燃料，与年轻人中流行的想法毫无关系。", "身高": "语义：身高是人的身体数值，不能作为年轻人中流行的东西。"}, "sentence_index": 0, "correct_answer": "思潮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他养成了早睡的思潮。", "explanation": "这里应该用〈习惯〉。思潮指社会上流行的思想倾向，不用于说个人长期形成的生活习惯。"}, {"text": "我有一种不舒服的思潮。", "explanation": "这里应该用〈感觉〉。思潮指思想上的潮流，不用于说个人身体或心理上的感受。"}, {"text": "我的桌子上放着一个思潮。", "explanation": "这里应该用〈台灯〉。思潮是抽象的思想倾向，不能放在桌子上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24854, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思潮", "is_correct": true, "explanation": "正确。“回乡生活的思潮”指一种共同流行的想法，与“出现”搭配自然，句意通顺。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不能作为一种共同流行的想法出现在城市里。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是日常用品，与“回乡生活”这种共同想法毫不相关。"}, {"text": "棉花", "is_correct": false, "explanation": "搭配：“回乡生活的”后接的应是社会上的想法或现象，不能接棉花这类原料。"}], "explanations": {"思潮": "正确。“回乡生活的思潮”指一种共同流行的想法，与“出现”搭配自然，句意通顺。", "厨房": "语义：厨房是房间，不能作为一种共同流行的想法出现在城市里。", "雨伞": "语义：雨伞是日常用品，与“回乡生活”这种共同想法毫不相关。", "棉花": "搭配：“回乡生活的”后接的应是社会上的想法或现象，不能接棉花这类原料。"}, "sentence_index": 6, "correct_answer": "思潮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都喝一杯思潮。", "explanation": "这里应该用〈牛奶〉。牛奶可以喝，思潮是很多人共同的想法，不能喝。"}, {"text": "她发烧了，思潮很高。", "explanation": "这里应该用〈体温〉。体温是身体的温度，思潮是社会上流行的想法。"}, {"text": "这股思潮从山上流下来，很凉。", "explanation": "这里应该用〈泉水〉。泉水会从山上流下来，思潮是抽象的想法，不会流动、不凉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24854, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "校园里出现了一只新思潮。", "corrected_sentence": "校园里出现了一股新思潮。", "error_description": "量词错误：“思潮”应搭配量词“股”，“只”用于动物等，不能用于思潮。应说“一股新思潮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24854, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想弄清这股思潮们从哪里来。", "corrected_sentence": "我想弄清这股思潮从哪里来。", "error_description": "词缀错误：“们”只用于指人的名词，“思潮”后不能加“们”。应说“这股思潮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24856, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动态", "is_correct": true, "explanation": "“动态”与“静态”相对，指事物运动、变化的状态，是这一义项的反义词。"}, {"text": "桌子", "is_correct": false, "explanation": "“桌子”是具体名词，与“静态”的“不变化、不动”义没有反义关系。"}, {"text": "音乐", "is_correct": false, "explanation": "“音乐”与“静态”的“不变化、不动”义没有反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "“海洋”与“静态”的“不变化、不动”义没有反义关系。"}], "correct_answer": "动态", "explanations": {"动态": "“动态”与“静态”相对，指事物运动、变化的状态，是这一义项的反义词。", "桌子": "“桌子”是具体名词，与“静态”的“不变化、不动”义没有反义关系。", "音乐": "“音乐”与“静态”的“不变化、不动”义没有反义关系。", "海洋": "“海洋”与“静态”的“不变化、不动”义没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24856, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "动态", "is_correct": true, "explanation": "“动态”与“静态”相对，指事物运动、变化的状态，是这一义项的反义词。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”与“静态”的“不变化、不动”义没有反义关系。"}, {"text": "墨水", "is_correct": false, "explanation": "“墨水”与“静态”的“不变化、不动”义没有反义关系。"}, {"text": "蔬菜", "is_correct": false, "explanation": "“蔬菜”与“静态”的“不变化、不动”义没有反义关系。"}], "correct_answer": "动态", "explanations": {"动态": "“动态”与“静态”相对，指事物运动、变化的状态，是这一义项的反义词。", "窗户": "“窗户”与“静态”的“不变化、不动”义没有反义关系。", "墨水": "“墨水”与“静态”的“不变化、不动”义没有反义关系。", "蔬菜": "“蔬菜”与“静态”的“不变化、不动”义没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24856, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "不变化、不动。", "primary_collocate": null, "pronunciation": "jìng tài", "ipa": "tɕiŋ˥˩ tʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "老师先讲静态图，再讲动画。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机壁纸是静态的。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏的背景是静态的。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上的图片是静态的，不会动。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍的是静态照片，不是视频。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画太静态了，缺少动感。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张海报的画面完全静态。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把静态图片换成动画。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的网站只有静态页面。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网页上的这张图是静态的，旁边的广告一直在动。", "target_word": "静态", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "靜態", "label": "繁体"}, {"form": "静态图", "label": "复合"}], "register": "中性", "sense_fingerprint": "不变化、不动的样子，常指画面、页面、工作等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3bb68faa-3174-49c6-8b97-9428afdeed62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "味道", "is_correct": false, "explanation": "语义：图不会有味道，“静态图”不能换成“味道图”。"}, {"text": "静态", "is_correct": true, "explanation": "正确：“静态图”指不变化的图，与后面的“动画”相对。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“歌曲图”不是常用说法，“图”前面不用“歌曲”修饰。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能作为图的类别，与“再讲动画”的语境不符。"}], "explanations": {"味道": "语义：图不会有味道，“静态图”不能换成“味道图”。", "静态": "正确：“静态图”指不变化的图，与后面的“动画”相对。", "歌曲": "搭配：“歌曲图”不是常用说法，“图”前面不用“歌曲”修饰。", "声音": "语义：声音不能作为图的类别，与“再讲动画”的语境不符。"}, "sentence_index": 0, "correct_answer": "静态"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的性格是静态的，喜欢大声说话。", "explanation": "这里应该用〈活泼〉。“静态”指不变化、不动，形容性格要用“活泼”之类的词；与“大声说话”也不合。"}, {"text": "这首歌的节奏很静态，听起来让人想跳舞。", "explanation": "这里应该用〈有动感〉。节奏要有动感才让人想跳舞；“静态”指不动，与“想跳舞”矛盾。"}, {"text": "他的工作是静态的，每天要跑很多地方。", "explanation": "这里应该用〈奔波〉。工作要到处跑，“静态”指不动，与“每天要跑很多地方”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘈杂", "is_correct": false, "explanation": "语义：“嘈杂”形容声音杂乱，海报画面不会嘈杂。"}, {"text": "沙哑", "is_correct": false, "explanation": "语义：“沙哑”形容嗓音，不能用来形容海报的画面。"}, {"text": "吵闹", "is_correct": false, "explanation": "搭配：“吵闹”形容声音或环境，“画面完全吵闹”说不通。"}, {"text": "静态", "is_correct": true, "explanation": "正确：“完全静态”说画面没有变化，与“海报”的语境一致。"}], "explanations": {"嘈杂": "语义：“嘈杂”形容声音杂乱，海报画面不会嘈杂。", "沙哑": "语义：“沙哑”形容嗓音，不能用来形容海报的画面。", "吵闹": "搭配：“吵闹”形容声音或环境，“画面完全吵闹”说不通。", "静态": "正确：“完全静态”说画面没有变化，与“海报”的语境一致。"}, "sentence_index": 6, "correct_answer": "静态"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的兴趣很静态，每周都去攀岩和跳伞。", "explanation": "这里应该用〈广泛〉。兴趣要用“广泛”来形容；“静态”指不动，与“攀岩和跳伞”矛盾。"}, {"text": "这辆车处于静态，开得很快。", "explanation": "这里应该用〈行驶状态〉。车在开动，处于行驶状态；“静态”指不动，与“开得很快”矛盾。"}, {"text": "这只猫很静态，一会儿跳上桌子，一会儿跑出门。", "explanation": "这里应该用〈好动〉。猫跳跑是运动，“静态”指不动，与“跳上桌子”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这幅画是静态了。", "corrected_sentence": "这幅画是静态的。", "error_description": "了的错误：“是……的”判断句不用“了”。正确说法是“这幅画是静态的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个画面放在静态。", "corrected_sentence": "这个画面处于静态。", "error_description": "搭配错误：表示状态要说“处于静态”，不能说“放在静态”。正确说法是“这个画面处于静态”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3be3c1a7-3e2b-4f1d-887c-0b5e3142faab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24858, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "结束", "is_correct": true, "explanation": "“结束”与“延续”在“事情不断进行、没有停止”这一义上构成反义。"}, {"text": "打扫", "is_correct": false, "explanation": "“打扫”与“延续”没有反义或近义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”与“延续”既非反义也非近义，不构成对应关系。"}, {"text": "询问", "is_correct": false, "explanation": "“询问”与“延续”没有反义或近义关系。"}], "correct_answer": "结束", "explanations": {"结束": "“结束”与“延续”在“事情不断进行、没有停止”这一义上构成反义。", "打扫": "“打扫”与“延续”没有反义或近义关系。", "散步": "“散步”与“延续”既非反义也非近义，不构成对应关系。", "询问": "“询问”与“延续”没有反义或近义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24858, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "停止", "is_correct": true, "explanation": "“停止”与“延续”在“事情不断进行、没有停止”这一义上构成反义。"}, {"text": "思考", "is_correct": false, "explanation": "“思考”与“延续”没有反义或近义关系。"}, {"text": "整理", "is_correct": false, "explanation": "“整理”与“延续”没有反义或近义关系。"}, {"text": "观察", "is_correct": false, "explanation": "“观察”与“延续”没有反义或近义关系。"}], "correct_answer": "停止", "explanations": {"停止": "“停止”与“延续”在“事情不断进行、没有停止”这一义上构成反义。", "思考": "“思考”与“延续”没有反义或近义关系。", "整理": "“整理”与“延续”没有反义或近义关系。", "观察": "“观察”与“延续”没有反义或近义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24858, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一件事不断进行，没有停止。", "primary_collocate": null, "pronunciation": "yán xù", "ipa": "jɛn˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "这场雨从早上一直延续到晚上。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛延续了三个小时才结束。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场大雪已经延续了一个星期。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议延续到很晚，大家都累了。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的争论延续了一整天。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的高温会延续到九月。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这样的好天气还会延续几天。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出延续着，观众一直没有离开。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的谈话延续了很久。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种热闹的局面延续了十年。", "target_word": "延续", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "延续着", "label": "体标（着）"}, {"form": "延续了", "label": "体标（了）"}, {"form": "延续过", "label": "体标（过）"}, {"form": "延续下去", "label": "复合（趋向补语）"}], "register": "中性", "sense_fingerprint": "延续：雨、比赛、会议等事情不断进行，没有停止", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca04757e-f18e-4f27-8a23-f6806ffa8172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24858, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "延续", "is_correct": true, "explanation": "“延续”指事情不断进行、没有停止，与“从早上一直……到晚上”的持续义一致。"}, {"text": "结束", "is_correct": false, "explanation": "体貌：“结束”是瞬间完成的动作，不能与表示持续的“一直……到晚上”搭配。"}, {"text": "放晴", "is_correct": false, "explanation": "语义：“放晴”指天气转好、云散开，与“这场雨”一直下着的情形不符。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”指不再进行，与“一直……到晚上”的持续义相反。"}], "explanations": {"延续": "“延续”指事情不断进行、没有停止，与“从早上一直……到晚上”的持续义一致。", "结束": "体貌：“结束”是瞬间完成的动作，不能与表示持续的“一直……到晚上”搭配。", "放晴": "语义：“放晴”指天气转好、云散开，与“这场雨”一直下着的情形不符。", "停止": "语义：“停止”指不再进行，与“一直……到晚上”的持续义相反。"}, "sentence_index": 0, "correct_answer": "延续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子延续了十厘米。", "explanation": "这里应该用〈长〉。“延续”指事情不断进行，不表示身高增加。"}, {"text": "停电后，比赛又延续了。", "explanation": "这里应该用〈恢复〉。比赛停了之后重新开始，要用“恢复”；“延续”只指不停地进行下去。"}, {"text": "比赛在下午三点延续了。", "explanation": "这里应该用〈开始〉。“延续”指已经在进行的事情不停，不能表示事情的开始。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24858, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "延续", "is_correct": true, "explanation": "“延续”指持续进行、不停止，与“还会……几天”的持续义一致。"}, {"text": "结束", "is_correct": false, "explanation": "体貌：“结束”是瞬间完成的动作，不能用“还会……几天”表示持续一段时间。"}, {"text": "转变", "is_correct": false, "explanation": "语义：“转变”指事物改变原来的状态，与“好天气”持续不变的意思相反。"}, {"text": "扩大", "is_correct": false, "explanation": "搭配：“扩大”的对象是范围、规模，不能说扩大天气的时间。"}], "explanations": {"延续": "“延续”指持续进行、不停止，与“还会……几天”的持续义一致。", "结束": "体貌：“结束”是瞬间完成的动作，不能用“还会……几天”表示持续一段时间。", "转变": "语义：“转变”指事物改变原来的状态，与“好天气”持续不变的意思相反。", "扩大": "搭配：“扩大”的对象是范围、规模，不能说扩大天气的时间。"}, "sentence_index": 6, "correct_answer": "延续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的规模延续了一倍。", "explanation": "这里应该用〈扩大〉。“延续”指事情不断进行，不用于规模的扩大。"}, {"text": "这段路程延续了一半。", "explanation": "这里应该用〈缩短〉。“延续”指事情不断进行，不表示路程的缩短。"}, {"text": "这棵树延续了三米。", "explanation": "这里应该用〈生长〉。“延续”不用于植物长高，树木长高要用“生长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24858, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场比赛延续在了深夜。", "corrected_sentence": "这场比赛延续到了深夜。", "error_description": "表示延续到的终点要用介词“到”，应说“延续到了深夜”；“在”不能引出这样的时间终点，“延续在了深夜”不对。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24858, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场大雨一直延续过，没有停。", "corrected_sentence": "这场大雨一直延续着，没有停。", "error_description": "“过”表示曾经有过的经历，不能表示正在持续进行，此处应用“着”，说“一直延续着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24860, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
