INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24860, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指机器、设备等能自己想办法、学得快。", "primary_collocate": null, "pronunciation": "zhì néng", "ipa": "tʂɻ̩˥˩ nɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这个机器人很智能，会自己学习。", "target_word": "智能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新手机比旧手机更智能。", "target_word": "智能", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这台洗衣机很智能，会自己选水量。", "target_word": "智能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的灯是智能的，可以用声音开关。", "target_word": "智能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这辆车很智能，会自己找停车的地方。", "target_word": "智能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个音箱不太智能，常常听不懂我的话。", "target_word": "智能", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想买一个更智能的手表。", "target_word": "智能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新电脑学得很快，用得越久越智能。", "target_word": "智能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个软件很智能，会帮你想办法。", "target_word": "智能", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的公司要做更智能的机器。", "target_word": "智能", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "智能化", "label": "复合"}, {"form": "智能手机", "label": "复合"}, {"form": "人工智能", "label": "复合"}], "register": "中性", "sense_fingerprint": "智能：会自己想办法、学得快的（机器、设备）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fb7fbe2-03dc-4c00-8c7e-e16f093b9f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24860, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "智能", "is_correct": true, "explanation": "正确答案：智能 zhì néng，形容机器会自己想办法、学得快。"}, {"text": "只能", "is_correct": false, "explanation": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是仅能。"}, {"text": "职能", "is_correct": false, "explanation": "zhí（第二声）与 zhì（第四声）声调不同，意思是职务上的作用。"}, {"text": "技能", "is_correct": false, "explanation": "jì 与 zhì 声母不同（j 与 zh），意思是技术和本领。"}], "explanations": {"智能": "正确答案：智能 zhì néng，形容机器会自己想办法、学得快。", "只能": "zhǐ（第三声）与 zhì（第四声）声调不同，意思是仅能。", "职能": "zhí（第二声）与 zhì（第四声）声调不同，意思是职务上的作用。", "技能": "jì 与 zhì 声母不同（j 与 zh），意思是技术和本领。"}, "sentence_index": null, "correct_answer": "智能"}, "level_3": {"options": [{"text": "笨", "is_correct": false, "explanation": "语义：“笨”形容不聪明，与后句“会自己学习”的能力相矛盾。"}, {"text": "智能", "is_correct": true, "explanation": "正确：“智能”形容机器会自己想办法、学得快，与“会自己学习”一致。"}, {"text": "笨拙", "is_correct": false, "explanation": "语义：“笨拙”形容动作不灵活，不能说明机器会自己学习的能力。"}, {"text": "简陋", "is_correct": false, "explanation": "搭配：“简陋”多形容房屋、设备的粗糙，不用来说明机器的学习能力。"}], "explanations": {"笨": "语义：“笨”形容不聪明，与后句“会自己学习”的能力相矛盾。", "智能": "正确：“智能”形容机器会自己想办法、学得快，与“会自己学习”一致。", "笨拙": "语义：“笨拙”形容动作不灵活，不能说明机器会自己学习的能力。", "简陋": "搭配：“简陋”多形容房屋、设备的粗糙，不用来说明机器的学习能力。"}, "sentence_index": 0, "correct_answer": "智能"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很智能，学东西很快，做事很认真。", "explanation": "这里应该用〈聪明〉。智能多形容机器、设备会自己想办法，形容人学东西快要用〈聪明〉。"}, {"text": "他的脾气很智能，从来不发火。", "explanation": "这里应该用〈温和〉。智能只形容机器或设备，不能形容人的脾气。"}, {"text": "这家餐厅的菜很智能，味道很好。", "explanation": "这里应该用〈美味〉。智能用于机器和设备，不能用来形容食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24860, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "懒惰", "is_correct": false, "explanation": "搭配：“懒惰”多形容人的性情，不能用来修饰手表。"}, {"text": "迟钝", "is_correct": false, "explanation": "语义：“迟钝”指反应慢，与“想买更……的手表”所追求的功能不合。"}, {"text": "智能", "is_correct": true, "explanation": "正确：“更智能的手表”指功能更会自动学习，符合语境。"}, {"text": "狡猾", "is_correct": false, "explanation": "搭配：“狡猾”形容人的心机，不用来修饰手表。"}], "explanations": {"懒惰": "搭配：“懒惰”多形容人的性情，不能用来修饰手表。", "迟钝": "语义：“迟钝”指反应慢，与“想买更……的手表”所追求的功能不合。", "智能": "正确：“更智能的手表”指功能更会自动学习，符合语境。", "狡猾": "搭配：“狡猾”形容人的心机，不用来修饰手表。"}, "sentence_index": 6, "correct_answer": "智能"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个问题很智能，需要慢慢思考。", "explanation": "这里应该用〈复杂〉。智能形容机器会自己想办法，不能用来形容问题。"}, {"text": "这条路很智能，一直通到山顶。", "explanation": "这里应该用〈长〉。智能用于机器和设备，不能用来形容道路。"}, {"text": "这棵老树很智能，每年都开很多花。", "explanation": "这里应该用〈繁茂〉。智能用于机器和设备，不能用来形容树木的生长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24860, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个音箱是智能，可以用手机控制。", "corrected_sentence": "这个音箱是智能的，可以用手机控制。", "error_description": "错误形式：“是……的”结构中漏掉“的”；正确形式：“是智能的”。原因：“智能”作形容词谓语时，“是……的”结构要求补上“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24860, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新款洗衣机比旧款最智能。", "corrected_sentence": "新款洗衣机比旧款更智能。", "error_description": "程度副词错误：“比”字句中表示程度要用“更”，不能用“最”；应说“比旧款更智能”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
