INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24862, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不停地问，想知道更多。", "primary_collocate": null, "pronunciation": "zhuī wèn", "ipa": "ʈʂweɪ˥ wən˥˩", "syllable_count": 2, "sentences": [{"text": "孩子总爱追问为什么。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他追问个不停，大家都笑了。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师刚讲完，小明又追问了一句。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我追问了好几次，她才告诉我。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别再追问了，他不想说。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者追问市长什么时候开始工作。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶追问着我的工作情况。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对这个问题一直追问下去。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈追问我是不是病了。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友追问我为什么不去。", "target_word": "追问", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追问了", "label": "体标"}, {"form": "追问过", "label": "体标"}, {"form": "追问着", "label": "体标"}], "register": "中性", "sense_fingerprint": "一个问题接一个问题地问，想知道更多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca04757e-f18e-4f27-8a23-f6806ffa8172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24862, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追赶", "is_correct": false, "explanation": "搭配：“追赶”后要接具体对象，不能接“为什么”这类疑问内容。"}, {"text": "追悼", "is_correct": false, "explanation": "语义：“追悼”指悼念死者，与“孩子爱问”的语境完全不符。"}, {"text": "追问", "is_correct": true, "explanation": "正确：“追问为什么”指一个问题接一个问题地问，想知道更多。"}, {"text": "追求", "is_correct": false, "explanation": "配价：“追求”的宾语是目标，不能接“为什么”这类疑问内容。"}], "explanations": {"追赶": "搭配：“追赶”后要接具体对象，不能接“为什么”这类疑问内容。", "追悼": "语义：“追悼”指悼念死者，与“孩子爱问”的语境完全不符。", "追问": "正确：“追问为什么”指一个问题接一个问题地问，想知道更多。", "追求": "配价：“追求”的宾语是目标，不能接“为什么”这类疑问内容。"}, "sentence_index": 0, "correct_answer": "追问"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一直在追问那辆公交车。", "explanation": "这里应该用〈追赶〉。“追问”的对象是人或问题，不能用于车辆。"}, {"text": "他一直追问那位老师的脚步。", "explanation": "这里应该用〈追随〉。“追问”是提问，不表示跟随别人的行动。"}, {"text": "人们追问那只小猫。", "explanation": "这里应该用〈追赶〉。“追问”的对象是人或问题，不能用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24862, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追逐", "is_correct": false, "explanation": "搭配：“追逐”指追赶物体，不能用于“工作情况”。"}, {"text": "追悔", "is_correct": false, "explanation": "语义：“追悔”指事后后悔，与“奶奶询问工作情况”的语境不符。"}, {"text": "追问", "is_correct": true, "explanation": "正确：“追问着我的工作情况”指接连地询问，想弄清楚更多。"}, {"text": "追捧", "is_correct": false, "explanation": "搭配：“追捧”指热烈推崇人或事物，不能与“工作情况”搭配。"}], "explanations": {"追逐": "搭配：“追逐”指追赶物体，不能用于“工作情况”。", "追悔": "语义：“追悔”指事后后悔，与“奶奶询问工作情况”的语境不符。", "追问": "正确：“追问着我的工作情况”指接连地询问，想弄清楚更多。", "追捧": "搭配：“追捧”指热烈推崇人或事物，不能与“工作情况”搭配。"}, "sentence_index": 6, "correct_answer": "追问"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我常常追问童年的时光。", "explanation": "这里应该用〈追忆〉。“追问”是提问，不能用于回想往事。"}, {"text": "猎人在山里追问野兔。", "explanation": "这里应该用〈追踪〉。“追问”的对象是人或问题，不能用于动物。"}, {"text": "他终于追问了前面的队伍。", "explanation": "这里应该用〈追上〉。“追问”表示提问，不表示赶上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24862, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈追问他了好几遍。", "corrected_sentence": "妈妈追问了他好几遍。", "error_description": "“了”应紧跟动词，说“追问了他”；“追问他了”把“了”放在宾语后，不符合语法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24862, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈追问了着我的病情。", "corrected_sentence": "妈妈追问着我的病情。", "error_description": "“了”和“着”不能同时用在同一个动词上；“追问了着”重复了体标，应只用“着”，即“追问着我的病情”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
