INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24866, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子是人们住的地方。", "primary_collocate": null, "pronunciation": "fáng zi", "ipa": "fɑŋ˧˥ tsɹ̩", "syllable_count": 2, "sentences": [{"text": "我家的房子在河边。", "target_word": "房子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座房子很大，也很旧。", "target_word": "房子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们想买一套新房子。", "target_word": "房子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗在房子前面玩。", "target_word": "房子", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个房子有三个房间，住四个人刚好。", "target_word": "房子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸正在刷房子外面的墙。", "target_word": "房子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们昨天搬进了新房子，很高兴。", "target_word": "房子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋房子是我爷爷住过的。", "target_word": "房子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子太贵了，他们只好租一个小的。", "target_word": "房子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我把房子打扫得很干净，等朋友来住。", "target_word": "房子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "栋", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "口语", "sense_fingerprint": "房子：人住的建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6fb7fbe2-03dc-4c00-8c7e-e16f093b9f50') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24866, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房子", "is_correct": true, "explanation": "正确：房子是人们住的地方，“我家的房子”指自己的住所，与“在河边”相合。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不能说“我家的太阳”，也不是人住的地方。"}, {"text": "海洋", "is_correct": false, "explanation": "搭配：“我家的”修饰的是可以拥有的东西，不能说“我家的海洋”。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：天空无法被“我家的”限定，这句话不成立。"}], "explanations": {"房子": "正确：房子是人们住的地方，“我家的房子”指自己的住所，与“在河边”相合。", "太阳": "语义：太阳是天体，不能说“我家的太阳”，也不是人住的地方。", "海洋": "搭配：“我家的”修饰的是可以拥有的东西，不能说“我家的海洋”。", "天空": "搭配：天空无法被“我家的”限定，这句话不成立。"}, "sentence_index": 0, "correct_answer": "房子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把书放进房子里，背着去上学。", "explanation": "这里应该用〈书包〉。房子是人住的建筑，不能背着走。"}, {"text": "他每天开着房子去上班，路上很堵。", "explanation": "这里应该用〈车〉。房子是人住的建筑，不能开着上路。"}, {"text": "他把房子放进口袋里带走了。", "explanation": "这里应该用〈钥匙〉。房子是人住的建筑，不能装进口袋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24866, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "房子", "is_correct": true, "explanation": "正确：“搬进”的对象是住所，房子符合“他们搬进了新……”的语境。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“搬进”的对象是住所，不能说“搬进了新名字”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：天气不能被搬进，与“搬进了”不搭。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是作品，不是可以搬进去的地方，与“很高兴”的语境也无关。"}], "explanations": {"房子": "正确：“搬进”的对象是住所，房子符合“他们搬进了新……”的语境。", "名字": "搭配：“搬进”的对象是住所，不能说“搬进了新名字”。", "天气": "搭配：天气不能被搬进，与“搬进了”不搭。", "歌曲": "语义：歌曲是作品，不是可以搬进去的地方，与“很高兴”的语境也无关。"}, "sentence_index": 6, "correct_answer": "房子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上八点去房子上班，路上要坐一个小时车。", "explanation": "这里应该用〈公司〉。“房子”指人住的建筑，上班要去“公司”，不说“去房子上班”。"}, {"text": "我每天下班都去房子看电影。", "explanation": "这里应该用〈电影院〉。“房子”指人住的建筑，看电影要去“电影院”，不能说“去房子看电影”。"}, {"text": "我们坐房子去北京旅游，路上要两个小时。", "explanation": "这里应该用〈火车〉。房子是人住的建筑，不是交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24866, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把房子是我们去年买的。", "corrected_sentence": "这套房子是我们去年买的。", "error_description": "量词用错：“房子”的量词应用“套”，“把”用于有柄或可握的东西，不能修饰房子。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24866, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在山上盖了一部房子。", "corrected_sentence": "他们在山上盖了一栋房子。", "error_description": "量词用错：“房子”的量词应用“栋”，“部”用于电影、手机等，不能修饰房子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '523bc86b-7d76-4cbe-bed4-12eddf214c58') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
