INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24868, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "层数很多、很高的楼房。", "primary_collocate": null, "pronunciation": "gāo lóu", "ipa": "kau˥ lou˧˥", "syllable_count": 2, "sentences": [{"text": "这座城市有很多高楼。", "target_word": "高楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在一栋高楼里。", "target_word": "高楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋高楼的窗户很大。", "target_word": "高楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "远处有一座高楼，非常漂亮。", "target_word": "高楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近新建了几栋高楼。", "target_word": "高楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在高楼上，可以看到整个城市。", "target_word": "高楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人不喜欢住高楼，上下不方便。", "target_word": "高楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高楼之间有一个小公园。", "target_word": "高楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片老房子旁边盖起了一座高楼。", "target_word": "高楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，高楼的灯都亮着。", "target_word": "高楼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一栋高楼", "label": "量词（栋）"}, {"form": "一座高楼", "label": "量词（座）"}, {"form": "高楼大厦", "label": "复合词"}], "register": "中性", "sense_fingerprint": "高楼：层数很多、很高的楼房", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '071f4daf-d2f5-4352-a46c-90263f231feb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24868, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老虎", "is_correct": false, "explanation": "语义：城市里不会有很多老虎，与“城市”的语境不符。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“大海”是唯一的事物，不能用“很多”来计数。"}, {"text": "高楼", "is_correct": true, "explanation": "正确：“高楼”指层数多、很高的楼房，可以用“很多”修饰，符合城市的语境。"}, {"text": "手指", "is_correct": false, "explanation": "语义：“手指”不是城市里的组成部分，不符合“城市有很多”的语境。"}], "explanations": {"老虎": "语义：城市里不会有很多老虎，与“城市”的语境不符。", "大海": "搭配：“大海”是唯一的事物，不能用“很多”来计数。", "高楼": "正确：“高楼”指层数多、很高的楼房，可以用“很多”修饰，符合城市的语境。", "手指": "语义：“手指”不是城市里的组成部分，不符合“城市有很多”的语境。"}, "sentence_index": 0, "correct_answer": "高楼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口停着一只高楼。", "explanation": "这里应该用〈座〉或〈栋〉。〈只〉用于动物或小件物品，“高楼”是建筑，量词不对。"}, {"text": "这栋高楼只有一层。", "explanation": "这里应该用〈平房〉。“平房”指只有一层的房子；“高楼”指层数很多、很高的楼房，二者意思相反。"}, {"text": "这座高楼很矮。", "explanation": "这里应该用〈小楼〉。“小楼”指规模不大的楼房；“高楼”指层数多、很高的楼房，“很矮”与“高楼”的意思相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24868, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "平房", "is_correct": false, "explanation": "语义：平房没有楼层，与“上下不方便”的理由相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能住人，句中“住”的对象必须是可以居住的地方。"}, {"text": "高楼", "is_correct": true, "explanation": "正确：“高楼”层数多，住在高处才会有“上下不方便”的问题，符合句意。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“住”不能与“树木”搭配，人不住在树木里。"}], "explanations": {"平房": "语义：平房没有楼层，与“上下不方便”的理由相矛盾。", "桌子": "语义：桌子不能住人，句中“住”的对象必须是可以居住的地方。", "高楼": "正确：“高楼”层数多，住在高处才会有“上下不方便”的问题，符合句意。", "树木": "搭配：“住”不能与“树木”搭配，人不住在树木里。"}, "sentence_index": 6, "correct_answer": "高楼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在草原上盖了一棵高楼。", "explanation": "这里应该用〈座〉或〈栋〉。〈棵〉用于树木，“高楼”是建筑，量词不对。"}, {"text": "我们把高楼搬进了屋子里。", "explanation": "这里“高楼”用错了：它指很高的楼房，是无法搬进屋子里的建筑，不能用“搬进屋子”来说。"}, {"text": "这座高楼很小巧，可以放在书桌上。", "explanation": "这里“高楼”用错了：它指很高的楼房，“很小巧，可以放在书桌上”描述的是小型物件，二者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24868, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片区域新建了一只高楼。", "corrected_sentence": "这片区域新建了一座高楼。", "error_description": "量词错误：“高楼”是建筑，应该用量词“座”，不能用“只”，应说“一座高楼”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24868, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片城区有许多高楼们。", "corrected_sentence": "这片城区有许多高楼。", "error_description": "词缀错误：“们”只用于表示人的复数，不能加在“高楼”后面，也不能与“许多”同时使用，应说“许多高楼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a166acff-29cb-43f9-a687-ccc8d4a208ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24870, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难看", "is_correct": true, "explanation": "正确：“难看”与“好看”相对，指外表不美观，是反义词。"}, {"text": "干净", "is_correct": false, "explanation": "与“好看”无反义关系，“干净”指没有污物，不对应外表好坏。"}, {"text": "粗糙", "is_correct": false, "explanation": "与“好看”无反义关系，“粗糙”指表面不光滑，不与“好看”相对。"}, {"text": "安静", "is_correct": false, "explanation": "与“好看”无反义关系，“安静”指没有声音，与外表无关。"}], "correct_answer": "难看", "explanations": {"难看": "正确：“难看”与“好看”相对，指外表不美观，是反义词。", "干净": "与“好看”无反义关系，“干净”指没有污物，不对应外表好坏。", "粗糙": "与“好看”无反义关系，“粗糙”指表面不光滑，不与“好看”相对。", "安静": "与“好看”无反义关系，“安静”指没有声音，与外表无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24870, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难看", "is_correct": true, "explanation": "正确：“难看”与“好看”相对，指外表不美观，是反义词。"}, {"text": "陈旧", "is_correct": false, "explanation": "与“好看”无反义关系，“陈旧”指过时，不对应外表的好坏。"}, {"text": "明亮", "is_correct": false, "explanation": "与“好看”无反义关系，“明亮”指光线充足，不与“好看”相对。"}, {"text": "清楚", "is_correct": false, "explanation": "与“好看”无反义关系，“清楚”指明白，与外表无关。"}], "correct_answer": "难看", "explanations": {"难看": "正确：“难看”与“好看”相对，指外表不美观，是反义词。", "陈旧": "与“好看”无反义关系，“陈旧”指过时，不对应外表的好坏。", "明亮": "与“好看”无反义关系，“明亮”指光线充足，不与“好看”相对。", "清楚": "与“好看”无反义关系，“清楚”指明白，与外表无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24870, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "样子漂亮，看着让人喜欢。", "primary_collocate": null, "pronunciation": "hǎo kàn", "ipa": "xɑʊ̯˨˩ kʰan˥˩", "syllable_count": 2, "sentences": [{"text": "这朵花很好看。", "target_word": "好看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你的新衣服真好看。", "target_word": "好看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她穿红裙子特别好看。", "target_word": "好看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书的图片很好看。", "target_word": "好看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山上的花开了，好看极了。", "target_word": "好看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的小狗长得很好看。", "target_word": "好看", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "窗外的雪景真好看，我拍了照片。", "target_word": "好看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服颜色好看，可是有点贵。", "target_word": "好看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个房间不太好看，我们换一下吧。", "target_word": "好看", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑起来很好看。", "target_word": "好看", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "好看：外表让人看了觉得高兴、漂亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24870, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好看", "is_correct": true, "explanation": "正确：“这朵花很好看”说花的外表漂亮，与句意一致。"}, {"text": "好吃", "is_correct": false, "explanation": "语义：花不能吃，“好吃”说的是味道，不能用来说花。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“清楚”形容看得明白或说得明白，不用来形容花的样子。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：花没有心情，“高兴”是人的情绪，不能用来说花。"}], "explanations": {"好看": "正确：“这朵花很好看”说花的外表漂亮，与句意一致。", "好吃": "语义：花不能吃，“好吃”说的是味道，不能用来说花。", "清楚": "搭配：“清楚”形容看得明白或说得明白，不用来形容花的样子。", "高兴": "语义：花没有心情，“高兴”是人的情绪，不能用来说花。"}, "sentence_index": 0, "correct_answer": "好看"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的旋律很好看。", "explanation": "这里应该用〈好听〉。“好看”形容外表，说声音、旋律要用〈好听〉。"}, {"text": "这杯咖啡很好看，我一口气喝完了。", "explanation": "这里应该用〈好喝〉。“好看”形容外表，说饮料的味道要用〈好喝〉。"}, {"text": "他的演讲很好看，大家都很感动。", "explanation": "这里应该用〈精彩〉。“好看”形容外表，评价演讲要用〈精彩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24870, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好看", "is_correct": true, "explanation": "正确：“窗外的雪景真好看”说景色美，与“我拍了照片”相符。"}, {"text": "好闻", "is_correct": false, "explanation": "语义：雪景是用来看的，不能说“好闻”。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容物品坚固，不用来形容雪景。"}, {"text": "辛苦", "is_correct": false, "explanation": "语义：雪景没有劳累的感受，“辛苦”不能用来形容景色。"}], "explanations": {"好看": "正确：“窗外的雪景真好看”说景色美，与“我拍了照片”相符。", "好闻": "语义：雪景是用来看的，不能说“好闻”。", "结实": "搭配：“结实”形容物品坚固，不用来形容雪景。", "辛苦": "语义：雪景没有劳累的感受，“辛苦”不能用来形容景色。"}, "sentence_index": 6, "correct_answer": "好看"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份工作很好看，工资也高。", "explanation": "这里应该用〈轻松〉。“好看”只说外表，不能用来评价工作。"}, {"text": "他很好看地回答了问题。", "explanation": "这里应该用〈流利〉。“好看”形容外表，不用来修饰回答问题的方式。"}, {"text": "这个笑话很好看，大家都笑了。", "explanation": "这里应该用〈好笑〉。评价笑话要说“好笑”，“好看”只指外表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24870, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件衣服好看很。", "corrected_sentence": "这件衣服好看得很。", "error_description": "补语标记缺失：程度补语前要用“得”，应说“好看得很”，不能说“好看很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24870, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这束花的颜色很好看着。", "corrected_sentence": "这束花的颜色很好看。", "error_description": "动态助词错误：形容词“好看”后不能加“着”，应直接说“很好看”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24872, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赔", "is_correct": true, "explanation": "正确：赔与赚构成反义，指损失钱，与“用劳动换钱”相对。"}, {"text": "煮", "is_correct": false, "explanation": "煮是烹调，与赚没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑是奔跑，与赚没有反义关系。"}, {"text": "画", "is_correct": false, "explanation": "画是绘画，与赚没有反义关系。"}], "correct_answer": "赔", "explanations": {"赔": "正确：赔与赚构成反义，指损失钱，与“用劳动换钱”相对。", "煮": "煮是烹调，与赚没有反义关系。", "跑": "跑是奔跑，与赚没有反义关系。", "画": "画是绘画，与赚没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24872, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "赔", "is_correct": true, "explanation": "正确：赔与赚构成反义，指损失钱，与“赚钱”相对。"}, {"text": "写", "is_correct": false, "explanation": "写是书写，与赚没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "唱是歌唱，与赚没有反义关系。"}, {"text": "修", "is_correct": false, "explanation": "修是修理，与赚没有反义关系。"}], "correct_answer": "赔", "explanations": {"赔": "正确：赔与赚构成反义，指损失钱，与“赚钱”相对。", "写": "写是书写，与赚没有反义关系。", "唱": "唱是歌唱，与赚没有反义关系。", "修": "修是修理，与赚没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24872, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用劳动换钱。", "primary_collocate": null, "pronunciation": "zhuàn", "ipa": "ʈʂwan˥˩", "syllable_count": 1, "sentences": [{"text": "爸爸每天工作，赚钱养家。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在饭店打工，赚一点钱。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她白天上班，晚上也赚钱。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠送快递赚钱。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "暑假我想去工作，赚自己的学费。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做饭给别人吃，赚了一点钱。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手艺赚钱，不靠别人。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民种了一年地，才赚这么多。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作很累，但是能赚不少。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生做小工赚的钱不多。", "target_word": "赚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赚了", "label": "体标"}, {"form": "赚过", "label": "体标"}, {"form": "赚钱", "label": "复合"}, {"form": "賺", "label": "繁体"}], "register": "中性", "sense_fingerprint": "用自己的劳动换来钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9396a7ad-604e-4eae-9004-ebab4a4f74bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24872, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "赚", "is_correct": true, "explanation": "正确：赚（zhuàn，第四声），意思是用自己的劳动换来钱。"}, {"text": "专", "is_correct": false, "explanation": "专（zhuān，第一声）与赚（zhuàn，第四声）声调不同，意思是专门、专业。"}, {"text": "砖", "is_correct": false, "explanation": "砖（zhuān，第一声）与赚（zhuàn，第四声）声调不同，意思是砖头。"}, {"text": "撞", "is_correct": false, "explanation": "撞（zhuàng）与赚（zhuàn）韵尾不同，撞是碰撞，不是挣钱。"}, {"text": "壮", "is_correct": false, "explanation": "壮（zhuàng）与赚（zhuàn）韵尾不同，意思是强壮。"}], "explanations": {"赚": "正确：赚（zhuàn，第四声），意思是用自己的劳动换来钱。", "专": "专（zhuān，第一声）与赚（zhuàn，第四声）声调不同，意思是专门、专业。", "砖": "砖（zhuān，第一声）与赚（zhuàn，第四声）声调不同，意思是砖头。", "撞": "撞（zhuàng）与赚（zhuàn）韵尾不同，撞是碰撞，不是挣钱。", "壮": "壮（zhuàng）与赚（zhuàn）韵尾不同，意思是强壮。"}, "sentence_index": null, "correct_answer": "赚"}, "level_3": {"options": [{"text": "赚", "is_correct": true, "explanation": "正确：赚，表示用劳动换钱，与“爸爸每天工作”和“养家”的意思相符。"}, {"text": "种", "is_correct": false, "explanation": "语义：“种”指栽培植物，钱不能种，句子不通。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能以“钱”作宾语，“咬钱养家”不成立。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”表示抛弃，与“养家”的意思相反。"}], "explanations": {"赚": "正确：赚，表示用劳动换钱，与“爸爸每天工作”和“养家”的意思相符。", "种": "语义：“种”指栽培植物，钱不能种，句子不通。", "咬": "搭配：“咬”不能以“钱”作宾语，“咬钱养家”不成立。", "扔": "语义：“扔”表示抛弃，与“养家”的意思相反。"}, "sentence_index": 0, "correct_answer": "赚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于赚到了好消息。", "explanation": "这里应该用〈听到〉。赚的对象是钱或利益，消息要说听到。"}, {"text": "他赚得了好成绩。", "explanation": "这里应该用〈取得〉。赚的对象是钱或利益，成绩要说取得。"}, {"text": "他赚了父亲的事业。", "explanation": "这里应该用〈继承〉。赚的对象是钱或利益，事业要说继承。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24872, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "赚", "is_correct": true, "explanation": "正确：赚（zhuàn），意思是用自己的劳动换来钱。"}, {"text": "串", "is_correct": false, "explanation": "串（chuàn）与赚（zhuàn）声母不同（ch 与 zh），意思是串起来。"}, {"text": "钻", "is_correct": false, "explanation": "钻（zuàn）与赚（zhuàn）声母不同（z 与 zh），意思是钻石或钻研。"}, {"text": "涮", "is_correct": false, "explanation": "涮（shuàn）与赚（zhuàn）声母不同（sh 与 zh），意思是在汤里来回烫。"}, {"text": "窜", "is_correct": false, "explanation": "窜（cuàn）与赚（zhuàn）声母不同（c 与 zh），意思是乱跑。"}], "explanations": {"赚": "正确：赚（zhuàn），意思是用自己的劳动换来钱。", "串": "串（chuàn）与赚（zhuàn）声母不同（ch 与 zh），意思是串起来。", "钻": "钻（zuàn）与赚（zhuàn）声母不同（z 与 zh），意思是钻石或钻研。", "涮": "涮（shuàn）与赚（zhuàn）声母不同（sh 与 zh），意思是在汤里来回烫。", "窜": "窜（cuàn）与赚（zhuàn）声母不同（c 与 zh），意思是乱跑。"}, "sentence_index": null, "correct_answer": "赚"}, "level_3": {"options": [{"text": "赚", "is_correct": true, "explanation": "正确：赚，表示用劳动换钱，与“用手艺”和“不靠别人”的语境相符。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指挖掘，钱不能挖，句子不通。"}, {"text": "踩", "is_correct": false, "explanation": "搭配：“踩”不能以“钱”作宾语，“踩钱”不成立。"}, {"text": "劈", "is_correct": false, "explanation": "语义：“劈”指劈开，与钱无关，句子不通。"}], "explanations": {"赚": "正确：赚，表示用劳动换钱，与“用手艺”和“不靠别人”的语境相符。", "挖": "语义：“挖”指挖掘，钱不能挖，句子不通。", "踩": "搭配：“踩”不能以“钱”作宾语，“踩钱”不成立。", "劈": "语义：“劈”指劈开，与钱无关，句子不通。"}, "sentence_index": 6, "correct_answer": "赚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他赚起了生活的担子。", "explanation": "这里应该用〈挑起〉。赚的对象是钱或利益，生活的担子要说挑起。"}, {"text": "他赚了很多努力。", "explanation": "这里应该用〈付出〉。赚的对象是钱或利益，努力要说付出。"}, {"text": "他赚了一封信。", "explanation": "这里应该用〈寄〉。赚的对象是钱或利益，信件要说寄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24872, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年在工厂了赚两万块。", "corrected_sentence": "他去年在工厂赚了两万块。", "error_description": "错误：“了”放在动词“赚”前面。正确：“赚了”，完成的“了”要放在动词后面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24872, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个夏天，他在餐厅打工赚没到钱。", "corrected_sentence": "这个夏天，他在餐厅打工没赚到钱。", "error_description": "错误：“没”与“到”的位置错误。正确：“没赚到”，否定词“没”要放在动词前面，不能说“赚没到”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
