INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24874, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来购买商品和服务的货币。", "primary_collocate": null, "pronunciation": "qián", "ipa": "tɕʰjɛn˧˥", "syllable_count": 1, "sentences": [{"text": "我没有钱。", "target_word": "钱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书多少钱？", "target_word": "钱", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每个月存一些钱。", "target_word": "钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想用这笔钱买一台电脑。", "target_word": "钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈给了我二十块钱。", "target_word": "钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我身上没带钱，不能买苹果。", "target_word": "钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他很会花钱，每个月都不剩钱。", "target_word": "钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一直在工作，想多赚点钱。", "target_word": "钱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我借给他一百块钱，他还没还。", "target_word": "钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了买房子，他们存了很多钱。", "target_word": "钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔钱", "label": "量词搭配"}, {"form": "零钱", "label": "复合词"}, {"form": "钱包", "label": "复合词"}], "register": "中性", "sense_fingerprint": "钱：买东西用的货币", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc7d612e-20ca-4dd1-8228-5889a24a7062') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24874, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "钱", "is_correct": true, "explanation": "“钱”读 qián（第二声），指买东西用的货币，即本词。"}, {"text": "千", "is_correct": false, "explanation": "千（qiān，第一声）与 qián（第二声）声调不同，意思是数字“千”。"}, {"text": "欠", "is_correct": false, "explanation": "欠（qiàn，第四声）与 qián 声调不同，意思是“欠债”。"}, {"text": "浅", "is_correct": false, "explanation": "浅（qiǎn，第三声）与 qián 声调不同，意思是“不深”。"}, {"text": "牵", "is_correct": false, "explanation": "牵（qiān，第一声）与 qián 声调不同，意思是“牵引”。"}], "explanations": {"钱": "“钱”读 qián（第二声），指买东西用的货币，即本词。", "千": "千（qiān，第一声）与 qián（第二声）声调不同，意思是数字“千”。", "欠": "欠（qiàn，第四声）与 qián 声调不同，意思是“欠债”。", "浅": "浅（qiǎn，第三声）与 qián 声调不同，意思是“不深”。", "牵": "牵（qiān，第一声）与 qián 声调不同，意思是“牵引”。"}, "sentence_index": null, "correct_answer": "钱"}, "level_3": {"options": [{"text": "春天", "is_correct": false, "explanation": "语义：“我没有春天”不成立，春天不是可以拥有的东西。"}, {"text": "钱", "is_correct": true, "explanation": "“钱”指货币，“我没有钱”符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“我没有空气”不成立，空气不是可以拥有的东西，与句意不合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“没有”不与“价格”搭配，“价格”不表示可以拥有的东西。"}], "explanations": {"春天": "语义：“我没有春天”不成立，春天不是可以拥有的东西。", "钱": "“钱”指货币，“我没有钱”符合句意。", "空气": "语义：“我没有空气”不成立，空气不是可以拥有的东西，与句意不合。", "价格": "搭配：“没有”不与“价格”搭配，“价格”不表示可以拥有的东西。"}, "sentence_index": 0, "correct_answer": "钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想吃这笔钱，它看起来很好吃。", "explanation": "钱是用来买东西的货币，不能吃，这里应该说〈吃饭〉。"}, {"text": "这笔钱每天早上五点起床唱歌。", "explanation": "这里应该用〈歌手〉。钱是货币，不会起床唱歌，把它当人来写不符合词义，应说〈歌手〉。"}, {"text": "我住在一笔钱里，觉得很舒服。", "explanation": "钱是货币，不是可以居住的场所，这里应该说〈住在房子里〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24874, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "钱", "is_correct": true, "explanation": "“钱”读 qián（第二声），指买东西用的货币，即本词。"}, {"text": "签", "is_correct": false, "explanation": "签（qiān，第一声）与 qián（第二声）声调不同，意思是“签署”。"}, {"text": "歉", "is_correct": false, "explanation": "歉（qiàn，第四声）与 qián 声调不同，意思是“抱歉”。"}, {"text": "迁", "is_correct": false, "explanation": "迁（qiān，第一声）与 qián 声调不同，意思是“迁移”。"}], "explanations": {"钱": "“钱”读 qián（第二声），指买东西用的货币，即本词。", "签": "签（qiān，第一声）与 qián（第二声）声调不同，意思是“签署”。", "歉": "歉（qiàn，第四声）与 qián 声调不同，意思是“抱歉”。", "迁": "迁（qiān，第一声）与 qián 声调不同，意思是“迁移”。"}, "sentence_index": null, "correct_answer": "钱"}, "level_3": {"options": [{"text": "房子", "is_correct": false, "explanation": "语义：房子不能像钱一样被花掉，“花房子”不成立。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能被花掉，“很会花桌子”不成立。"}, {"text": "钱", "is_correct": true, "explanation": "“花钱”指支出钱财，与后文“每个月都不剩钱”呼应。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被花掉，与“很会花”不合。"}], "explanations": {"房子": "语义：房子不能像钱一样被花掉，“花房子”不成立。", "桌子": "语义：桌子不能被花掉，“很会花桌子”不成立。", "钱": "“花钱”指支出钱财，与后文“每个月都不剩钱”呼应。", "石头": "语义：石头不能被花掉，与“很会花”不合。"}, "sentence_index": 6, "correct_answer": "钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "为了买房子，他们把钱读完了。", "explanation": "这里应该用〈数〉。钱是用来买东西的货币，不能读，清点钱应说〈数〉。"}, {"text": "为了买房子，他们把钱浇了花。", "explanation": "“浇”只能用于水等液体，钱不能浇；这里应说〈花了钱〉。"}, {"text": "为了买房子，他们把钱种在了院子里。", "explanation": "这里应该用〈埋〉。“种”指播种或栽植，钱不能种下去，把钱藏进土里应说〈埋〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24874, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我身上还有一只钱。", "corrected_sentence": "我身上还有一块钱。", "error_description": "量词误用：「只」用于动物或成对器物中的一件，不能用来数钱，应改为「一块钱」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24874, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他存了一本钱。", "corrected_sentence": "他存了一笔钱。", "error_description": "量词误用：「本」用于书本，钱的数量要用「笔」，应改为「一笔钱」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64ca69b-64e3-4334-9155-6b7ad34fc6c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
