INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24876, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "价钱高，要花很多钱才能买到。", "primary_collocate": null, "pronunciation": "guì", "ipa": "kweɪ˥˩", "syllable_count": 1, "sentences": [{"text": "这件衣服太贵了。", "target_word": "贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京的房子很贵。", "target_word": "贵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个手机贵不贵？", "target_word": "贵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我不想买，因为太贵。", "target_word": "贵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家饭店的菜有点贵。", "target_word": "贵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "好看的鞋子常常比较贵。", "target_word": "贵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "苹果这个月比上个月贵。", "target_word": "贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水果在冬天会贵一点。", "target_word": "贵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买书不贵，但是买电脑很贵。", "target_word": "贵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "东西这么贵，我们别买了。", "target_word": "贵", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "贵了", "label": "体标"}], "register": "口语", "sense_fingerprint": "价钱高，要花很多钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a6c53470-eab2-4aaa-a8c7-536b79bbc5b7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24876, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "贵", "is_correct": true, "explanation": "贵：guì（第四声），意思是价钱高，要花很多钱才能买到。"}, {"text": "鬼", "is_correct": false, "explanation": "guǐ（第三声）与 guì（第四声）声调不同，意思是鬼。"}, {"text": "龟", "is_correct": false, "explanation": "guī（第一声）与 guì（第四声）声调不同，意思是乌龟。"}, {"text": "归", "is_correct": false, "explanation": "guī（第一声）与 guì（第四声）声调不同，意思是回来。"}, {"text": "会", "is_correct": false, "explanation": "huì（第四声）与 guì 声母不同，意思是会议或会见。"}, {"text": "规", "is_correct": false, "explanation": "guī（第一声）与 guì（第四声）声调不同，意思是规矩、规则。"}], "explanations": {"贵": "贵：guì（第四声），意思是价钱高，要花很多钱才能买到。", "鬼": "guǐ（第三声）与 guì（第四声）声调不同，意思是鬼。", "龟": "guī（第一声）与 guì（第四声）声调不同，意思是乌龟。", "归": "guī（第一声）与 guì（第四声）声调不同，意思是回来。", "会": "huì（第四声）与 guì 声母不同，意思是会议或会见。", "规": "guī（第一声）与 guì（第四声）声调不同，意思是规矩、规则。"}, "sentence_index": null, "correct_answer": "贵"}, "level_3": {"options": [{"text": "贵", "is_correct": true, "explanation": "贵指价钱高，要花很多钱才能买到，“太贵了”正好说衣服价格高。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说的是味道，不能用来形容衣服的价格。"}, {"text": "累", "is_correct": false, "explanation": "语义：“累”说的是人的状态，衣服不会累，句子说不通。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“远”用来说距离，不能用来形容衣服。"}], "explanations": {"贵": "贵指价钱高，要花很多钱才能买到，“太贵了”正好说衣服价格高。", "甜": "语义：“甜”说的是味道，不能用来形容衣服的价格。", "累": "语义：“累”说的是人的状态，衣服不会累，句子说不通。", "远": "搭配：“远”用来说距离，不能用来形容衣服。"}, "sentence_index": 0, "correct_answer": "贵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张老照片对我来说意义很贵。", "explanation": "这里应该用〈珍贵〉。贵指价钱高，说照片的情感价值要用“珍贵”，不能说“意义很贵”。"}, {"text": "他的品格很贵，大家都很佩服他。", "explanation": "这里应该用〈高贵〉。贵指价钱高，说人的品格要用“高贵”。"}, {"text": "这个人的脾气很贵。", "explanation": "这里应该用〈大〉。贵指价钱高，人的脾气程度要说“大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24876, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "贵", "is_correct": true, "explanation": "贵：guì（第四声），意思是价钱高，要花很多钱才能买到。"}, {"text": "愧", "is_correct": false, "explanation": "kuì（第四声）与 guì 声母不同，意思是惭愧。"}, {"text": "过", "is_correct": false, "explanation": "guò（第四声）与 guì 韵母不同，意思是经过。"}, {"text": "怪", "is_correct": false, "explanation": "guài（第四声）与 guì 韵母不同，意思是奇怪。"}, {"text": "挂", "is_correct": false, "explanation": "guà（第四声）与 guì 韵母不同，意思是挂起来。"}, {"text": "会", "is_correct": false, "explanation": "huì（第四声）与 guì 声母不同，意思是会议或会见。"}], "explanations": {"贵": "贵：guì（第四声），意思是价钱高，要花很多钱才能买到。", "愧": "kuì（第四声）与 guì 声母不同，意思是惭愧。", "过": "guò（第四声）与 guì 韵母不同，意思是经过。", "怪": "guài（第四声）与 guì 韵母不同，意思是奇怪。", "挂": "guà（第四声）与 guì 韵母不同，意思是挂起来。", "会": "huì（第四声）与 guì 声母不同，意思是会议或会见。"}, "sentence_index": null, "correct_answer": "贵"}, "level_3": {"options": [{"text": "贵", "is_correct": true, "explanation": "贵指价钱高，“比上个月贵”正好说苹果的价格涨了。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”说的是高矮，不能用来比较苹果的价格。"}, {"text": "清楚", "is_correct": false, "explanation": "搭配：“比……”后面要接表示高低的形容词，“清楚”不能用来比较价格。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”说的是人或动物的体形，不能用来形容苹果的价格。"}], "explanations": {"贵": "贵指价钱高，“比上个月贵”正好说苹果的价格涨了。", "矮": "语义：“矮”说的是高矮，不能用来比较苹果的价格。", "清楚": "搭配：“比……”后面要接表示高低的形容词，“清楚”不能用来比较价格。", "胖": "语义：“胖”说的是人或动物的体形，不能用来形容苹果的价格。"}, "sentence_index": 6, "correct_answer": "贵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试，他的成绩很贵。", "explanation": "这里应该用〈高〉。贵指价钱高，成绩的好坏要用“高”。"}, {"text": "老师的意见很贵，我们要认真听。", "explanation": "这里应该用〈宝贵〉。贵指价钱高，意见的价值要用“宝贵”。"}, {"text": "这份友谊很贵，我会一直珍惜。", "explanation": "这里应该用〈可贵〉。贵指价钱高，抽象的价值要用“可贵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24876, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件大衣比那件很贵三百块。", "corrected_sentence": "这件大衣比那件贵三百块。", "error_description": "错误形式：比那件很贵。正确形式：比那件贵。比字句中的形容词前不能加「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24876, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个包没贵，我买得起。", "corrected_sentence": "这个包不贵，我买得起。", "error_description": "错误形式是“没”，正确形式是“不”。否定形容词表示的状态要用“不”，不能用“没”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa29b907-5038-4975-9c83-47b668cb4b9b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24878, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "花钱", "is_correct": true, "explanation": "花钱与“赚钱”意思相反，指把钱用掉。"}, {"text": "读书", "is_correct": false, "explanation": "读书是学习或阅读，与“赚钱”没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是快速移动双脚，与“赚钱”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉是休息、入睡，与“赚钱”没有反义关系。"}], "correct_answer": "花钱", "explanations": {"花钱": "花钱与“赚钱”意思相反，指把钱用掉。", "读书": "读书是学习或阅读，与“赚钱”没有反义关系。", "跑步": "跑步是快速移动双脚，与“赚钱”没有反义关系。", "睡觉": "睡觉是休息、入睡，与“赚钱”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
