INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24878, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "赚钱就是做事情得到钱。", "primary_collocate": null, "pronunciation": "zhuàn qián", "ipa": "ʈʂwan˥˩ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "他每天很早起床去赚钱。", "target_word": "赚钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸为了赚钱，常常加班。", "target_word": "赚钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在网上卖衣服赚钱。", "target_word": "赚钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想暑假去打工赚钱。", "target_word": "赚钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意不一定能赚钱。", "target_word": "赚钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他赚钱很辛苦，所以不乱花钱。", "target_word": "赚钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人都想多赚钱买自己的房子。", "target_word": "赚钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开出租车赚钱养家。", "target_word": "赚钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥在大城市赚钱，每月寄给家里。", "target_word": "赚钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想靠父母，要自己赚钱。", "target_word": "赚钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "赚了钱", "label": "离合词扩展（了）"}, {"form": "赚过钱", "label": "离合词扩展（过）"}, {"form": "赚大钱", "label": "离合词扩展"}, {"form": "賺錢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "赚钱：动词，通过工作或做生意得到钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd4466d2-ac6f-4a40-a8e9-8cb0ae81f61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24878, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赚钱", "is_correct": true, "explanation": "“赚钱”是通过工作得到钱，“他每天很早起床去赚钱”搭配自然。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是身体不适，不能表示外出的目的，句意不通。"}, {"text": "买钱", "is_correct": false, "explanation": "搭配：“买”不跟“钱”搭配，不能说买钱。"}, {"text": "摔倒", "is_correct": false, "explanation": "语义：“摔倒”是意外跌倒，不是外出的目的，句意不通。"}], "explanations": {"赚钱": "“赚钱”是通过工作得到钱，“他每天很早起床去赚钱”搭配自然。", "生病": "语义：“生病”是身体不适，不能表示外出的目的，句意不通。", "买钱": "搭配：“买”不跟“钱”搭配，不能说买钱。", "摔倒": "语义：“摔倒”是意外跌倒，不是外出的目的，句意不通。"}, "sentence_index": 0, "correct_answer": "赚钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向银行赚了一笔钱。", "explanation": "这里应该用〈借〉。“赚钱”指靠劳动或经营得到钱，向银行得到钱要用“借”。"}, {"text": "他把一台电脑赚给了朋友。", "explanation": "这里应该用〈送〉。“赚”表示自己靠劳动或经营得到钱，不能表示把东西给别人，要用“送”。"}, {"text": "他向山区赚了一批衣服。", "explanation": "这里应该用〈捐〉。“赚”表示自己得到钱，把衣服给山区要用“捐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24878, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "赚钱", "is_correct": true, "explanation": "“赚钱”指靠劳动得到钱，“想多赚钱买自己的房子”搭配自然。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与买房子的手段无关，句意不通。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”不能表示买房子的手段，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“买房子”搭配来表示手段。"}], "explanations": {"赚钱": "“赚钱”指靠劳动得到钱，“想多赚钱买自己的房子”搭配自然。", "游泳": "语义：“游泳”与买房子的手段无关，句意不通。", "散步": "语义：“散步”不能表示买房子的手段，句意不通。", "吃": "搭配：“吃”不能与“买房子”搭配来表示手段。"}, "sentence_index": 6, "correct_answer": "赚钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天赚一场电影。", "explanation": "这里应该用〈看〉。“赚”指靠劳动或经营得到钱，看电影要用“看”，不能说赚电影。"}, {"text": "他每天赚一个电话。", "explanation": "这里应该用〈打〉。“赚”的对象是钱，打电话要用“打”，不能说赚电话。"}, {"text": "他每天赚一场比赛。", "explanation": "这里应该用〈打〉。“赚”指靠劳动或经营得到钱，比赛要用“打”，不能说赚比赛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24878, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个月赚钱了三千块钱。", "corrected_sentence": "他这个月赚了三千块钱。", "error_description": "错误形式“赚钱了三千块钱”，正确形式“赚了三千块钱”。“赚钱”是离合词，“钱”已在“三千块钱”中，“赚”后不能再加“钱”，应说“赚了三千块钱”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24878, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这个月赚钱得很多。", "corrected_sentence": "他这个月赚钱赚得很多。", "error_description": "错误形式“赚钱得很多”，正确形式“赚钱赚得很多”。程度补语“得很多”要紧跟动词“赚”，不能直接接在“赚钱”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
