INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24880, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指公司的主人或管你的人。", "primary_collocate": null, "pronunciation": "lǎo bǎn", "ipa": "lau̯˨˩˦ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的老板人很好。", "target_word": "老板", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板今天不在公司。", "target_word": "老板", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家饭馆的老板是我朋友。", "target_word": "老板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板请大家吃了午饭。", "target_word": "老板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想跟老板请一天假。", "target_word": "老板", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板说下个月要给大家加工资。", "target_word": "老板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市老板每天很早就来开门。", "target_word": "老板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王工作很努力，老板常常夸他。", "target_word": "老板", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板正看着电脑，没有听到我说话。", "target_word": "老板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我去买水果，老板多送了我两个苹果。", "target_word": "老板", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "老板娘", "label": "复合词"}, {"form": "老板们", "label": "复数形式"}], "register": "口语", "sense_fingerprint": "公司或店铺的主人，或管理员工的上司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed69058d-24aa-4c07-bc40-36884250d128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24880, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "老板", "is_correct": true, "explanation": "正确答案：老板（lǎo bǎn）指公司或店铺的主人"}, {"text": "老伴", "is_correct": false, "explanation": "bàn（第四声）与 bǎn（第三声）声调不同，意思是配偶"}, {"text": "老班", "is_correct": false, "explanation": "bān（第一声）与 bǎn（第三声）声调不同，意思是班主任"}, {"text": "老本", "is_correct": false, "explanation": "běn 与 bǎn 韵母不同（en 与 an），意思是本钱、积蓄"}], "explanations": {"老板": "正确答案：老板（lǎo bǎn）指公司或店铺的主人", "老伴": "bàn（第四声）与 bǎn（第三声）声调不同，意思是配偶", "老班": "bān（第一声）与 bǎn（第三声）声调不同，意思是班主任", "老本": "běn 与 bǎn 韵母不同（en 与 an），意思是本钱、积蓄"}, "sentence_index": null, "correct_answer": "老板"}, "level_3": {"options": [{"text": "老虎", "is_correct": false, "explanation": "语义：老虎是动物，不能说“我的老虎人很好”"}, {"text": "老板", "is_correct": true, "explanation": "正确答案：老板指公司或店铺的主人，是人，可以说“人很好”"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，没有“人”，不能说人很好"}, {"text": "房子", "is_correct": false, "explanation": "搭配：房子不能作“人很好”的主语，搭配不当"}], "explanations": {"老虎": "语义：老虎是动物，不能说“我的老虎人很好”", "老板": "正确答案：老板指公司或店铺的主人，是人，可以说“人很好”", "手机": "语义：手机是物品，没有“人”，不能说人很好", "房子": "搭配：房子不能作“人很好”的主语，搭配不当"}, "sentence_index": 0, "correct_answer": "老板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位老板每天给我们上语文课。", "explanation": "这里应该用〈老师〉。老板指公司或店铺的主人，给学生上课的人要称老师"}, {"text": "我们班的老板都很努力。", "explanation": "这里应该用〈学生〉。老板指经营者或上司，班里的同学应称学生"}, {"text": "这本书的老板很多。", "explanation": "这里应该用〈读者〉。老板指管理者，阅读这本书的人要称读者"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24880, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演员", "is_correct": false, "explanation": "语义：演员不负责超市开门，句意不通"}, {"text": "老板", "is_correct": true, "explanation": "正确答案：老板是超市的主人或负责人，会每天早来开门"}, {"text": "钟表", "is_correct": false, "explanation": "搭配：钟表不能自己来开门，搭配不当"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物不能负责超市开门，与句意不符"}], "explanations": {"演员": "语义：演员不负责超市开门，句意不通", "老板": "正确答案：老板是超市的主人或负责人，会每天早来开门", "钟表": "搭配：钟表不能自己来开门，搭配不当", "宠物": "语义：宠物不能负责超市开门，与句意不符"}, "sentence_index": 6, "correct_answer": "老板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板住在紫禁城里。", "explanation": "这里应该用〈皇帝〉。老板是口语词，指公司或店铺的主人，古代帝王不能称老板"}, {"text": "老板们守卫着边境。", "explanation": "这里应该用〈战士〉。老板指经营者，守卫边境的应是战士"}, {"text": "老板向路人乞讨。", "explanation": "这里应该用〈乞丐〉。老板指经营者，向路人乞讨的人应称乞丐"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24880, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只老板走进了办公室。", "corrected_sentence": "一位老板走进了办公室。", "error_description": "错误：“一只老板”；正确：“一位老板”。“只”用于动物，指人的“老板”要用“位”或“个”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24880, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几位老板们来参加了会议。", "corrected_sentence": "几位老板来参加了会议。", "error_description": "错误：“几位……老板们”；正确：“几位老板”。有数词和量词时不再加“们”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b40bdfe4-ba79-4ecd-b88f-4c9a825bd20a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
