INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24882, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "心里想要买下这个东西。", "primary_collocate": null, "pronunciation": "xiǎng mǎi", "ipa": "ɕjɑŋ˨˩˦ maɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想买一杯热咖啡。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着那双鞋，心里想买。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师想买几本中文书。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们想买一台新电视。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想买一件送给妈妈的礼物。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我昨天就想买了，可是商店关门了。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是不是想买这个包？", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥想买一只小狗。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一张去北京的票。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直想买一辆红色的车。", "target_word": "想买", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "想买了", "label": "体标"}, {"form": "想买过", "label": "体标"}, {"form": "不想买", "label": "否定"}], "register": "中性", "sense_fingerprint": "心里想要买下某个具体东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9396a7ad-604e-4eae-9004-ebab4a4f74bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24882, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "想买", "is_correct": true, "explanation": "正确。“我想买一杯热咖啡”，表示心里想要购买。"}, {"text": "想洗", "is_correct": false, "explanation": "搭配：“洗”的对象不能是一杯咖啡，咖啡应是喝的。"}, {"text": "想拆", "is_correct": false, "explanation": "语义：咖啡是饮品，不能被拆开，与句子的语境不符。"}, {"text": "想听", "is_correct": false, "explanation": "语义：咖啡不能被“听”，这个动词与饮品无关。"}], "explanations": {"想买": "正确。“我想买一杯热咖啡”，表示心里想要购买。", "想洗": "搭配：“洗”的对象不能是一杯咖啡，咖啡应是喝的。", "想拆": "语义：咖啡是饮品，不能被拆开，与句子的语境不符。", "想听": "语义：咖啡不能被“听”，这个动词与饮品无关。"}, "sentence_index": 0, "correct_answer": "想买"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想买昨天。", "explanation": "“昨天”是过去的时间，不能用钱买，“买”的对象应是商品。"}, {"text": "他想买一片海。", "explanation": "海是自然景物，不能用钱买，“买”的对象应是商品。"}, {"text": "妈妈想买一场雨。", "explanation": "雨是天气现象，不能购买，“买”不能用于天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24882, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "想买", "is_correct": true, "explanation": "正确。“你是不是想买这个包”，表示心里想要购买这个包。"}, {"text": "想喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮料，不能说“喝这个包”。"}, {"text": "想听", "is_correct": false, "explanation": "语义：包不能被“听”，“听”的对象是声音。"}, {"text": "想读", "is_correct": false, "explanation": "搭配：“读”的对象是书、文章，不能说“读这个包”。"}], "explanations": {"想买": "正确。“你是不是想买这个包”，表示心里想要购买这个包。", "想喝": "搭配：“喝”的对象是饮料，不能说“喝这个包”。", "想听": "语义：包不能被“听”，“听”的对象是声音。", "想读": "搭配：“读”的对象是书、文章，不能说“读这个包”。"}, "sentence_index": 6, "correct_answer": "想买"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想买天上的太阳。", "explanation": "太阳是天体，不能用钱买，“买”的对象应是商品。"}, {"text": "我们想买一句谢谢。", "explanation": "“谢谢”是言语，不是可以交易的商品，不能用“买”。"}, {"text": "老师想买那个月亮。", "explanation": "月亮是天体，不能用钱买，“买”的对象应是商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24882, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哥哥把想买一块手表。", "corrected_sentence": "哥哥想买一块手表。", "error_description": "错误：多了“把”。“把”字句需要处置对象，“想买”前不能直接加“把”，应说“哥哥想买一块手表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
