INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24884, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近", "is_correct": true, "explanation": "正确：“近”与“很远”构成反义，都用来说两地之间的距离。"}, {"text": "高", "is_correct": false, "explanation": "“高”说高度，与“远”不构成反义关系，不能用来描述距离。"}, {"text": "大", "is_correct": false, "explanation": "“大”说体积或范围，与距离的远近没有反义关系。"}, {"text": "快", "is_correct": false, "explanation": "“快”说速度，与距离的远近没有反义关系。"}], "correct_answer": "近", "explanations": {"近": "正确：“近”与“很远”构成反义，都用来说两地之间的距离。", "高": "“高”说高度，与“远”不构成反义关系，不能用来描述距离。", "大": "“大”说体积或范围，与距离的远近没有反义关系。", "快": "“快”说速度，与距离的远近没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24884, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近", "is_correct": true, "explanation": "正确：“近”与“很远”构成反义，都用来说两地之间的距离。"}, {"text": "深", "is_correct": false, "explanation": "“深”说深浅，与距离的远近没有反义关系。"}, {"text": "重", "is_correct": false, "explanation": "“重”说重量，与距离的远近没有反义关系。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”说速度，与距离的远近没有反义关系。"}], "correct_answer": "近", "explanations": {"近": "正确：“近”与“很远”构成反义，都用来说两地之间的距离。", "深": "“深”说深浅，与距离的远近没有反义关系。", "重": "“重”说重量，与距离的远近没有反义关系。", "慢": "“慢”说速度，与距离的远近没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24884, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很远是说两个东西中间隔了很多路。", "primary_collocate": null, "pronunciation": "hěn yuǎn", "ipa": "xən˨˩ ɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家离学校很远。", "target_word": "很远", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个地方很远。", "target_word": "很远", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "从这儿到北京很远。", "target_word": "很远", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他住得很远。", "target_word": "很远", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校离我家不是很远。", "target_word": "很远", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "机场离城市很远，要坐一个小时车。", "target_word": "很远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "太阳离地球很远。", "target_word": "很远", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "虽然他家很远，但是他每天都来。", "target_word": "很远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的老家很远，坐火车要两天。", "target_word": "很远", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家超市离我们很远，我们去那家吧。", "target_word": "很远", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "两地之间的距离很长", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7dd17ffc-a76b-42f7-bbad-b8985cc3d540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24884, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "很远", "is_correct": true, "explanation": "正确：很远，hěn yuǎn，意思是两个东西中间隔了很多路。"}, {"text": "很圆", "is_correct": false, "explanation": "yuán（第二声）与 yuǎn（第三声）声调不同，很圆的意思是非常圆，与距离无关。"}, {"text": "很冤", "is_correct": false, "explanation": "yuān（第一声）与 yuǎn（第三声）声调不同，很冤的意思是非常冤枉。"}, {"text": "很怨", "is_correct": false, "explanation": "yuàn（第四声）与 yuǎn（第三声）声调不同，很怨的意思是非常怨恨。"}], "explanations": {"很远": "正确：很远，hěn yuǎn，意思是两个东西中间隔了很多路。", "很圆": "yuán（第二声）与 yuǎn（第三声）声调不同，很圆的意思是非常圆，与距离无关。", "很冤": "yuān（第一声）与 yuǎn（第三声）声调不同，很冤的意思是非常冤枉。", "很怨": "yuàn（第四声）与 yuǎn（第三声）声调不同，很怨的意思是非常怨恨。"}, "sentence_index": null, "correct_answer": "很远"}, "level_3": {"options": [{"text": "很远", "is_correct": true, "explanation": "正确：“我家离学校很远”中，“很远”说明两地距离长，是唯一合适的说法。"}, {"text": "很高", "is_correct": false, "explanation": "语义：“高”说的是高度，不能用来说两地之间的距离。"}, {"text": "很大", "is_correct": false, "explanation": "搭配：“大”说体积或范围，不能说“离学校很大”。"}, {"text": "很贵", "is_correct": false, "explanation": "语义：“贵”说价格，与两地之间的距离无关。"}], "explanations": {"很远": "正确：“我家离学校很远”中，“很远”说明两地距离长，是唯一合适的说法。", "很高": "语义：“高”说的是高度，不能用来说两地之间的距离。", "很大": "搭配：“大”说体积或范围，不能说“离学校很大”。", "很贵": "语义：“贵”说价格，与两地之间的距离无关。"}, "sentence_index": 0, "correct_answer": "很远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜做得很远。", "explanation": "这里应该用〈很好〉。很远说空间距离，形容做菜的水平要用很好。"}, {"text": "他的汉语说得很远。", "explanation": "这里应该用〈很流利〉。很远说空间距离，形容说话的水平要用很流利。"}, {"text": "这件衣服很远。", "explanation": "这里应该用〈很漂亮〉。很远说空间距离，形容衣服好看要用很漂亮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24884, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很远", "is_correct": true, "explanation": "正确：“太阳离地球很远”中，“很远”表示两者之间距离长。"}, {"text": "很亮", "is_correct": false, "explanation": "语义：“亮”说光线明暗，不能用来说天体之间的距离。"}, {"text": "很重", "is_correct": false, "explanation": "搭配：“重”说重量，不能说“离地球很重”。"}, {"text": "很甜", "is_correct": false, "explanation": "语义：“甜”说味道，与距离毫无关系。"}], "explanations": {"很远": "正确：“太阳离地球很远”中，“很远”表示两者之间距离长。", "很亮": "语义：“亮”说光线明暗，不能用来说天体之间的距离。", "很重": "搭配：“重”说重量，不能说“离地球很重”。", "很甜": "语义：“甜”说味道，与距离毫无关系。"}, "sentence_index": 6, "correct_answer": "很远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影很远。", "explanation": "这里应该用〈很好看〉。“很远”说空间距离，形容电影好看要用“很好看”。"}, {"text": "这个孩子长得很远。", "explanation": "这里应该用〈很高〉。很远说空间距离，形容身高要用很高。"}, {"text": "他的字写得很远。", "explanation": "这里应该用〈很工整〉。“很远”说空间距离，形容字写得好要用“很工整”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24884, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹住得很很远。", "corrected_sentence": "我妹妹住得很远。", "error_description": "错误形式：很很远；正确形式：很远。“很”已经修饰“远”，不能重复叠加一个“很”，应去掉多余的“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24884, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我姐姐住得很远很。", "corrected_sentence": "我姐姐住得很远。", "error_description": "错误形式：句末多出一个“很”；正确形式：“住得很远”。“很”只能修饰“远”，不能在“远”之后单独出现，应去掉句末的“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9322487-61c7-4266-a918-2c333c598f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
