INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24886, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把问题处理好，让它不再有麻烦。", "primary_collocate": null, "pronunciation": "jiě jué", "ipa": "tɕjɛ˨˩˦ tɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "我们一起解决这个问题。", "target_word": "解决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮我解决了难题。", "target_word": "解决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个麻烦很快就解决了。", "target_word": "解决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想办法解决水电问题。", "target_word": "解决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你自己能解决吗？", "target_word": "解决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "问题还没有解决，大家别走。", "target_word": "解决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用两天解决了所有麻烦。", "target_word": "解决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络坏了，请你帮忙解决一下。", "target_word": "解决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想先解决钱的问题。", "target_word": "解决", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理把问题解决了。", "target_word": "解决", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解决了", "label": "体标"}, {"form": "解决过", "label": "体标"}, {"form": "解决方案", "label": "复合"}, {"form": "解決", "label": "繁体"}], "register": "中性", "sense_fingerprint": "处理问题或麻烦，使其不再存在", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '810ac7fa-1260-4d9e-be13-37017ce45fe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解决", "is_correct": true, "explanation": "正确：「解决这个问题」指把问题处理掉，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：问题不能被吃，「一起吃这个问题」语义不通。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：「煮」不与「问题」搭配，不能说煮问题。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：「擦」不与「问题」搭配，不能说擦问题。"}], "explanations": {"解决": "正确：「解决这个问题」指把问题处理掉，符合句意。", "吃": "语义：问题不能被吃，「一起吃这个问题」语义不通。", "煮": "搭配：「煮」不与「问题」搭配，不能说煮问题。", "擦": "搭配：「擦」不与「问题」搭配，不能说擦问题。"}, "sentence_index": 0, "correct_answer": "解决"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师很快解决了这支铅笔。", "explanation": "这里应该用〈削〉。「解决」用于问题或麻烦，削铅笔要用「削」。"}, {"text": "他慢慢解决了绳子。", "explanation": "这里应该用〈解开〉。「解开」指打开绳结，「解决」用于问题或麻烦。"}, {"text": "医生解决了这只青蛙的变化。", "explanation": "这里应该用〈研究〉。「解决」用于问题或麻烦，观察、研究生物的变化要用「研究」，不说「解决变化」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解决", "is_correct": true, "explanation": "正确：「用两天解决了所有麻烦」指用时间处理掉麻烦，符合句意。"}, {"text": "喝", "is_correct": false, "explanation": "语义：麻烦不能被喝，「用两天喝了所有麻烦」语义不通。"}, {"text": "织", "is_correct": false, "explanation": "搭配：「织」不与「麻烦」搭配，不能说织麻烦。"}, {"text": "挖", "is_correct": false, "explanation": "搭配：「挖」不与「麻烦」搭配，不能说挖麻烦。"}], "explanations": {"解决": "正确：「用两天解决了所有麻烦」指用时间处理掉麻烦，符合句意。", "喝": "语义：麻烦不能被喝，「用两天喝了所有麻烦」语义不通。", "织": "搭配：「织」不与「麻烦」搭配，不能说织麻烦。", "挖": "搭配：「挖」不与「麻烦」搭配，不能说挖麻烦。"}, "sentence_index": 6, "correct_answer": "解决"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "军队终于解决了这座城市。", "explanation": "这里应该用〈解放〉。「解放」指推翻压迫、获得自由，用于地区或人民；「解决」用于问题。"}, {"text": "校长解决了全体学生。", "explanation": "这里应该用〈解散〉。「解散」指让集体离开，「解决」不能用于人群。"}, {"text": "她很快解决了那只手，我们都笑了。", "explanation": "这里应该用〈握〉。「解决」用于问题或麻烦，握手要用「握」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个问题他解决很快。", "corrected_sentence": "这个问题他解决得很快。", "error_description": "补语错误：表示动作程度的补语前要加「得」，应说「解决得很快」，不能说「解决很快」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个问题我们以前解决了过。", "corrected_sentence": "这个问题我们以前解决过。", "error_description": "体标冲突：表示经历的「过」与「了」不能同时用在「解决」后，应说「解决过」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
