INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24888, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "种菜的地方，可以长出青菜和萝卜。", "primary_collocate": null, "pronunciation": "cài dì", "ipa": "tsʰaɪ̯˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "菜地里有青菜，也有白萝卜。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶的菜地在山下，走路要十分钟。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块菜地今年种了萝卜。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友在学校的菜地里学种菜。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想在院子里开一块菜地。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天到了，菜地里一片绿。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们每天给菜地浇水，菜长得很快。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜地里的萝卜已经可以吃了。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜地边上有几只鸡在找虫子吃。", "target_word": "菜地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸用小车把水送到菜地里。", "target_word": "菜地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块菜地", "label": "量词（块）"}, {"form": "一片菜地", "label": "量词（片）"}], "register": "中性", "sense_fingerprint": "种青菜、萝卜的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9396a7ad-604e-4eae-9004-ebab4a4f74bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24888, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "菜地", "is_correct": true, "explanation": "正确答案：菜地，种着青菜和萝卜，与“有青菜，也有白萝卜”相符。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架用来放书，不长青菜和萝卜，与句子不相符。"}, {"text": "鱼缸", "is_correct": false, "explanation": "语义：鱼缸用来养鱼，不种青菜和萝卜，句意冲突。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“操场”是运动场地，“操场里有青菜”不成立，不能与“有青菜”搭配。"}], "explanations": {"菜地": "正确答案：菜地，种着青菜和萝卜，与“有青菜，也有白萝卜”相符。", "书架": "语义：书架用来放书，不长青菜和萝卜，与句子不相符。", "鱼缸": "语义：鱼缸用来养鱼，不种青菜和萝卜，句意冲突。", "操场": "搭配：“操场”是运动场地，“操场里有青菜”不成立，不能与“有青菜”搭配。"}, "sentence_index": 0, "correct_answer": "菜地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶今天买了两斤菜地。", "explanation": "这里应该用〈萝卜〉。菜地是土地，不能按斤称重买卖，买的是萝卜。"}, {"text": "院子门口有一块菜地在叫。", "explanation": "这里应该用〈小狗〉。菜地是种菜的土地，不会叫，会叫的是小狗。"}, {"text": "这块菜地很甜。", "explanation": "这里应该用〈西瓜〉。菜地是种菜的土地，不能用“甜”来形容，甜的是西瓜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24888, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "菜地", "is_correct": true, "explanation": "正确答案：菜地，是需要浇水的土地，与“菜长得很快”相关。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不需要浇水，句子说的是给土地或植物浇水。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油是液体燃料，不需要“给汽油浇水”，也不会长出菜。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不需要浇水，浇水也不会让它长得快。"}], "explanations": {"菜地": "正确答案：菜地，是需要浇水的土地，与“菜长得很快”相关。", "书本": "语义：书本不需要浇水，句子说的是给土地或植物浇水。", "汽油": "语义：汽油是液体燃料，不需要“给汽油浇水”，也不会长出菜。", "桌子": "语义：桌子不需要浇水，浇水也不会让它长得快。"}, "sentence_index": 6, "correct_answer": "菜地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们一家人去菜地看电影。", "explanation": "这里应该用〈电影院〉。菜地是种菜的土地，不能放映电影，看电影要去电影院。"}, {"text": "爸爸把菜地装进了卡车。", "explanation": "这里应该用〈青菜〉。菜地是土地，不能装进卡车，装的是青菜。"}, {"text": "妈妈按照菜地做了一道菜。", "explanation": "这里应该用〈菜谱〉。菜地是种菜的地，做菜要按菜谱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24888, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子后面有一座菜地。", "corrected_sentence": "院子后面有一块菜地。", "error_description": "量词用错：“菜地”应说“一块菜地”，不能说“一座菜地”。“座”用于山、房屋等大型固定的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24888, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔叔的一张菜地在河边。", "corrected_sentence": "叔叔的一块菜地在河边。", "error_description": "量词用错：“菜地”应说“一块菜地”，不能说“一张菜地”。“张”用于纸、桌子等扁平的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '262058fb-ffae-436a-9afa-628a922d9e2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
