INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24890, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西放到嘴里，嚼一嚼，然后咽下去。", "primary_collocate": null, "pronunciation": "chī", "ipa": "ʈʂʰɨ˥", "syllable_count": 1, "sentences": [{"text": "我早上吃面包和鸡蛋。", "target_word": "吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不喜欢吃青菜。", "target_word": "吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃了两碗米饭。", "target_word": "吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没吃过这种水果。", "target_word": "吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈做的饺子，大家都爱吃。", "target_word": "吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一边走一边吃着苹果。", "target_word": "吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想吃什么？我请客。", "target_word": "吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中午我们去学校外面吃面条。", "target_word": "吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先洗手，再吃东西。", "target_word": "吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那块蛋糕吃完了。", "target_word": "吃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吃了", "label": "体标"}, {"form": "吃过", "label": "体标"}, {"form": "吃着", "label": "体标"}, {"form": "吃饭", "label": "复合"}], "register": "中性", "sense_fingerprint": "把食物放进嘴里嚼后咽下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f9422c-71d5-4159-b92d-1d18b93b36af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24890, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吃", "is_correct": true, "explanation": "正确：“吃”指把食物放进嘴里咽下，即本词的读音。"}, {"text": "迟", "is_correct": false, "explanation": "chí（第二声）与 chī（第一声）声调不同，意思是迟到的“迟”。"}, {"text": "齿", "is_correct": false, "explanation": "chǐ（第三声）与 chī（第一声）声调不同，意思是牙齿的“齿”。"}, {"text": "湿", "is_correct": false, "explanation": "shī 与 chī 声母不同（sh 与 ch），意思是湿润的“湿”。"}, {"text": "知", "is_correct": false, "explanation": "zhī 与 chī 声母不同（zh 与 ch），意思是知道的“知”。"}, {"text": "翅", "is_correct": false, "explanation": "chì（第四声）与 chī（第一声）声调不同，意思是翅膀的“翅”。"}], "explanations": {"吃": "正确：“吃”指把食物放进嘴里咽下，即本词的读音。", "迟": "chí（第二声）与 chī（第一声）声调不同，意思是迟到的“迟”。", "齿": "chǐ（第三声）与 chī（第一声）声调不同，意思是牙齿的“齿”。", "湿": "shī 与 chī 声母不同（sh 与 ch），意思是湿润的“湿”。", "知": "zhī 与 chī 声母不同（zh 与 ch），意思是知道的“知”。", "翅": "chì（第四声）与 chī（第一声）声调不同，意思是翅膀的“翅”。"}, "sentence_index": null, "correct_answer": "吃"}, "level_3": {"options": [{"text": "吃", "is_correct": true, "explanation": "正确：“吃”指把食物放进嘴里咽下，“我早上吃面包和鸡蛋”成立。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语是饮料，面包和鸡蛋不能喝。"}, {"text": "穿", "is_correct": false, "explanation": "配价：“穿”的宾语是衣物，面包和鸡蛋不能穿。"}, {"text": "戴", "is_correct": false, "explanation": "配价：“戴”的宾语是帽子、眼镜等，面包和鸡蛋不能戴。"}], "explanations": {"吃": "正确：“吃”指把食物放进嘴里咽下，“我早上吃面包和鸡蛋”成立。", "喝": "搭配：“喝”的宾语是饮料，面包和鸡蛋不能喝。", "穿": "配价：“穿”的宾语是衣物，面包和鸡蛋不能穿。", "戴": "配价：“戴”的宾语是帽子、眼镜等，面包和鸡蛋不能戴。"}, "sentence_index": 0, "correct_answer": "吃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上吃一杯牛奶。", "explanation": "这里应该用〈喝〉。牛奶是液体，要说喝，不说吃。"}, {"text": "他每天早上吃一首歌，心情很好。", "explanation": "这里应该用〈听〉。歌曲要说听，不能说吃。"}, {"text": "他每天早上吃一封信，然后去上班。", "explanation": "这里应该用〈读〉。信要说读，不说吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24890, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吃", "is_correct": true, "explanation": "正确：“吃”指把食物放进嘴里咽下，即本词的读音。"}, {"text": "池", "is_correct": false, "explanation": "chí（第二声）与 chī（第一声）声调不同，意思是池塘的“池”。"}, {"text": "尺", "is_correct": false, "explanation": "chǐ（第三声）与 chī（第一声）声调不同，意思是尺子的“尺”。"}, {"text": "狮", "is_correct": false, "explanation": "shī 与 chī 声母不同（sh 与 ch），意思是狮子的“狮”。"}, {"text": "织", "is_correct": false, "explanation": "zhī 与 chī 声母不同（zh 与 ch），意思是编织的“织”。"}, {"text": "持", "is_correct": false, "explanation": "chí（第二声）与 chī（第一声）声调不同，意思是坚持的“持”。"}], "explanations": {"吃": "正确：“吃”指把食物放进嘴里咽下，即本词的读音。", "池": "chí（第二声）与 chī（第一声）声调不同，意思是池塘的“池”。", "尺": "chǐ（第三声）与 chī（第一声）声调不同，意思是尺子的“尺”。", "狮": "shī 与 chī 声母不同（sh 与 ch），意思是狮子的“狮”。", "织": "zhī 与 chī 声母不同（zh 与 ch），意思是编织的“织”。", "持": "chí（第二声）与 chī（第一声）声调不同，意思是坚持的“持”。"}, "sentence_index": null, "correct_answer": "吃"}, "level_3": {"options": [{"text": "吃", "is_correct": true, "explanation": "正确：“吃”指把食物咽下，“你想吃什么？我请客”成立。"}, {"text": "住", "is_correct": false, "explanation": "配价：“住”的宾语是住所，不能接“什么”指食物。"}, {"text": "坐", "is_correct": false, "explanation": "配价：“坐”的宾语是座位或交通工具，不能指食物。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”指清洁，与“请客”的饮食语境不合。"}], "explanations": {"吃": "正确：“吃”指把食物咽下，“你想吃什么？我请客”成立。", "住": "配价：“住”的宾语是住所，不能接“什么”指食物。", "坐": "配价：“坐”的宾语是座位或交通工具，不能指食物。", "洗": "语义：“洗”指清洁，与“请客”的饮食语境不合。"}, "sentence_index": 6, "correct_answer": "吃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天在书房里吃报纸。", "explanation": "这里应该用〈读〉。报纸要说读，不说吃。"}, {"text": "他把那本书吃在桌子上。", "explanation": "这里应该用〈放〉。把东西放在某处要说放，吃没有放置的意思。"}, {"text": "他每天早上吃衣服，然后去上班。", "explanation": "这里应该用〈穿〉。衣服要说穿，不说吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他吃着了苹果看电视。", "corrected_sentence": "他吃着苹果看电视。", "error_description": "体标错误：“着”与“了”不能同时用在“吃”后。表示一边吃一边做别的事，只说“吃着苹果”，不能说“吃着了苹果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他吃很饱，一点也没剩。", "corrected_sentence": "他吃得很饱，一点也没剩。", "error_description": "状态补语错误：“吃”后接“很饱”要用“得”，应说“吃得很饱”，不能说“吃很饱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
