INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24893, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "蔬菜是我们可以吃的植物，比如白菜、萝卜。", "primary_collocate": null, "pronunciation": "shū cài", "ipa": "ʂu˥ tsʰaɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢吃蔬菜。", "target_word": "蔬菜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈在市场买了很多蔬菜。", "target_word": "蔬菜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多吃蔬菜对身体好。", "target_word": "蔬菜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的蔬菜很新鲜。", "target_word": "蔬菜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "白菜和萝卜都是蔬菜。", "target_word": "蔬菜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷在院子里种了一些蔬菜。", "target_word": "蔬菜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子不爱吃蔬菜，妈妈很担心。", "target_word": "蔬菜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我先洗蔬菜，然后用刀切开。", "target_word": "蔬菜", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天的蔬菜比夏天的贵。", "target_word": "蔬菜", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "吃饭时要有肉，也要有蔬菜。", "target_word": "蔬菜", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "份", "label": "量词"}, {"form": "蔬菜汤", "label": "复合"}, {"form": "蔬菜沙拉", "label": "复合"}], "register": "中性", "sense_fingerprint": "蔬菜：可以吃的菜类植物，如白菜、萝卜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffce3848-4e7c-4ec3-885e-673579ba7e56') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24893, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蔬菜", "is_correct": true, "explanation": "正确：“蔬菜”（shū cài）指可以吃的菜类植物。"}, {"text": "出菜", "is_correct": false, "explanation": "chū 与 shū 只有声母不同（ch 与 sh），出菜指上菜。"}, {"text": "苏菜", "is_correct": false, "explanation": "sū（第一声）与 shū 声母不同（s/sh），意思是江苏菜。"}, {"text": "熟菜", "is_correct": false, "explanation": "shú（第二声）与 shū 声调不同，意思是熟食。"}, {"text": "蜀菜", "is_correct": false, "explanation": "shǔ（第三声）与 shū 只有声调不同，蜀菜指四川菜。"}], "explanations": {"蔬菜": "正确：“蔬菜”（shū cài）指可以吃的菜类植物。", "出菜": "chū 与 shū 只有声母不同（ch 与 sh），出菜指上菜。", "苏菜": "sū（第一声）与 shū 声母不同（s/sh），意思是江苏菜。", "熟菜": "shú（第二声）与 shū 声调不同，意思是熟食。", "蜀菜": "shǔ（第三声）与 shū 只有声调不同，蜀菜指四川菜。"}, "sentence_index": null, "correct_answer": "蔬菜"}, "level_3": {"options": [{"text": "蔬菜", "is_correct": true, "explanation": "正确：“蔬菜”是可以吃的植物，与动词“吃”搭配，符合句意。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说吃汽车。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是食物，与“喜欢吃”的句意不符。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“报纸”是用来读的，不能说吃报纸。"}], "explanations": {"蔬菜": "正确：“蔬菜”是可以吃的植物，与动词“吃”搭配，符合句意。", "汽车": "搭配：“吃”的宾语应是食物，不能说吃汽车。", "电脑": "语义：电脑不是食物，与“喜欢吃”的句意不符。", "报纸": "搭配：“报纸”是用来读的，不能说吃报纸。"}, "sentence_index": 0, "correct_answer": "蔬菜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只蔬菜。", "explanation": "这里应该用〈种〉或〈把〉。“只”多用于动物或成对物品中的一个，不能用来计量蔬菜。"}, {"text": "我买了一张蔬菜。", "explanation": "这里应该用〈种〉。“张”用于纸、桌子等扁平的东西，蔬菜不能用“张”计量。"}, {"text": "我买了一副蔬菜。", "explanation": "这里应该用〈种〉。“副”用于成套或成对的物品，蔬菜不能用“副”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24893, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "蔬菜", "is_correct": true, "explanation": "正确：“蔬菜”是可以吃的食物，与“不爱吃”搭配，符合句意。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“吃”不能和乐器搭配，不能说吃钢琴。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是电器，不是食物，与“不爱吃”的句意不符。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“吃”的宾语不能是家具，不能说吃椅子。"}], "explanations": {"蔬菜": "正确：“蔬菜”是可以吃的食物，与“不爱吃”搭配，符合句意。", "钢琴": "搭配：“吃”不能和乐器搭配，不能说吃钢琴。", "冰箱": "语义：冰箱是电器，不是食物，与“不爱吃”的句意不符。", "椅子": "搭配：“吃”的宾语不能是家具，不能说吃椅子。"}, "sentence_index": 6, "correct_answer": "蔬菜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一条蔬菜。", "explanation": "这里应该用〈种〉或〈把〉。“条”用于细长的东西，蔬菜不能用“条”计量。"}, {"text": "我买了一座蔬菜。", "explanation": "这里应该用〈种〉。“座”用于山、桥、房屋等大型物体，不能用来计量蔬菜。"}, {"text": "我买了一本蔬菜。", "explanation": "这里应该用〈种〉。“本”用于书、本子等，蔬菜不能用“本”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天吃了很多蔬菜们。", "corrected_sentence": "我昨天吃了很多蔬菜。", "error_description": "错误：“们”只用于指人的名词，“蔬菜”后面不能加“们”，而且前面已有“很多”表示数量。正确：“我昨天吃了很多蔬菜。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我吃了很蔬菜。", "corrected_sentence": "我吃了很多蔬菜。", "error_description": "修饰语错误：“很”是程度副词，不能直接修饰名词“蔬菜”，表示数量要用“很多”，应为“我吃了很多蔬菜”，不能说“我吃了很蔬菜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad60c45b-4ca7-40b4-bf0c-f205e95e64b0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24896, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆", "is_correct": true, "explanation": "拆与“建”（修造）意思相反，指把建好的东西拆掉。"}, {"text": "跑", "is_correct": false, "explanation": "跑是跑步、奔跑，与“建”没有反义关系。"}, {"text": "哭", "is_correct": false, "explanation": "哭是流泪、出声，与“建”没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "笑是高兴时的表情或声音，与“建”没有反义关系。"}], "correct_answer": "拆", "explanations": {"拆": "拆与“建”（修造）意思相反，指把建好的东西拆掉。", "跑": "跑是跑步、奔跑，与“建”没有反义关系。", "哭": "哭是流泪、出声，与“建”没有反义关系。", "笑": "笑是高兴时的表情或声音，与“建”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
