INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24896, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "修造房子、桥、路等。", "primary_collocate": null, "pronunciation": "jiàn", "ipa": "tɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "他们打算在河上建一座新桥。", "target_word": "建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是去年建的。", "target_word": "建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在山下建了一个小房子。", "target_word": "建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校旁边正在建一座大医院。", "target_word": "建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在城外建了一条新路。", "target_word": "建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座体育馆建了三年才完成。", "target_word": "建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里想建一个新的游泳池。", "target_word": "建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用砖一块一块地建墙。", "target_word": "建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这里要建一座地铁站。", "target_word": "建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在海边建过一个大工厂。", "target_word": "建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "建了", "label": "体标（了）"}, {"form": "建过", "label": "体标（过）"}, {"form": "建造", "label": "复合词"}, {"form": "建立", "label": "复合词"}], "register": "中性", "sense_fingerprint": "建：动词，修造房子、桥、路等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bd4466d2-ac6f-4a40-a8e9-8cb0ae81f61a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24896, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "建", "is_correct": true, "explanation": "正确答案“建”（jiàn，第四声），意思是修造房屋、桥梁等建筑。"}, {"text": "煎", "is_correct": false, "explanation": "煎（jiān，第一声）与建（jiàn，第四声）声调不同，意思是用油煎。"}, {"text": "剪", "is_correct": false, "explanation": "剪（jiǎn，第三声）与建（jiàn，第四声）声调不同，意思是剪断。"}, {"text": "降", "is_correct": false, "explanation": "降（jiàng，第四声）与建（jiàn）韵母不同（-ng 与 -n），意思是下降。"}, {"text": "欠", "is_correct": false, "explanation": "欠（qiàn，第四声）与建（jiàn）声母不同（q 与 j），意思是欠（钱）。"}], "explanations": {"建": "正确答案“建”（jiàn，第四声），意思是修造房屋、桥梁等建筑。", "煎": "煎（jiān，第一声）与建（jiàn，第四声）声调不同，意思是用油煎。", "剪": "剪（jiǎn，第三声）与建（jiàn，第四声）声调不同，意思是剪断。", "降": "降（jiàng，第四声）与建（jiàn）韵母不同（-ng 与 -n），意思是下降。", "欠": "欠（qiàn，第四声）与建（jiàn）声母不同（q 与 j），意思是欠（钱）。"}, "sentence_index": null, "correct_answer": "建"}, "level_3": {"options": [{"text": "建", "is_correct": true, "explanation": "“建”是修造，“在河上建一座新桥”搭配自然，符合“打算”的语境。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是水、茶等饮料，不能说“喝一座桥”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能带“桥”作宾语，不说“唱一座桥”。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”是挖掘，桥不能挖出来，“挖一座新桥”不合常理。"}], "explanations": {"建": "“建”是修造，“在河上建一座新桥”搭配自然，符合“打算”的语境。", "喝": "搭配：“喝”的对象是水、茶等饮料，不能说“喝一座桥”。", "唱": "搭配：“唱”不能带“桥”作宾语，不说“唱一座桥”。", "挖": "语义：“挖”是挖掘，桥不能挖出来，“挖一座新桥”不合常理。"}, "sentence_index": 0, "correct_answer": "建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他们正在建一双新鞋。", "explanation": "这里应该用〈做〉。建用于房屋、桥梁等建筑设施，不能用于鞋子，做鞋应说“做”。"}, {"text": "这家工厂每天建几十辆汽车。", "explanation": "这里应该用〈造〉。造用于汽车等制造物，建只用于房屋、桥梁等建筑设施，不能说建汽车。"}, {"text": "工人正在建一盏新电灯。", "explanation": "这里应该用〈装〉。装用于电灯、门窗等设备的安装，建用于大型建筑，不说建电灯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24896, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "建", "is_correct": true, "explanation": "正确答案“建”（jiàn，第四声），意思是修造房屋、桥梁等建筑。"}, {"text": "肩", "is_correct": false, "explanation": "肩（jiān，第一声）与建（jiàn，第四声）声调不同，意思是肩膀。"}, {"text": "尖", "is_correct": false, "explanation": "尖（jiān，第一声）与建（jiàn，第四声）声调不同，意思是尖锐、尖端。"}, {"text": "检", "is_correct": false, "explanation": "检（jiǎn，第三声）与建（jiàn，第四声）声调不同，意思是检查。"}, {"text": "减", "is_correct": false, "explanation": "减（jiǎn，第三声）与建（jiàn，第四声）声调不同，意思是减少。"}], "explanations": {"建": "正确答案“建”（jiàn，第四声），意思是修造房屋、桥梁等建筑。", "肩": "肩（jiān，第一声）与建（jiàn，第四声）声调不同，意思是肩膀。", "尖": "尖（jiān，第一声）与建（jiàn，第四声）声调不同，意思是尖锐、尖端。", "检": "检（jiǎn，第三声）与建（jiàn，第四声）声调不同，意思是检查。", "减": "减（jiǎn，第三声）与建（jiàn，第四声）声调不同，意思是减少。"}, "sentence_index": null, "correct_answer": "建"}, "level_3": {"options": [{"text": "建", "is_correct": true, "explanation": "“建”是修造，“村里想建一个新的游泳池”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不跟“游泳池”搭配，不能说吃游泳池。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”的对象是书、文章，不能说“读一个游泳池”。"}, {"text": "教", "is_correct": false, "explanation": "配价：“教”要求带受教的人作宾语，不能说教一个游泳池。"}], "explanations": {"建": "“建”是修造，“村里想建一个新的游泳池”搭配自然。", "吃": "搭配：“吃”不跟“游泳池”搭配，不能说吃游泳池。", "读": "搭配：“读”的对象是书、文章，不能说“读一个游泳池”。", "教": "配价：“教”要求带受教的人作宾语，不能说教一个游泳池。"}, "sentence_index": 6, "correct_answer": "建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上都建一顿饭。", "explanation": "“建”用于房屋、桥梁等建筑设施，不能带“饭”作宾语；做饭要说“做”，不说建饭。"}, {"text": "妈妈在厨房里建了一个好主意。", "explanation": "“建”指修造，不用于想出的主意；主意要说“想”或“提”，不说建主意。"}, {"text": "他在台上建了一首新歌。", "explanation": "“建”指修造，不能用于歌曲；唱歌或写歌要用“唱”或“写”，不说建歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24896, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于把桥建了好。", "corrected_sentence": "他终于把桥建好了。", "error_description": "错误形式“建了好”，正确形式“建好了”。结果补语“好”应紧跟动词“建”，“了”放在句末，不能放在“好”的前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24896, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路是前年建了的。", "corrected_sentence": "这条路是前年建的。", "error_description": "错误形式“建了的”，正确形式“建的”。“是……的”句强调已发生动作的时间，动词后不再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '760b2615-f079-4360-889c-f016e8bb97e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
