INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "绿色植物是含有叶绿素、能自己制造食物的植物。", "primary_collocate": null, "pronunciation": "lǜ sè zhí wù", "ipa": "ly˥˩ sɤ˥˩ ʈʂɨ˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "绿色植物有绿色的叶子，但不会走路。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿色植物不会走路，只能站在一个地方。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小草和大树都是绿色植物。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿色植物自己造食物，不用吃饭。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在阳台上养了很多绿色植物。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道哪些是绿色植物吗？", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绿色植物喜欢太阳，也要喝水。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的绿色植物长得很快。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带我们去看公园里的绿色植物。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花不是动物，是绿色植物。", "target_word": "绿色植物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一盆绿色植物", "label": "量词"}, {"form": "一种绿色植物", "label": "量词"}], "register": "中性", "sense_fingerprint": "绿色植物：含叶绿素、能自己制造食物的植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6c5f7b6-97db-4c5b-be74-c6e035cd0ce7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24898, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绿色植物", "is_correct": true, "explanation": "正确。植物有绿色的叶子，又不会走路，符合整句的描述。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗没有叶子，与“叶子是绿的”矛盾。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫没有叶子，而且会走路，与“不会走路”矛盾。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“叶子”属于植物，“石头的叶子”说不通，与“叶子是绿的”搭配不上。"}], "explanations": {"绿色植物": "正确。植物有绿色的叶子，又不会走路，符合整句的描述。", "小狗": "语义：小狗没有叶子，与“叶子是绿的”矛盾。", "猫": "语义：猫没有叶子，而且会走路，与“不会走路”矛盾。", "石头": "搭配：“叶子”属于植物，“石头的叶子”说不通，与“叶子是绿的”搭配不上。"}, "sentence_index": 0, "correct_answer": "绿色植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府鼓励市民绿色植物出行。", "explanation": "这里应该用〈绿色〉。“绿色植物”指植物，不能用来表示环保的出行方式；“绿色出行”是常用说法。"}, {"text": "绿色植物是一种含在叶子里的绿色物质。", "explanation": "这里应该用〈叶绿素〉。叶绿素是一种含在叶子里的物质，“绿色植物”指植物这种生物，不能用来指物质。"}, {"text": "吸收阳光、制造养分的过程叫绿色植物。", "explanation": "这里应该用〈光合作用〉。“绿色植物”指植物这种生物，不能用来指一个过程；“光合作用”才指这个过程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绿色植物", "is_correct": true, "explanation": "正确。植物喜欢阳光，也要喝水，符合整句的描述。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有喜好，也不需要喝水。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“喝水”用于人和生物，汽车要说“加油”，不说“喝水”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子无生命，既不会喜欢太阳，也不需要喝水。"}], "explanations": {"绿色植物": "正确。植物喜欢阳光，也要喝水，符合整句的描述。", "石头": "语义：石头没有喜好，也不需要喝水。", "汽车": "搭配：“喝水”用于人和生物，汽车要说“加油”，不说“喝水”。", "桌子": "语义：桌子无生命，既不会喜欢太阳，也不需要喝水。"}, "sentence_index": 6, "correct_answer": "绿色植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把窗帘染成了绿色植物。", "explanation": "这里应该用〈绿色〉，说“染成了绿色”。“绿色植物”指植物，不能用来指颜色。"}, {"text": "我们应该少开车，过绿色植物的生活。", "explanation": "这里应该用〈绿色〉。“绿色生活”指环保的生活方式；“绿色植物”指植物，不能这样用。"}, {"text": "这朵花的花瓣是绿色植物。", "explanation": "这里应该用〈绿色〉，说“花瓣是绿色的”。“绿色植物”指整株植物，不能用来指花瓣这样的一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家阳台上有一只绿色植物。", "corrected_sentence": "我家阳台上有一盆绿色植物。", "error_description": "量词用错。“只”用于动物，不用于植物；植物可用“盆”，应说“一盆绿色植物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我摸了摸绿色植物地叶子。", "corrected_sentence": "我摸了摸绿色植物的叶子。", "error_description": "修饰语用错。名词前的修饰语要用“的”，不用“地”（“地”用于动词、形容词前作状语），应说“绿色植物的叶子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '138888af-873c-47fc-bd5e-dbe14baeca24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
