INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24900, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把钱或东西用出去，希望以后能赚更多的钱。", "primary_collocate": null, "pronunciation": "tóu zī", "ipa": "tʰoʊ˧˥ tsɹ̩˥", "syllable_count": 2, "sentences": [{"text": "他想投资一家小公司。", "target_word": "投资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把钱投资在房子上。", "target_word": "投资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸不敢投资股票。", "target_word": "投资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人愿意投资教育。", "target_word": "投资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友投资了一家饭店。", "target_word": "投资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "投资以前，要先了解这家公司。", "target_word": "投资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用十万块钱投资，结果赚了不少。", "target_word": "投资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人可以把工资的一部分投资在基金上。", "target_word": "投资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司打算明年投资一家工厂。", "target_word": "投资", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说投资有风险，要小心。", "target_word": "投资", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "投资了", "label": "体标"}, {"form": "投资过", "label": "体标"}, {"form": "投资者", "label": "复合"}], "register": "中性", "sense_fingerprint": "拿出钱或东西，希望以后赚更多的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0457a638-19e5-4662-9085-4b0c62c030be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24900, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投资", "is_correct": true, "explanation": "正确：投资指把钱用于经营以求回报，“想投资一家小公司”说得通。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，公司不能被“吃”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”一般搭配歌曲，不能说“唱一家小公司”。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”的对象是可以分割的物体，公司不能被切。"}], "explanations": {"投资": "正确：投资指把钱用于经营以求回报，“想投资一家小公司”说得通。", "吃": "语义：“吃”的对象是食物，公司不能被“吃”。", "唱": "搭配：“唱”一般搭配歌曲，不能说“唱一家小公司”。", "切": "语义：“切”的对象是可以分割的物体，公司不能被切。"}, "sentence_index": 0, "correct_answer": "投资"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把全部精力投资到工作中。", "explanation": "这里应该用〈投入〉。投资专指把钱用于经营以求回报，精力和时间要说投入。"}, {"text": "大家都投资了这位候选人。", "explanation": "这里应该用〈投票〉。投资是把钱用于经营以求回报，选举时表示支持要说投票。"}, {"text": "他把一大笔钱投资给了灾区。", "explanation": "这里应该用〈捐〉。投资是为了以后赚更多的钱，给灾区是无偿的，要说捐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24900, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投资", "is_correct": true, "explanation": "正确：投资的目的是赚钱，“用十万块钱投资，结果赚了不少”说得通。"}, {"text": "花费", "is_correct": false, "explanation": "语义：花费是把钱用掉，不会带来收益，与“赚了不少”矛盾。"}, {"text": "赔", "is_correct": false, "explanation": "语义：赔是亏掉钱，与“赚了不少”矛盾。"}, {"text": "借", "is_correct": false, "explanation": "搭配：“借”不能与“用十万块钱”连用来表示收益，这里说不通。"}], "explanations": {"投资": "正确：投资的目的是赚钱，“用十万块钱投资，结果赚了不少”说得通。", "花费": "语义：花费是把钱用掉，不会带来收益，与“赚了不少”矛盾。", "赔": "语义：赔是亏掉钱，与“赚了不少”矛盾。", "借": "搭配：“借”不能与“用十万块钱”连用来表示收益，这里说不通。"}, "sentence_index": 6, "correct_answer": "投资"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行投资了五千块。", "explanation": "这里应该用〈花费〉。投资是为了以后赚钱，旅行只是花钱，不能说投资。"}, {"text": "周末他在商场投资了很多。", "explanation": "这里应该用〈消费〉。投资要以赚钱为目的，在商场买东西是消费。"}, {"text": "周末我们去游乐场投资了一整天。", "explanation": "这里应该用〈娱乐〉。投资要以赚钱为目的，去游乐场玩是为了娱乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24900, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把钱投资房子上。", "corrected_sentence": "他把钱投资在房子上。", "error_description": "错误：漏了“在”。“把钱投资”后说明投到哪里要用“在……上”，应说“把钱投资在房子上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24900, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他投资的很谨慎。", "corrected_sentence": "他投资得很谨慎。", "error_description": "补语标记错误：“得”是补语标记，应紧接动词“投资”，说“投资得很谨慎”。“的”不能用来引出补语，“投资的很谨慎”不自然。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '121e23d8-0237-4343-865b-c6f46e8ee6c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
