INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24902, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有好几层的房子，也指房子的第几层。", "primary_collocate": null, "pronunciation": "lóu", "ipa": "loʊ˧˥", "syllable_count": 1, "sentences": [{"text": "他家那栋楼很高。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋楼有电梯吗？", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室在五楼。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我住的楼没有电梯。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在楼前玩儿。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼是去年盖好的。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，你住几楼？", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在楼里等了半个小时。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司租了一整座楼。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那边的楼都很旧了。", "target_word": "楼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "栋", "label": "量词"}, {"form": "楼房", "label": "复合"}, {"form": "樓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "好几层的房子；房子的第几层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f270e504-0a47-4d31-b06d-9aa60be4a027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24902, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "楼", "is_correct": true, "explanation": "lóu 第二声，意思是楼房，是正确答案。"}, {"text": "漏", "is_correct": false, "explanation": "lòu 与 lóu 声调不同（第四声与第二声），意思是漏出。"}, {"text": "劳", "is_correct": false, "explanation": "láo 与 lóu 韵母不同（ao 与 ou），声调相同，意思是劳动。"}, {"text": "龙", "is_correct": false, "explanation": "lóng 与 lóu 韵母不同（ong 与 ou），声调相同，意思是龙。"}, {"text": "搂", "is_correct": false, "explanation": "lǒu 与 lóu 声调不同（第三声与第二声），意思是搂抱。"}], "explanations": {"楼": "lóu 第二声，意思是楼房，是正确答案。", "漏": "lòu 与 lóu 声调不同（第四声与第二声），意思是漏出。", "劳": "láo 与 lóu 韵母不同（ao 与 ou），声调相同，意思是劳动。", "龙": "lóng 与 lóu 韵母不同（ong 与 ou），声调相同，意思是龙。", "搂": "lǒu 与 lóu 声调不同（第三声与第二声），意思是搂抱。"}, "sentence_index": null, "correct_answer": "楼"}, "level_3": {"options": [{"text": "楼", "is_correct": true, "explanation": "“那栋楼”指一座楼房，很高，符合句意。"}, {"text": "桥", "is_correct": false, "explanation": "搭配：量词“栋”只用于房屋，不能说“那栋桥”。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树用“棵”计量，不能说“他家那栋树”。"}, {"text": "山", "is_correct": false, "explanation": "语义：山是天然地形，不会属于“他家”，也不是房屋。"}], "explanations": {"楼": "“那栋楼”指一座楼房，很高，符合句意。", "桥": "搭配：量词“栋”只用于房屋，不能说“那栋桥”。", "树": "搭配：树用“棵”计量，不能说“他家那栋树”。", "山": "语义：山是天然地形，不会属于“他家”，也不是房屋。"}, "sentence_index": 0, "correct_answer": "楼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌一共有二十楼。", "explanation": "这里应该用〈段〉。楼指房屋或楼层，歌曲的分段要用“段”，不能说“二十楼”。"}, {"text": "他把瓶子的楼拧紧了。", "explanation": "这里应该用〈瓶盖〉。楼指房屋，不能指瓶子的盖子，拧紧的是瓶盖。"}, {"text": "这张纸的楼很厚。", "explanation": "这里应该用〈厚度〉。楼指房屋或楼层，纸的厚薄要说「厚度」，不能用「楼」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24902, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "楼", "is_correct": true, "explanation": "lóu 第二声，意思是楼房，是正确答案。"}, {"text": "篓", "is_correct": false, "explanation": "lǒu 与 lóu 声调不同（第三声与第二声），意思是竹篓。"}, {"text": "留", "is_correct": false, "explanation": "liú 与 lóu 韵母不同（iu 与 ou），声调相同，意思是留下。"}, {"text": "炉", "is_correct": false, "explanation": "lú 与 lóu 韵母不同（u 与 ou），声调相同，意思是炉子。"}, {"text": "露", "is_correct": false, "explanation": "lòu 与 lóu 声调不同（第四声与第二声），意思是露出（口语读音）。"}], "explanations": {"楼": "lóu 第二声，意思是楼房，是正确答案。", "篓": "lǒu 与 lóu 声调不同（第三声与第二声），意思是竹篓。", "留": "liú 与 lóu 韵母不同（iu 与 ou），声调相同，意思是留下。", "炉": "lú 与 lóu 韵母不同（u 与 ou），声调相同，意思是炉子。", "露": "lòu 与 lóu 声调不同（第四声与第二声），意思是露出（口语读音）。"}, "sentence_index": null, "correct_answer": "楼"}, "level_3": {"options": [{"text": "楼", "is_correct": true, "explanation": "问“你住几楼”，楼指楼层，符合句意。"}, {"text": "桌", "is_correct": false, "explanation": "搭配：“桌”用于计量桌子，不能说“你住几桌”。"}, {"text": "厅", "is_correct": false, "explanation": "语义：住房问的是楼层，“几厅”问的是客厅数量，不能用来问住在哪里。"}, {"text": "窗", "is_correct": false, "explanation": "搭配：窗用“扇”计量，“几窗”不能用来问住在第几层。"}], "explanations": {"楼": "问“你住几楼”，楼指楼层，符合句意。", "桌": "搭配：“桌”用于计量桌子，不能说“你住几桌”。", "厅": "语义：住房问的是楼层，“几厅”问的是客厅数量，不能用来问住在哪里。", "窗": "搭配：窗用“扇”计量，“几窗”不能用来问住在第几层。"}, "sentence_index": 6, "correct_answer": "楼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下雨的时候，我们不坐电梯，改走楼。", "explanation": "这里应该用〈楼梯〉。走楼梯是常见说法，楼是房屋，不能作为上下的通道。"}, {"text": "这个柜子一共有四楼。", "explanation": "这里应该用〈层〉。楼指整座房屋，柜子的分层要用“层”。"}, {"text": "这套楼有三间卧室。", "explanation": "这里应该用〈房子〉。“套”计量住宅单元，楼指整栋建筑，不能说“这套楼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条楼的电梯坏了。", "corrected_sentence": "那座楼的电梯坏了。", "error_description": "量词错误：“楼”应用“座”或“栋”，说“那座楼”；“条”用于细长的东西，不能修饰楼房。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她搬到了楼五。", "corrected_sentence": "她搬到了五楼。", "error_description": "语序错误：表示楼层时数字要放在「楼」前面，应说「五楼」，不能说「楼五」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
