INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家或社会有足够的粮食，让人人都有饭吃、不挨饿。", "primary_collocate": null, "pronunciation": "liáng shi ān quán", "ipa": "ljɑŋ˧˥ ʂɻ̩ an˥ tɕʰɥɛn˧˥", "syllable_count": 4, "sentences": [{"text": "粮食安全对一个国家很重要。", "target_word": "粮食安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气不好，会影响粮食安全。", "target_word": "粮食安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府很重视粮食安全。", "target_word": "粮食安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护土地，才能保证粮食安全。", "target_word": "粮食安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "粮食安全就是让大家都有饭吃。", "target_word": "粮食安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几年，国家一直在努力保障粮食安全。", "target_word": "粮食安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱让粮食安全出了问题。", "target_word": "粮食安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民种好地，是粮食安全的基础。", "target_word": "粮食安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "浪费粮食会影响粮食安全。", "target_word": "粮食安全", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了粮食安全的重要性。", "target_word": "粮食安全", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "国家或社会有足够的粮食,人人有饭吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24904, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：玩具是儿童的娱乐用品，与国家层面的粮食问题无关，作主语说不通。"}, {"text": "饭桶", "is_correct": false, "explanation": "语域：「饭桶」是口语中骂人笨的贬义词，不能用于正式语境中谈论国家大事。"}, {"text": "粮食安全", "is_correct": true, "explanation": "「粮食安全」指国家或社会有足够的粮食、人人有饭吃，作主语正合句意。"}, {"text": "蚊子", "is_correct": false, "explanation": "语义：蚊子是小型昆虫，不是国家层面的大事，句子说不通。"}], "explanations": {"玩具": "语义：玩具是儿童的娱乐用品，与国家层面的粮食问题无关，作主语说不通。", "饭桶": "语域：「饭桶」是口语中骂人笨的贬义词，不能用于正式语境中谈论国家大事。", "粮食安全": "「粮食安全」指国家或社会有足够的粮食、人人有饭吃，作主语正合句意。", "蚊子": "语义：蚊子是小型昆虫，不是国家层面的大事，句子说不通。"}, "sentence_index": 0, "correct_answer": "粮食安全"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个城市每天都有大量粮食安全。", "explanation": "这里应该用〈粮食供应〉。「大量」说的是数量，粮食安全描述的是一种状况，不能计数量。"}, {"text": "今年粮食安全又涨了。", "explanation": "这里应该用〈粮食价格〉。「涨」用于价格或数量，粮食安全是状况，不能说涨。"}, {"text": "这是一只重要的粮食安全。", "explanation": "这里应该用〈个〉或〈项〉。「只」用于某些动物或成对的东西，抽象的粮食安全不用「只」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脸蛋", "is_correct": false, "explanation": "体貌：「脸蛋」只指面颊的外观，干旱不会让它出问题，句子不通。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是工具书，干旱不会让字典出问题，语义上说不通。"}, {"text": "拖鞋", "is_correct": false, "explanation": "语义：拖鞋与干旱无关，“干旱让拖鞋出了问题”句意不通。"}, {"text": "粮食安全", "is_correct": true, "explanation": "「粮食安全」是抽象的状况，干旱可以让它出现问题，句意通顺。"}], "explanations": {"脸蛋": "体貌：「脸蛋」只指面颊的外观，干旱不会让它出问题，句子不通。", "字典": "语义：字典是工具书，干旱不会让字典出问题，语义上说不通。", "拖鞋": "语义：拖鞋与干旱无关，“干旱让拖鞋出了问题”句意不通。", "粮食安全": "「粮食安全」是抽象的状况，干旱可以让它出现问题，句意通顺。"}, "sentence_index": 6, "correct_answer": "粮食安全"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火车把粮食安全运到了灾区。", "explanation": "这里应该用〈谷物〉。「粮食安全」指抽象的保障状况，不能被运送；运送的是具体的谷物。"}, {"text": "这场大火烧毁了粮食安全。", "explanation": "这里应该用〈粮仓〉。「烧毁」的对象是具体的建筑或物品，粮食安全是抽象的状况，不能被烧毁。"}, {"text": "农民正在播种粮食安全。", "explanation": "这里应该用〈小麦〉。「播种」的对象是种子或作物，粮食安全是抽象概念，不能播种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府出台了粮食安全地政策。", "corrected_sentence": "政府出台了粮食安全的政策。", "error_description": "「粮食安全」后面修饰名词「政策」应用定语助词「的」，写成「地」是误用：「地」用来修饰动词或形容词，不能用在名词前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家很关心粮食安全们。", "corrected_sentence": "这个国家很关心粮食安全。", "error_description": "「们」只用于指人的名词，抽象的「粮食安全」不能加「们」，应直接说「粮食安全」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
