INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24906, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示做事很认真或很不错。", "primary_collocate": null, "pronunciation": "hǎo hǎo", "ipa": "xɑʊ˨˩ xɑʊ˨˩", "syllable_count": 2, "sentences": [{"text": "我们要好好讨论这个方案。", "target_word": "好好", "complexity_tier": "T3", "furigana": "wǒmen yào hǎohāo tǎolùn zhège fāng''àn。", "sentence_source": "generated"}, {"text": "你要好好记住这件事。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都好好练习写汉字。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家好好看着黑板。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会好好爱护这本书。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前，好好检查一下你的包。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们好好准备，明天有考试。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题，我们要好好想办法。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他好好准备了这次面试。", "target_word": "好好", "complexity_tier": "T3", "furigana": "tā hǎohāo zhǔnbèi le zhè cì miànshì。", "sentence_source": "generated"}, {"text": "老师告诉我们，要好好做作业。", "target_word": "好好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好好儿", "label": "儿化"}, {"form": "好好地", "label": "状语形式"}], "register": "口语", "sense_fingerprint": "做事认真、尽力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f270e504-0a47-4d31-b06d-9aa60be4a027') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24906, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好好", "is_correct": true, "explanation": "hǎo hǎo，意思是做事认真、不错，是正确答案。"}, {"text": "很好", "is_correct": false, "explanation": "hěn hǎo 与 hǎo hǎo 第一音节韵母不同（en 与 ao），意思是非常好。"}, {"text": "好搞", "is_correct": false, "explanation": "hǎo gǎo 与 hǎo hǎo 第二音节声母不同（g 与 h），意思是容易处理。"}, {"text": "好少", "is_correct": false, "explanation": "hǎo shǎo 与 hǎo hǎo 第二音节声母不同（sh 与 h），意思是很少。"}, {"text": "好找", "is_correct": false, "explanation": "hǎo zhǎo 与 hǎo hǎo 第二音节声母不同（zh 与 h），意思是容易找到。"}], "explanations": {"好好": "hǎo hǎo，意思是做事认真、不错，是正确答案。", "很好": "hěn hǎo 与 hǎo hǎo 第一音节韵母不同（en 与 ao），意思是非常好。", "好搞": "hǎo gǎo 与 hǎo hǎo 第二音节声母不同（g 与 h），意思是容易处理。", "好少": "hǎo shǎo 与 hǎo hǎo 第二音节声母不同（sh 与 h），意思是很少。", "好找": "hǎo zhǎo 与 hǎo hǎo 第二音节声母不同（zh 与 h），意思是容易找到。"}, "sentence_index": null, "correct_answer": "好好"}, "level_3": {"options": [{"text": "好好", "is_correct": true, "explanation": "“好好讨论”表示认真地讨论，符合“要”的目的。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒然、没有结果，与“要讨论”的目的性相矛盾。"}, {"text": "草草", "is_correct": false, "explanation": "语义：“草草”表示敷衍、马虎，与“要认真讨论方案”的要求相反。"}, {"text": "差点", "is_correct": false, "explanation": "语义：“差点”表示几乎没有做，与“要讨论”相矛盾。"}], "explanations": {"好好": "“好好讨论”表示认真地讨论，符合“要”的目的。", "白白": "语义：“白白”表示徒然、没有结果，与“要讨论”的目的性相矛盾。", "草草": "语义：“草草”表示敷衍、马虎，与“要认真讨论方案”的要求相反。", "差点": "语义：“差点”表示几乎没有做，与“要讨论”相矛盾。"}, "sentence_index": 0, "correct_answer": "好好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在书店好好碰到了老朋友。", "explanation": "这里应该用〈恰好〉。好好表示认真或很不错，不表示偶然的巧遇，碰到老朋友是偶然的，要说“恰好”。"}, {"text": "他好好就回来了。", "explanation": "这里应该用〈马上〉。好好表示认真、充分，不表示时间，应说“马上就回来了”。"}, {"text": "我好好把钥匙丢了，找了半天。", "explanation": "这里应该用〈不小心〉。好好表示认真、尽力，丢钥匙是无意的，应说“不小心把钥匙丢了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24906, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好好", "is_correct": true, "explanation": "“好好准备”表示认真地准备，符合“明天有考试”的语境。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示次数很少，与“明天有考试”的紧迫矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从不，与“准备”的行为相反。"}, {"text": "乱", "is_correct": false, "explanation": "搭配：“乱”不与“准备”搭配，准备应是有条理的。"}], "explanations": {"好好": "“好好准备”表示认真地准备，符合“明天有考试”的语境。", "偶尔": "语义：“偶尔”表示次数很少，与“明天有考试”的紧迫矛盾。", "从来": "语义：“从来”表示从不，与“准备”的行为相反。", "乱": "搭配：“乱”不与“准备”搭配，准备应是有条理的。"}, "sentence_index": 6, "correct_answer": "好好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他好好摔了一跤，腿受伤了。", "explanation": "这里应该用〈不小心〉。好好表示认真、尽力，摔跤是无意的，应说“不小心摔了一跤”。"}, {"text": "我好好迟到了，老师很生气。", "explanation": "这里应该用〈不小心〉。好好表示认真、充分，迟到是无意的，应说“不小心迟到了”。"}, {"text": "他好好把窗户打碎了。", "explanation": "这里应该用〈失手〉。好好表示认真、充分，打碎窗户是无意的，应说“失手打碎了窗户”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你要好好好照顾自己。", "corrected_sentence": "你要好好照顾自己。", "error_description": "重叠形式错误：“好好”已是重叠形式，不能多写一个“好”成“好好好”，应说“好好照顾自己”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你们要好好好准备明天的考试。", "corrected_sentence": "你们要好好准备明天的考试。", "error_description": "重叠形式错误：“好好”已是重叠形式，不能再多写一个“好”成“好好好”，应说“好好准备”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4716b350-ba93-4c2f-8738-ad7379babccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
