INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24908, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一件事情做完，让它变得很好。", "primary_collocate": null, "pronunciation": "zuò hǎo", "ipa": "tswo˥˩ xaʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "你一定要做好今天的作业。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这件事做好了。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先做好作业，再出去玩。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作做好以后，你可以回家休息。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，我们要做好每一件小事。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她做好了自己的工作，心里很高兴。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要你肯认真做，就一定能做好。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直很努力，想把工作做好。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次的任务很重要，大家一定要做好。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事很认真，每件事都能做好。", "target_word": "做好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "做好了", "label": "体标（了）"}, {"form": "没做好", "label": "否定式"}, {"form": "做不好", "label": "可能补语否定式"}], "register": "中性", "sense_fingerprint": "把事情认真做完并做得令人满意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b87e49c7-61d3-43e4-8c3e-581be990683a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24908, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "做好", "is_correct": true, "explanation": "“做好”指把事情认真做完并做得令人满意，与“今天的作业”搭配自然。"}, {"text": "烧好", "is_correct": false, "explanation": "语义：“烧”的对象是食物或水，作业不能烧，与“认真完成”的语境不合。"}, {"text": "煮好", "is_correct": false, "explanation": "语义：“煮”用于做饭等，不能用于作业，与“一定要”的任务语境不合。"}, {"text": "缝好", "is_correct": false, "explanation": "搭配：“缝”只用于衣物等布料，不能用于作业。"}], "explanations": {"做好": "“做好”指把事情认真做完并做得令人满意，与“今天的作业”搭配自然。", "烧好": "语义：“烧”的对象是食物或水，作业不能烧，与“认真完成”的语境不合。", "煮好": "语义：“煮”用于做饭等，不能用于作业，与“一定要”的任务语境不合。", "缝好": "搭配：“缝”只用于衣物等布料，不能用于作业。"}, "sentence_index": 0, "correct_answer": "做好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要做好友谊。", "explanation": "这里应该用〈增进〉。“增进”用于友谊、团结等关系；“做好”指把具体事务做完、做得好，不用于友谊。"}, {"text": "我们终于做好了这个困难。", "explanation": "这里应该用〈克服〉。做好指把事情做完、做得好；困难要说「克服」。"}, {"text": "他终于做好了信心，要参加比赛。", "explanation": "这里应该用〈树立〉。做好指把事情做完、做得好；信心要说「树立」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24908, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "做好", "is_correct": true, "explanation": "“做好”指把事情做得很好，与“只要你肯认真做”的语境一致。"}, {"text": "吃好", "is_correct": false, "explanation": "语义：“吃”的对象是食物，“就一定能吃好”与“认真做”的语境不合。"}, {"text": "熨好", "is_correct": false, "explanation": "搭配：“熨”只用于衣物，不能用于泛指的事情。"}, {"text": "炖好", "is_correct": false, "explanation": "语义：“炖”用于做菜，与泛指的“认真做”不合。"}], "explanations": {"做好": "“做好”指把事情做得很好，与“只要你肯认真做”的语境一致。", "吃好": "语义：“吃”的对象是食物，“就一定能吃好”与“认真做”的语境不合。", "熨好": "搭配：“熨”只用于衣物，不能用于泛指的事情。", "炖好": "语义：“炖”用于做菜，与泛指的“认真做”不合。"}, "sentence_index": 6, "correct_answer": "做好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两国终于做好了关系，互派大使。", "explanation": "这里应该用〈修好〉。“修好”指两国或人际之间建立和睦关系，“做好”不用于关系。"}, {"text": "他终于把烦恼做好了，不再难过。", "explanation": "这里应该用〈消除〉。烦恼要说消除；“做好”指把事情做完、做得好，不用于烦恼。"}, {"text": "他的病终于做好了，可以出院了。", "explanation": "这里应该用〈治好〉。做好指制作完成或把事情做得好；病要说「治好」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24908, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师希望我们把作业做好地。", "corrected_sentence": "老师希望我们把作业做好。", "error_description": "错误：“做好”是动补结构，其后不能再加“地”；“地”只修饰动词，“做好地”不成立，应删去“地”，即“老师希望我们把作业做好。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24908, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把这项任务做好了了。", "corrected_sentence": "她把这项任务做好了。", "error_description": "错误：“做好了”后多加了一个“了”，结果补语与体标重复，应删去多余的“了”，即“她把这项任务做好了。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edfee2d8-cb11-4467-b59a-da561cd30af9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24910, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难受", "is_correct": true, "explanation": "反义词：“难受”指身体或心里感到不适，与“舒服”的本义相对。"}, {"text": "清晰", "is_correct": false, "explanation": "无反义关系：“清晰”形容看得或听得分明，与身心感受无关。"}, {"text": "宽阔", "is_correct": false, "explanation": "无反义关系：“宽阔”形容空间面积大，与“舒服”不构成相对关系。"}, {"text": "缓慢", "is_correct": false, "explanation": "无反义关系：“缓慢”形容速度慢，与身心感受无关。"}], "correct_answer": "难受", "explanations": {"难受": "反义词：“难受”指身体或心里感到不适，与“舒服”的本义相对。", "清晰": "无反义关系：“清晰”形容看得或听得分明，与身心感受无关。", "宽阔": "无反义关系：“宽阔”形容空间面积大，与“舒服”不构成相对关系。", "缓慢": "无反义关系：“缓慢”形容速度慢，与身心感受无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24910, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "难受", "is_correct": true, "explanation": "反义词：“难受”指身体或心里感到不适，与“舒服”的本义相对。"}, {"text": "凌乱", "is_correct": false, "explanation": "无反义关系：“凌乱”形容东西杂乱无章，与身心感受无关。"}, {"text": "遥远", "is_correct": false, "explanation": "无反义关系：“遥远”形容距离远，与“舒服”不构成相对关系。"}, {"text": "热烈", "is_correct": false, "explanation": "无反义关系：“热烈”形容气氛或情感强烈，与身心感受无关。"}], "correct_answer": "难受", "explanations": {"难受": "反义词：“难受”指身体或心里感到不适，与“舒服”的本义相对。", "凌乱": "无反义关系：“凌乱”形容东西杂乱无章，与身心感受无关。", "遥远": "无反义关系：“遥远”形容距离远，与“舒服”不构成相对关系。", "热烈": "无反义关系：“热烈”形容气氛或情感强烈，与身心感受无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24910, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "身体或心里感觉很轻松，不难受。", "primary_collocate": null, "pronunciation": "shū fu", "ipa": "ʂu˥˥ fu", "syllable_count": 2, "sentences": [{"text": "睡了一觉以后，我觉得舒服多了。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天天气不冷不热，走在路上很舒服。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你哪里不舒服？我们去医院看看吧。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服很软，穿在身上特别舒服。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她和家人在一起，心里觉得很舒服。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喝了一杯热水，胃里舒服了一点。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个椅子太硬，坐久了很不舒服。", "target_word": "舒服", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在海边吹吹风，真舒服啊！", "target_word": "舒服", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨天待在家里，喝着热茶，真舒服。", "target_word": "舒服", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗了澡，换上干净的衣服，我觉得舒服极了。", "target_word": "舒服", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "舒舒服服", "label": "重叠（AABB）"}, {"form": "不舒服", "label": "否定形式"}], "register": "口语", "sense_fingerprint": "身体或心里轻松自在、不难受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1031e19-faab-40d9-8d4c-621f2590ab55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "舒服", "is_correct": true, "explanation": "正确：睡了一觉以后身心轻松了许多，“舒服多了”符合语境。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”形容东西老旧，不能用来形容人的感觉。"}, {"text": "狂热", "is_correct": false, "explanation": "语义：“狂热”形容情绪极度激动，与“睡了一觉以后”的平和状态相矛盾。"}, {"text": "粗壮", "is_correct": false, "explanation": "搭配：“粗壮”多形容体格，不能用“我觉得……多了”来说感受。"}], "explanations": {"舒服": "正确：睡了一觉以后身心轻松了许多，“舒服多了”符合语境。", "陈旧": "语义：“陈旧”形容东西老旧，不能用来形容人的感觉。", "狂热": "语义：“狂热”形容情绪极度激动，与“睡了一觉以后”的平和状态相矛盾。", "粗壮": "搭配：“粗壮”多形容体格，不能用“我觉得……多了”来说感受。"}, "sentence_index": 0, "correct_answer": "舒服"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到这个消息，我特别舒服，一直笑个不停。", "explanation": "这里应该用〈开心〉。“舒服”指身体或心里没有不适，不用来形容因喜讯而兴奋的心情。"}, {"text": "这位老师对学生很舒服，作业都要检查。", "explanation": "这里应该用〈严格〉。“舒服”描述人的身心感受，不能用来形容老师的管理态度。"}, {"text": "他的成绩很舒服，全班排第一。", "explanation": "这里应该用〈优秀〉。“舒服”不能用来形容成绩的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舒服", "is_correct": true, "explanation": "正确：椅子太硬、坐久了身体不适，“很不舒服”符合语境。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”形容光线或色彩，与椅子的软硬、舒适无关，“很不明亮”不成立。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：“陡峭”形容地势或坡度，不能用来形容椅子。"}, {"text": "清秀", "is_correct": false, "explanation": "体貌：“清秀”形容人的相貌，不能用来形容椅子。"}], "explanations": {"舒服": "正确：椅子太硬、坐久了身体不适，“很不舒服”符合语境。", "明亮": "语义：“明亮”形容光线或色彩，与椅子的软硬、舒适无关，“很不明亮”不成立。", "陡峭": "搭配：“陡峭”形容地势或坡度，不能用来形容椅子。", "清秀": "体貌：“清秀”形容人的相貌，不能用来形容椅子。"}, "sentence_index": 6, "correct_answer": "舒服"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的字写得很舒服，同学们都夸他。", "explanation": "这里应该用〈漂亮〉。“舒服”指身心感受，不能用来评价字的美观与否。"}, {"text": "他把问题讲得很舒服，大家都听明白了。", "explanation": "这里应该用〈清楚〉。“舒服”形容身心感受，不能用来说明讲解是否清楚。"}, {"text": "他做事很舒服，从来不拖延。", "explanation": "这里应该用〈认真〉。“舒服”指身心感觉，不能用来形容做事的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张床非常舒服极了。", "corrected_sentence": "这张床舒服极了。", "error_description": "“舒服极了”已经表示程度很高，前面不能再加程度副词“非常”。可以说“舒服极了”或“非常舒服”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午在树荫下读书，我觉得很舒舒服服。", "corrected_sentence": "下午在树荫下读书，我觉得很舒服。", "error_description": "“舒舒服服”是“舒服”的重叠形式，不能直接受程度副词“很”修饰。正确的说法是“很舒服”，或者用“舒舒服服”而不加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
