INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24912, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以吃的、树上或地上长出来的东西，比如苹果和香蕉。", "primary_collocate": null, "pronunciation": "shuǐ guǒ", "ipa": "ʂweɪ˨˩˦ kwɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我每天都吃一些水果。", "target_word": "水果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天有很多好吃的水果。", "target_word": "水果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的水果又新鲜又便宜。", "target_word": "水果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你最喜欢什么水果？", "target_word": "水果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一斤水果回来。", "target_word": "水果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一盘水果。", "target_word": "水果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "苹果和香蕉都是水果。", "target_word": "水果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多吃水果对身体好。", "target_word": "水果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把水果洗干净了。", "target_word": "水果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去超市买水果和牛奶。", "target_word": "水果", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种水果", "label": "量词"}, {"form": "一斤水果", "label": "量词"}, {"form": "水果店", "label": "复合"}, {"form": "水果刀", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以直接吃的植物果实，如苹果、香蕉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f9422c-71d5-4159-b92d-1d18b93b36af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24912, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水果", "is_correct": true, "explanation": "正确答案。水果 shuǐguǒ 指可以直接吃的果实。"}, {"text": "水管", "is_correct": false, "explanation": "水管 shuǐguǎn 与 水果 shuǐguǒ 声调相同，韵母不同（-uan 与 -uo），意思是输水的管子。"}, {"text": "水火", "is_correct": false, "explanation": "huǒ 与 guǒ 声母不同（h 与 g），意思是水和火。"}, {"text": "睡过", "is_correct": false, "explanation": "shuìguò 与 shuǐguǒ 声调不同（均为第四声），意思是“睡了觉”，如“我睡过了”。"}, {"text": "水鬼", "is_correct": false, "explanation": "guǐ 与 guǒ 韵母不同（-i 与 -o），意思是传说中淹死的鬼。"}], "explanations": {"水果": "正确答案。水果 shuǐguǒ 指可以直接吃的果实。", "水管": "水管 shuǐguǎn 与 水果 shuǐguǒ 声调相同，韵母不同（-uan 与 -uo），意思是输水的管子。", "水火": "huǒ 与 guǒ 声母不同（h 与 g），意思是水和火。", "睡过": "shuìguò 与 shuǐguǒ 声调不同（均为第四声），意思是“睡了觉”，如“我睡过了”。", "水鬼": "guǐ 与 guǒ 韵母不同（-i 与 -o），意思是传说中淹死的鬼。"}, "sentence_index": null, "correct_answer": "水果"}, "level_3": {"options": [{"text": "水果", "is_correct": true, "explanation": "水果可以直接吃，与“吃一些”搭配，句子通顺。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“吃”用于固体食物，饮料要说“喝”，不说“吃饮料”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能吃，与“吃一些”冲突。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被吃，句子不成立。"}], "explanations": {"水果": "水果可以直接吃，与“吃一些”搭配，句子通顺。", "饮料": "搭配：“吃”用于固体食物，饮料要说“喝”，不说“吃饮料”。", "桌子": "语义：桌子不能吃，与“吃一些”冲突。", "空气": "语义：空气不能被吃，句子不成立。"}, "sentence_index": 0, "correct_answer": "水果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我早上喝了一杯水果。", "explanation": "这里应该用〈果汁〉。水果是要直接吃的果实，要喝的饮品用〈果汁〉。"}, {"text": "妈妈在厨房里用水果做了一锅红烧肉。", "explanation": "这里应该用〈排骨〉。水果不能当红烧肉的主料，做红烧肉要用〈排骨〉这类肉类。"}, {"text": "妈妈用水果给孩子做了一件衣服。", "explanation": "这里应该用〈布〉。水果不能用来做衣服，做衣服的材料要用〈布〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水果", "is_correct": true, "explanation": "苹果和香蕉都属于水果，“都是水果”说法正确。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：苹果和香蕉不是蔬菜，句子不符合事实。"}, {"text": "动物", "is_correct": false, "explanation": "语义：苹果和香蕉不是动物，句子不成立。"}, {"text": "调料", "is_correct": false, "explanation": "搭配：“是”后的类别要能概括苹果和香蕉，调料只用于调味，与二者不搭。"}], "explanations": {"水果": "苹果和香蕉都属于水果，“都是水果”说法正确。", "蔬菜": "语义：苹果和香蕉不是蔬菜，句子不符合事实。", "动物": "语义：苹果和香蕉不是动物，句子不成立。", "调料": "搭配：“是”后的类别要能概括苹果和香蕉，调料只用于调味，与二者不搭。"}, "sentence_index": 6, "correct_answer": "水果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "面包上抹了一层水果。", "explanation": "这里应该用〈果酱〉。水果不能像酱一样抹在面包上，抹的要用〈果酱〉。"}, {"text": "晚饭后我们喝了一碗水果。", "explanation": "这里应该用〈汤〉。水果是要直接吃的，不能当汤喝。"}, {"text": "聚会时大家都喝水果。", "explanation": "这里应该用〈啤酒〉。水果不是饮品，喝的东西要用〈啤酒〉之类的饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去市场买了一水果。", "corrected_sentence": "我们去市场买了一种水果。", "error_description": "错误：“一水果”。正确：“一种水果”。“水果”前的数词后面要加量词，“一种”表示类别。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把水果们放进了冰箱。", "corrected_sentence": "妈妈把水果放进了冰箱。", "error_description": "错误：“水果们”。正确：“水果”。“水果”不加“们”表示复数，多样水果直接说“水果”或“一些水果”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24914, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丑化", "is_correct": true, "explanation": "丑化：使变得难看，与“美化”意义相反。"}, {"text": "思考", "is_correct": false, "explanation": "思考：动脑想问题，与“美化”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：到外地游览，与“美化”没有反义关系。"}, {"text": "睡觉", "is_correct": false, "explanation": "睡觉：闭眼休息，与“美化”没有反义关系。"}], "correct_answer": "丑化", "explanations": {"丑化": "丑化：使变得难看，与“美化”意义相反。", "思考": "思考：动脑想问题，与“美化”没有反义关系。", "旅行": "旅行：到外地游览，与“美化”没有反义关系。", "睡觉": "睡觉：闭眼休息，与“美化”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24914, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "丑化", "is_correct": true, "explanation": "丑化：使变得难看，与“美化”意义相反。"}, {"text": "跳舞", "is_correct": false, "explanation": "跳舞：随音乐做动作，与“美化”没有反义关系。"}, {"text": "阅读", "is_correct": false, "explanation": "阅读：看书报文字，与“美化”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：慢慢走动，与“美化”没有反义关系。"}], "correct_answer": "丑化", "explanations": {"丑化": "丑化：使变得难看，与“美化”意义相反。", "跳舞": "跳舞：随音乐做动作，与“美化”没有反义关系。", "阅读": "阅读：看书报文字，与“美化”没有反义关系。", "散步": "散步：慢慢走动，与“美化”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24914, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更好看。", "primary_collocate": null, "pronunciation": "měi huà", "ipa": "meɪ̯˨˩˦ xu̯a˥˩", "syllable_count": 2, "sentences": [{"text": "工人们正在美化我们的小区。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，市政府开始美化城市的街道。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们用画把教室的墙美化了一下。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里种了很多花，美化了环境。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想用一些小灯美化我的房间。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把旧车站美化过，现在很漂亮。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了美化校园，大家一起种树。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河以前很脏，政府美化了两岸。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用花布美化了我们的厨房。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在院子里种花，想把院子美化一下。", "target_word": "美化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美化了", "label": "体标（完成）"}, {"form": "美化过", "label": "体标（经历）"}, {"form": "美化着", "label": "体标（持续）"}], "register": "中性", "sense_fingerprint": "使环境或物品变得更好看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba150852-d904-4479-b91a-fa17ed59eed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24914, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "美化", "is_correct": true, "explanation": "měi huà（美化）指让东西变得更好看。"}, {"text": "梅花", "is_correct": false, "explanation": "méi huā 与 měi huà 两个音节的声调都不同，意思是梅花。"}, {"text": "买花", "is_correct": false, "explanation": "mǎi 与 měi 的韵母不同（ai 与 ei），意思是买花。"}, {"text": "米花", "is_correct": false, "explanation": "mǐ 与 měi 的韵母不同（i 与 ei），第二个音节声调也不同，意思是米花。"}], "explanations": {"美化": "měi huà（美化）指让东西变得更好看。", "梅花": "méi huā 与 měi huà 两个音节的声调都不同，意思是梅花。", "买花": "mǎi 与 měi 的韵母不同（ai 与 ei），意思是买花。", "米花": "mǐ 与 měi 的韵母不同（i 与 ei），第二个音节声调也不同，意思是米花。"}, "sentence_index": null, "correct_answer": "美化"}, "level_3": {"options": [{"text": "美化", "is_correct": true, "explanation": "美化与“我们的小区”搭配，指让小区变得更好看。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象不能是小区，与“工人们正在”的语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不带“小区”这类处所作宾语。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬的对象不能是小区，句子不成立。"}], "explanations": {"美化": "美化与“我们的小区”搭配，指让小区变得更好看。", "吃": "语义：“吃”的对象不能是小区，与“工人们正在”的语境不符。", "唱": "搭配：“唱”不带“小区”这类处所作宾语。", "咬": "语义：咬的对象不能是小区，句子不成立。"}, "sentence_index": 0, "correct_answer": "美化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班昨天美化了一场考试。", "explanation": "这里应该用〈举行〉。美化指使东西变得更好看，不能用来指考试。"}, {"text": "工人正在美化断裂的水管。", "explanation": "这里应该用〈修理〉。“美化”指使事物变得更好看，不指修补断裂的东西。"}, {"text": "奶奶美化了断掉的椅子腿。", "explanation": "这里应该用〈修理〉。“美化”指使事物变得更好看，不指修好断掉的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美化", "is_correct": true, "explanation": "美化与“校园”搭配，符合“为了……大家一起种树”的目的。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：拆除与“大家一起种树”的目的相矛盾。"}, {"text": "监视", "is_correct": false, "explanation": "语义：监视不能用来改善校园，与“种树”不协调。"}, {"text": "切割", "is_correct": false, "explanation": "搭配：“切割”不常用于“校园”这类场所。"}], "explanations": {"美化": "美化与“校园”搭配，符合“为了……大家一起种树”的目的。", "拆除": "语义：拆除与“大家一起种树”的目的相矛盾。", "监视": "语义：监视不能用来改善校园，与“种树”不协调。", "切割": "搭配：“切割”不常用于“校园”这类场所。"}, "sentence_index": 6, "correct_answer": "美化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她去医院美化了摔断的腿。", "explanation": "这里应该用〈治疗〉。美化指使东西变得更好看，不指治好摔断的腿。"}, {"text": "爸爸美化了摔坏的自行车。", "explanation": "这里应该用〈修理〉。“美化”指使东西变好看，不指修好摔坏的车。"}, {"text": "叔叔美化了被风吹倒的篱笆。", "explanation": "这里应该用〈修理〉。“美化”指使东西变好看，不指扶起并修好被风吹倒的篱笆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把教室美化很漂亮。", "corrected_sentence": "我们把教室美化得很漂亮。", "error_description": "情态补语前要加“得”，应说“美化得很漂亮”，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们鲜花美化了阳台。", "corrected_sentence": "我们用鲜花美化了阳台。", "error_description": "工具状语“鲜花”前缺少介词“用”，应说“用鲜花美化了阳台”，不能直接说“鲜花美化了阳台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
