INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24916, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "接口是让两个东西连在一起的地方。", "primary_collocate": null, "pronunciation": "jiē kǒu", "ipa": "tɕjɛ˥ kʰoʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这台电视有两个接口。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管的接口漏水了。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "耳机要插在手机的接口里。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根线的接口坏了。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把线插进接口里。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子后面有一个充电接口。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两根管子的接口要拧紧。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找不到音箱的接口。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "接口太小，插头放不进去。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用布擦了擦接口上的灰。", "target_word": "接口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "充电接口", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体上让两个东西连在一起的具体位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca04757e-f18e-4f27-8a23-f6806ffa8172') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24916, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "接口", "is_correct": true, "explanation": "“接口”指物体上可以连接其他东西的位置，电视上有两个接口，符合句意。"}, {"text": "亲戚", "is_correct": false, "explanation": "语义：“亲戚”是人，不是电视的部件，句意不通。"}, {"text": "课程", "is_correct": false, "explanation": "语义：“课程”是教学内容，与电视的部件无关，句意不通。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：“有”后接电视的部件，“厨房”与电视无关，搭配不当。"}], "explanations": {"接口": "“接口”指物体上可以连接其他东西的位置，电视上有两个接口，符合句意。", "亲戚": "语义：“亲戚”是人，不是电视的部件，句意不通。", "课程": "语义：“课程”是教学内容，与电视的部件无关，句意不通。", "厨房": "搭配：“有”后接电视的部件，“厨房”与电视无关，搭配不当。"}, "sentence_index": 0, "correct_answer": "接口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家银行有三个接口，可以办理业务。", "explanation": "这里应该用〈窗口〉。“接口”指物体之间连接的地方，不指银行办理业务的营业窗口。"}, {"text": "这个村子的接口很少，大家都很熟悉。", "explanation": "这里应该用〈人口〉。“接口”指物体之间连接的地方，不指村子里的人数。"}, {"text": "这家饭馆的接口很好吃。", "explanation": "这里应该用〈菜〉。“接口”指物体之间连接的地方，不指食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "接口", "is_correct": true, "explanation": "“接口”是管子上连接的位置，“拧紧”可以用于它，符合句意。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“拧紧”一般用于螺丝、盖子等连接件，不说拧紧颜色。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“拧紧”不与“味道”搭配，味道不能拧。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字与管子的连接没有关系，句意说的是管子的连接处要拧紧。"}], "explanations": {"接口": "“接口”是管子上连接的位置，“拧紧”可以用于它，符合句意。", "颜色": "搭配：“拧紧”一般用于螺丝、盖子等连接件，不说拧紧颜色。", "味道": "搭配：“拧紧”不与“味道”搭配，味道不能拧。", "名字": "语义：名字与管子的连接没有关系，句意说的是管子的连接处要拧紧。"}, "sentence_index": 6, "correct_answer": "接口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按了一下电源接口。", "explanation": "这里应该用〈按钮〉。按钮是可以按的部件，接口是连接插头的地方，不能按。"}, {"text": "抽屉上装着一个接口，拉的时候很方便。", "explanation": "这里应该用〈把手〉。把手是用来拉的部件，接口是连接其他东西的地方，不能用来拉。"}, {"text": "他每天早上都喝一杯接口。", "explanation": "这里应该用〈饮料〉。“接口”指物体之间连接的地方，不能用来喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "插头太大，插不进这根小接口。", "corrected_sentence": "插头太大，插不进这个小接口。", "error_description": "“接口”的量词用“个”，“根”多用于线、棍等细长物，应说“这个小接口”，不说“这根小接口”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "插头一直在接口上插过。", "corrected_sentence": "插头一直在接口上插着。", "error_description": "“过”表示曾经有过的经历，不能和“一直”一起表示持续的状态，此处应用“着”，说“一直在接口上插着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f66ecc78-2c2c-450c-8104-578991c72c7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
