INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24918, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "买到就是得到自己付钱想要的东西。", "primary_collocate": null, "pronunciation": "mǎi dào", "ipa": "mai̯˨˩˦ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "你买到你想要的衣服了吗？", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我买到了一双便宜的鞋。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的牛奶很好买到。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他去了三家店才买到这本书。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天太晚了，我没买到面包。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王买到了回家的车票。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药在小店里买到了吗？", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在书店买到了女儿喜欢的故事书。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那个玩具很难买到。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早上六点就去排队，终于买到了热包子。", "target_word": "买到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "买到了", "label": "体标（完成）"}, {"form": "买到过", "label": "体标（经历）"}, {"form": "买得到", "label": "可能补语（肯定）"}, {"form": "买不到", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "付钱得到想要的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba150852-d904-4479-b91a-fa17ed59eed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "买到", "is_correct": true, "explanation": "正确。“你……你想要的衣服了吗”，表示付钱得到想要的东西。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的对象是食物，衣服不能吃。"}, {"text": "喂饱", "is_correct": false, "explanation": "配价：“喂饱”要求有生命的受事，衣服不能被喂饱。"}, {"text": "唱完", "is_correct": false, "explanation": "语义：“唱完”的对象是歌曲等，不能用于衣服。"}], "explanations": {"买到": "正确。“你……你想要的衣服了吗”，表示付钱得到想要的东西。", "吃掉": "搭配：“吃掉”的对象是食物，衣服不能吃。", "喂饱": "配价：“喂饱”要求有生命的受事，衣服不能被喂饱。", "唱完": "语义：“唱完”的对象是歌曲等，不能用于衣服。"}, "sentence_index": 0, "correct_answer": "买到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在草丛里买到了丢失的戒指。", "explanation": "这里应该用〈找到〉。买到指付钱得到东西，丢失的戒指要找回来，不能买。"}, {"text": "我买到了朋友的生日祝福。", "explanation": "这里应该用〈收到〉。买到指付钱得到，祝福是别人送来的，要说收到。"}, {"text": "他在市场买到了一个老同学。", "explanation": "这里应该用〈遇到〉。买到指用钱换得可买卖的东西，在市场碰见老同学要说遇到，不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "买到", "is_correct": true, "explanation": "正确。“这种药在小店里……了吗”，表示买到。"}, {"text": "修好", "is_correct": false, "explanation": "搭配：“修好”的对象是能修的东西，药不能修。"}, {"text": "说出", "is_correct": false, "explanation": "语义：“说出”的对象是话语，药不能被说出来。"}, {"text": "点亮", "is_correct": false, "explanation": "语义：“点亮”的对象是灯火等，药不能被点亮。"}], "explanations": {"买到": "正确。“这种药在小店里……了吗”，表示买到。", "修好": "搭配：“修好”的对象是能修的东西，药不能修。", "说出": "语义：“说出”的对象是话语，药不能被说出来。", "点亮": "语义：“点亮”的对象是灯火等，药不能被点亮。"}, "sentence_index": 6, "correct_answer": "买到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她花钱买到了一片云。", "explanation": "这里应该用〈看到〉。买到指用钱换得可买卖的东西，天上的云不是商品，要说看到。"}, {"text": "他花钱买到了朋友的笑容。", "explanation": "这里应该用〈赢得〉。买到指用钱换得可买卖的东西，朋友的笑容要靠真心赢得，不能用钱买到。"}, {"text": "我花钱买到了一个明天。", "explanation": "这里应该用〈迎来〉。买到指用钱换得可买卖的东西，明天不是商品，要靠时间迎来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹已经在书店买到一本漫画书。", "corrected_sentence": "妹妹已经在书店买到了一本漫画书。", "error_description": "错误：“买到一本”；正确：“买到了一本”。“已经”表示动作已经完成，完成的“买到”后要加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们到得太晚，没买到了门票。", "corrected_sentence": "我们到得太晚，没买到门票。", "error_description": "错误：“没买到了”；正确：“没买到”。否定句中“没”与“了”不能同用，否定的结果补语后不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
