INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24920, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "心里觉得怎么样，比如冷、热、开心。", "primary_collocate": null, "pronunciation": "gǎn jué", "ipa": "kan˨˩˦ tɕɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "我感觉有点冷，想多穿一件衣服。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完药，他感觉头不疼了。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋子里太热，我感觉很难受。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天收到朋友的礼物，我感觉很开心。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "跑了一个小时，他感觉特别累。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个人在国外，我常常感觉很孤单。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站在台上，感觉心跳得很快。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐了一天车，妹妹感觉有点晕。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "喝了热茶以后，我感觉暖和多了。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "站在雪地里，我感觉手和脚都冻僵了。", "target_word": "感觉", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "感觉到", "label": "结果补语形式"}, {"form": "感觉了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "身体或心里觉得冷热、开心等状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 雪地 (Zipf 3.4), 冻 (Zipf 3.76), 僵 (Zipf 3.58)']::text[], 'd1031e19-faab-40d9-8d4c-621f2590ab55') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感觉", "is_correct": true, "explanation": "正确。这里指身体上冷的感受。"}, {"text": "判断", "is_correct": false, "explanation": "配价：“判断”需要带宾语，不能直接接“有点冷”。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，不能用来描述身体的冷暖感受。"}, {"text": "打算", "is_correct": false, "explanation": "搭配：“打算”后面要接计划或动作，“打算有点冷”搭配不当。"}], "explanations": {"感觉": "正确。这里指身体上冷的感受。", "判断": "配价：“判断”需要带宾语，不能直接接“有点冷”。", "讨厌": "语义：“讨厌”表示厌恶，不能用来描述身体的冷暖感受。", "打算": "搭配：“打算”后面要接计划或动作，“打算有点冷”搭配不当。"}, "sentence_index": 0, "correct_answer": "感觉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我感觉了一个生日蛋糕。", "explanation": "这里应该用〈买〉。感觉表示感受，不能表示购买或拿到实物。"}, {"text": "我感觉了一本小说。", "explanation": "这里应该用〈读〉。感觉表示心里的感受，不能表示阅读书籍。"}, {"text": "他感觉了一把伞。", "explanation": "这里应该用〈拿〉。感觉不表示拿取物品这类动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "感觉", "is_correct": true, "explanation": "正确。这里指他站在台上时心跳加快的身体感受。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：“忘记”表示遗忘，不能用来描述当下的身体感受，句意不通。"}, {"text": "希望", "is_correct": false, "explanation": "语义：“希望”表示期盼，与“心跳得很快”这种已经发生的感受不符。"}, {"text": "反对", "is_correct": false, "explanation": "配价：“反对”需要接对象或观点，不能直接接“心跳得很快”。"}], "explanations": {"感觉": "正确。这里指他站在台上时心跳加快的身体感受。", "忘记": "语义：“忘记”表示遗忘，不能用来描述当下的身体感受，句意不通。", "希望": "语义：“希望”表示期盼，与“心跳得很快”这种已经发生的感受不符。", "反对": "配价：“反对”需要接对象或观点，不能直接接“心跳得很快”。"}, "sentence_index": 6, "correct_answer": "感觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我感觉了一首歌。", "explanation": "这里应该用〈听〉。感觉不表示听取歌曲这类动作。"}, {"text": "他感觉了一场比赛。", "explanation": "这里应该用〈参加〉。感觉表示感受或想法，不能表示参与比赛。"}, {"text": "妈妈感觉了一顿晚饭。", "explanation": "这里应该用〈做〉。感觉不表示准备或制作食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我感觉得有点饿，想吃一点东西。", "corrected_sentence": "我感觉有点饿，想吃一点东西。", "error_description": "“感觉”后面不能直接用补语标记“得”引出状态，应说“感觉有点饿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐了一整天，感觉得特别累。", "corrected_sentence": "他坐了一整天，感觉特别累。", "error_description": "“感觉”后面不能加补语“得”。正确的说法是“感觉特别累”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25dba7a4-1b67-453f-ab61-ccae91d0c914') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
