INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很高的房子，里面有很多房间。", "primary_collocate": null, "pronunciation": "dà lóu", "ipa": "ta˥˩ lou̯˧˥", "syllable_count": 2, "sentences": [{"text": "我家附近新盖了一座大楼。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋大楼里有很多房间。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在大楼上，可以看到整个城市。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座大楼太高了，我不敢往下看。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼的门口站着一个保安。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在城中心的一栋大楼里。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我们先跑进大楼里。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座大楼没有电梯，爬上去很累。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看着窗外高高的大楼。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大楼里的每个房间都很干净。", "target_word": "大楼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "栋", "label": "量词"}, {"form": "大樓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很高、房间很多的房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ba150852-d904-4479-b91a-fa17ed59eed5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24922, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大楼", "is_correct": true, "explanation": "正确。大楼 dà lóu，指很高、房间很多的房子。"}, {"text": "大牢", "is_correct": false, "explanation": "láo（第二声）与 lóu（第二声）韵母不同，意思是大牢，指监狱。"}, {"text": "大头", "is_correct": false, "explanation": "tóu（第二声）与 lóu（第二声）声母不同，意思是大头。"}, {"text": "大路", "is_correct": false, "explanation": "lù（第四声）与 lóu（第二声）韵母和声调不同，意思是大路。"}], "explanations": {"大楼": "正确。大楼 dà lóu，指很高、房间很多的房子。", "大牢": "láo（第二声）与 lóu（第二声）韵母不同，意思是大牢，指监狱。", "大头": "tóu（第二声）与 lóu（第二声）声母不同，意思是大头。", "大路": "lù（第四声）与 lóu（第二声）韵母和声调不同，意思是大路。"}, "sentence_index": null, "correct_answer": "大楼"}, "level_3": {"options": [{"text": "大楼", "is_correct": true, "explanation": "正确。“新盖了一座”后面需要一个建筑，大楼正合适。"}, {"text": "山", "is_correct": false, "explanation": "搭配：“盖”用于人建造的东西，山是自然形成的，不能说盖。"}, {"text": "岛", "is_correct": false, "explanation": "搭配：岛是自然形成的陆地，不能说新盖了一座岛。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是文字作品，不是建筑，不能“盖”。"}], "explanations": {"大楼": "正确。“新盖了一座”后面需要一个建筑，大楼正合适。", "山": "搭配：“盖”用于人建造的东西，山是自然形成的，不能说盖。", "岛": "搭配：岛是自然形成的陆地，不能说新盖了一座岛。", "小说": "语义：小说是文字作品，不是建筑，不能“盖”。"}, "sentence_index": 0, "correct_answer": "大楼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼只有一个房间，很小，我们进去站一下就出来了。", "explanation": "这里应该用〈小屋〉。大楼指很高、房间很多的建筑，只有一个小房间的建筑要说小屋，不能说大楼。"}, {"text": "这座大楼矮矮的，我一伸手就能摸到屋顶。", "explanation": "这里应该用〈草棚〉。大楼指很高的建筑，又矮又简陋的棚子要说草棚，不能说大楼。"}, {"text": "我家对面有一块大楼，什么建筑都没有，孩子们在那里踢球。", "explanation": "这里应该用〈空地〉。大楼是有很多房间的建筑，什么建筑都没有的地方要说空地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24922, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大楼", "is_correct": true, "explanation": "正确。大楼 dà lóu，指很高、房间很多的房子。"}, {"text": "大笼", "is_correct": false, "explanation": "lóng（第二声）与 lóu（第二声）韵母不同，意思是大笼子。"}, {"text": "大牢", "is_correct": false, "explanation": "láo（第二声）与 lóu（第二声）韵母不同，意思是大牢，指监狱。"}, {"text": "大炉", "is_correct": false, "explanation": "lú（第二声）与 lóu（第二声）韵母不同，意思是大火炉。"}], "explanations": {"大楼": "正确。大楼 dà lóu，指很高、房间很多的房子。", "大笼": "lóng（第二声）与 lóu（第二声）韵母不同，意思是大笼子。", "大牢": "láo（第二声）与 lóu（第二声）韵母不同，意思是大牢，指监狱。", "大炉": "lú（第二声）与 lóu（第二声）韵母不同，意思是大火炉。"}, "sentence_index": null, "correct_answer": "大楼"}, "level_3": {"options": [{"text": "大楼", "is_correct": true, "explanation": "正确。“下雨了，我们先跑进……里”需要一个能躲雨的建筑，大楼正合适。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙是实体，人跑不进去，不能用来躲雨。"}, {"text": "河", "is_correct": false, "explanation": "语义：跑进河里是跳水，不是躲雨，与“先跑进”的语境不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“跑进”后面的地点要能容人，石头里面不能跑进去。"}], "explanations": {"大楼": "正确。“下雨了，我们先跑进……里”需要一个能躲雨的建筑，大楼正合适。", "墙": "语义：墙是实体，人跑不进去，不能用来躲雨。", "河": "语义：跑进河里是跳水，不是躲雨，与“先跑进”的语境不符。", "石头": "搭配：“跑进”后面的地点要能容人，石头里面不能跑进去。"}, "sentence_index": 6, "correct_answer": "大楼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们家是一座大楼，只有一层。", "explanation": "这里应该用〈平房〉。大楼指很高、房间很多的建筑，只有一层的房子不能说大楼。"}, {"text": "公园里有一大片大楼，长满了青草，我们在上面玩。", "explanation": "这里应该用〈草坪〉。大楼指很高的建筑，长满青草的平地要说草坪。"}, {"text": "我们用石头堆了一座大楼，只有半米高。", "explanation": "这里应该用〈石堆〉。大楼指很高、房间很多的建筑，半米高的石头堆要说石堆，不能说大楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司搬进了一只新大楼。", "corrected_sentence": "我们公司搬进了一栋新大楼。", "error_description": "错误：“一只大楼”；正确：“一栋大楼”。“只”多用于动物，大楼的量词应为“栋”或“座”，两句只有量词不同。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "街道对面有一座很高大楼。", "corrected_sentence": "街道对面有一座很高的大楼。", "error_description": "错误：“很高大楼”；正确：“很高的大楼”。修饰名词的形容词短语后面要加“的”，漏掉“的”不符合语法。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa9ffce2-6301-4596-a3e0-50b80ebb44d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
