INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24924, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "直直地上下和左右相交成直角。", "primary_collocate": null, "pronunciation": "chuí zhí", "ipa": "ʈʂʰueɪ³⁵ ʈʂɻ̩³⁵", "syllable_count": 2, "sentences": [{"text": "桌子的两条边互相垂直。", "target_word": "垂直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旗杆和地面是垂直的。", "target_word": "垂直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把这条线画得和那条垂直。", "target_word": "垂直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙应该和地面垂直，不然房子会歪。", "target_word": "垂直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他让梯子和墙保持垂直。", "target_word": "垂直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十字路口的两条马路互相垂直。", "target_word": "垂直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树干和地面基本垂直。", "target_word": "垂直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书的边和桌子的边垂直，放得很整齐。", "target_word": "垂直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画图时，横线和竖线要垂直。", "target_word": "垂直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座塔很高，几乎和地面垂直。", "target_word": "垂直", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "垂直线", "label": "复合"}, {"form": "垂直于", "label": "复合"}], "register": "中性", "sense_fingerprint": "日常说法：物体上下与左右直直相交成直角", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45fe73ad-99b7-41e9-9b37-32d47e8af85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24924, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”说多个物件排列有序，不能与“互相”搭配描述两条边的位置关系。"}, {"text": "垂直", "is_correct": true, "explanation": "垂直指两条边相交成直角，与“互相”搭配，符合句意。"}, {"text": "光滑", "is_correct": false, "explanation": "语义：“光滑”描述表面平滑，不说明两条边之间的相交关系。"}, {"text": "平稳", "is_correct": false, "explanation": "语义：“平稳”描述运动或状态安稳，与两条边的位置关系无关。"}], "explanations": {"整齐": "搭配：“整齐”说多个物件排列有序，不能与“互相”搭配描述两条边的位置关系。", "垂直": "垂直指两条边相交成直角，与“互相”搭配，符合句意。", "光滑": "语义：“光滑”描述表面平滑，不说明两条边之间的相交关系。", "平稳": "语义：“平稳”描述运动或状态安稳，与两条边的位置关系无关。"}, "sentence_index": 0, "correct_answer": "垂直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两根铁轨要保持垂直，火车才能安全行驶。", "explanation": "这里应该用〈平行〉。铁轨要并排延伸、互不相交，两轨成直角就无法安全行驶。"}, {"text": "杯子要放在垂直的桌面上，水才不会洒出来。", "explanation": "这里应该用〈水平〉。桌面竖起来，杯子里的水会全部洒出，只有水平的桌面才能保持水不洒。"}, {"text": "门框的上边和下边应该互相垂直。", "explanation": "这里应该用〈平行〉。门框的上边和下边应当并排、互不相交，不能互相垂直。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24924, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "结实", "is_correct": false, "explanation": "搭配：“结实”形容物体坚固，不用来说明树干与地面的位置关系。"}, {"text": "鲜艳", "is_correct": false, "explanation": "语义：“鲜艳”说颜色明亮，与树干和地面的几何位置无关。"}, {"text": "垂直", "is_correct": true, "explanation": "垂直指树干与地面近似成直角，与“基本”搭配，符合句意。"}, {"text": "弯曲", "is_correct": false, "explanation": "语义：“弯曲”说形状不直，与“基本……”描述的直角关系相反。"}], "explanations": {"结实": "搭配：“结实”形容物体坚固，不用来说明树干与地面的位置关系。", "鲜艳": "语义：“鲜艳”说颜色明亮，与树干和地面的几何位置无关。", "垂直": "垂直指树干与地面近似成直角，与“基本”搭配，符合句意。", "弯曲": "语义：“弯曲”说形状不直，与“基本……”描述的直角关系相反。"}, "sentence_index": 6, "correct_answer": "垂直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张示意图一看就懂，非常垂直。", "explanation": "这里应该用〈直观〉。垂直只描述线、面的几何位置，说图示容易看懂要用〈直观〉。"}, {"text": "操场的地面很垂直，适合跑步。", "explanation": "这里应该用〈平整〉。垂直指与地面成直角，地面竖起来无法跑步；说地面平坦要用〈平整〉。"}, {"text": "这条山路很垂直，适合散步。", "explanation": "这里应该用〈平缓〉。垂直指直角，不能用来形容适合散步的路；说坡度不陡要用〈平缓〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24924, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两根木棍应该互相得垂直。", "corrected_sentence": "这两根木棍应该互相垂直。", "error_description": "错误：“互相得垂直”；正确：“互相垂直”。“垂直”在此是形容词作谓语，前面不需要结构助词“得”，直接用“互相”作状语即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24924, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这根电线杆和地面是垂直。", "corrected_sentence": "这根电线杆和地面是垂直的。", "error_description": "错误：“是垂直”；正确：“是垂直的”。形容词“垂直”用在“是”后面作谓语时，要用“是……的”结构，句末不能少“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
