INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24926, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农民住和干活的地方。", "primary_collocate": null, "pronunciation": "nóng cūn", "ipa": "nʊŋ˧˥ tsʰuən˥", "syllable_count": 2, "sentences": [{"text": "农村是农民生活和种地的地方。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐了三个小时的车才到农村。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村里有很多田，也有小河。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年春节都带孩子回农村看父母。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我老家的农村很小，只有五十多户人家。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的早晨，鸡叫声常常把人叫醒。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天农村的晚上，大家喜欢坐在门口聊天。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小在农村帮妈妈种菜、喂鸡。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里太吵了，我想搬到农村住。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村的学校虽然小，但老师都很好。", "target_word": "农村", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "農村", "label": "繁体"}, {"form": "农村地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "农村：农民住和干活的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3caebe75-670d-474d-a611-b9d000242724') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24926, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "农村", "is_correct": true, "explanation": "农村是农民住和干活的地方，与句意完全一致。"}, {"text": "城市", "is_correct": false, "explanation": "语义：城市是人口密集的大城镇，不是农民种地的地方，与“农民”“种地”不符。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是治病的地方，与农民生活和种地无关。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“种地”一般在田地里进行，不能与工厂搭配。"}], "explanations": {"农村": "农村是农民住和干活的地方，与句意完全一致。", "城市": "语义：城市是人口密集的大城镇，不是农民种地的地方，与“农民”“种地”不符。", "医院": "语义：医院是治病的地方，与农民生活和种地无关。", "工厂": "搭配：“种地”一般在田地里进行，不能与工厂搭配。"}, "sentence_index": 0, "correct_answer": "农村"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我爸爸是一个农村。", "explanation": "这里应该用〈农民〉。农村指地方，指人要说农民。"}, {"text": "这些农村都放在仓库里。", "explanation": "这里应该用〈农具〉。农村是地方，不能像东西一样放进仓库。"}, {"text": "他从小就很会做农村。", "explanation": "这里应该用〈农活〉。农村指地方，不能被做；做的是农活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24926, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，晚上没有“坐在门口聊天”的情境，句意不通。"}, {"text": "农村", "is_correct": true, "explanation": "农村的夏夜常有人坐在门口聊天，与句中的情境相符。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“坐在门口聊天”多见于村子或住宅区，银行晚上不会有这种场景。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是学习用的书，不是地点，“课本的晚上”句意不通。"}], "explanations": {"冰箱": "语义：冰箱是家用电器，晚上没有“坐在门口聊天”的情境，句意不通。", "农村": "农村的夏夜常有人坐在门口聊天，与句中的情境相符。", "银行": "搭配：“坐在门口聊天”多见于村子或住宅区，银行晚上不会有这种场景。", "课本": "语义：课本是学习用的书，不是地点，“课本的晚上”句意不通。"}, "sentence_index": 6, "correct_answer": "农村"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农村要放在柜子里，不能让孩子碰。", "explanation": "这里应该用〈农药〉。农村是地方，不能放进柜子里；有毒的东西要放进柜子的是农药。"}, {"text": "玉米、小麦都是常见的农村。", "explanation": "这里应该用〈农作物〉。农村指地方，不指植物；玉米、小麦属于农作物。"}, {"text": "现在是农村季节，大家都很忙。", "explanation": "这里应该用〈农忙〉。农村指地方，不能指一个季节；忙碌的季节要说农忙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24926, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我小时候在一台农村住过。", "corrected_sentence": "我小时候在一个农村住过。", "error_description": "量词错误：“台”用于机器等物品，不能用来数农村，应说“一个农村”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24926, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她农村搬到城市里去了。", "corrected_sentence": "她从农村搬到城市里去了。", "error_description": "介词错误：表示起点时，“农村”前要加“从”，应说“她从农村搬到城市里去了”，不能省略“从”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
