INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以吃的东西。", "primary_collocate": null, "pronunciation": "shí wù", "ipa": "ʂɨ˧˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "这些食物都很新鲜。", "target_word": "食物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在找食物吃。", "target_word": "食物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里还有很多食物。", "target_word": "食物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不喜欢吃什么食物？", "target_word": "食物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们带了足够的食物去爬山。", "target_word": "食物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过期的食物不能吃。", "target_word": "食物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把食物放进了冰箱。", "target_word": "食物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方的食物又便宜又好吃。", "target_word": "食物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天来了，小鸟很难找到食物。", "target_word": "食物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，生病时要吃清淡的食物。", "target_word": "食物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "食物链", "label": "复合"}, {"form": "食物中毒", "label": "复合"}], "register": "中性", "sense_fingerprint": "可以吃的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '61123057-4989-4a95-82bf-725897152c51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24928, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "食物", "is_correct": true, "explanation": "正确：食物 shí wù（第二声、第四声）指可以吃的东西，与句意一致。"}, {"text": "事物", "is_correct": false, "explanation": "shì wù（第四声）与 shí wù（第二声）第一个音节声调不同，意思是事物，不指可以吃的东西。"}, {"text": "失误", "is_correct": false, "explanation": "shī wù（第一声）与 shí wù（第二声）第一个音节声调不同，意思是失误。"}, {"text": "石屋", "is_correct": false, "explanation": "shí wū（第一声）与 shí wù（第四声）第二个音节声调不同，意思是石头造的房子。"}], "explanations": {"食物": "正确：食物 shí wù（第二声、第四声）指可以吃的东西，与句意一致。", "事物": "shì wù（第四声）与 shí wù（第二声）第一个音节声调不同，意思是事物，不指可以吃的东西。", "失误": "shī wù（第一声）与 shí wù（第二声）第一个音节声调不同，意思是失误。", "石屋": "shí wū（第一声）与 shí wù（第四声）第二个音节声调不同，意思是石头造的房子。"}, "sentence_index": null, "correct_answer": "食物"}, "level_3": {"options": [{"text": "食物", "is_correct": true, "explanation": "正确：“食物”指可以吃的东西，可以用“新鲜”来形容，符合句意。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”不能用“新鲜”来形容，句子说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "搭配：“新鲜”多用于食物、空气等，不能用来形容“钢琴”。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“新鲜”多形容食物或空气，“窗户”不能说新鲜。"}], "explanations": {"食物": "正确：“食物”指可以吃的东西，可以用“新鲜”来形容，符合句意。", "石头": "语义：“石头”不能用“新鲜”来形容，句子说不通。", "钢琴": "搭配：“新鲜”多用于食物、空气等，不能用来形容“钢琴”。", "窗户": "搭配：“新鲜”多形容食物或空气，“窗户”不能说新鲜。"}, "sentence_index": 0, "correct_answer": "食物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他渴了，就去喝食物。", "explanation": "这里应该用〈饮料〉。食物指可以吃的东西，喝的东西要说〈饮料〉，不能说“喝食物”。"}, {"text": "我们在山上尽情呼吸食物。", "explanation": "这里应该用〈空气〉。食物不能呼吸，要说“呼吸空气”。"}, {"text": "他今天穿了新食物。", "explanation": "这里应该用〈衣服〉。食物不能穿，穿的东西要说〈衣服〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食物", "is_correct": true, "explanation": "正确：食物可以放进冰箱，符合“把……放进冰箱”的语境。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳无法放进冰箱，句子说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "体貌：钢琴体积太大，放不进冰箱，与句意不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无法被“放进”冰箱，句子不合理。"}], "explanations": {"食物": "正确：食物可以放进冰箱，符合“把……放进冰箱”的语境。", "太阳": "语义：太阳无法放进冰箱，句子说不通。", "钢琴": "体貌：钢琴体积太大，放不进冰箱，与句意不符。", "空气": "语义：空气无法被“放进”冰箱，句子不合理。"}, "sentence_index": 6, "correct_answer": "食物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用食物开门。", "explanation": "这里应该用〈钥匙〉。食物不能用来开门，开门的工具要说〈钥匙〉。"}, {"text": "手机没电了，他要给手机充食物。", "explanation": "这里应该用〈电〉。食物不能充进手机，给手机补充电量要说“充电”。"}, {"text": "他每天读食物两个小时。", "explanation": "这里应该用〈书〉。食物不能用来阅读，要说“读书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只食物很便宜。", "corrected_sentence": "这种食物很便宜。", "error_description": "量词错误：“只”多用于动物或成对的东西，修饰“食物”应该用“种”，应说“这种食物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把食物们装进了袋子里。", "corrected_sentence": "我把食物装进了袋子里。", "error_description": "“食物”是无生命的名词，不能加后缀“们”表示复数。应说“我把食物装进了袋子里”，不说“食物们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82282c0f-c852-4e81-8345-ad24bbafabfb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
