INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以吃的东西，比如米饭、水果、糖果。", "primary_collocate": null, "pronunciation": "shí pǐn", "ipa": "ʂɻ̩˧˥ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家店的食品又新鲜又便宜。", "target_word": "食品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "超市里的食品都要看日期。", "target_word": "食品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不要把食品放在太阳下面。", "target_word": "食品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶每个星期都去买食品。", "target_word": "食品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种食品里有很多糖，别吃太多。", "target_word": "食品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小孩子不能吃过期的食品。", "target_word": "食品", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家卖食品的公司工作。", "target_word": "食品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅行的时候，我会带一些食品。", "target_word": "食品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买食品以前，先看看上面写的字。", "target_word": "食品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱里的食品已经坏了，快扔掉。", "target_word": "食品", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "可以吃的东西的总称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '474535a0-0dad-4240-b06c-55efe2468b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24930, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "食品", "is_correct": true, "explanation": "正确。食品：可以吃的东西，此处指店里卖的吃的东西。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“新鲜”多用于食物，不能说“新鲜的衣服”。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍不能吃，也不能用“新鲜”来形容。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能吃，与“新鲜”的说法不合。"}], "explanations": {"食品": "正确。食品：可以吃的东西，此处指店里卖的吃的东西。", "衣服": "搭配：“新鲜”多用于食物，不能说“新鲜的衣服”。", "书籍": "语义：书籍不能吃，也不能用“新鲜”来形容。", "玩具": "语义：玩具不能吃，与“新鲜”的说法不合。"}, "sentence_index": 0, "correct_answer": "食品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天用食品写作业。", "explanation": "这里应该用〈铅笔〉。食品是可以吃的东西，不能用来写字。"}, {"text": "他早上用食品刷牙。", "explanation": "这里应该用〈牙膏〉。食品是可以吃的东西，不能用来刷牙。"}, {"text": "他用食品洗手。", "explanation": "这里应该用〈肥皂〉。食品是吃的东西，不能用来洗手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食品", "is_correct": true, "explanation": "正确。食品：可以吃的东西，此处指卖吃的东西的公司。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不能拿来买卖，与“卖”后接商品的意思不符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不是商品，“他在一家卖月亮的公司工作”说不通。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“卖”不跟“名字”搭配，不能说“卖名字”。"}], "explanations": {"食品": "正确。食品：可以吃的东西，此处指卖吃的东西的公司。", "天空": "语义：天空不能拿来买卖，与“卖”后接商品的意思不符。", "月亮": "语义：月亮不是商品，“他在一家卖月亮的公司工作”说不通。", "名字": "搭配：“卖”不跟“名字”搭配，不能说“卖名字”。"}, "sentence_index": 6, "correct_answer": "食品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生们在食品吃午饭。", "explanation": "这里应该用〈食堂〉。食品指吃的东西，不能指吃饭的地方。"}, {"text": "他每天穿着食品去上班。", "explanation": "这里应该用〈衣服〉。食品指可以吃的东西，不能用来穿。"}, {"text": "他累了，就坐在食品上休息。", "explanation": "这里应该用〈椅子〉。食品指可以吃的东西，不是用来坐的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家超市的食品们很多。", "corrected_sentence": "这家超市的食品很多。", "error_description": "错误：“食品们”。“食品”是集合名词，不能加“们”，应说“这家超市的食品很多”。“们”一般只用于指人的名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把那只食品吃完了。", "corrected_sentence": "我把那种食品吃完了。", "error_description": "量词错误：“那只食品”。“只”用于动物，“食品”这类东西应用“种”，应说“我把那种食品吃完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24932, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放心", "is_correct": true, "explanation": "“放心”与“担心”是反义词，表示不再担忧，与“担心”构成对立。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”是一种活动，与“担心”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "“游泳”是一种运动，与“担心”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”是一种行为，与“担心”没有反义关系。"}], "correct_answer": "放心", "explanations": {"放心": "“放心”与“担心”是反义词，表示不再担忧，与“担心”构成对立。", "散步": "“散步”是一种活动，与“担心”没有反义关系。", "游泳": "“游泳”是一种运动，与“担心”没有反义关系。", "唱歌": "“唱歌”是一种行为，与“担心”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24932, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放心", "is_correct": true, "explanation": "“放心”与“担心”是反义词，表示不再担忧，与“担心”构成对立。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”是一种运动，与“担心”没有反义关系。"}, {"text": "读书", "is_correct": false, "explanation": "“读书”是一种活动，与“担心”没有反义关系。"}, {"text": "画画", "is_correct": false, "explanation": "“画画”是一种爱好，与“担心”没有反义关系。"}], "correct_answer": "放心", "explanations": {"放心": "“放心”与“担心”是反义词，表示不再担忧，与“担心”构成对立。", "跑步": "“跑步”是一种运动，与“担心”没有反义关系。", "读书": "“读书”是一种活动，与“担心”没有反义关系。", "画画": "“画画”是一种爱好，与“担心”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24932, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "害怕不好的事情发生。", "primary_collocate": null, "pronunciation": "dān xīn", "ipa": "tan˥ ɕin˥", "syllable_count": 2, "sentences": [{"text": "妈妈很担心我的身体。", "target_word": "担心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "别担心，这个问题不难。", "target_word": "担心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他不来，我有点担心。", "target_word": "担心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下雨了，我担心他没带伞。", "target_word": "担心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你不用担心，我会照顾好孩子。", "target_word": "担心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她担心考试考不好，晚上睡不着。", "target_word": "担心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子这么晚还没回家，爸爸很担心。", "target_word": "担心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你一个人去，我一点也不担心。", "target_word": "担心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他担心过很多次，可是什么也没发生。", "target_word": "担心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说没事，大家都不用担心了。", "target_word": "担心", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "担心了", "label": "完成体"}, {"form": "担心过", "label": "经验体"}, {"form": "担心着", "label": "持续体"}, {"form": "擔心", "label": "繁体"}], "register": "中性", "sense_fingerprint": "因为怕坏事发生而心里不安", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9d72c37e-001c-46ce-9b8e-ae187f9ffc54') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24932, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "担心", "is_correct": true, "explanation": "“担心”表示因怕坏事发生而心里不安，与“妈妈很……我的身体”的关切语境相符，是唯一合适的选项。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，妈妈“讨厌”孩子的身体与关切的语境相反。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：“庆祝”用于喜事，不能用来对待身体，“很庆祝我的身体”句意不通。"}, {"text": "伤害", "is_correct": false, "explanation": "语义：“伤害”是损害，妈妈“伤害”孩子的身体与关切的语境正好相反。"}], "explanations": {"担心": "“担心”表示因怕坏事发生而心里不安，与“妈妈很……我的身体”的关切语境相符，是唯一合适的选项。", "讨厌": "语义：“讨厌”表示厌恶，妈妈“讨厌”孩子的身体与关切的语境相反。", "庆祝": "语义：“庆祝”用于喜事，不能用来对待身体，“很庆祝我的身体”句意不通。", "伤害": "语义：“伤害”是损害，妈妈“伤害”孩子的身体与关切的语境正好相反。"}, "sentence_index": 0, "correct_answer": "担心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "路上一定要担心，注意安全。", "explanation": "这里应该用〈小心〉。“担心”表示怕不好的事发生，提醒对方留意行动要用“小心”，不能说“担心”。"}, {"text": "你担心吧，我会照顾好他的。", "explanation": "这里是安慰对方，应该用〈放心〉。“担心”表示忧虑，与安慰的语境相反。"}, {"text": "我担心这座城市的夜景很美。", "explanation": "这里是赞美夜景，应该用〈欣赏〉。“担心”表示忧虑，与“很美”的赞美语境相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24932, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "担心", "is_correct": true, "explanation": "“担心”表示因怕坏事发生而心里不安，与“孩子晚归”的语境相符，是唯一合适的选项。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”表示喜爱，孩子晚归时爸爸不会“很喜欢”，与语境相反。"}, {"text": "同意", "is_correct": false, "explanation": "语义：“同意”表示赞成某种意见，孩子晚归时爸爸“很同意”，语义说不通。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示感激，孩子晚归时爸爸没有感谢的理由。"}], "explanations": {"担心": "“担心”表示因怕坏事发生而心里不安，与“孩子晚归”的语境相符，是唯一合适的选项。", "喜欢": "语义：“喜欢”表示喜爱，孩子晚归时爸爸不会“很喜欢”，与语境相反。", "同意": "语义：“同意”表示赞成某种意见，孩子晚归时爸爸“很同意”，语义说不通。", "感谢": "语义：“感谢”表示感激，孩子晚归时爸爸没有感谢的理由。"}, "sentence_index": 6, "correct_answer": "担心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我担心你考了好成绩，所以不高兴。", "explanation": "这里说的是好结果，应该用〈为……高兴〉。“担心”表示怕坏事发生，用于好结果时与“不高兴”的语境不符。"}, {"text": "今天是我的生日，我很担心，一直在笑。", "explanation": "这里描述生日时的快乐心情，应该用〈开心〉。“担心”表示怕坏事发生，与“生日”“一直在笑”的愉快语境相矛盾。"}, {"text": "他担心得很高兴，一直笑个不停。", "explanation": "这里描述心情，应该用〈高兴〉。“担心”表示忧虑，与“高兴”的状态相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24932, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我担心地很。", "corrected_sentence": "我担心得很。", "error_description": "错误：担心的补语“很”前应用“得”，说“担心得很”，不能用“地”。“地”引出修饰动词的状语，不能接“很”作补语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24932, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天的考试你不用担心过，早点睡觉吧。", "corrected_sentence": "明天的考试你不用担心，早点睡觉吧。", "error_description": "错误：“不用担心过”。“不用”劝对方现在或以后不要做某事，所以后面的“担心”不能带表示经历的“过”。正确的说法是“不用担心”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d4c3f44-8c4f-4a9e-a931-44df4946c2a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
