INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24934, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示程度比原来更高。", "primary_collocate": null, "pronunciation": "gèng jiā", "ipa": "kɤŋ˥˩ tɕja˥", "syllable_count": 2, "sentences": [{"text": "昨天很冷，今天更加冷了。", "target_word": "更加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很有意思，那本书更加有意思。", "target_word": "更加", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，空气更加新鲜了。", "target_word": "更加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他学了一年，说得更加流利了。", "target_word": "更加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的菜很好吃，那家店的菜更加好吃。", "target_word": "更加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了老师的话，我更加努力学习了。", "target_word": "更加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑以后，街上更加安静了。", "target_word": "更加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友来了，我们家更加热闹了。", "target_word": "更加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她本来就很漂亮，穿上新裙子更加漂亮了。", "target_word": "更加", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他本来就很忙，现在更加忙碌了。", "target_word": "更加", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "副词，放在形容词或动词前，表示程度比之前或比较对象更深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '60fb9430-b8df-4950-a53e-fc0e3676837a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24934, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "更加", "is_correct": true, "explanation": "“更加”表示程度比之前更深，与“昨天很冷”形成对比。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的经历，与“今天”的时间矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示进行中，不与表示完成变化的“冷了”搭配。"}, {"text": "仍然", "is_correct": false, "explanation": "语义：“仍然”表示状态延续，与“冷了”所表示的变化矛盾。"}], "explanations": {"更加": "“更加”表示程度比之前更深，与“昨天很冷”形成对比。", "曾经": "语义：“曾经”指过去的经历，与“今天”的时间矛盾。", "正在": "搭配：“正在”表示进行中，不与表示完成变化的“冷了”搭配。", "仍然": "语义：“仍然”表示状态延续，与“冷了”所表示的变化矛盾。"}, "sentence_index": 0, "correct_answer": "更加"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是更加唯一的一本字典。", "explanation": "这里不能用〈更加〉。〈唯一〉表示独一无二，没有程度之分，不能再用“更加”修饰。"}, {"text": "这两本书更加一样。", "explanation": "这里不能用〈更加〉。〈一样〉表示相同，没有程度可以加深，应说“这两本书一样”。"}, {"text": "这张照片更加黑白。", "explanation": "这里不能用〈更加〉。〈黑白〉指颜色种类，不能分程度，应说“这张照片是黑白的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24934, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "更加", "is_correct": true, "explanation": "“更加”表示程度比之前更深，天黑以后街上比白天更安静。"}, {"text": "总是", "is_correct": false, "explanation": "语义：“总是”表示一贯的习惯，不适合“天黑以后”这种一次性的变化。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作正在进行，不能修饰“安静了”这种表示状态变化的说法。"}, {"text": "仍旧", "is_correct": false, "explanation": "语义：“仍旧”表示状态没有改变，与“安静了”的变化矛盾。"}], "explanations": {"更加": "“更加”表示程度比之前更深，天黑以后街上比白天更安静。", "总是": "语义：“总是”表示一贯的习惯，不适合“天黑以后”这种一次性的变化。", "正在": "搭配：“正在”表示动作正在进行，不能修饰“安静了”这种表示状态变化的说法。", "仍旧": "语义：“仍旧”表示状态没有改变，与“安静了”的变化矛盾。"}, "sentence_index": 6, "correct_answer": "更加"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新国家更加诞生了。", "explanation": "这里不能用〈更加〉。〈诞生〉是一次性的事件，发生后不能再分程度。"}, {"text": "他的父亲更加去世了。", "explanation": "这里不能用〈更加〉。〈去世〉是一次性的事件，不能比较程度。"}, {"text": "他更加出生在上海。", "explanation": "这里不能用〈更加〉。〈出生〉是一次性的事件，不能用程度副词修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个房间比以前更加更干净了。", "corrected_sentence": "这个房间比以前更加干净了。", "error_description": "错误：“更加”前面又多加了一个“更”（更加更干净）。正确：只用“更加”，说“更加干净”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "最近的天气很更加凉爽了。", "corrected_sentence": "最近的天气更加凉爽了。", "error_description": "错误：“很”和“更加”都是程度副词，不能叠用。正确：去掉“很”，只用“更加”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af59f68c-12f2-4b76-a7d4-22045b744e01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
