INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24936, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "给人们需要的东西。", "primary_collocate": null, "pronunciation": "gōng yìng", "ipa": "kʊŋ˥ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这家工厂向全城供应牛奶。", "target_word": "供应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市每天供应新鲜的菜。", "target_word": "供应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天学校供应免费的凉茶。", "target_word": "供应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座水库每天向城里供应大量的饮用水。", "target_word": "供应", "complexity_tier": "T3", "furigana": "zhè zuò shuǐkù měitiān xiàng chénglǐ gōngyìng dàliàng de yǐnyòngshuǐ", "sentence_source": "generated"}, {"text": "山区的商店供应不上大米了。", "target_word": "供应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "食堂早上供应面包和牛奶。", "target_word": "供应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里二十四小时供应热水。", "target_word": "供应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场把新鲜的水果供应给附近的店。", "target_word": "供应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店供应的东西很多，也很便宜。", "target_word": "供应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店只供应午饭，不供应晚饭。", "target_word": "供应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "供应了", "label": "体标"}, {"form": "供应着", "label": "体标"}, {"form": "供应商", "label": "复合"}, {"form": "供應", "label": "繁体"}], "register": "中性", "sense_fingerprint": "供应：向人们提供所需的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '474535a0-0dad-4240-b06c-55efe2468b5f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24936, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "供应", "is_correct": true, "explanation": "正确。供应：向人们提供所需的物品。"}, {"text": "公用", "is_correct": false, "explanation": "yòng 与 yìng 的韵母不同（o 与 i），意思是公共使用，与“提供所需的物品”不符。"}, {"text": "公营", "is_correct": false, "explanation": "yíng（第二声）与 yìng（第四声）声调不同，意思是公家经营。"}, {"text": "工艺", "is_correct": false, "explanation": "yì 没有 ng 韵尾，意思是手工技艺。"}], "explanations": {"供应": "正确。供应：向人们提供所需的物品。", "公用": "yòng 与 yìng 的韵母不同（o 与 i），意思是公共使用，与“提供所需的物品”不符。", "公营": "yíng（第二声）与 yìng（第四声）声调不同，意思是公家经营。", "工艺": "yì 没有 ng 韵尾，意思是手工技艺。"}, "sentence_index": null, "correct_answer": "供应"}, "level_3": {"options": [{"text": "供应", "is_correct": true, "explanation": "正确。供应：向人们提供所需的物品，此处指工厂向全城提供牛奶。"}, {"text": "监督", "is_correct": false, "explanation": "搭配：“监督”的对象是人或工作，不能说“监督牛奶”。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”是去看地方或展览，不能用来指向城里送东西。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受，与句中工厂向城里送牛奶的意思相反。"}], "explanations": {"供应": "正确。供应：向人们提供所需的物品，此处指工厂向全城提供牛奶。", "监督": "搭配：“监督”的对象是人或工作，不能说“监督牛奶”。", "参观": "语义：“参观”是去看地方或展览，不能用来指向城里送东西。", "拒绝": "语义：“拒绝”是不接受，与句中工厂向城里送牛奶的意思相反。"}, "sentence_index": 0, "correct_answer": "供应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "灾区缺少医生，我们要去供应他们。", "explanation": "这里应该用〈支援〉。供应 只用于提供物资，派人去帮助灾区要用〈支援〉。"}, {"text": "他把自己的座位供应给了老人。", "explanation": "这里应该用〈让〉。供应 指向人们提供所需的物资，把座位让给别人要用〈让〉。"}, {"text": "老师供应了我很多好的建议。", "explanation": "这里应该用〈提供〉。供应 多用于物资，“建议”是抽象内容，要用〈提供〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24936, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "供应", "is_correct": true, "explanation": "正确。供应：向人们提供所需的物品。"}, {"text": "公益", "is_correct": false, "explanation": "yì 与 yìng 的韵尾不同（没有 ng），意思是公共利益。"}, {"text": "功用", "is_correct": false, "explanation": "yòng 与 yìng 的韵母不同（o 与 i），意思是作用。"}, {"text": "恭迎", "is_correct": false, "explanation": "yíng（第二声）与 yìng（第四声）声调不同，意思是恭敬地迎接。"}], "explanations": {"供应": "正确。供应：向人们提供所需的物品。", "公益": "yì 与 yìng 的韵尾不同（没有 ng），意思是公共利益。", "功用": "yòng 与 yìng 的韵母不同（o 与 i），意思是作用。", "恭迎": "yíng（第二声）与 yìng（第四声）声调不同，意思是恭敬地迎接。"}, "sentence_index": null, "correct_answer": "供应"}, "level_3": {"options": [{"text": "供应", "is_correct": true, "explanation": "正确。供应：向人们提供所需的物品，此处指二十四小时提供热水。"}, {"text": "感到", "is_correct": false, "explanation": "搭配：“感到”后接的是感受，不能说“感到热水”。"}, {"text": "观看", "is_correct": false, "explanation": "语义：“观看”是用眼睛看，与句中提供热水的意思不符。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”是拆掉，与“二十四小时……热水”的意思不符。"}], "explanations": {"供应": "正确。供应：向人们提供所需的物品，此处指二十四小时提供热水。", "感到": "搭配：“感到”后接的是感受，不能说“感到热水”。", "观看": "语义：“观看”是用眼睛看，与句中提供热水的意思不符。", "拆除": "语义：“拆除”是拆掉，与“二十四小时……热水”的意思不符。"}, "sentence_index": 6, "correct_answer": "供应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他按时供应房租，从不拖欠。", "explanation": "这里应该用〈支付〉。供应 指提供物资，按时付房租要用〈支付〉。"}, {"text": "这所学校供应了三十名新生。", "explanation": "这里应该用〈录取〉。供应 用于物资，招收新生要用〈录取〉。"}, {"text": "这家公司供应了大量的就业机会。", "explanation": "这里应该用〈提供〉。供应 多指日常物资的供给，就业机会是抽象的，要用〈提供〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24936, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家商店每天供应了新鲜的面包。", "corrected_sentence": "这家商店每天供应新鲜的面包。", "error_description": "错误：“供应了”。“每天”表示经常性的动作，不与“了”搭配，应说“这家商店每天供应新鲜的面包”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24936, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店把供应午饭。", "corrected_sentence": "这家店在供应午饭。", "error_description": "介词错误：“把”用错。“把”要求被处置的对象提到动词前，这里“供应”前没有对象；表示正在进行应用“在”，应说“这家店在供应午饭”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e47fe9b-3d79-4d9d-abf7-e34753d2a57d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
