INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一年里不同的时间，比如春天、夏天、秋天、冬天。", "primary_collocate": null, "pronunciation": "jì jié", "ipa": "tɕi˥˩ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "春天是我最喜欢的季节。", "target_word": "季节", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个季节常常下雨。", "target_word": "季节", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一年有四个季节。", "target_word": "季节", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "秋天是收获的季节。", "target_word": "季节", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不同的季节要穿不同的衣服。", "target_word": "季节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天是吃西瓜的好季节。", "target_word": "季节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在这个季节，山上的叶子都红了。", "target_word": "季节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你最喜欢哪个季节？", "target_word": "季节", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬天是北方最冷的季节，常常下雪。", "target_word": "季节", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个季节的水果又便宜又好吃。", "target_word": "季节", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "季节性", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：一年中按气候分出的时期（春夏秋冬）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b139088-ecac-459a-8b81-09a754a5d1d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24938, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "季节", "is_correct": true, "explanation": "季节（jì jié）：一年中按气候分出的时期，是正确答案。"}, {"text": "几节", "is_correct": false, "explanation": "几节（jǐ jié）：jǐ（第三声）与 jì（第四声）声调不同，意思是几段，如几节课。"}, {"text": "细节", "is_correct": false, "explanation": "细节（xì jié）：xì 与 jì 声母不同（x 与 j），意思是细小的部分。"}, {"text": "字节", "is_correct": false, "explanation": "字节（zì jié）：zì 与 jì 声母不同（z 与 j），意思是计算机存储的单位。"}], "explanations": {"季节": "季节（jì jié）：一年中按气候分出的时期，是正确答案。", "几节": "几节（jǐ jié）：jǐ（第三声）与 jì（第四声）声调不同，意思是几段，如几节课。", "细节": "细节（xì jié）：xì 与 jì 声母不同（x 与 j），意思是细小的部分。", "字节": "字节（zì jié）：zì 与 jì 声母不同（z 与 j），意思是计算机存储的单位。"}, "sentence_index": null, "correct_answer": "季节"}, "level_3": {"options": [{"text": "动物", "is_correct": false, "explanation": "语义：“春天”是时令，不能说最喜欢的动物。"}, {"text": "季节", "is_correct": true, "explanation": "季节：一年中按气候分出的时期，与“春天是我最喜欢的”相符。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“春天”不是学科，“最喜欢的数学”与句意不合。"}, {"text": "菜", "is_correct": false, "explanation": "语义：“春天”不能是菜，“最喜欢的菜”与句意不合。"}], "explanations": {"动物": "语义：“春天”是时令，不能说最喜欢的动物。", "季节": "季节：一年中按气候分出的时期，与“春天是我最喜欢的”相符。", "数学": "语义：“春天”不是学科，“最喜欢的数学”与句意不合。", "菜": "语义：“春天”不能是菜，“最喜欢的菜”与句意不合。"}, "sentence_index": 0, "correct_answer": "季节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个星期的季节很好。", "explanation": "这里应该用〈天气〉。季节指一年中的时段，一周内的天气状况不能说季节。"}, {"text": "这家店的季节很好。", "explanation": "这里应该用〈地点〉。季节指一年中的时段，店铺的位置要用地点。"}, {"text": "早上的季节很低。", "explanation": "这里应该用〈气温〉。季节不指温度高低，表示温度要用气温。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：“身高”描写人的身体，与叶子变红无关。"}, {"text": "季节", "is_correct": true, "explanation": "季节：一年中的时段，与“山上的叶子都红了”的秋季景象相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不能使叶子变红，与句意不合。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”不能使叶子变红，与句意不合。"}], "explanations": {"身高": "体貌：“身高”描写人的身体，与叶子变红无关。", "季节": "季节：一年中的时段，与“山上的叶子都红了”的秋季景象相符。", "年龄": "语义：“年龄”不能使叶子变红，与句意不合。", "味道": "语义：“味道”不能使叶子变红，与句意不合。"}, "sentence_index": 6, "correct_answer": "季节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些水果的季节很便宜。", "explanation": "这里应该用〈价格〉。季节不能说钱的多少，表示价钱要用价格。"}, {"text": "他的季节很高。", "explanation": "这里应该用〈身高〉。季节指时段，表示人的高矮要用身高。"}, {"text": "这辆车的季节很快。", "explanation": "这里应该用〈速度〉。季节不指快慢，表示快慢要用速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "地球上一年分为四次季节。", "corrected_sentence": "地球上一年分为四个季节。", "error_description": "量词错误：“季节”应用量词“个”，不能用“次”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春夏秋冬是四个季节们。", "corrected_sentence": "春夏秋冬是四个季节。", "error_description": "加“们”错误：“季节”指时段，不指人，不能加“们”，应删去“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '214fb5f7-35d5-48bc-b068-7e84c0cbfed4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24940, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "运走", "is_correct": true, "explanation": "运走：把东西运到别处去，与“运来”的方向相反。"}, {"text": "出售", "is_correct": false, "explanation": "出售指把东西卖给别人，与运送方向无关，不是“运来”的反义。"}, {"text": "保存", "is_correct": false, "explanation": "保存指把东西妥善留存，与运来没有反义关系。"}, {"text": "制作", "is_correct": false, "explanation": "制作指把材料做成物品，与运送方向无关，不是“运来”的反义。"}], "correct_answer": "运走", "explanations": {"运走": "运走：把东西运到别处去，与“运来”的方向相反。", "出售": "出售指把东西卖给别人，与运送方向无关，不是“运来”的反义。", "保存": "保存指把东西妥善留存，与运来没有反义关系。", "制作": "制作指把材料做成物品，与运送方向无关，不是“运来”的反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24940, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "运走", "is_correct": true, "explanation": "运走：把东西运到别处去，与“运来”的方向相反。"}, {"text": "购买", "is_correct": false, "explanation": "购买指用钱获得物品，不涉及运送方向，不是“运来”的反义。"}, {"text": "烹饪", "is_correct": false, "explanation": "烹饪指做饭做菜，与运送方向无关，不是“运来”的反义。"}, {"text": "冷藏", "is_correct": false, "explanation": "冷藏指用低温保存食物，与运来没有反义关系。"}], "correct_answer": "运走", "explanations": {"运走": "运走：把东西运到别处去，与“运来”的方向相反。", "购买": "购买指用钱获得物品，不涉及运送方向，不是“运来”的反义。", "烹饪": "烹饪指做饭做菜，与运送方向无关，不是“运来”的反义。", "冷藏": "冷藏指用低温保存食物，与运来没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24940, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用车或船把东西送过来。", "primary_collocate": null, "pronunciation": "yùn lái", "ipa": "yn˥˩ lai˧˥", "syllable_count": 2, "sentences": [{"text": "工人用大车把煤运来了。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的船运来了很多木头。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的牛奶都是早上运来的。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花是从云南运来的。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友给我们运来了一车苹果。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，船今天没能把货运来。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新衣服明天就会运来，请您再等一下。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人都在等卡车运来粮食。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子是用船从国外运来的。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店刚运来一批新鲜的鱼。", "target_word": "运来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "運來", "label": "繁体"}, {"form": "运来了", "label": "体标"}], "register": "中性", "sense_fingerprint": "运来：用车或船把东西送过来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3caebe75-670d-474d-a611-b9d000242724') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运来", "is_correct": true, "explanation": "运来表示用车把东西送过来，与“用大车把煤”“了”的语境相符。"}, {"text": "挖出", "is_correct": false, "explanation": "语义：“挖出”是动手掘取，不是用大车运送，与“用大车”矛盾。"}, {"text": "烧掉", "is_correct": false, "explanation": "语义：煤被烧掉不是用大车搬运，句意与“用大车把煤”不符。"}, {"text": "吃光", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃光煤”。"}], "explanations": {"运来": "运来表示用车把东西送过来，与“用大车把煤”“了”的语境相符。", "挖出": "语义：“挖出”是动手掘取，不是用大车运送，与“用大车”矛盾。", "烧掉": "语义：煤被烧掉不是用大车搬运，句意与“用大车把煤”不符。", "吃光": "搭配：“吃”的对象是食物，不能说“吃光煤”。"}, "sentence_index": 0, "correct_answer": "运来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次旅行给我运来了很多快乐。", "explanation": "这里应该用〈带来〉。运来用于运送实物，不用于快乐这类感受。"}, {"text": "我从朋友那里运来一个消息。", "explanation": "这里应该用〈听来〉。运来指运送实物，消息是听到的，不能被运来。"}, {"text": "他的话运来了不少麻烦。", "explanation": "这里应该用〈招来〉。运来用于实物，不用于麻烦这类抽象结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿破", "is_correct": false, "explanation": "语义：新衣服不会明天就穿破，且与“请您再等一下”的语境不符。"}, {"text": "运来", "is_correct": true, "explanation": "运来表示把衣服送过来，与“请您再等一下”的等待语境相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：衣服不会生病，“新衣服明天就会生病”句意不通。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说“吃掉新衣服”。"}], "explanations": {"穿破": "语义：新衣服不会明天就穿破，且与“请您再等一下”的语境不符。", "运来": "运来表示把衣服送过来，与“请您再等一下”的等待语境相符。", "生病": "语义：衣服不会生病，“新衣服明天就会生病”句意不通。", "吃掉": "搭配：“吃”的对象是食物，不能说“吃掉新衣服”。"}, "sentence_index": 6, "correct_answer": "运来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村里运来一名新干部。", "explanation": "这里应该用〈派来〉。运来用于货物，不用于人，派人要用派来。"}, {"text": "远处运来一阵歌声。", "explanation": "这里应该用〈传来〉。运来指运送实物，声音不能被运来。"}, {"text": "这篇文章运来了很多批评。", "explanation": "这里应该用〈引来〉。运来用于实物，不用于批评这类抽象结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些木头是从南方运来了的。", "corrected_sentence": "这些木头是从南方运来的。", "error_description": "时态助词错误：“是……的”句式中“运来”后不用“了”，应说“是从南方运来的”，不能说“运来了的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "港口的船今早运来来了一批煤。", "corrected_sentence": "港口的船今早运来了一批煤。", "error_description": "补语错误：“运来”中的“来”已是趋向补语，多写了一个“来”，应说“运来了一批煤”，不说“运来来了一批煤”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
