INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24942, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "太阳照出来的亮光。", "primary_collocate": null, "pronunciation": "yáng guāng", "ipa": "jɑŋ˧˥ kwɑŋ˥", "syllable_count": 2, "sentences": [{"text": "阳光从窗户照进房间。", "target_word": "阳光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天阳光很好，我们去公园吧。", "target_word": "阳光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在阳光下玩儿。", "target_word": "阳光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花需要水和阳光才能长大。", "target_word": "阳光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天的阳光太热了。", "target_word": "阳光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐在阳光里看书。", "target_word": "阳光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阳光照着小狗的脸。", "target_word": "阳光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上的阳光让房间很亮。", "target_word": "阳光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢躺在窗边享受阳光。", "target_word": "阳光", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗帘一开，阳光就进来了。", "target_word": "阳光", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缕", "label": "量词"}, {"form": "束", "label": "量词"}, {"form": "陽光", "label": "繁体"}], "register": "中性", "sense_fingerprint": "太阳发出的光线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '810ac7fa-1260-4d9e-be13-37017ce45fe6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24942, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雨水", "is_correct": false, "explanation": "搭配：“照进”的主语须是光，雨水不能照进房间。"}, {"text": "阳光", "is_correct": true, "explanation": "正确：阳光是太阳发出的光，可以从窗户照进房间。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指冷热阴晴等气候状况，不是光，不能“照进”房间。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：空气是无形的气体，不说“照进”，只有光线才能照进来。"}], "explanations": {"雨水": "搭配：“照进”的主语须是光，雨水不能照进房间。", "阳光": "正确：阳光是太阳发出的光，可以从窗户照进房间。", "天气": "语义：天气指冷热阴晴等气候状况，不是光，不能“照进”房间。", "空气": "搭配：空气是无形的气体，不说“照进”，只有光线才能照进来。"}, "sentence_index": 0, "correct_answer": "阳光"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "晚上我们在阳光下学习。", "explanation": "这里应该用〈灯光〉。阳光是白天太阳发出的光，晚上屋里没有阳光，要说灯光。"}, {"text": "他用布把阳光擦干净了。", "explanation": "这里应该用〈窗户〉。擦是擦玻璃、窗户等实物的动作，阳光是光，擦不到，也擦不干净。"}, {"text": "阳光把窗户打碎了。", "explanation": "这里应该用〈石头〉。阳光是光，打不碎窗户；打碎窗户要用「石头」等硬物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24942, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "泪水", "is_correct": false, "explanation": "搭配：“照着”的主语须是光，泪水不能照东西。"}, {"text": "阳光", "is_correct": true, "explanation": "正确：阳光可以照在小狗的脸上，符合句子的意思。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是光被挡住后留下的暗处，本身不会照东西。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能发出光去照小狗的脸。"}], "explanations": {"泪水": "搭配：“照着”的主语须是光，泪水不能照东西。", "阳光": "正确：阳光可以照在小狗的脸上，符合句子的意思。", "影子": "语义：影子是光被挡住后留下的暗处，本身不会照东西。", "小猫": "语义：小猫是动物，不能发出光去照小狗的脸。"}, "sentence_index": 6, "correct_answer": "阳光"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "阳光刮得很大，院子里的树都在响。", "explanation": "这里应该用〈风〉。刮是风的动作，阳光是太阳发出的光，不会刮。"}, {"text": "我们在阳光上种花。", "explanation": "这里应该用〈阳台〉。种花要有地方，阳光是光，不能当作种花的地方。"}, {"text": "阳光很硬，我的手碰上去都疼了。", "explanation": "这里应该用〈石头〉。硬是石头等实物的性质，阳光是光，没有硬度，碰不疼手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24942, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我喜欢在很亮阳光下散步。", "corrected_sentence": "我喜欢在很亮的阳光下散步。", "error_description": "“很亮”修饰“阳光”时，中间要加“的”，应说“很亮的阳光”；漏掉“的”就不自然。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24942, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗外射进一个阳光，落在桌上。", "corrected_sentence": "窗外射进一缕阳光，落在桌上。", "error_description": "量词错误：“阳光”的量词应用“缕”或“束”，不说“一个阳光”；应改为“一缕阳光”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '792dd777-1725-4a90-833e-a1a265eb0b88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
