INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种透明、可以喝、会流动的东西。", "primary_collocate": null, "pronunciation": "shuǐ", "ipa": "ʂuei˨˩˦", "syllable_count": 1, "sentences": [{"text": "桌子上有一杯水。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很渴，想喝水。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水从高处流到低处。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在河边喝水。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的水很凉。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以带一瓶水去学校。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在雨后的水里玩。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水流得很快。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这水可以喝，很干净。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把水倒进杯子里。", "target_word": "水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯", "label": "量词"}, {"form": "瓶", "label": "量词"}], "register": "中性", "sense_fingerprint": "水|透明、可以喝、会流动的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d87bd1f-744f-4914-a5d1-ee173b9f4aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24944, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "水", "is_correct": true, "explanation": "shuǐ（第三声）：透明、可以喝、会流动的东西，即“水”。"}, {"text": "谁", "is_correct": false, "explanation": "shuí（第二声）与 shuǐ（第三声）声调不同，意思是“谁”。"}, {"text": "睡", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是“睡”。"}, {"text": "鼠", "is_correct": false, "explanation": "shǔ 与 shuǐ 韵母不同：shǔ 为 u，shuǐ 为 ui，意思是“老鼠”。"}], "explanations": {"水": "shuǐ（第三声）：透明、可以喝、会流动的东西，即“水”。", "谁": "shuí（第二声）与 shuǐ（第三声）声调不同，意思是“谁”。", "睡": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是“睡”。", "鼠": "shǔ 与 shuǐ 韵母不同：shǔ 为 u，shuǐ 为 ui，意思是“老鼠”。"}, "sentence_index": null, "correct_answer": "水"}, "level_3": {"options": [{"text": "水", "is_correct": true, "explanation": "“一杯水”符合句意，水是可以盛在杯子里的透明液体。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，不能像液体那样盛在杯子里。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：量词“杯”不用于石头，石头应说“块”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“杯”不用于书，书应说“本”。"}], "explanations": {"水": "“一杯水”符合句意，水是可以盛在杯子里的透明液体。", "空气": "语义：空气看不见，不能像液体那样盛在杯子里。", "石头": "搭配：量词“杯”不用于石头，石头应说“块”。", "书": "搭配：量词“杯”不用于书，书应说“本”。"}, "sentence_index": 0, "correct_answer": "水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "炉子里的水很旺，快添柴吧。", "explanation": "这里应该用〈火〉。“旺”说的是火，水不能说“旺”。"}, {"text": "天黑了，请把水打开，屋里太暗了。", "explanation": "这里应该用〈灯〉。“打开”后让屋里变亮的是灯，水不能照亮屋子。"}, {"text": "我用刀把这杯水切开，分给大家。", "explanation": "这里应该用〈豆腐〉。“切开、分给大家”说的是有形状的固体食物，水是液体，不能切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24944, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "水", "is_correct": true, "explanation": "shuǐ（第三声）：透明、可以喝、会流动的东西，即“水”。"}, {"text": "税", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是“税”。"}, {"text": "毁", "is_correct": false, "explanation": "huǐ（第三声）与 shuǐ 声母不同（h 与 sh），意思是“毁坏”。"}, {"text": "耍", "is_correct": false, "explanation": "shuǎ（第三声）与 shuǐ 韵母不同（ua 与 ui），意思是“耍”。"}], "explanations": {"水": "shuǐ（第三声）：透明、可以喝、会流动的东西，即“水”。", "税": "shuì（第四声）与 shuǐ（第三声）声调不同，意思是“税”。", "毁": "huǐ（第三声）与 shuǐ 声母不同（h 与 sh），意思是“毁坏”。", "耍": "shuǎ（第三声）与 shuǐ 韵母不同（ua 与 ui），意思是“耍”。"}, "sentence_index": null, "correct_answer": "水"}, "level_3": {"options": [{"text": "水", "is_correct": true, "explanation": "孩子们可以在雨后积起的水里玩，“水里”符合句意。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是可以让人“在里面玩”的场所。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是固体，不能说“在木头里玩”。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“在……里玩”要搭配可以容纳人活动的场所，钢笔不搭配。"}], "explanations": {"水": "孩子们可以在雨后积起的水里玩，“水里”符合句意。", "饭": "语义：饭不是可以让人“在里面玩”的场所。", "木头": "语义：木头是固体，不能说“在木头里玩”。", "钢笔": "搭配：“在……里玩”要搭配可以容纳人活动的场所，钢笔不搭配。"}, "sentence_index": 6, "correct_answer": "水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "窗台上的水很脆，别碰碎了。", "explanation": "这里应该用〈玻璃〉。水是液体，没有脆性；“碰碎”说的是玻璃这类固体。"}, {"text": "地里的水用手能捏成团。", "explanation": "这里应该用〈泥〉。“捏成团”说的是泥土这类可塑的东西，水是液体，不能捏成团。"}, {"text": "水很硬，不容易弯。", "explanation": "这里应该用〈铁〉。“硬”和“不容易弯”说的是金属，水是液体，不能这样说。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的书包里有一块水。", "corrected_sentence": "我的书包里有一瓶水。", "error_description": "量词错误：“水”应该用“瓶”或“杯”计量，“块”用于固体，不能用于水。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子渴了，要吃一杯水。", "corrected_sentence": "孩子渴了，要喝一杯水。", "error_description": "搭配错误：“水”应与动词“喝”搭配，说“喝水”；“吃”不能用于水。只需把“吃”改为“喝”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a03281-d422-4dcf-b9b4-5440a5a652ee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
