INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很大的电影。", "primary_collocate": null, "pronunciation": "dà piàn", "ipa": "ta˥˩ pʰjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "今晚电影院要放一部新的大片。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部大片的场面特别大。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们都想去看那部动画大片。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢在家用大屏幕看大片。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部大片有很多有名的演员。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的春节大片我都看过。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看大片的时候，我常常买爆米花。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友请我周末一起看大片。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部大片又长又好看，我看了三个小时。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影院的大银幕最适合看大片。", "target_word": "大片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "好莱坞大片", "label": "复合"}, {"form": "贺岁大片", "label": "复合"}], "register": "口语", "sense_fingerprint": "大片|很大的电影", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3caebe75-670d-474d-a611-b9d000242724') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24946, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大片", "is_correct": true, "explanation": "“大片”（dà piàn）指很大的电影。"}, {"text": "大件", "is_correct": false, "explanation": "“件”（jiàn）与“片”（piàn）声母不同（j 与 p），意思是体积大的物品。"}, {"text": "大变", "is_correct": false, "explanation": "“变”（biàn）与“片”（piàn）声母不同（b 与 p），意思是很大的变化。"}, {"text": "大殿", "is_correct": false, "explanation": "“殿”（diàn）与“片”（piàn）声母不同（d 与 p），意思是高大的殿堂。"}], "explanations": {"大片": "“大片”（dà piàn）指很大的电影。", "大件": "“件”（jiàn）与“片”（piàn）声母不同（j 与 p），意思是体积大的物品。", "大变": "“变”（biàn）与“片”（piàn）声母不同（b 与 p），意思是很大的变化。", "大殿": "“殿”（diàn）与“片”（piàn）声母不同（d 与 p），意思是高大的殿堂。"}, "sentence_index": null, "correct_answer": "大片"}, "level_3": {"options": [{"text": "唱片", "is_correct": false, "explanation": "搭配：电影院放映的是影片，“唱片”不能在电影院里放映。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说是供人阅读的，不能在电影院放映。"}, {"text": "大片", "is_correct": true, "explanation": "“一部新的大片”指新上映的大型电影，可以在电影院放映。"}, {"text": "文件", "is_correct": false, "explanation": "语义：文件不能在电影院里放映。"}], "explanations": {"唱片": "搭配：电影院放映的是影片，“唱片”不能在电影院里放映。", "小说": "语义：小说是供人阅读的，不能在电影院放映。", "大片": "“一部新的大片”指新上映的大型电影，可以在电影院放映。", "文件": "语义：文件不能在电影院里放映。"}, "sentence_index": 0, "correct_answer": "大片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地上种着大片的玉米。", "explanation": "这里的“大片”指成片的面积，是另一个意思，不是“很大的电影”。"}, {"text": "这部大片是作家十年的心血，写了一千多页。", "explanation": "这里应该用〈小说〉。大片指电影，不能用来说写了一千多页的作品，这里应说“小说”。"}, {"text": "这部大片一共有五十集。", "explanation": "这里应该用〈电视剧〉。大片是一部完整的电影，不分集。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报纸", "is_correct": false, "explanation": "语义：报纸是供人阅读的印刷品，与买爆米花的场景不合。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是用来读的书，与买爆米花的场景不合。"}, {"text": "大片", "is_correct": true, "explanation": "“看大片”指看大型电影，买爆米花是看电影时常见的事。"}, {"text": "乐曲", "is_correct": false, "explanation": "搭配：“看”不搭配“乐曲”，乐曲要听。"}], "explanations": {"报纸": "语义：报纸是供人阅读的印刷品，与买爆米花的场景不合。", "课本": "语义：课本是用来读的书，与买爆米花的场景不合。", "大片": "“看大片”指看大型电影，买爆米花是看电影时常见的事。", "乐曲": "搭配：“看”不搭配“乐曲”，乐曲要听。"}, "sentence_index": 6, "correct_answer": "大片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部大片只有十分钟，适合在课堂上放映。", "explanation": "这里应该用〈短片〉。大片指规模很大的电影，只有十分钟的片子不能叫大片。"}, {"text": "我们周末在电脑上玩大片。", "explanation": "这里应该用〈游戏〉。大片是用来看的电影，不能说“玩”。"}, {"text": "大片在剧场演出，观众很多。", "explanation": "这里应该用〈话剧〉。大片是电影，要在影院放映，不在剧场演出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家影院下周末会放一只新的大片。", "corrected_sentence": "这家影院下周末会放一部新的大片。", "error_description": "量词错误：“只”用于动物、船等单个的东西，不能用来数大片，应说“一部新的大片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们周末去看着大片。", "corrected_sentence": "我们周末去看了大片。", "error_description": "体标错误：“看着”；正确：“看了”。“着”表示状态持续，句中说的是周末已经完成的动作，应用“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
