INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24948, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "为了以后有好处，先想好办法。", "primary_collocate": null, "pronunciation": "zhàn lüè xìng", "ipa": "ʈʂan˥˩ lɥe˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "他先学英语，是一个战略性的选择。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司现在少赚钱，是战略性的安排。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了以后卖得更多，商店做了战略性降价。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店战略性地送出了很多小礼物。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他先让对手赢一局，这是战略性的做法。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司战略性地把新店开在学校旁边。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板战略性地降低价格，想留住老客人。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她战略性地先不回答，想看看别人怎么说。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队战略性地让主力休息，准备下一场比赛。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先做小生意，再做大生意，这很有战略性。", "target_word": "战略性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "战略性思维", "label": "复合"}, {"form": "战略性投资", "label": "复合"}], "register": "书面", "sense_fingerprint": "为以后的好处先做安排的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4210cd39-20e1-42e6-8e4f-325ff395f566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "战略性", "is_correct": true, "explanation": "正确：修饰“选择”，指为以后的好处先做打算，与“先学英语”的安排相合。"}, {"text": "随意性", "is_correct": false, "explanation": "语义：“随意性”指没有计划，与“先学英语”这种有意的安排相反。"}, {"text": "偶然性", "is_correct": false, "explanation": "语义：“偶然性”指出于意外，与“先学英语”这种预先的考虑不合。"}, {"text": "被动性", "is_correct": false, "explanation": "搭配：“被动性”多用于局面、状态，不常用来修饰“选择”。"}], "explanations": {"战略性": "正确：修饰“选择”，指为以后的好处先做打算，与“先学英语”的安排相合。", "随意性": "语义：“随意性”指没有计划，与“先学英语”这种有意的安排相反。", "偶然性": "语义：“偶然性”指出于意外，与“先学英语”这种预先的考虑不合。", "被动性": "搭配：“被动性”多用于局面、状态，不常用来修饰“选择”。"}, "sentence_index": 0, "correct_answer": "战略性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他战略性地忘了作业，老师很生气。", "explanation": "这里应该用〈疏忽〉。“战略性”指有意识地预先筹划，而“忘了作业”是无意的疏忽，二者不能搭配。"}, {"text": "我战略性地把钥匙丢在了车上。", "explanation": "这里应该用〈无意〉。丢钥匙是无心之失，“战略性”指有计划地为以后打算，二者相反。"}, {"text": "他太累了，战略性地睡着了。", "explanation": "这里应该用〈不知不觉〉。睡着是不受控制的，不能事先筹划；“战略性”指为了以后的好处有意先做安排。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战略性", "is_correct": true, "explanation": "正确：修饰动作“降低价格”，说明事先筹划以留住老客人，与句意相合。"}, {"text": "任性", "is_correct": false, "explanation": "语域：“任性”口语色彩较强，与书面语境不合，且与“想留住老客人”的目的相抵。"}, {"text": "冲动", "is_correct": false, "explanation": "语义：“冲动”指不加考虑地行动，与“想留住老客人”的有意目的矛盾。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“随便”指不经考虑、不加挑选，与“想留住老客人”的目的不合。"}], "explanations": {"战略性": "正确：修饰动作“降低价格”，说明事先筹划以留住老客人，与句意相合。", "任性": "语域：“任性”口语色彩较强，与书面语境不合，且与“想留住老客人”的目的相抵。", "冲动": "语义：“冲动”指不加考虑地行动，与“想留住老客人”的有意目的矛盾。", "随便": "语义：“随便”指不经考虑、不加挑选，与“想留住老客人”的目的不合。"}, "sentence_index": 6, "correct_answer": "战略性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一看到打折就战略性地买东西，毫无计划。", "explanation": "这里应该用〈随意〉。“一看到打折就买”说明没有事先筹划，“战略性”指为以后的好处预先考虑，二者矛盾。"}, {"text": "听完笑话，他战略性地笑了起来。", "explanation": "这里应该用〈忍不住〉。听笑话发笑是自然反应，不是为以后的好处事先安排的，不能用“战略性”。"}, {"text": "他冲着老板战略性地发了火。", "explanation": "这里应该用〈冲动〉。发火是即时的情绪反应，“战略性”指为以后的好处先做打算，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他战略性得决定先不回答。", "corrected_sentence": "他战略性地决定先不回答。", "error_description": "助词误用：修饰动词的状语应用“地”，此处误用补语标记“得”；应为“战略性地决定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司战略性得先收购了一家小工厂。", "corrected_sentence": "这家公司战略性地先收购了一家小工厂。", "error_description": "助词误用：修饰动词“收购”的状语应用“地”，此处误用“得”；应为“战略性地先收购”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
