INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市里的长草和树的地方，可以去玩。", "primary_collocate": null, "pronunciation": "chéng shì lǜ dì", "ipa": "ʈʂʰɤŋ˧˥ ʂɻ̩˥˩ ly˥˩ ti˥˩", "syllable_count": 4, "sentences": [{"text": "我家旁边有一块城市绿地。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市绿地里有草，也有树。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课后，我们去城市绿地玩。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带着狗到城市绿地跑步。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市绿地不大，但是很干净。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天，城市绿地里开了很多花。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在城市绿地踢球。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，大家喜欢在城市绿地坐一坐。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市绿地的草很绿。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在城市绿地吃了午饭。", "target_word": "城市绿地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块城市绿地", "label": "量词"}, {"form": "一片城市绿地", "label": "量词"}, {"form": "城市绿地面积", "label": "复合"}, {"form": "城市綠地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "城市里有草有树、可以去玩的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '871aef36-6f52-465a-aab9-0f77eb16f723') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "城市绿地", "is_correct": true, "explanation": "城市绿地：有草有树、可以去玩的地方，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“块”用于有形的块状物，空气不能用“一块”计量。"}, {"text": "星期", "is_correct": false, "explanation": "搭配：“块”不能用于时间单位，“一块星期”搭配不当。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：“游戏”不是可以占地的场所，“一块游戏”句意不通。"}], "explanations": {"城市绿地": "城市绿地：有草有树、可以去玩的地方，符合句意。", "空气": "搭配：“块”用于有形的块状物，空气不能用“一块”计量。", "星期": "搭配：“块”不能用于时间单位，“一块星期”搭配不当。", "游戏": "语义：“游戏”不是可以占地的场所，“一块游戏”句意不通。"}, "sentence_index": 0, "correct_answer": "城市绿地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "城市绿地有三层楼，里面有很多店。", "explanation": "这里应该用〈商场〉。城市绿地是有草有树的户外场所，没有楼层和店铺，说有几层楼要用商场。"}, {"text": "我在城市绿地里洗了个热水澡。", "explanation": "这里应该用〈浴室〉。城市绿地是有草有树的户外场所，洗热水澡要在浴室。"}, {"text": "我家的城市绿地里有一台电视机。", "explanation": "这里应该用〈客厅〉。城市绿地是露天的公共场所，摆放电视机要说客厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "城市绿地", "is_correct": true, "explanation": "城市绿地：有草有树、可以玩耍的户外场所，符合句意。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆要求安静，不能在里面踢球，句意冲突。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是医疗场所，不能在里面踢球，句意冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不是可以踢球的场所，搭配不当。"}], "explanations": {"城市绿地": "城市绿地：有草有树、可以玩耍的户外场所，符合句意。", "图书馆": "语义：图书馆要求安静，不能在里面踢球，句意冲突。", "医院": "语义：医院是医疗场所，不能在里面踢球，句意冲突。", "冰箱": "搭配：“冰箱”不是可以踢球的场所，搭配不当。"}, "sentence_index": 6, "correct_answer": "城市绿地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在城市绿地里做了一次手术。", "explanation": "这里应该用〈医院〉。城市绿地是户外场所，做手术要在医院进行，不能在绿地里做。"}, {"text": "妈妈把牛奶放进了城市绿地。", "explanation": "这里应该用〈冰箱〉。城市绿地是户外场所，不能放牛奶保鲜，放牛奶要用冰箱。"}, {"text": "我们在城市绿地里考了一场期末考试。", "explanation": "这里应该用〈教室〉。城市绿地是户外休闲场所，考试要在教室里进行，不能在绿地里考。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这所城市绿地每天都有很多人来散步。", "corrected_sentence": "这片城市绿地每天都有很多人来散步。", "error_description": "量词用错：“城市绿地”应配“片”或“块”，“所”用于学校、医院等机构，不能用于绿地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些城市绿地们都很干净。", "corrected_sentence": "这些城市绿地都很干净。", "error_description": "词缀用错：“城市绿地”是无生命的事物，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '36b2a15f-28d7-4928-8c20-65c2c3c46dfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
