INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24952, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "楼顶是房子的最上面。", "primary_collocate": null, "pronunciation": "lóu dǐng", "ipa": "lou˧˥ tiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这栋楼的楼顶很平，可以放很多花盆。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，楼顶上有很多水。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不能一个人上楼顶玩。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从楼顶往下看，车像小盒子一样。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家住六楼，楼顶就在上面。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼顶有太阳能板，家里一直有热水。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在楼顶挂了一面大红旗。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼顶没有人，非常安静。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟儿飞到楼顶，停在栏杆上。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼顶太热了，中午别上去。", "target_word": "楼顶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "樓頂", "label": "繁体"}, {"form": "楼顶花园", "label": "复合"}], "register": "中性", "sense_fingerprint": "楼顶：房子的最上面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3caebe75-670d-474d-a611-b9d000242724') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "楼梯", "is_correct": false, "explanation": "体貌：楼梯有一级级的台阶，不平，与“很平”矛盾。"}, {"text": "楼顶", "is_correct": true, "explanation": "“楼顶”是房子最上面的平面，很平，可以放花盆。"}, {"text": "大门", "is_correct": false, "explanation": "语义：大门是出入口，不能用来摆放很多花盆。"}, {"text": "山坡", "is_correct": false, "explanation": "搭配：“这栋楼的”后面不能接“山坡”，而且山坡也不平。"}], "explanations": {"楼梯": "体貌：楼梯有一级级的台阶，不平，与“很平”矛盾。", "楼顶": "“楼顶”是房子最上面的平面，很平，可以放花盆。", "大门": "语义：大门是出入口，不能用来摆放很多花盆。", "山坡": "搭配：“这栋楼的”后面不能接“山坡”，而且山坡也不平。"}, "sentence_index": 0, "correct_answer": "楼顶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "楼顶的邻居半夜总是弹钢琴，吵得我睡不着。", "explanation": "这里应该用〈楼上〉。“楼上”是我家的上一层，“楼顶”是房子最上面的顶部，不能指邻居所在的位置。"}, {"text": "他把自行车放在楼顶的地下室里。", "explanation": "这里应该用〈楼下〉。地下室在房子最下面，“楼顶”是房子最上面，二者位置矛盾。"}, {"text": "楼顶共有三十层，电梯每天运行。", "explanation": "这里应该用〈楼房〉。楼房整栋可以说有几层，“楼顶”只是最上面的部分，不能说有几层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地板", "is_correct": false, "explanation": "搭配：挂旗要挂在竖直的面上，“地板”是水平的，不能挂旗。"}, {"text": "楼顶", "is_correct": true, "explanation": "“楼顶”是可以悬挂东西的高处，适合挂旗。"}, {"text": "水井", "is_correct": false, "explanation": "语义：水井是取水的深坑，不能在里面挂旗。"}, {"text": "石桌", "is_correct": false, "explanation": "体貌：石桌是平放的桌面，挂不了旗。"}], "explanations": {"地板": "搭配：挂旗要挂在竖直的面上，“地板”是水平的，不能挂旗。", "楼顶": "“楼顶”是可以悬挂东西的高处，适合挂旗。", "水井": "语义：水井是取水的深坑，不能在里面挂旗。", "石桌": "体貌：石桌是平放的桌面，挂不了旗。"}, "sentence_index": 6, "correct_answer": "楼顶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家住在楼顶的一楼，窗户朝南。", "explanation": "这里应该用〈顶楼〉。“楼顶”是房子最上面的顶部，与“一楼”矛盾；住最上一层应说“顶楼”。"}, {"text": "楼顶的老人很爱养花，院子里摆满了花盆。", "explanation": "这里应该用〈楼下〉。住在低层、在院子里养花应说“楼下”，“楼顶”与“院子里”的位置矛盾。"}, {"text": "楼顶的门厅很宽，可以停放自行车。", "explanation": "这里应该用〈一楼〉。门厅在最底层，应说“一楼”，“楼顶”不能指门厅所在的位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把衣服挂在一座楼顶上了。", "corrected_sentence": "她把衣服挂在楼顶上了。", "error_description": "量词错误：“座”用于楼房、山等大型建筑或山体，不能用来数“楼顶”，应直接说“挂在楼顶上”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他那天爬了上楼顶，找到了丢的风筝。", "corrected_sentence": "他那天爬上了楼顶，找到了丢的风筝。", "error_description": "“了”位置错误：“了”应紧跟补语“上”，说“爬上了楼顶”，不能说“爬了上楼顶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
