INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24954, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24954, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "图景就是看到的画面或样子。", "primary_collocate": null, "pronunciation": "tú jǐng", "ipa": "tʰu˧˥ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "山上的春天是一幅美丽的图景。", "target_word": "图景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给我们讲了未来城市的图景。", "target_word": "图景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们一起玩，这是一幅温暖的图景。", "target_word": "图景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她心里总有一幅回家的图景。", "target_word": "图景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里描写了一幅古代生活的图景。", "target_word": "图景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外下着雪，是一幅安静的图景。", "target_word": "图景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着眼前的图景，说不出话来。", "target_word": "图景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们画出心中的图景。", "target_word": "图景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边日落的图景让人难忘。", "target_word": "图景", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家写出了农村生活的图景。", "target_word": "图景", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幅", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "眼前或想象中的画面、景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cdc1bb5e-b14c-41de-8ff0-76ccf8bb8da0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24954, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地图", "is_correct": false, "explanation": "语义：地图是示意图，不是春天的景象，句意不通。"}, {"text": "图景", "is_correct": true, "explanation": "图景：指眼前或想象中的画面，与“山上的春天”相合。"}, {"text": "书法", "is_correct": false, "explanation": "语义：书法是写字的艺术，不描绘春天的景象。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“幅”用于画面、字画，不能用来数地毯。"}], "explanations": {"地图": "语义：地图是示意图，不是春天的景象，句意不通。", "图景": "图景：指眼前或想象中的画面，与“山上的春天”相合。", "书法": "语义：书法是写字的艺术，不描绘春天的景象。", "地毯": "搭配：“幅”用于画面、字画，不能用来数地毯。"}, "sentence_index": 0, "correct_answer": "图景"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上挂着一只图景。", "explanation": "这里应该用量词〈幅〉。“只”用于动物等，不用于画面。"}, {"text": "这个图景的保质期是一年。", "explanation": "这里应该用〈食品〉。保质期用于食品等商品，图景是画面，不能说“保质期”。"}, {"text": "这个图景喝起来很甜。", "explanation": "这里应该用〈果汁〉。图景是画面，不能喝，“喝起来很甜”形容的应是饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲是用“听”的，不用“看”，与“看着眼前的”不符。"}, {"text": "图景", "is_correct": true, "explanation": "图景：指眼前的画面或景象，与“看着”相合，句意通顺。"}, {"text": "声音", "is_correct": false, "explanation": "配价：“看着”的宾语应是可见的东西，“声音”不能看。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道要用“闻”或“尝”，不用“看”。"}], "explanations": {"歌曲": "语义：歌曲是用“听”的，不用“看”，与“看着眼前的”不符。", "图景": "图景：指眼前的画面或景象，与“看着”相合，句意通顺。", "声音": "配价：“看着”的宾语应是可见的东西，“声音”不能看。", "味道": "语义：味道要用“闻”或“尝”，不用“看”。"}, "sentence_index": 6, "correct_answer": "图景"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他给我的第一图景很好。", "explanation": "这里应该用〈印象〉。图景是画面，不表示给人的感受，应说“第一印象”。"}, {"text": "他一口气吃了一大碗图景。", "explanation": "这里应该用〈饭〉。图景是画面，不能吃，应说“吃了一大碗饭”。"}, {"text": "这个东西的图景很便宜。", "explanation": "这里应该用〈价格〉。图景是画面，不是价格，“很便宜”形容的应是价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "湖面上的晚霞形成一本迷人的图景。", "corrected_sentence": "湖面上的晚霞形成一幅迷人的图景。", "error_description": "量词错误：“图景”应配量词“幅”，“本”用于书册，不能用于画面，正确为“一幅迷人的图景”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他站在山顶，吃着眼前的图景。", "corrected_sentence": "他站在山顶，看着眼前的图景。", "error_description": "搭配错误：“吃”不能与“图景”搭配，应为“看着眼前的图景”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd63076ef-1850-48aa-a439-995318801ef7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24956, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "充足", "is_correct": true, "explanation": "正确：“充足”与“短缺”是反义词，都指数量够不够。"}, {"text": "清楚", "is_correct": false, "explanation": "与“短缺”没有反义关系：“清楚”形容看得明白。"}, {"text": "明亮", "is_correct": false, "explanation": "与“短缺”没有反义关系：“明亮”形容光线或颜色。"}, {"text": "健康", "is_correct": false, "explanation": "与“短缺”没有反义关系：“健康”形容身体状况。"}], "correct_answer": "充足", "explanations": {"充足": "正确：“充足”与“短缺”是反义词，都指数量够不够。", "清楚": "与“短缺”没有反义关系：“清楚”形容看得明白。", "明亮": "与“短缺”没有反义关系：“明亮”形容光线或颜色。", "健康": "与“短缺”没有反义关系：“健康”形容身体状况。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24956, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "充足", "is_correct": true, "explanation": "正确：“充足”与“短缺”是反义词，都指数量够不够。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“短缺”没有反义关系：“陡峭”形容坡面。"}, {"text": "响亮", "is_correct": false, "explanation": "与“短缺”没有反义关系：“响亮”形容声音。"}, {"text": "温和", "is_correct": false, "explanation": "与“短缺”没有反义关系：“温和”形容性格或气候。"}], "correct_answer": "充足", "explanations": {"充足": "正确：“充足”与“短缺”是反义词，都指数量够不够。", "陡峭": "与“短缺”没有反义关系：“陡峭”形容坡面。", "响亮": "与“短缺”没有反义关系：“响亮”形容声音。", "温和": "与“短缺”没有反义关系：“温和”形容性格或气候。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24956, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西不够用了。", "primary_collocate": null, "pronunciation": "duǎn quē", "ipa": "twan˨˩ tɕʰɥɛ˥", "syllable_count": 2, "sentences": [{"text": "这个地方的水很短缺。", "target_word": "短缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，村里的粮食短缺。", "target_word": "短缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的药品一直很短缺。", "target_word": "短缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为资金短缺，学校没有盖新楼。", "target_word": "短缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱让这里的食物更加短缺。", "target_word": "短缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市里的电有时也会短缺。", "target_word": "短缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今年的教材很短缺，书店里几乎买不到。", "target_word": "短缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时期，人们的衣服和粮食都很短缺。", "target_word": "短缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个季节，菜很短缺，价格也高。", "target_word": "短缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的老师短缺，一个人要教两个班。", "target_word": "短缺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "物资、资金等数量不足，不够用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a7a008-8700-472e-9416-a17e42e54d73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短缺", "is_correct": true, "explanation": "正确：“短缺”表示水的供应不够，与语境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：水不会“高兴”，此处不能用于描述水。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：水不具备“聪明”的特性，与“水很___”的语境不符。"}, {"text": "健壮", "is_correct": false, "explanation": "搭配：“健壮”形容人或动物的身体，不用于形容水。"}], "explanations": {"短缺": "正确：“短缺”表示水的供应不够，与语境相符。", "高兴": "语义：水不会“高兴”，此处不能用于描述水。", "聪明": "语义：水不具备“聪明”的特性，与“水很___”的语境不符。", "健壮": "搭配：“健壮”形容人或动物的身体，不用于形容水。"}, "sentence_index": 0, "correct_answer": "短缺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师很短缺耐心，学生都有点怕她。", "explanation": "这里应该用〈缺乏〉。“短缺”指物资、资金等数量不足，“耐心”是抽象的品质，要说缺乏。"}, {"text": "他的能力很短缺，做事总是出错。", "explanation": "这里应该用〈不足〉。“短缺”多用于物资、资金的供应，说能力、水平不够要用“不足”。"}, {"text": "他很短缺勇气，不敢说话。", "explanation": "这里应该用〈缺少〉。“短缺”说的是供应不够，“勇气”是个人品质，要说缺少。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短缺", "is_correct": true, "explanation": "正确：“短缺”说教材供应不够，与后半句“几乎买不到”相呼应。"}, {"text": "充足", "is_correct": false, "explanation": "语义：“充足”与后半句“几乎买不到”矛盾，语境不通。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：教材不会“幽默”，与“很___”的语境不符。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体型或物体的高度，不用于形容教材。"}], "explanations": {"短缺": "正确：“短缺”说教材供应不够，与后半句“几乎买不到”相呼应。", "充足": "语义：“充足”与后半句“几乎买不到”矛盾，语境不通。", "幽默": "语义：教材不会“幽默”，与“很___”的语境不符。", "高大": "搭配：“高大”形容体型或物体的高度，不用于形容教材。"}, "sentence_index": 6, "correct_answer": "短缺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条裤子很短缺，穿上不合身。", "explanation": "这里应该用〈短〉。“短缺”指物资、资金等供应不足，不能用于衣物的长度。"}, {"text": "他的个子很短缺，站在队伍里不太显眼。", "explanation": "这里应该用〈矮〉。“短缺”说的是供应不够，不能用来形容身高。"}, {"text": "这次考试他的分数短缺，没能通过。", "explanation": "这里应该用〈不够〉。“短缺”指物资、资金的供应不足，考试分数不够要说“不够”，不能说短缺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一带的电很短缺着，夜里常停电。", "corrected_sentence": "这一带的电很短缺，夜里常停电。", "error_description": "动态助词误用：“很短缺”描述的是状态，形容词谓语后不能加“着”，应说“很短缺”，不说“很短缺着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年冬天，村里的粮食曾经短缺着。", "corrected_sentence": "去年冬天，村里的粮食曾经短缺过。", "error_description": "动态助词误用：“曾经”表示经历，应与“过”搭配，不能接表示持续的“着”。正确应为“短缺过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
