INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事情里最重要的部分。", "primary_collocate": null, "pronunciation": "yào sù", "ipa": "jɑʊ˥˩ su˥˩", "syllable_count": 2, "sentences": [{"text": "做饭时，火候是关键要素。", "target_word": "要素", "complexity_tier": "T3", "furigana": "zuò fàn shí, huǒ hou shì guān jiàn yào sù.", "sentence_source": "generated"}, {"text": "买房子，位置是第一要素。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事成不成，时间是主要要素。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你说说，这个游戏好玩的要素是什么？", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，心态是取胜的核心要素。", "target_word": "要素", "complexity_tier": "T3", "furigana": "zhè cì bǐ sài, xīn tài shì qǔ shèng de hé xīn yào sù.", "sentence_source": "generated"}, {"text": "他把赢得比赛的要素写在本子上。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "找工作时，你最看重哪个要素？", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格不是唯一的要素。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学好汉语，多听多说是要素之一。", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板问我们，开店有哪些要素？", "target_word": "要素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个要素", "label": "量词"}, {"form": "一项要素", "label": "量词"}], "register": "中性", "sense_fingerprint": "一件事里最重要的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'af392f55-520a-41c6-8a55-f0d8a216dfb3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要素", "is_correct": true, "explanation": "要素：事情里最重要的部分，火候正是做饭成败的关键。"}, {"text": "厨具", "is_correct": false, "explanation": "语义：“厨具”是做饭用的器具，火候不是厨具，句意不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与做饭的火候无关，句意不通。"}, {"text": "调料", "is_correct": false, "explanation": "语义：调料是放进菜里调味的东西，火候不是调料，句意不通。"}], "explanations": {"要素": "要素：事情里最重要的部分，火候正是做饭成败的关键。", "厨具": "语义：“厨具”是做饭用的器具，火候不是厨具，句意不通。", "颜色": "语义：“颜色”与做饭的火候无关，句意不通。", "调料": "语义：调料是放进菜里调味的东西，火候不是调料，句意不通。"}, "sentence_index": 0, "correct_answer": "要素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个游戏有几座好玩的要素？", "explanation": "量词错误：〈座〉用于山、桥、房屋等大型建筑，要素应该用〈个〉或〈项〉。"}, {"text": "这家餐厅的要素很好吃，我每次都来。", "explanation": "这里应该用〈菜〉。要素指事情里最重要的部分，不能用“好吃”形容；餐厅里的食物要说〈菜〉。"}, {"text": "这个游戏的要素很勇敢，大家都很佩服。", "explanation": "这里应该用〈主人公〉。要素指事情里最重要的部分，不能用“勇敢”形容；说故事里的人物勇敢，要用〈主人公〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要素", "is_correct": true, "explanation": "要素：事情里最重要的部分，找工作时要看重的正是这些关键部分。"}, {"text": "天气", "is_correct": false, "explanation": "语义：问的是找工作时最看重什么，“天气”不是可以挑选的择业因素，句意不通。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：“地铁”是交通工具，不能作为找工作时看重的因素。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是找工作时挑选的因素，句意不通。"}], "explanations": {"要素": "要素：事情里最重要的部分，找工作时要看重的正是这些关键部分。", "天气": "语义：问的是找工作时最看重什么，“天气”不是可以挑选的择业因素，句意不通。", "地铁": "语义：“地铁”是交通工具，不能作为找工作时看重的因素。", "雨伞": "语义：雨伞不是找工作时挑选的因素，句意不通。"}, "sentence_index": 6, "correct_answer": "要素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板问我们，开店有哪只要素？", "explanation": "量词错误：〈只〉多用于动物或成对器物中的一件，要素应该用〈个〉或〈项〉。"}, {"text": "老板想把开店的要素一次买完。", "explanation": "这里应该用〈材料〉。要素指事情里最重要的部分，不能拿来购买；开店时要买的东西要说〈材料〉。"}, {"text": "老板说，这家店的要素很好喝。", "explanation": "这里应该用〈饮料〉。要素指事情里最重要的部分，不能用“好喝”形容；店里可以喝的东西要说〈饮料〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他认为，勤奋是成功的一片要素。", "corrected_sentence": "他认为，勤奋是成功的一个要素。", "error_description": "量词错误：“要素”是抽象的组成部分，应用“个”，“片”用于叶子、面积等扁平的东西，应改为“一个要素”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "开店时，选址是重要地要素。", "corrected_sentence": "开店时，选址是重要的要素。", "error_description": "结构助词错误：形容词修饰名词要用“的”，“地”用于修饰动词，应说“重要的要素”，“重要地要素”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83821f2f-9519-48e2-8a46-5eb77199775d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
