INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24960, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不够的部分加上，让东西变多或变全。", "primary_collocate": null, "pronunciation": "bǔ chōng", "ipa": "pu˨˩ ʈʂʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "天气很热，要经常补充水分。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的作业少了一页，老师让我补充。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱里的牛奶没有了，要补充一些。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说完以后，朋友又补充了两句。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病人身体很弱，需要补充营养。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告不够完整，请你补充一下。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑完步，我喝了一杯水补充体力。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想补充一个小问题。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市每天早上都会补充新鲜的蔬菜。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里缺少的内容，我已经补充好了。", "target_word": "补充", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "补充了", "label": "体标"}, {"form": "补充过", "label": "体标"}, {"form": "補充", "label": "繁体"}, {"form": "补充说明", "label": "复合"}], "register": "通用", "sense_fingerprint": "补充|把不够的部分加上使变多变全", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3caebe75-670d-474d-a611-b9d000242724') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "补充", "is_correct": true, "explanation": "动词用法，表示把不够的水分加上，与“要经常”的提醒相符。"}, {"text": "消耗", "is_correct": false, "explanation": "语义：“消耗”是减少，与“要经常补充水分”的要求相反。"}, {"text": "流失", "is_correct": false, "explanation": "语义：“流失”指丢失，与“要经常补充”的要求相反。"}, {"text": "排泄", "is_correct": false, "explanation": "语义：“排泄”指把废物排出体外，水分不是废物，句意不通。"}], "explanations": {"补充": "动词用法，表示把不够的水分加上，与“要经常”的提醒相符。", "消耗": "语义：“消耗”是减少，与“要经常补充水分”的要求相反。", "流失": "语义：“流失”指丢失，与“要经常补充”的要求相反。", "排泄": "语义：“排泄”指把废物排出体外，水分不是废物，句意不通。"}, "sentence_index": 0, "correct_answer": "补充"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的个子这个月补充了两厘米。", "explanation": "这里应该用〈长〉。补充表示补上缺少的部分，个子变高要说长。"}, {"text": "这次旅行补充了他的生活。", "explanation": "这里应该用〈丰富〉。补充是补上缺少的部分，不用来说生活变得丰富。"}, {"text": "这次补贴补充了农民的负担。", "explanation": "这里应该用〈减轻〉。补充表示补上缺少的部分，负担减少要说减轻，不能说补充负担。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "补充", "is_correct": true, "explanation": "动词用法，表示补上消耗掉的体力，与“跑完步”的语境相符。"}, {"text": "减少", "is_correct": false, "explanation": "语义：“减少”与句意“喝水后体力得到恢复”相反。"}, {"text": "支配", "is_correct": false, "explanation": "语义：“支配”指掌控，喝水不能“支配”体力，句意不通。"}, {"text": "扣除", "is_correct": false, "explanation": "搭配：“扣除”多用于费用、分数，不与“体力”搭配。"}], "explanations": {"补充": "动词用法，表示补上消耗掉的体力，与“跑完步”的语境相符。", "减少": "语义：“减少”与句意“喝水后体力得到恢复”相反。", "支配": "语义：“支配”指掌控，喝水不能“支配”体力，句意不通。", "扣除": "搭配：“扣除”多用于费用、分数，不与“体力”搭配。"}, "sentence_index": 6, "correct_answer": "补充"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在地下室补充了水管的漏洞。", "explanation": "这里应该用〈堵住〉。补充表示补上缺少的部分，堵漏洞要说堵住，不能说补充漏洞。"}, {"text": "他这次考试补充了十分。", "explanation": "这里应该用〈提高〉。补充表示补上缺少的部分，成绩上升要说提高。"}, {"text": "公司通过改进工艺，补充了成本。", "explanation": "这里应该用〈降低〉。补充表示增加缺少的部分，成本减少要说降低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把缺少的内容补充出去了。", "corrected_sentence": "他把缺少的内容补充进去了。", "error_description": "补语错误：“补充出去”；正确：“补充进去”。“补充”是把缺少的内容加进去，应用“进去”，“出去”表示向外，与句意相反。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们补充着三次库存。", "corrected_sentence": "我们补充过三次库存。", "error_description": "体标错误：“补充着三次库存”；正确：“补充过三次库存”。“着”表示动作持续，句中说的是已经发生的几次补充，应用“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75a426d6-99f1-4aba-bf7b-f11dcbbf84da') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
