INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24962, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "过去一直有的意思。", "primary_collocate": null, "pronunciation": "chuán tǒng yì yì", "ipa": "ʈʂʰwan˧˥ tʰʊŋ˨˩˦ i˥˩ i˥˩", "syllable_count": 4, "sentences": [{"text": "这个字的传统意义，现在很少有人知道。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了“龙”的传统意义。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红色的传统意义是吉利和喜庆。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日已经没有传统意义了。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道“福”字倒着贴的传统意义吗？", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“宗”字的传统意义是祖庙，现在很少这样用了。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说，这个词有它的传统意义。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手势的传统意义和现在不一样。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我查了词典，想了解这个成语的传统意义。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的“朋友”和传统意义的朋友不一样。", "target_word": "传统意义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "传统意义上", "label": "复合"}], "register": "书面", "sense_fingerprint": "过去一直有的老意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4210cd39-20e1-42e6-8e4f-325ff395f566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "传统意义", "is_correct": true, "explanation": "正确：指这个字过去一直有的意思，与“现在很少有人知道”形成对比，句意相合。"}, {"text": "天气预报", "is_correct": false, "explanation": "语义：“天气预报”是天气信息，与“字”的古义无关，句意不通。"}, {"text": "常见用法", "is_correct": false, "explanation": "语义：“常见用法”指现在普遍使用的方式，与“现在很少有人知道”相矛盾。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”与“字”无关，句意不通。"}], "explanations": {"传统意义": "正确：指这个字过去一直有的意思，与“现在很少有人知道”形成对比，句意相合。", "天气预报": "语义：“天气预报”是天气信息，与“字”的古义无关，句意不通。", "常见用法": "语义：“常见用法”指现在普遍使用的方式，与“现在很少有人知道”相矛盾。", "体重": "语义：“体重”与“字”无关，句意不通。"}, "sentence_index": 0, "correct_answer": "传统意义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个节日的传统意义很便宜。", "explanation": "这里应该用〈价格〉。“传统意义”指过去一直有的意思，不指价钱高低，说便宜要用“价格”。"}, {"text": "这个节日的传统意义很快。", "explanation": "这里应该用〈速度〉。“传统意义”指过去一直有的意思，不指快慢，说快要用“速度”。"}, {"text": "这个节日的传统意义很长。", "explanation": "这里应该用〈历史〉。“传统意义”指意思，不指时间长短，说历史长要用“历史”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "传统意义", "is_correct": true, "explanation": "正确：指这个词过去一直有的意思，与“爷爷说”的语境相合。"}, {"text": "口头禅", "is_correct": false, "explanation": "语义：“口头禅”指人常挂在嘴边的话，词本身不会“有它的口头禅”，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人或物的高矮，与“词”的含义无关，句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”与“词”的含义无关，句意不通。"}], "explanations": {"传统意义": "正确：指这个词过去一直有的意思，与“爷爷说”的语境相合。", "口头禅": "语义：“口头禅”指人常挂在嘴边的话，词本身不会“有它的口头禅”，句意不通。", "身高": "语义：“身高”指人或物的高矮，与“词”的含义无关，句意不通。", "体重": "语义：“体重”与“词”的含义无关，句意不通。"}, "sentence_index": 6, "correct_answer": "传统意义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种动物的传统意义很长。", "explanation": "这里应该用〈寿命〉。“传统意义”指词义或事物的意思，不指生存时间，说寿命长要用“寿命”。"}, {"text": "他的传统意义很好。", "explanation": "这里应该用〈名声〉。“传统意义”不指社会评价，说名声好要用“名声”。"}, {"text": "这首歌的传统意义很好听。", "explanation": "这里应该用〈声音〉。“传统意义”指词义，不指声音，说声音好听要用“声音”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个成语传统意义是“好运气”。", "corrected_sentence": "这个成语的传统意义是“好运气”。", "error_description": "漏“的”：“这个成语”与“传统意义”之间需要“的”，应为“这个成语的传统意义”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个节日地传统意义是祭祀祖先。", "corrected_sentence": "这个节日的传统意义是祭祀祖先。", "error_description": "错误：“地”用于修饰动词或形容词，不能连接“这个节日”与“传统意义”；表示领属应用“的”。正确：“这个节日的传统意义”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
