INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24964, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人们造出来住在里面或做事的房子、大楼。", "primary_collocate": null, "pronunciation": "jiàn zhù", "ipa": "tɕjɛn˥˩ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "这座建筑已经有一百年了。", "target_word": "建筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市中间有很多高大的建筑。", "target_word": "建筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是学校里最老的建筑。", "target_word": "建筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座白色的建筑是图书馆。", "target_word": "建筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京有很多古老的建筑。", "target_word": "建筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢拍各种漂亮的建筑。", "target_word": "建筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这栋建筑是去年盖好的。", "target_word": "建筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅游时我们参观了当地有名的建筑。", "target_word": "建筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园里的建筑都是红色的。", "target_word": "建筑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边那座新建的建筑样子很特别。", "target_word": "建筑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座建筑", "label": "量词"}, {"form": "一栋建筑", "label": "量词"}, {"form": "建筑师", "label": "复合"}], "register": "中性", "sense_fingerprint": "人们盖成的房屋、大楼等建造物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '12f9422c-71d5-4159-b92d-1d18b93b36af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24964, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "建筑", "is_correct": true, "explanation": "正确答案。建筑 jiànzhù 指人造的房屋、大楼。"}, {"text": "建树", "is_correct": false, "explanation": "shù（第四声）与 zhù 声母不同（sh 与 zh），意思是取得成就，如“有所建树”。"}, {"text": "建制", "is_correct": false, "explanation": "zhì 与 zhù 韵母不同（-i 与 -u），意思是编制或组织体系。"}, {"text": "箭竹", "is_correct": false, "explanation": "zhú（第二声）与 zhù（第四声）声调不同，意思是一种竹子。"}, {"text": "现住", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），意思是目前居住。"}], "explanations": {"建筑": "正确答案。建筑 jiànzhù 指人造的房屋、大楼。", "建树": "shù（第四声）与 zhù 声母不同（sh 与 zh），意思是取得成就，如“有所建树”。", "建制": "zhì 与 zhù 韵母不同（-i 与 -u），意思是编制或组织体系。", "箭竹": "zhú（第二声）与 zhù（第四声）声调不同，意思是一种竹子。", "现住": "xiàn 与 jiàn 声母不同（x 与 j），意思是目前居住。"}, "sentence_index": null, "correct_answer": "建筑"}, "level_3": {"options": [{"text": "建筑", "is_correct": true, "explanation": "“建筑”指房屋、大楼，可以“有一百年”，与“座”搭配。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“座”用于山、楼、桥等大型物体，树要用“棵”，不说“座树”。"}, {"text": "歌", "is_correct": false, "explanation": "搭配：歌用“首”，不用“座”，句子不通。"}, {"text": "人", "is_correct": false, "explanation": "搭配：人用“个”或“位”，不用“座”，不说“这座人”。"}], "explanations": {"建筑": "“建筑”指房屋、大楼，可以“有一百年”，与“座”搭配。", "树": "搭配：“座”用于山、楼、桥等大型物体，树要用“棵”，不说“座树”。", "歌": "搭配：歌用“首”，不用“座”，句子不通。", "人": "搭配：人用“个”或“位”，不用“座”，不说“这座人”。"}, "sentence_index": 0, "correct_answer": "建筑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的爷爷是一座很善良的建筑。", "explanation": "这里应该用〈人〉。“建筑”指房屋和大楼，不能指人，说人善良要用“人”。"}, {"text": "我把一座建筑放进了书包里。", "explanation": "这里应该用〈书〉。建筑是很大的房屋，不能放进书包，要放进书包的是〈书〉。"}, {"text": "我喜欢吃建筑。", "explanation": "这里应该用〈食物〉。建筑是房屋，不能吃，要吃的东西用〈食物〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24964, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建筑", "is_correct": true, "explanation": "“栋”用于房屋，被“盖”的正是建筑。"}, {"text": "车", "is_correct": false, "explanation": "搭配：“栋”用于房屋，车用“辆”，车也不说“盖”。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不能“盖”，句子不成立。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：电视用“台”，不用“栋”。"}], "explanations": {"建筑": "“栋”用于房屋，被“盖”的正是建筑。", "车": "搭配：“栋”用于房屋，车用“辆”，车也不说“盖”。", "饼干": "语义：饼干不能“盖”，句子不成立。", "电视": "搭配：电视用“台”，不用“栋”。"}, "sentence_index": 6, "correct_answer": "建筑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座建筑很甜。", "explanation": "这里应该用〈蛋糕〉。建筑不能有甜味，形容甜的要用〈蛋糕〉这类食物。"}, {"text": "他在河边钓了半天，钓到了一座建筑。", "explanation": "这里应该用〈鱼〉。建筑不能被钓，钓的是〈鱼〉。"}, {"text": "他跑得很快，简直像一座建筑。", "explanation": "这里应该用〈风〉。建筑不会动，形容跑得快要用〈风〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些建筑们都很高。", "corrected_sentence": "这些建筑都很高。", "error_description": "错误：“建筑们”。正确：“建筑”。“建筑”不加“们”表示复数，多座建筑直接说“这些建筑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这颗建筑很高。", "corrected_sentence": "这栋建筑很高。", "error_description": "错误：“颗”。正确：“栋”。“颗”用于小而圆的东西，建筑应用“栋”或“座”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe4d3447-d802-4dcc-982d-cc53a9016261') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24966, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生产性", "is_correct": true, "explanation": "反义：“生产性”与“非生产性”构成对立，指能帮助做出东西或得到好处。"}, {"text": "紧凑的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是结构或布局。"}, {"text": "清晰的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是清楚程度。"}, {"text": "宽敞的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是空间大小。"}], "correct_answer": "生产性", "explanations": {"生产性": "反义：“生产性”与“非生产性”构成对立，指能帮助做出东西或得到好处。", "紧凑的": "与“非生产性”的意义没有反义关系，描述的是结构或布局。", "清晰的": "与“非生产性”的意义没有反义关系，描述的是清楚程度。", "宽敞的": "与“非生产性”的意义没有反义关系，描述的是空间大小。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24966, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "生产性", "is_correct": true, "explanation": "反义：“生产性”与“非生产性”构成对立，指能帮助做出东西或得到好处。"}, {"text": "灵活的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是动作或做法的变通程度。"}, {"text": "陈旧的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是事物过时、不新。"}, {"text": "迟缓的", "is_correct": false, "explanation": "与“非生产性”的意义没有反义关系，描述的是动作慢。"}], "correct_answer": "生产性", "explanations": {"生产性": "反义：“生产性”与“非生产性”构成对立，指能帮助做出东西或得到好处。", "灵活的": "与“非生产性”的意义没有反义关系，描述的是动作或做法的变通程度。", "陈旧的": "与“非生产性”的意义没有反义关系，描述的是事物过时、不新。", "迟缓的": "与“非生产性”的意义没有反义关系，描述的是动作慢。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24966, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不能帮助做出东西或得到好处的。", "primary_collocate": null, "pronunciation": "fēi shēng chǎn xìng", "ipa": "fei˥ ʂɤŋ˥ ʈʂʰan˨˩˦ ɕiŋ˥˩", "syllable_count": 4, "sentences": [{"text": "他整天玩手机，做的都是非生产性的事。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "聊天太久是非生产性的，应该早点工作。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类会议多为非生产性活动，与会人员都不愿参加。", "target_word": "非生产性", "complexity_tier": "T3", "furigana": "zhè lèi huìyì duō wéi fēi shēngchǎn xìng huódòng, yǔhuì rényuán dōu bú yuàn cānjiā.", "sentence_source": "generated"}, {"text": "排队等了两个小时，这是非生产性的时间。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不喜欢员工做非生产性的工作。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不停地检查邮件，是一种非生产性的行为。", "target_word": "非生产性", "complexity_tier": "T3", "furigana": "bù tíng de jiǎnchá yóujiàn, shì yī zhǒng fēi shēngchǎn xìng de xíngwéi.", "sentence_source": "generated"}, {"text": "这些表格没有用，填写它们是非生产性劳动。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个下午全是非生产性的忙碌。", "target_word": "非生产性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "让机器空转着，没有任何产出，是非生产性的消耗。", "target_word": "非生产性", "complexity_tier": "T3", "furigana": "ràng jīqì kōngzhuàn zhe, méi yǒu rènhé chǎnchū, shì fēi shēngchǎn xìng de xiāohào.", "sentence_source": "generated"}, {"text": "他说看电视是非生产性的消遣，不能赚钱。", "target_word": "非生产性", "complexity_tier": "T3", "furigana": "tā shuō kàn diànshì shì fēi shēngchǎn xìng de xiāoqiǎn, bù néng zhuàn qián.", "sentence_source": "generated"}], "morphological_forms": [{"form": "非生产性支出", "label": "复合"}, {"form": "非生产性活动", "label": "复合"}], "register": "书面", "sense_fingerprint": "不能做出东西或得到好处的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4210cd39-20e1-42e6-8e4f-325ff395f566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "非生产性", "is_correct": true, "explanation": "“做的都是非生产性的事”指不能做出东西或得到好处的事，与“整天玩手机”相符。"}, {"text": "生产性", "is_correct": false, "explanation": "语义：“整天玩手机”不会做出有益的事，说“生产性的事”与语境矛盾。"}, {"text": "高效", "is_correct": false, "explanation": "语义：“整天玩手机”的事不是高效的，“高效的事”与句中语境冲突。"}, {"text": "高产", "is_correct": false, "explanation": "搭配：“高产”多形容农作物或产量，不用来修饰“事”，与玩手机的语境也矛盾。"}], "explanations": {"非生产性": "“做的都是非生产性的事”指不能做出东西或得到好处的事，与“整天玩手机”相符。", "生产性": "语义：“整天玩手机”不会做出有益的事，说“生产性的事”与语境矛盾。", "高效": "语义：“整天玩手机”的事不是高效的，“高效的事”与句中语境冲突。", "高产": "搭配：“高产”多形容农作物或产量，不用来修饰“事”，与玩手机的语境也矛盾。"}, "sentence_index": 0, "correct_answer": "非生产性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂利用非生产性设备生产了大量产品。", "explanation": "“非生产性”指不能做出东西，这里说“生产了大量产品”，应说〈生产性〉，不能用“非生产性”形容能做出东西的设备。"}, {"text": "这份合同为公司带来了大笔收入，是非生产性的文件。", "explanation": "“非生产性”指不能帮助做出东西或得到好处，这里“带来了大笔收入”说明有好处，应说〈有益〉或〈生产性〉。"}, {"text": "他一个人完成了三份报告，非生产性地工作。", "explanation": "这里与“完成了三份报告”矛盾：“非生产性”指不能产出，句中工作有成果，应说〈高效〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "非生产性", "is_correct": true, "explanation": "“非生产性劳动”指不能带来产出的劳动，与“这些表格没有用”的语境相符。"}, {"text": "创造性", "is_correct": false, "explanation": "语义：句中“表格没有用”，填写表格不是创造性劳动，“创造性”与语境矛盾。"}, {"text": "创新性", "is_correct": false, "explanation": "语义：填写没用的表格与“创新”无关，句中语境不支持这种说法。"}, {"text": "生产性", "is_correct": false, "explanation": "语义：“生产性劳动”指能带来产出的劳动，与“表格没有用”的语境矛盾。"}], "explanations": {"非生产性": "“非生产性劳动”指不能带来产出的劳动，与“这些表格没有用”的语境相符。", "创造性": "语义：句中“表格没有用”，填写表格不是创造性劳动，“创造性”与语境矛盾。", "创新性": "语义：填写没用的表格与“创新”无关，句中语境不支持这种说法。", "生产性": "语义：“生产性劳动”指能带来产出的劳动，与“表格没有用”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "非生产性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电视剧能带来很高的收益，是非生产性的消遣。", "explanation": "这里与“能带来很高的收益”矛盾。“非生产性”指不能直接产生经济效益，应说〈生产性〉。"}, {"text": "他每天都做非生产性的事，却赚了很多钱。", "explanation": "“非生产性”指不能带来好处，与“却赚了很多钱”矛盾，应说〈生产性〉。"}, {"text": "他每天认真学习，学会了三门外语，这段时间是非生产性的。", "explanation": "学会三门外语是有收获的事，与“非生产性”（不能得到好处）矛盾，应说〈有效〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他整天刷视频，做的都是很非生产性的事。", "corrected_sentence": "他整天刷视频，做的都是非生产性的事。", "error_description": "错误形式：“很非生产性”。正确形式：“非生产性”。“很”一般不直接修饰这个书面化的固定词，“很非生产性”不自然，应说“非生产性的事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台非生产性活动应该减少。", "corrected_sentence": "这项非生产性活动应该减少。", "error_description": "量词错误：“活动”应用量词“项”，不用“台”（“台”多用于机器、设备）。正确：“这项非生产性活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
