INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子的外面这一面。", "primary_collocate": null, "pronunciation": "lì miàn", "ipa": "li˥˩ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这座房子的立面朝着大街，很漂亮。", "target_word": "立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的立面上有很多石头雕花。", "target_word": "立面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人正在给这栋楼的立面刷漆。", "target_word": "立面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这栋楼的立面看起来很新。", "target_word": "立面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们画一画这座楼的立面。", "target_word": "立面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店的立面挂着红灯笼。", "target_word": "立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "台风过后，房子的立面坏了一块。", "target_word": "立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把房子的立面刷成了黄色。", "target_word": "立面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从街上看，这座房子的立面很宽。", "target_word": "立面", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新房子的立面全是玻璃，很亮。", "target_word": "立面", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "立面图", "label": "复合"}, {"form": "正立面", "label": "复合"}], "register": "中性", "sense_fingerprint": "房子的外面这一面，从外面看到的墙面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4210cd39-20e1-42e6-8e4f-325ff395f566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "立面", "is_correct": true, "explanation": "“这座房子的立面朝着大街”指房子朝外的一面朝向大街，与句意相符。"}, {"text": "地板", "is_correct": false, "explanation": "语义：地板在室内，不会朝着大街，“地板朝着大街”与句意矛盾。"}, {"text": "地基", "is_correct": false, "explanation": "语义：地基埋在地下，不会朝着大街，与“漂亮”的描述无关。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是小物件，不会朝着大街，与“房子朝着大街”的描述无关。"}], "explanations": {"立面": "“这座房子的立面朝着大街”指房子朝外的一面朝向大街，与句意相符。", "地板": "语义：地板在室内，不会朝着大街，“地板朝着大街”与句意矛盾。", "地基": "语义：地基埋在地下，不会朝着大街，与“漂亮”的描述无关。", "钥匙": "语义：钥匙是小物件，不会朝着大街，与“房子朝着大街”的描述无关。"}, "sentence_index": 0, "correct_answer": "立面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在这座房子的立面里睡了一夜。", "explanation": "“立面”指房子朝外的一面，不指室内的空间，这里应说〈房间〉。"}, {"text": "我把书放在书包的立面里。", "explanation": "“立面”指房子朝外的一面，不指包的内部，这里应说〈里面〉。"}, {"text": "这张桌子的立面很平，可以放书。", "explanation": "“立面”指建筑朝外的一面，不指家具的表面，这里应说〈桌面〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立面", "is_correct": true, "explanation": "“台风过后，房子的立面坏了一块”指房子外观的一面受损，与句意相符。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子不会因台风而坏掉，“影子坏了一块”与句意矛盾。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是房子的一部分，“房子的天空坏了一块”不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度坏了一块”的搭配不当，温度不会像物体一样坏掉。"}], "explanations": {"立面": "“台风过后，房子的立面坏了一块”指房子外观的一面受损，与句意相符。", "影子": "语义：影子不会因台风而坏掉，“影子坏了一块”与句意矛盾。", "天空": "语义：天空不是房子的一部分，“房子的天空坏了一块”不通。", "温度": "搭配：“温度坏了一块”的搭配不当，温度不会像物体一样坏掉。"}, "sentence_index": 6, "correct_answer": "立面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的立面很干净，今天刚刷过牙。", "explanation": "“立面”指建筑朝外的一面，不指人的脸，这里应说〈脸〉或〈面孔〉。"}, {"text": "这只猫的立面很光滑，摸起来很舒服。", "explanation": "“立面”指房子朝外的一面，不指动物的毛皮，这里应说〈皮毛〉。"}, {"text": "孩子们在这片湖的立面上玩耍，很开心。", "explanation": "“立面”指房子朝外的一面，不指湖的水面，这里应说〈水面〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座房子的一只立面朝着大街，很漂亮。", "corrected_sentence": "这座房子的一个立面朝着大街，很漂亮。", "error_description": "错误形式：“一只立面”。正确形式：“一个立面”。“立面”的量词应用“个”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "冰雹过后，房子的立面坏了一把。", "corrected_sentence": "冰雹过后，房子的立面坏了一块。", "error_description": "量词错误：表示受损的一部分用“块”，“把”多用于有柄的器物，不能用于“立面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
