INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24972, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个小东西放进另一个东西里面。", "primary_collocate": null, "pronunciation": "qiàn rù", "ipa": "tɕʰjɛn˥˩ ʐu˥˩", "syllable_count": 2, "sentences": [{"text": "工人把一块玻璃嵌入了墙里。", "target_word": "嵌入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这颗小宝石嵌入戒指里，很漂亮。", "target_word": "嵌入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把小灯嵌入木板中间。", "target_word": "嵌入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上嵌入了一面小镜子。", "target_word": "嵌入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把小石子嵌入泥土里。", "target_word": "嵌入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块芯片嵌入手表里，手表更聪明。", "target_word": "嵌入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅正在把铁片嵌入门里。", "target_word": "嵌入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张小卡片嵌入盒子的一边。", "target_word": "嵌入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把一朵干花嵌入书页中间。", "target_word": "嵌入", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这扇门上嵌入着一块红玻璃。", "target_word": "嵌入", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "嵌入了", "label": "体标"}, {"form": "嵌入着", "label": "体标"}, {"form": "嵌入过", "label": "体标"}, {"form": "嵌入式", "label": "复合"}], "register": "中性", "sense_fingerprint": "把小物件紧紧放进另一物体里面固定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '59a7a008-8700-472e-9416-a17e42e54d73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "嵌入", "is_correct": true, "explanation": "正确：嵌入（qiàn rù）指把小物件紧紧放进另一物体里。"}, {"text": "潜入", "is_correct": false, "explanation": "声调不同：第一个音节 qián（第二声）与 qiàn（第四声）不同，意思是暗中进入。"}, {"text": "陷入", "is_correct": false, "explanation": "声母不同：xiàn 的声母是 x，qiàn 的声母是 q，意思是陷进去、落入。"}, {"text": "迁入", "is_correct": false, "explanation": "声调不同：第一个音节 qiān（第一声）与 qiàn（第四声）不同，意思是迁移到某地居住。"}], "explanations": {"嵌入": "正确：嵌入（qiàn rù）指把小物件紧紧放进另一物体里。", "潜入": "声调不同：第一个音节 qián（第二声）与 qiàn（第四声）不同，意思是暗中进入。", "陷入": "声母不同：xiàn 的声母是 x，qiàn 的声母是 q，意思是陷进去、落入。", "迁入": "声调不同：第一个音节 qiān（第一声）与 qiàn（第四声）不同，意思是迁移到某地居住。"}, "sentence_index": null, "correct_answer": "嵌入"}, "level_3": {"options": [{"text": "嵌入", "is_correct": true, "explanation": "正确：“嵌入”指把小物件紧紧放进另一物体里，这里是把玻璃嵌进墙里。"}, {"text": "吃", "is_correct": false, "explanation": "语义：玻璃不能吃，与“一块玻璃”相矛盾。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于擦拭表面，不能说擦进墙里。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”用于食物或液体，与玻璃、墙都不搭。"}], "explanations": {"嵌入": "正确：“嵌入”指把小物件紧紧放进另一物体里，这里是把玻璃嵌进墙里。", "吃": "语义：玻璃不能吃，与“一块玻璃”相矛盾。", "擦": "搭配：“擦”用于擦拭表面，不能说擦进墙里。", "煮": "语义：“煮”用于食物或液体，与玻璃、墙都不搭。"}, "sentence_index": 0, "correct_answer": "嵌入"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他嵌入了房间。", "explanation": "这里应该用〈进入〉。“嵌入”指把小物件紧紧放进另一物体里，人走进房间要用“进入”。"}, {"text": "她把饭嵌入了碗里。", "explanation": "这里应该用〈放入〉。“嵌入”要求小物件紧固在物体里，饭只是盛放到碗里，应用“放入”。"}, {"text": "我们嵌入了困境。", "explanation": "这里应该用〈陷入〉。“嵌入”用于把小物件放进物体里，处于困境要用“陷入”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24972, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嵌入", "is_correct": true, "explanation": "正确：“嵌入”指把小物件紧紧放进另一物体里，这里是把铁片嵌进门里。"}, {"text": "咬", "is_correct": false, "explanation": "语义：咬要用牙齿，铁片不能用来咬。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是液体，铁片不能喝。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”用于文字、纸面，不能说写进门里。"}], "explanations": {"嵌入": "正确：“嵌入”指把小物件紧紧放进另一物体里，这里是把铁片嵌进门里。", "咬": "语义：咬要用牙齿，铁片不能用来咬。", "喝": "语义：“喝”的对象是液体，铁片不能喝。", "写": "搭配：“写”用于文字、纸面，不能说写进门里。"}, "sentence_index": 6, "correct_answer": "嵌入"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钱嵌入了银行。", "explanation": "这里应该用〈存入〉。“嵌入”指小物件紧固在物体里，钱存进银行要用“存入”。"}, {"text": "我们嵌入了这场比赛。", "explanation": "这里应该用〈加入〉。“嵌入”指小物件紧固在物体里，参加比赛要用“加入”。"}, {"text": "他嵌入了大人们的谈话。", "explanation": "这里应该用〈参与〉。“嵌入”不用于人加入谈话，参与谈话要用“参与”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墙上嵌入着了一面小镜子。", "corrected_sentence": "墙上嵌入着一面小镜子。", "error_description": "体标错误：“嵌入着”已表示状态，后面不能再加“了”，应说“嵌入着一面小镜子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "师傅正在把铜片嵌入过桌面里。", "corrected_sentence": "师傅正在把铜片嵌入桌面里。", "error_description": "体标错误：“正在”表示动作进行中，不能与表示经历的“过”同用；应去掉“过”，说“正在把铜片嵌入桌面里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '66f38db7-9c14-48aa-ab1e-864b969d105d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
