INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24974, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让一个地方变绿，比如种树和种花。", "primary_collocate": null, "pronunciation": "lǜ huà", "ipa": "ly˥˩ xua˥˩", "syllable_count": 2, "sentences": [{"text": "我们想绿化学校的操场。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈种了很多花，把阳台绿化了。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，大家一起绿化小区。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路没有树，应该绿化。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生去山上种树，绿化那里。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用花草绿化了院子。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去绿化河边的空地。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方绿化以后，鸟也来了。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要绿化教室，可以放几盆花。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想绿化办公室的楼顶。", "target_word": "绿化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "绿化了", "label": "体标"}, {"form": "绿化过", "label": "体标"}], "register": "中性", "sense_fingerprint": "种树种花让一个地方变绿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115b89f7-bdbd-4625-a077-7b8981880a73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24974, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "绿化", "is_correct": true, "explanation": "正确：“想绿化学校的操场”表示想让操场变绿，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，不能直接带“学校的操场”作宾语。"}, {"text": "摧毁", "is_correct": false, "explanation": "语义：“摧毁”与“想…操场”的意愿相反，不符合句意。"}, {"text": "唱歌", "is_correct": false, "explanation": "配价：“唱歌”是离合式动宾词，不能再带“学校的操场”作宾语。"}], "explanations": {"绿化": "正确：“想绿化学校的操场”表示想让操场变绿，符合句意。", "散步": "配价：“散步”是不及物动词，不能直接带“学校的操场”作宾语。", "摧毁": "语义：“摧毁”与“想…操场”的意愿相反，不符合句意。", "唱歌": "配价：“唱歌”是离合式动宾词，不能再带“学校的操场”作宾语。"}, "sentence_index": 0, "correct_answer": "绿化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在窗台上绿化了几盆花。", "explanation": "这里应该用〈摆放〉。绿化指让地方变绿，不指把花搬来摆在某处。"}, {"text": "园丁每天绿化这些花。", "explanation": "这里应该用〈浇灌〉。绿化是让地方变绿，不指给某些植物浇水。"}, {"text": "工人绿化了这台电脑。", "explanation": "这里应该用〈修理〉。绿化是让地方变绿，不能用于电器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24974, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绿化", "is_correct": true, "explanation": "正确：“去绿化河边的空地”表示去让那片空地变绿，符合句意。"}, {"text": "跳舞", "is_correct": false, "explanation": "配价：“跳舞”不能带“河边的空地”作宾语，“去跳舞河边的空地”说不通。"}, {"text": "烧毁", "is_correct": false, "explanation": "语义：“烧毁”是破坏，与周末去处理空地的意图不符。"}, {"text": "睡觉", "is_correct": false, "explanation": "配价：“睡觉”是不及物动词，不能带“河边的空地”作宾语。"}], "explanations": {"绿化": "正确：“去绿化河边的空地”表示去让那片空地变绿，符合句意。", "跳舞": "配价：“跳舞”不能带“河边的空地”作宾语，“去跳舞河边的空地”说不通。", "烧毁": "语义：“烧毁”是破坏，与周末去处理空地的意图不符。", "睡觉": "配价：“睡觉”是不及物动词，不能带“河边的空地”作宾语。"}, "sentence_index": 6, "correct_answer": "绿化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民给稻田绿化，让庄稼长得更好。", "explanation": "这里应该用〈施肥〉。绿化是让地方变绿，不指给庄稼施肥。"}, {"text": "园丁绿化了灌木的枝叶。", "explanation": "这里应该用〈修剪〉。绿化是使地方变绿，不是对枝叶做整理。"}, {"text": "裁缝绿化了一件衣服。", "explanation": "这里应该用〈缝制〉。绿化是让地方变绿，不能用于衣物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24974, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区绿化的很好。", "corrected_sentence": "这个小区绿化得很好。", "error_description": "助词错误：表示程度的补语要用“得”，不能用“的”，应说“绿化得很好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24974, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们把山坡绿化。", "corrected_sentence": "他们把山坡绿化了。", "error_description": "结构错误：“把”字句中动词后需要其他成分，如“了”，应说“把山坡绿化了”，不能只说“把山坡绿化”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
