INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "钱先变成东西，再卖出去变成更多钱，这样转一圈就是资本循环。", "primary_collocate": null, "pronunciation": "zī běn xún huán", "ipa": "tsɨ˥ pən˨˩˦ ɕyn˧˥ xwan˧˥", "syllable_count": 4, "sentences": [{"text": "老板用钱买货，卖出去赚更多钱，这就是资本循环。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先花钱进货，再卖货收钱，这叫资本循环。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店的资本循环很简单：买进来，卖出去。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "资本循环转得快，小店就能多赚钱。", "target_word": "资本循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师用一家水果店讲了资本循环。", "target_word": "资本循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "钱停在仓库里，资本循环就慢了。", "target_word": "资本循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想搞清楚什么是资本循环。", "target_word": "资本循环", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货卖不出去，资本循环就走不下去了。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的资本循环已经转了一整圈。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学过资本循环是怎么回事。", "target_word": "资本循环", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "产业资本循环", "label": "复合"}, {"form": "货币资本循环", "label": "复合"}], "register": "中性", "sense_fingerprint": "钱变成货物，货物卖出后变成更多的钱，转一圈的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4210cd39-20e1-42e6-8e4f-325ff395f566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资本循环", "is_correct": true, "explanation": "前句描述钱变成货、货卖出后赚回更多钱，这正是资本循环。"}, {"text": "税收", "is_correct": false, "explanation": "语义：税收是政府征收的款项，与“买货、卖出、赚钱”的过程无关。"}, {"text": "存款", "is_correct": false, "explanation": "语义：存款是把钱存进银行，不是买货卖货、转一圈的过程。"}, {"text": "八卦", "is_correct": false, "explanation": "语义：“八卦”指闲聊传闻，与买货卖货赚钱的过程无关。"}], "explanations": {"资本循环": "前句描述钱变成货、货卖出后赚回更多钱，这正是资本循环。", "税收": "语义：税收是政府征收的款项，与“买货、卖出、赚钱”的过程无关。", "存款": "语义：存款是把钱存进银行，不是买货卖货、转一圈的过程。", "八卦": "语义：“八卦”指闲聊传闻，与买货卖货赚钱的过程无关。"}, "sentence_index": 0, "correct_answer": "资本循环"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板今天把资本循环卖给了邻居。", "explanation": "这里应该用〈货〉。资本循环是钱变货又变钱的过程，不能拿来卖；卖出去的是货。"}, {"text": "他把资本循环放进了钱包。", "explanation": "这里应该用〈钱〉。资本循环是钱变货又变钱的过程，不是能放进钱包的东西。"}, {"text": "小店这个月的资本循环装进了三个箱子。", "explanation": "这里应该用〈资金〉。资本循环是过程，不是实物，装进箱子的是资金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资本循环", "is_correct": true, "explanation": "“搞清楚什么是”后接需要理解的经济概念，资本循环符合句意。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：午饭是日常饮食，不是需要“搞清楚”的经济概念。"}, {"text": "星期三", "is_correct": false, "explanation": "语义：星期三是时间名词，不是需要“搞清楚”的概念。"}, {"text": "嘴唇", "is_correct": false, "explanation": "搭配：“嘴唇”指具体器官，不与“搞清楚什么是”这类抽象概念搭配。"}], "explanations": {"资本循环": "“搞清楚什么是”后接需要理解的经济概念，资本循环符合句意。", "午饭": "语义：午饭是日常饮食，不是需要“搞清楚”的经济概念。", "星期三": "语义：星期三是时间名词，不是需要“搞清楚”的概念。", "嘴唇": "搭配：“嘴唇”指具体器官，不与“搞清楚什么是”这类抽象概念搭配。"}, "sentence_index": 6, "correct_answer": "资本循环"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家小店的资本循环正在逐步对外招股。", "explanation": "这里应该用〈资本市场〉。资本循环是资本运动的过程，不是可以对外招股的场所。"}, {"text": "他的资本循环很厚，不急着花。", "explanation": "这里应该用〈资产〉。资本循环是过程，不能用“厚”形容；说家底多要用“资产”。"}, {"text": "这次进货的资本循环很重，老板搬不动。", "explanation": "这里应该用〈货〉。资本循环是钱变货又变钱的过程，不能用“重”来形容，搬不动的是货。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "资本循环转下来，小店就能多赚钱。", "corrected_sentence": "资本循环转起来，小店就能多赚钱。", "error_description": "补语错误：表示开始运转要说“转起来”，“转下来”不符合用法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他记录下了一座资本循环。", "corrected_sentence": "他记录下了一次资本循环。", "error_description": "量词错误：资本循环是过程，应以“次”计量，说“一次资本循环”；“座”用于建筑、山峰等大型固定物，不能用于过程。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6cc241-9bc7-4469-bfa6-0ac77477f4dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
