INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24978, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子最上面的部分。", "primary_collocate": null, "pronunciation": "wū dǐng", "ipa": "u⁵⁵ tiŋ²¹⁴", "syllable_count": 2, "sentences": [{"text": "屋顶上有一只小猫。", "target_word": "屋顶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家的屋顶是红色的。", "target_word": "屋顶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他爬上屋顶修房子。", "target_word": "屋顶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，雨打在屋顶上。", "target_word": "屋顶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "屋顶上落了很多雪。", "target_word": "屋顶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鸟儿站在屋顶上唱歌。", "target_word": "屋顶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座房子的屋顶很高。", "target_word": "屋顶", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸用梯子上了屋顶。", "target_word": "屋顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风太大，屋顶都吹坏了。", "target_word": "屋顶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在屋顶上看星星。", "target_word": "屋顶", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "平屋顶", "label": "复合"}, {"form": "屋頂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "房子顶部遮盖的那一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172f7e52-d98b-43ac-869e-8829631459cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "搭配：“空气”不是可以承载物体的地方，不能说“空气上有一只小猫”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是文字符号，不是实体，上面不能有小猫。"}, {"text": "屋顶", "is_correct": true, "explanation": "“屋顶”是房子的顶部，小猫可以待在上面，与语境相合。"}, {"text": "理想", "is_correct": false, "explanation": "搭配：“理想”是抽象概念，不能用“上”来定位小猫。"}], "explanations": {"空气": "搭配：“空气”不是可以承载物体的地方，不能说“空气上有一只小猫”。", "名字": "语义：“名字”是文字符号，不是实体，上面不能有小猫。", "屋顶": "“屋顶”是房子的顶部，小猫可以待在上面，与语境相合。", "理想": "搭配：“理想”是抽象概念，不能用“上”来定位小猫。"}, "sentence_index": 0, "correct_answer": "屋顶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天都拖屋顶。", "explanation": "这里应该用〈地板〉。拖的是地板，屋顶是房子最上面的部分，不能拖。"}, {"text": "他走进房子，关上了屋顶。", "explanation": "这里应该用〈门〉。关上的是门，屋顶是房子的顶部，不能关上。"}, {"text": "他每天开屋顶上班。", "explanation": "这里应该用〈汽车〉。上班要开的是车，屋顶是房子的一部分，不能开着去上班。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”不能用“高”来形容，“这座房子的钥匙很高”不合常理。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能说“高”，应说“浓”或“淡”。"}, {"text": "屋顶", "is_correct": true, "explanation": "“屋顶”指房子上部，说它“很高”符合常识，与句意相合。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”属于人，房子没有心情，“这座房子的心情”不通。"}], "explanations": {"钥匙": "语义：“钥匙”不能用“高”来形容，“这座房子的钥匙很高”不合常理。", "味道": "搭配：“味道”不能说“高”，应说“浓”或“淡”。", "屋顶": "“屋顶”指房子上部，说它“很高”符合常识，与句意相合。", "心情": "语义：“心情”属于人，房子没有心情，“这座房子的心情”不通。"}, "sentence_index": 6, "correct_answer": "屋顶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在院子里种了屋顶。", "explanation": "这里应该用〈花〉。种的是花草，屋顶是房子上方的结构，不能种植。"}, {"text": "妈妈用屋顶煮饭。", "explanation": "这里应该用〈锅〉。煮饭要用锅，屋顶是房子的顶部，不能用来煮饭。"}, {"text": "他把屋顶搬进了房间。", "explanation": "这里应该用〈家具〉。搬进房间的是家具，屋顶是固定在房子上方的结构，不能搬进房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那座房子有一只大屋顶。", "corrected_sentence": "那座房子有一个大屋顶。", "error_description": "错误：“屋顶”前的量词用了“只”。正确：“一个屋顶”。“只”多用于动物或成对事物中的一个，房顶是整体，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天爬了上屋顶。", "corrected_sentence": "他昨天爬上了屋顶。", "error_description": "错误：动态助词“了”位置不对，“爬了上”不成立。正确：“爬上了屋顶”，“了”应放在结果补语“上”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '522a0a63-ca91-46af-bf7c-07bce5feac33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
