INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24982, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "质量高的；品质好的。", "primary_collocate": null, "pronunciation": "gāo pǐn zhì", "ipa": "kɑʊ˥ pʰin˨˩˦ ʈʂɻ̩˥˩", "syllable_count": 3, "sentences": [{"text": "这双鞋是高品质的，穿着很舒服。", "target_word": "高品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我就喜欢买高品质的东西。", "target_word": "高品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子是高品质的，摔了也没坏。", "target_word": "高品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送我一支高品质的笔，我很喜欢。", "target_word": "高品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高品质的水果，吃起来又甜又脆。", "target_word": "高品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的面包是高品质的，价格也不贵。", "target_word": "高品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈只买高品质的米。", "target_word": "高品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件衣服是高品质的，看着就很舒服。", "target_word": "高品质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高品质的音响，声音特别清楚。", "target_word": "高品质", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我宁可多花钱，也要买高品质的床。", "target_word": "高品质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高品質", "label": "繁体"}], "register": "中性", "sense_fingerprint": "质量高的（区别词，常作定语或用于“是……的”）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e86e3800-c774-4bb9-819f-808d2bbca123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高品质", "is_correct": true, "explanation": "正确：“高品质”说明鞋子质量好，与后句“穿着很舒服”相符。"}, {"text": "硬邦邦", "is_correct": false, "explanation": "语义：“硬邦邦”形容鞋子很硬，穿着会不舒服，与后句矛盾。"}, {"text": "紧", "is_correct": false, "explanation": "语义：“紧”指鞋子箍得紧，穿着会难受，与“很舒服”相反。"}, {"text": "发霉", "is_correct": false, "explanation": "搭配：“发霉”多用于食物或衣物受潮的状态，不能用来评价鞋子的质量和舒适。"}], "explanations": {"高品质": "正确：“高品质”说明鞋子质量好，与后句“穿着很舒服”相符。", "硬邦邦": "语义：“硬邦邦”形容鞋子很硬，穿着会不舒服，与后句矛盾。", "紧": "语义：“紧”指鞋子箍得紧，穿着会难受，与“很舒服”相反。", "发霉": "搭配：“发霉”多用于食物或衣物受潮的状态，不能用来评价鞋子的质量和舒适。"}, "sentence_index": 0, "correct_answer": "高品质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个姑娘是高品质的，大家都夸她。", "explanation": "这里应该用〈漂亮〉。高品质说东西的质量，不用于形容人。"}, {"text": "他是个高品质的高个子。", "explanation": "这里应该用〈很高〉。高品质说质量，不表示身高。"}, {"text": "他这次考试的成绩是高品质的。", "explanation": "这里应该用〈好〉。高品质说产品的质量，不用于评价考试成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高品质", "is_correct": true, "explanation": "正确：“高品质”修饰“米”，指质量好，符合“妈妈只买”的语境。"}, {"text": "过期", "is_correct": false, "explanation": "语义：过期的米不能买，与“只买”的语境矛盾。"}, {"text": "免费", "is_correct": false, "explanation": "搭配：“免费”的东西一般不说“买”，与“买”搭配不通。"}, {"text": "生锈", "is_correct": false, "explanation": "语义：米不会生锈，“生锈的米”与日常买米的语境不合。"}], "explanations": {"高品质": "正确：“高品质”修饰“米”，指质量好，符合“妈妈只买”的语境。", "过期": "语义：过期的米不能买，与“只买”的语境矛盾。", "免费": "搭配：“免费”的东西一般不说“买”，与“买”搭配不通。", "生锈": "语义：米不会生锈，“生锈的米”与日常买米的语境不合。"}, "sentence_index": 6, "correct_answer": "高品质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只小狗是高品质的，大家都喜欢它。", "explanation": "这里应该用〈聪明〉。高品质说物品的质量，不用于动物。"}, {"text": "这道题是高品质的，我一下子就做出来了。", "explanation": "这里应该用〈简单〉。高品质不表示题目难易。"}, {"text": "今天的天气是高品质的，很暖和。", "explanation": "这里应该用〈好〉。高品质说物品的质量，不用来形容天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把椅子很高品质的，坐着很稳。", "corrected_sentence": "这把椅子是高品质的，坐着很稳。", "error_description": "「高品质」是区别词，不能受「很」修饰，应把「很」换成「是」，说「是高品质的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台电视是高品质了的，看着很清楚。", "corrected_sentence": "这台电视是高品质的，看着很清楚。", "error_description": "错误：形容词“高品质”后面加了“了”，又带“的”，不符合说法。正确：去掉“了”，说“这台电视是高品质的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
