INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "绿地是长着草和树的地方。", "primary_collocate": null, "pronunciation": "lǜ dì", "ipa": "ly˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "绿地上有很多花和草。", "target_word": "绿地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们跑到绿地上去玩。", "target_word": "绿地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校后面有一片大绿地。", "target_word": "绿地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小狗在绿地上跑来跑去。", "target_word": "绿地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们坐在绿地上吃午饭。", "target_word": "绿地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块绿地里有五棵大树。", "target_word": "绿地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天，绿地变得很漂亮。", "target_word": "绿地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那边的绿地很安静，适合看书。", "target_word": "绿地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天早上在绿地跑步。", "target_word": "绿地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "绿地中间有一条小路。", "target_word": "绿地", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "块", "label": "量词"}, {"form": "綠地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长着草和树的地方，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e86e3800-c774-4bb9-819f-808d2bbca123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24984, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "绿地", "is_correct": true, "explanation": "正确。绿地是长着草和树的地方，读作 lǜ dì。"}, {"text": "陆地", "is_correct": false, "explanation": "lù 与 lǜ 韵母不同（u 与 ü），意思是陆上的地面，不是长着草和树的地方。"}, {"text": "绿堤", "is_correct": false, "explanation": "dī（第一声）与 dì（第四声）声调不同，意思是堤坝。"}, {"text": "绿底", "is_correct": false, "explanation": "dǐ（第三声）与 dì（第四声）声调不同，意思是绿色的底色，不是长草和树的地方。"}], "explanations": {"绿地": "正确。绿地是长着草和树的地方，读作 lǜ dì。", "陆地": "lù 与 lǜ 韵母不同（u 与 ü），意思是陆上的地面，不是长着草和树的地方。", "绿堤": "dī（第一声）与 dì（第四声）声调不同，意思是堤坝。", "绿底": "dǐ（第三声）与 dì（第四声）声调不同，意思是绿色的底色，不是长草和树的地方。"}, "sentence_index": null, "correct_answer": "绿地"}, "level_3": {"options": [{"text": "绿地", "is_correct": true, "explanation": "正确。句子说的是长着花和草的地方，只有绿地符合。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：「上」多接桌面、地面等表面，「教室」是空间，应说「教室里」。"}, {"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不是长花草的地方，句子说花草长在它上面，语义不通。"}, {"text": "厨房", "is_correct": false, "explanation": "搭配：「厨房」是空间，不能与「上」组成表示花草所在位置的说法，应说「厨房里」。"}], "explanations": {"绿地": "正确。句子说的是长着花和草的地方，只有绿地符合。", "教室": "搭配：「上」多接桌面、地面等表面，「教室」是空间，应说「教室里」。", "地铁": "语义：地铁是交通工具，不是长花草的地方，句子说花草长在它上面，语义不通。", "厨房": "搭配：「厨房」是空间，不能与「上」组成表示花草所在位置的说法，应说「厨房里」。"}, "sentence_index": 0, "correct_answer": "绿地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口有一把大绿地。", "explanation": "这里应该用〈片〉或〈块〉。把用于有柄或可以握持的东西，绿地是一片场地，不用「把」。"}, {"text": "院子里有一棵大绿地。", "explanation": "这里应该用〈片〉或〈块〉。棵用于单株植物，绿地是一片地方，不是一棵植物。"}, {"text": "窗台上有一朵大绿地。", "explanation": "这里应该用〈片〉或〈块〉。朵用于花、云等，绿地不能用「朵」来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "绿地", "is_correct": true, "explanation": "正确。「春天，……变得很漂亮」说的是一片景色，只有绿地符合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格指钱的数目，不能「变得很漂亮」，句意不通。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：「漂亮」形容外观或景象，不能说「工资变得很漂亮」。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音是声音，没有可以「变得漂亮」的外观，语义不通。"}], "explanations": {"绿地": "正确。「春天，……变得很漂亮」说的是一片景色，只有绿地符合。", "价格": "语义：价格指钱的数目，不能「变得很漂亮」，句意不通。", "工资": "搭配：「漂亮」形容外观或景象，不能说「工资变得很漂亮」。", "噪音": "语义：噪音是声音，没有可以「变得漂亮」的外观，语义不通。"}, "sentence_index": 6, "correct_answer": "绿地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花的绿地很漂亮。", "explanation": "这里应该用〈绿叶〉。绿叶指植物的叶子，绿地是地面上的场地，不能用来说花的颜色和形态。"}, {"text": "他把绿地插进了花瓶里。", "explanation": "这里应该用〈花束〉。插进花瓶的是花束，绿地是场地，不能插进花瓶。"}, {"text": "他把这块绿地装进了书包。", "explanation": "这里应该用〈课本〉。课本可以装进书包，绿地是固定在地面上的场地，不能装进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "社区里有一棵绿地，长着草和树。", "corrected_sentence": "社区里有一块绿地，长着草和树。", "error_description": "「绿地」应用量词「块」，不应用「棵」。「棵」用于单株植物，绿地是一片场地，不是一棵植物。学习者常把植物的量词套用到场地上。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那些绿地们上都长着草。", "corrected_sentence": "那些绿地上都长着草。", "error_description": "「们」只用于指人或有生命的群体，绿地是无生命的场所，名词后不能加「们」，应直接说「那些绿地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
