INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24986, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "两个地方挨在一起。", "primary_collocate": null, "pronunciation": "pí lín", "ipa": "pʰi˧˥ lin˧˥", "syllable_count": 2, "sentences": [{"text": "我们的教室毗邻图书馆，很安静。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他家毗邻火车站，晚上有点吵。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市毗邻一所小学，上学时人很多。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司毗邻地铁口，上班很方便。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个村子毗邻，走路几分钟就到。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店毗邻海滩，出门就能看到大海。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想租一间毗邻公司的房子。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜市场毗邻公园，早上很热闹。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个湖毗邻森林，风景特别好。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街毗邻河边，晚上很多人来散步。", "target_word": "毗邻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "毗鄰", "label": "繁体"}, {"form": "毗邻着", "label": "体标"}], "register": "书面", "sense_fingerprint": "毗邻：两个地方挨在一起，位置紧靠", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e86e3800-c774-4bb9-819f-808d2bbca123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24986, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毗邻", "is_correct": true, "explanation": "正确：“毗邻”指挨在一起，说明教室与图书馆位置相邻，与“很安静”相符。"}, {"text": "占据", "is_correct": false, "explanation": "语义：“占据”指占用空间，“教室占据图书馆”说不通，与“很安静”也不相关。"}, {"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑，教室拆除图书馆的说法与句意不符。"}, {"text": "冲撞", "is_correct": false, "explanation": "搭配：“冲撞”后接的应是可以碰撞的对象，“教室冲撞图书馆”不成搭配，且与“很安静”矛盾。"}], "explanations": {"毗邻": "正确：“毗邻”指挨在一起，说明教室与图书馆位置相邻，与“很安静”相符。", "占据": "语义：“占据”指占用空间，“教室占据图书馆”说不通，与“很安静”也不相关。", "拆除": "语义：“拆除”指拆掉建筑，教室拆除图书馆的说法与句意不符。", "冲撞": "搭配：“冲撞”后接的应是可以碰撞的对象，“教室冲撞图书馆”不成搭配，且与“很安静”矛盾。"}, "sentence_index": 0, "correct_answer": "毗邻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小狗慢慢毗邻了主人。", "explanation": "这里应该用〈靠近〉。毗邻指两处位置挨在一起，不能表示人或动物主动走近。"}, {"text": "春节毗邻了，大家都忙着买年货。", "explanation": "这里应该用〈临近〉。毗邻只用于空间上的挨着，不能说时间上的接近。"}, {"text": "士兵毗邻了这场战争。", "explanation": "这里应该用〈参加〉。毗邻表示两处地方位置挨着，不能表示人参与某件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毗邻", "is_correct": true, "explanation": "正确：“毗邻”指挨着，修饰“房子”，说明房子在公司旁边，符合“想租”的语境。"}, {"text": "出售", "is_correct": false, "explanation": "语义：“出售”与“租”的意思相反，不能说想租一间出售的房子。"}, {"text": "拖欠", "is_correct": false, "explanation": "语义：“拖欠”指拖延付款，不能修饰房子，与“租”的语境冲突。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是生病，不能说明房子和公司的位置关系，“感冒公司的房子”说不通。"}], "explanations": {"毗邻": "正确：“毗邻”指挨着，修饰“房子”，说明房子在公司旁边，符合“想租”的语境。", "出售": "语义：“出售”与“租”的意思相反，不能说想租一间出售的房子。", "拖欠": "语义：“拖欠”指拖延付款，不能修饰房子，与“租”的语境冲突。", "感冒": "语义：“感冒”是生病，不能说明房子和公司的位置关系，“感冒公司的房子”说不通。"}, "sentence_index": 6, "correct_answer": "毗邻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一见到妈妈，就毗邻过去了。", "explanation": "这里应该用〈扑〉。毗邻表示位置相连，不能表示身体猛地冲向某人。"}, {"text": "医生仔细毗邻病人的伤口。", "explanation": "这里应该用〈检查〉。毗邻只说两处挨着，不能说对伤口进行仔细检视。"}, {"text": "师傅毗邻了那台机器。", "explanation": "这里应该用〈修理〉。毗邻表示位置相连，不表示对机器进行修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一条小河被毗邻我家，夏天很凉快。", "corrected_sentence": "一条小河毗邻我家，夏天很凉快。", "error_description": "错误：“毗邻”表示相邻关系，不能用“被”字句。正确：去掉“被”，说“一条小河毗邻我家”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条街在毗邻一条小河，景色很美。", "corrected_sentence": "这条街毗邻一条小河，景色很美。", "error_description": "错误：“在”表示动作正在进行，而“毗邻”是表示静态关系的动词，不能加“在”。正确：去掉“在”，说“这条街毗邻一条小河”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
