INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24988, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指一处地方能看到的样子。", "primary_collocate": null, "pronunciation": "jǐng guān", "ipa": "tɕiŋ˨˩˦ kwan˥", "syllable_count": 2, "sentences": [{"text": "从山顶看下去，景观非常开阔。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们订了一间景观很好的房间。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外的景观让人心情很好。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐火车去西藏，路上景观一直在变。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个阳台的景观很好，能看到整条江。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高层住宅的景观比低层好，价格也更高。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的景观单调，开车容易犯困。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢坐在窗边，欣赏外面的景观。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜晚的江边景观很美，灯光一直亮着。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了山顶，眼前的景观让大家都安静了。", "target_word": "景观", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "景觀", "label": "繁体"}, {"form": "景观设计", "label": "复合"}], "register": "中性", "sense_fingerprint": "景观：站在一处地方能看到的样子、风景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e86e3800-c774-4bb9-819f-808d2bbca123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24988, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "景观", "is_correct": true, "explanation": "正确：从山顶看下去所见的景象非常开阔。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：「非常开阔」形容空间或景象，价格不能开阔。"}, {"text": "湿度", "is_correct": false, "explanation": "搭配：湿度不能用「开阔」来形容，与山顶的视野描写不搭。"}, {"text": "字数", "is_correct": false, "explanation": "语义：字数与从山顶看到的景象无关，不符合句子的意思。"}], "explanations": {"景观": "正确：从山顶看下去所见的景象非常开阔。", "价格": "搭配：「非常开阔」形容空间或景象，价格不能开阔。", "湿度": "搭配：湿度不能用「开阔」来形容，与山顶的视野描写不搭。", "字数": "语义：字数与从山顶看到的景象无关，不符合句子的意思。"}, "sentence_index": 0, "correct_answer": "景观"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天的景观很好，一直在笑。", "explanation": "这里应该用〈心情〉。景观指从一处地方看到的样子，不能用来形容人的心情。"}, {"text": "窗外的景观很吵，我睡不着。", "explanation": "这里应该用〈声音〉。景观指看到的样子，不能用来形容声音的大小。"}, {"text": "他这次的景观很好，老师很满意。", "explanation": "这里应该用〈成绩〉。景观指看到的样子，不能用来形容考试成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "景观", "is_correct": true, "explanation": "正确：这条路沿途看到的风景单调，开车容易犯困。"}, {"text": "票价", "is_correct": false, "explanation": "搭配：票价不能用「单调」来形容，与路况的描写不搭。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历与路上看到的景色无关，不符合句子的意思。"}, {"text": "寿命", "is_correct": false, "explanation": "语义：寿命与路上的视线和景色无关，不能说这条路的寿命单调。"}], "explanations": {"景观": "正确：这条路沿途看到的风景单调，开车容易犯困。", "票价": "搭配：票价不能用「单调」来形容，与路况的描写不搭。", "学历": "语义：学历与路上看到的景色无关，不符合句子的意思。", "寿命": "语义：寿命与路上的视线和景色无关，不能说这条路的寿命单调。"}, "sentence_index": 6, "correct_answer": "景观"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤的景观很鲜，他喝了一口。", "explanation": "这里应该用〈味道〉。景观指看到的样子，不能用来形容汤的味道。"}, {"text": "他领到了景观，很高兴。", "explanation": "这里应该用〈工资〉。工资是劳动报酬，景观指看到的样子，不能领到景观。"}, {"text": "他的复习景观很好，考试拿了高分。", "explanation": "这里应该用〈效果〉。效果指复习的成效，景观指一处地方看到的样子，不能用来形容复习的成效。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "站在阳台上，这一张景观很美。", "corrected_sentence": "站在阳台上，这一处景观很美。", "error_description": "量词错误：景观应该用量词「处」，写成「张」是误用。「张」多用于平面的东西，不能修饰景观。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24988, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路地景观很美，沿途有很多花。", "corrected_sentence": "这条路的景观很美，沿途有很多花。", "error_description": "助词错误：修饰名词「景观」应用结构助词「的」，写成「地」是误用。「地」用于修饰动词，不能修饰名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
