INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24990, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西卖得比本来贵，多出来的钱。", "primary_collocate": null, "pronunciation": "yì jià", "ipa": "i˥˩ tɕia˥˩", "syllable_count": 2, "sentences": [{"text": "这个包有品牌溢价，所以比同类的贵很多。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演唱会的票有溢价，黄牛卖得比原价贵。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买这台手机，你要多付一千元的溢价。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "热门球鞋常常有溢价，转卖要贵很多。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的咖啡溢价很高，比别处贵一倍。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区里的水有溢价，一瓶要十元。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想付溢价，就等东西降价再买。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新车太热门，经销商要加收溢价。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老店的点心有名，价格里有一部分是溢价。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这件衣服的溢价太高，不值得买。", "target_word": "溢价", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "溢價", "label": "繁体"}, {"form": "溢价率", "label": "复合"}, {"form": "溢价发行", "label": "复合"}], "register": "中性", "sense_fingerprint": "溢价：东西卖得比原价或本来的价格贵，多出来的那部分钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e86e3800-c774-4bb9-819f-808d2bbca123') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "溢价", "is_correct": true, "explanation": "正确：溢价指东西卖得比本来贵，多出来的那部分钱。"}, {"text": "衣架", "is_correct": false, "explanation": "「溢」与「衣」声调不同（第四声与第一声），意思是挂衣服的架子。"}, {"text": "意见", "is_correct": false, "explanation": "「价」与「见」韵母不同（jià 与 jiàn），意思是对事情的看法。"}, {"text": "一家", "is_correct": false, "explanation": "「价」与「家」声调不同（第四声与第一声），意思是一个家庭。"}], "explanations": {"溢价": "正确：溢价指东西卖得比本来贵，多出来的那部分钱。", "衣架": "「溢」与「衣」声调不同（第四声与第一声），意思是挂衣服的架子。", "意见": "「价」与「见」韵母不同（jià 与 jiàn），意思是对事情的看法。", "一家": "「价」与「家」声调不同（第四声与第一声），意思是一个家庭。"}, "sentence_index": null, "correct_answer": "溢价"}, "level_3": {"options": [{"text": "溢价", "is_correct": true, "explanation": "正确：这个包因为品牌而比同类贵出来的那部分钱。"}, {"text": "折扣", "is_correct": false, "explanation": "语义：折扣是降低的价格，与「比同类的贵很多」相反。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色本身不会让包比同类贵很多，与前文的价格比较不符。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：品牌不能带来尺寸，「有品牌尺寸」说不通。"}], "explanations": {"溢价": "正确：这个包因为品牌而比同类贵出来的那部分钱。", "折扣": "语义：折扣是降低的价格，与「比同类的贵很多」相反。", "颜色": "语义：颜色本身不会让包比同类贵很多，与前文的价格比较不符。", "尺寸": "搭配：品牌不能带来尺寸，「有品牌尺寸」说不通。"}, "sentence_index": 0, "correct_answer": "溢价"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府今年给这家店拨了很多溢价。", "explanation": "这里应该用〈补贴〉。补贴是政府给的资助，溢价是东西卖得比本来贵出来的钱，不能指政府拨给店家的款项。"}, {"text": "公司今年发了很多溢价，大家都很高兴。", "explanation": "这里应该用〈奖金〉。奖金是额外发给员工的钱，溢价是卖得比本来贵的那部分钱，不能用来指奖金。"}, {"text": "他每年要交很多溢价。", "explanation": "这里应该用〈学费〉。学费是学校收取的费用，溢价不能指学费。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24990, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "溢价", "is_correct": true, "explanation": "正确：东西降价前，他不想多付的那部分钱。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：「付」的对象是钱，不能说付体积。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：「付重量」说不通，不能和「付」搭配。"}, {"text": "年份", "is_correct": false, "explanation": "语义：年份与东西降价前的钱没有关系，不符合句子的意思。"}], "explanations": {"溢价": "正确：东西降价前，他不想多付的那部分钱。", "体积": "搭配：「付」的对象是钱，不能说付体积。", "重量": "搭配：「付重量」说不通，不能和「付」搭配。", "年份": "语义：年份与东西降价前的钱没有关系，不符合句子的意思。"}, "sentence_index": 6, "correct_answer": "溢价"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的溢价很好听。", "explanation": "这里应该用〈旋律〉。溢价指卖得比本来贵的那部分钱，不能用来形容歌曲好听。"}, {"text": "这套房子的溢价有三间卧室。", "explanation": "这里应该用〈房间〉。溢价指卖得比本来贵的那部分钱，不能用来说房间的数量。"}, {"text": "寄快递时，他的溢价很热情。", "explanation": "这里应该用〈态度〉。溢价指卖得比本来贵的那部分钱，不能用来形容人的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "买这台电脑，你要多付一只溢价。", "corrected_sentence": "买这台电脑，你要多付一笔溢价。", "error_description": "量词错误：溢价应该用量词「笔」，写成「只」是误用。「只」不能修饰溢价这种钱款。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这双鞋常常是溢价，转手时能卖得更贵。", "corrected_sentence": "这双鞋常常有溢价，转手时能卖得更贵。", "error_description": "动词错误：表示存在应用「有」，写成「是」不地道。「是」表示判断，不能说某样东西「是溢价」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '46e4d88b-ff15-4e50-a07b-7d82aa326848') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
