INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24992, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "把钱投到公司或项目里，希望以后能赚更多钱的人。", "primary_collocate": null, "pronunciation": "tóu zī zhě", "ipa": "tʰoʊ˧˥ tsɹ̩˥ ʈʂɤ˨˩˦", "syllable_count": 3, "sentences": [{"text": "他是一位投资者，每年都买股票。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "投资者把钱给了这家新公司。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店有三位投资者。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "投资者希望以后能赚更多的钱。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她做过投资者，也亏过钱。", "target_word": "投资者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小公司需要投资者帮忙。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "投资者每天都看股票价格。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位投资者不想冒太大的风险。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板请投资者来看新工厂。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "投资者听了介绍，决定投钱。", "target_word": "投资者", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位投资者", "label": "量词"}, {"form": "个人投资者", "label": "复合"}], "register": "中性", "sense_fingerprint": "把钱投到公司或项目里希望赚更多钱的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c1b86e-9912-47bf-a178-2800ffb4869e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24992, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "投资者", "is_correct": true, "explanation": "正确。“每年都买股票”与投资者的含义一致，符合语境。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会买股票，与“每年都买股票”矛盾。"}, {"text": "麻雀", "is_correct": false, "explanation": "语义：麻雀是鸟，不是人，不会买股票，也不能用“一位”计量。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不是人，不会买股票，也不能用“一位”计量。"}], "explanations": {"投资者": "正确。“每年都买股票”与投资者的含义一致，符合语境。", "婴儿": "语义：婴儿不会买股票，与“每年都买股票”矛盾。", "麻雀": "语义：麻雀是鸟，不是人，不会买股票，也不能用“一位”计量。", "椅子": "语义：椅子是家具，不是人，不会买股票，也不能用“一位”计量。"}, "sentence_index": 0, "correct_answer": "投资者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用这笔钱买了很多投资者。", "explanation": "这里应该用〈股票〉。投资者是投钱的人，不能被买；买的是“股票”。"}, {"text": "这个项目的投资者是三百万元。", "explanation": "这里应该用〈投资额〉。投资者指投钱的人，不指投入的金额；金额要用“投资额”。"}, {"text": "那只投资者很有钱。", "explanation": "量词应用“位”或“个”；“只”多用于动物，投资者指人，不能用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24992, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "投资者", "is_correct": true, "explanation": "正确。句子说“每天都看股票价格”，主语应是关心股价、会投钱获利的人，即投资者。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子没有意识，不会“看股票价格”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有意识，不会“看股票价格”。"}, {"text": "狗", "is_correct": false, "explanation": "配价：“看股票价格”需要能理解价格的有意识主体，狗不能充当这一角色。"}], "explanations": {"投资者": "正确。句子说“每天都看股票价格”，主语应是关心股价、会投钱获利的人，即投资者。", "桌子": "语义：桌子没有意识，不会“看股票价格”。", "石头": "语义：石头没有意识，不会“看股票价格”。", "狗": "配价：“看股票价格”需要能理解价格的有意识主体，狗不能充当这一角色。"}, "sentence_index": 6, "correct_answer": "投资者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家投资者已经上市了。", "explanation": "这里应该用〈公司〉。投资者是投钱的人，不能上市；上市的是“公司”。"}, {"text": "学生们在投资者里上课。", "explanation": "这里应该用〈教室〉。投资者指投钱的人，不指场所；在教室里上课要说“教室”。"}, {"text": "这条投资者很有钱。", "explanation": "量词应用“位”或“个”；“条”用于细长的东西，不能用于人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24992, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只投资者，去年买了很多股票。", "corrected_sentence": "她是一位投资者，去年买了很多股票。", "error_description": "错误：“一只投资者”，正确：“一位投资者”。“只”多用于动物，投资者指人，量词要用“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24992, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "经理请来了两位投资者们看工厂。", "corrected_sentence": "经理请来了两位投资者看工厂。", "error_description": "错误：“投资者们”，正确：“两位投资者”。有数量词修饰时，名词后不加“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
