INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "房子里面所有房间加起来的面积。", "primary_collocate": null, "pronunciation": "jiàn zhù miàn jī", "ipa": "tɕjɛn˥˩ ʈʂu˥˩ mjɛn˥˩ tɕi˥", "syllable_count": 4, "sentences": [{"text": "我家的建筑面积是八十平方米。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这套房子的建筑面积不大。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想买建筑面积大一点的房子。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "建筑面积就是所有房间加起来的面积。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "广告上写着建筑面积一百平方米。", "target_word": "建筑面积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两套房子的建筑面积一样大。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房子的建筑面积越大，价格越高。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们看了三套建筑面积差不多的房子。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问这套房的建筑面积是多少？", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新家的建筑面积比旧家大二十平方米。", "target_word": "建筑面积", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "总建筑面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "房子里所有房间加起来的面积", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c1b86e-9912-47bf-a178-2800ffb4869e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "建筑面积", "is_correct": true, "explanation": "语义正确：“八十平方米”说的是房子的面积，只有“建筑面积”符合。"}, {"text": "房价", "is_correct": false, "explanation": "搭配：“房价”以元计，不能用“平方米”计量，与“是八十平方米”不搭。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身体数据，不是房屋的属性，与“平方米”也不搭。"}, {"text": "学号", "is_correct": false, "explanation": "语义：学号是学生的编号，与房屋面积毫无关系。"}], "explanations": {"建筑面积": "语义正确：“八十平方米”说的是房子的面积，只有“建筑面积”符合。", "房价": "搭配：“房价”以元计，不能用“平方米”计量，与“是八十平方米”不搭。", "身高": "语义：身高是人的身体数据，不是房屋的属性，与“平方米”也不搭。", "学号": "语义：学号是学生的编号，与房屋面积毫无关系。"}, "sentence_index": 0, "correct_answer": "建筑面积"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个操场的建筑面积是三千平方米。", "explanation": "这里应该用〈占地面积〉。操场是露天场地，没有建筑物，建筑面积不适用。"}, {"text": "这个水箱的建筑面积是一千升。", "explanation": "这里应该用〈容积〉。建筑面积是面积，要用平方米；“一千升”是容量，应说容积。"}, {"text": "这套房子的建筑面积有八十个。", "explanation": "量词错误：面积应用“平方米”计量，不能用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建筑面积", "is_correct": true, "explanation": "语义正确：“越大，价格越高”说的是房子的面积，只有“建筑面积”符合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有“大”小之分，“颜色越大，价格越高”不成立。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“体重”一般用于人或动物，不作为房子的属性。"}, {"text": "人数", "is_correct": false, "explanation": "语义：人数与房子的价格没有这样的关系，句子说的是房子本身的属性。"}], "explanations": {"建筑面积": "语义正确：“越大，价格越高”说的是房子的面积，只有“建筑面积”符合。", "颜色": "语义：颜色没有“大”小之分，“颜色越大，价格越高”不成立。", "体重": "搭配：“体重”一般用于人或动物，不作为房子的属性。", "人数": "语义：人数与房子的价格没有这样的关系，句子说的是房子本身的属性。"}, "sentence_index": 6, "correct_answer": "建筑面积"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的卧室建筑面积是十平方米。", "explanation": "建筑面积指整套房屋所有房间的面积总和，单个房间应说“面积”或“使用面积”。"}, {"text": "这条马路的建筑面积很大。", "explanation": "这里应该用〈占地面积〉。建筑面积只用于房屋建筑，马路是地面道路，应说占地面积。"}, {"text": "这套房子的建筑面积是五十万元。", "explanation": "这里应该用〈建筑成本〉。建筑面积是面积，要用平方米计量；五十万元是花费，应说建筑成本。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套公寓的建筑面积是九十米。", "corrected_sentence": "这套公寓的建筑面积是九十平方米。", "error_description": "量词错误：建筑面积是面积，应用“平方米”计量，“米”是长度单位，不能用来计量面积。应说“这套公寓的建筑面积是九十平方米”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新房的建筑面积跟旧房多二十平方米。", "corrected_sentence": "新房的建筑面积比旧房多二十平方米。", "error_description": "错误在于比较介词“比”被换成了“跟”。表示比较的“多”字句应用“比”，不能用“跟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
