INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24996, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个地方的中心部分。", "primary_collocate": null, "pronunciation": "hé xīn qū", "ipa": "xɤ˧˥ ɕin˥ tɕʰy˥", "syllable_count": 3, "sentences": [{"text": "公园的核心区有一个大湖。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家住在小镇的核心区。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "核心区的路很宽，车也多。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区的核心区不能抽烟。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从机场到城市核心区要一个小时。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古镇的核心区保留了很多老房子。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校园核心区有图书馆和食堂。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客大多都挤在核心区里。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园的核心区很安静。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们去了森林公园的核心区看鸟。", "target_word": "核心区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "核心區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个地方的中心部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c1b86e-9912-47bf-a178-2800ffb4869e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24996, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "核心区", "is_correct": true, "explanation": "正确。核心区指公园的中心部分，句中说这里有一个大湖，符合语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房与“一个大湖”没有关系，“公园的厨房有一个大湖”不成立。"}, {"text": "车库", "is_correct": false, "explanation": "语义：车库是停放车辆的地方，不能有大湖这样的景观，句子不合常理。"}, {"text": "地铁站", "is_correct": false, "explanation": "搭配：“地铁站有一个大湖”这种说法不成立，地铁站与湖泊不搭配。"}], "explanations": {"核心区": "正确。核心区指公园的中心部分，句中说这里有一个大湖，符合语境。", "厨房": "语义：厨房与“一个大湖”没有关系，“公园的厨房有一个大湖”不成立。", "车库": "语义：车库是停放车辆的地方，不能有大湖这样的景观，句子不合常理。", "地铁站": "搭配：“地铁站有一个大湖”这种说法不成立，地铁站与湖泊不搭配。"}, "sentence_index": 0, "correct_answer": "核心区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇论文的核心区是研究方法。", "explanation": "这里应该用〈重点〉。核心区指地方的中心部分，论文的主要内容要用“重点”。"}, {"text": "这次比赛的核心区是得分。", "explanation": "这里应该用〈关键〉。核心区是空间概念，“得分”是比赛的抽象内容，应说“关键”。"}, {"text": "这个城市有一条核心区很热闹。", "explanation": "核心区是地域，量词应用“个”或“片”；“条”用于细长的东西，不能用于地域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "核心区", "is_correct": true, "explanation": "正确。校园核心区指校园的中心部分，图书馆和食堂设在这里，符合语境。"}, {"text": "墓地", "is_correct": false, "explanation": "语义：墓地不会设有图书馆和食堂，与校园语境矛盾。"}, {"text": "码头", "is_correct": false, "explanation": "语义：码头不是校园的中心区域，“校园码头有图书馆和食堂”不成立。"}, {"text": "工地", "is_correct": false, "explanation": "搭配：工地是临时施工场所，不会配有图书馆和食堂这类长期设施。"}], "explanations": {"核心区": "正确。校园核心区指校园的中心部分，图书馆和食堂设在这里，符合语境。", "墓地": "语义：墓地不会设有图书馆和食堂，与校园语境矛盾。", "码头": "语义：码头不是校园的中心区域，“校园码头有图书馆和食堂”不成立。", "工地": "搭配：工地是临时施工场所，不会配有图书馆和食堂这类长期设施。"}, "sentence_index": 6, "correct_answer": "核心区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次展览的核心区是书画作品。", "explanation": "这里应该用〈焦点〉。核心区指地方的中心部分，展览的重心内容要用“焦点”。"}, {"text": "这个公园有一条核心区，游客很多。", "explanation": "核心区是地域，量词应用“个”或“片”；“条”用于细长的东西，不能用于地域。"}, {"text": "这份文件的核心区是付款条件。", "explanation": "这里应该用〈要点〉。核心区指空间上的中心部分，文件的主要内容要用“要点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子们核心区玩耍。", "corrected_sentence": "孩子们在核心区玩耍。", "error_description": "错误：缺少“在”。正确：“在核心区玩耍”。表示动作发生的地点，前面要加介词“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游客们在一条核心区看到了一座老塔。", "corrected_sentence": "游客们在核心区看到了一座老塔。", "error_description": "错误：“一条核心区”，正确：“核心区”。核心区是地域，不能用细长事物的量词“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
