INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24998, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "房子或楼里自成一体、可以单独居住或出租的一部分。", "primary_collocate": null, "pronunciation": "dān yuán", "ipa": "tan˥˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这套房子有一个独立的单元，可以出租。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室被改成了一个小单元。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个单元有自己的门和厨房。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把大房间分成了两个单元。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "后院有一个单元，客人可以住在那里。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租客住在后面的单元里，不用走前门。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个单元太小，放不下两张床。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房东打算把旁边的单元租给学生。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有一个单元专门给客人住。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "楼上的单元住着一位老人。", "target_word": "单元", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "单元房", "label": "复合"}], "register": "中性", "sense_fingerprint": "单元|房子或楼里可以单独居住或出租的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77bd49ee-81b2-46c0-a146-5020ea436bdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24998, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "单元", "is_correct": true, "explanation": "正确：“独立的单元”指房屋中可以单独出租的居住部分，与“这套房子”“可以出租”相合。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是可以单独出租的居住空间，“独立的窗户”不合理。"}, {"text": "日记", "is_correct": false, "explanation": "语义：日记是私人记录，不能单独出租，与句中“可以出租”冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“独立”多修饰空间或单位，不说“独立的冰箱”，与“出租”的语境不合。"}], "explanations": {"单元": "正确：“独立的单元”指房屋中可以单独出租的居住部分，与“这套房子”“可以出租”相合。", "窗户": "语义：窗户不是可以单独出租的居住空间，“独立的窗户”不合理。", "日记": "语义：日记是私人记录，不能单独出租，与句中“可以出租”冲突。", "冰箱": "搭配：“独立”多修饰空间或单位，不说“独立的冰箱”，与“出租”的语境不合。"}, "sentence_index": 0, "correct_answer": "单元"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条单元有两间卧室，客厅很亮。", "explanation": "量词〈条〉用于长形的东西，不能修饰“单元”，这里应该用〈个〉。"}, {"text": "这只单元住着一位老人。", "explanation": "量词〈只〉用于动物，不能修饰房屋中的一个部分，这里应该用〈个〉。"}, {"text": "面积的单元是平方米。", "explanation": "这里应该用〈单位〉。面积的度量标准说“单位”，“单元”指房屋中的独立部分，不用于度量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24998, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "单元", "is_correct": true, "explanation": "正确：“这个单元”指房屋中的一个独立部分，可以“太小、放不下床”，与句意相合。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是无边的大气，不是可以容纳床的空间，句子不成立。"}, {"text": "信箱", "is_correct": false, "explanation": "语义：信箱是收信的小箱子，不指居住空间，“放不下两张床”与信箱的功能无关。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“放不下两张床”说的是居住或摆放的空间，手机不能作为容纳床的空间。"}], "explanations": {"单元": "正确：“这个单元”指房屋中的一个独立部分，可以“太小、放不下床”，与句意相合。", "天空": "语义：天空是无边的大气，不是可以容纳床的空间，句子不成立。", "信箱": "语义：信箱是收信的小箱子，不指居住空间，“放不下两张床”与信箱的功能无关。", "手机": "搭配：“放不下两张床”说的是居住或摆放的空间，手机不能作为容纳床的空间。"}, "sentence_index": 6, "correct_answer": "单元"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那幅单元的窗户很大。", "explanation": "量词〈幅〉用于画作，不能修饰“单元”，这里应该用〈个〉。"}, {"text": "这个单元有三座公园，环境很好。", "explanation": "这里应该用〈小区〉。“单元”是房屋内的一部分，不能包含多座公园；整片住宅区要说“小区”。"}, {"text": "这张单元有电梯。", "explanation": "量词〈张〉用于桌子、床等平面的东西，不能修饰“单元”，这里应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24998, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这套房子隔成了两只单元，分别出租。", "corrected_sentence": "我把这套房子隔成了两个单元，分别出租。", "error_description": "量词错误：“单元”应搭配通用量词“个”，不能用动物量词“只”。正确说法是“两个单元”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (24998, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那座单元的厨房很干净。", "corrected_sentence": "那个单元的厨房很干净。", "error_description": "量词错误：“单元”应搭配“个”。“座”多用于大型建筑、山等，不能修饰房屋中的一个独立部分。正确说法是“那个单元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '92aa8ae7-b62c-4b3b-8ca5-eea7d1515997') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
