INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个地方的位置。", "primary_collocate": null, "pronunciation": "qū wèi", "ipa": "tɕʰy˥ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这家饭店的区位很方便。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买房子要先看区位。", "target_word": "区位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个学校的区位不太好。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家超市的区位很好，旁边就是地铁站。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他喜欢区位好的房子。", "target_word": "区位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "区位就是一个地方的位置。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块地的区位很特别。", "target_word": "区位", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老板很满意商店的区位。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个地方的区位差别很大。", "target_word": "区位", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "区位好，客人就多。", "target_word": "区位", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "区位优势", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个地方所在的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c1b86e-9912-47bf-a178-2800ffb4869e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "区位", "is_correct": true, "explanation": "语义正确：“区位”指地方的位置，“很方便”说的正是位置的便利。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”一般说“高/低”，不说“很方便”，与句意不搭。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的身体数据，不能用来形容饭店。"}, {"text": "学号", "is_correct": false, "explanation": "语义：学号是学生的编号，与饭店没有关系。"}], "explanations": {"区位": "语义正确：“区位”指地方的位置，“很方便”说的正是位置的便利。", "价格": "搭配：“价格”一般说“高/低”，不说“很方便”，与句意不搭。", "身高": "语义：身高是人的身体数据，不能用来形容饭店。", "学号": "语义：学号是学生的编号，与饭店没有关系。"}, "sentence_index": 0, "correct_answer": "区位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书的区位在第三层书架上。", "explanation": "这里应该用〈位置〉。书架上的摆放用“位置”，区位指地区或空间的经济地理位置。"}, {"text": "我的区位在最后一排。", "explanation": "这里应该用〈座位〉。区位指地区或空间的位置，不指座位。"}, {"text": "这台区位很好，离港口近。", "explanation": "量词错误：区位是抽象名词，不能用“台”（机器等的量词）计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "区位", "is_correct": true, "explanation": "语义正确：“这块地的___很特别”指地点的位置特别，只有“区位”符合。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是人的受教育程度，不能用来形容土地。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是物体或人的重量，与土地的特别之处无关。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指年数，“这块地的年龄很特别”不是评价地点的说法，与句意不合。"}], "explanations": {"区位": "语义正确：“这块地的___很特别”指地点的位置特别，只有“区位”符合。", "学历": "语义：学历是人的受教育程度，不能用来形容土地。", "体重": "语义：体重是物体或人的重量，与土地的特别之处无关。", "年龄": "语义：年龄指年数，“这块地的年龄很特别”不是评价地点的说法，与句意不合。"}, "sentence_index": 6, "correct_answer": "区位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次比赛的区位很激烈。", "explanation": "这里应该用〈竞争〉。区位指地点的位置，不能形容比赛的激烈程度，应说“竞争很激烈”。"}, {"text": "这首歌的区位很好听。", "explanation": "这里应该用〈旋律〉。区位指一个地方的位置，不能用来形容歌曲的好听程度，应说“旋律很好听”。"}, {"text": "他的区位很高。", "explanation": "这里应该用〈地位〉。区位指地点的位置，不用于描述人的社会地位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地的区位的不错。", "corrected_sentence": "这块地的区位不错。", "error_description": "错误在于“区位”后多加了“的”。“区位”后应直接接形容词“不错”，不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭店的区位好很。", "corrected_sentence": "这家饭店的区位很好。", "error_description": "语序错误：程度副词“很”应放在形容词“好”之前，应说“很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
