INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25002, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对事物的价值、水平或情况做出判断。", "primary_collocate": null, "pronunciation": "píng gū", "ipa": "pʰiŋ˧˥ ku˥˥", "syllable_count": 2, "sentences": [{"text": "公司正在评估这个新计划。", "target_word": "评估", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生要先评估病人的身体情况。", "target_word": "评估", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师评估了每个学生的学习水平。", "target_word": "评估", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要评估一下这次活动的效果。", "target_word": "评估", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家来评估这座房子的价格。", "target_word": "评估", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你评估一下这个办法行不行。", "target_word": "评估", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行会评估你还钱的能力。", "target_word": "评估", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们评估了这次旅行可能有的危险。", "target_word": "评估", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板还在评估这个新产品能不能卖好。", "target_word": "评估", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师评估后说，这座桥还可以用。", "target_word": "评估", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "評估", "label": "繁体"}, {"form": "评估报告", "label": "复合"}], "register": "中性", "sense_fingerprint": "对事物的价值、水平或情况做出判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25002, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "评估", "is_correct": true, "explanation": "原句说公司在对新计划做判断，“评估”指对事物的价值、水平做判断，正合适。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，不能说“喝这个计划”。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说“穿这个计划”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指种庄稼或花木，与对计划的判断无关。"}], "explanations": {"评估": "原句说公司在对新计划做判断，“评估”指对事物的价值、水平做判断，正合适。", "喝": "搭配：“喝”的对象是饮品，不能说“喝这个计划”。", "穿": "搭配：“穿”的对象是衣物，不能说“穿这个计划”。", "种植": "语义：“种植”指种庄稼或花木，与对计划的判断无关。"}, "sentence_index": 0, "correct_answer": "评估"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈评估了我的哭声，然后走开了。", "explanation": "这里应该用〈不理〉。“评估”是对价值或水平作判断，不能表示对哭声的态度，应说“不理”。"}, {"text": "我们评估你的到来。", "explanation": "这里应该用〈欢迎〉。“评估”是对事物做判断，不能表示对来客的迎接态度，应说“欢迎”。"}, {"text": "大家评估了他的生日。", "explanation": "这里应该用〈庆祝〉。“评估”不能用于生日这种节日活动，庆祝生日要用“庆祝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "评估", "is_correct": true, "explanation": "原句说银行对你还钱的能力做判断，“评估”正合适。"}, {"text": "忘记", "is_correct": false, "explanation": "语义：银行不会“忘记”能力，此处应指对能力的判断。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”的对象是物品，不能说“装饰能力”。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌，不能说“唱能力”。"}], "explanations": {"评估": "原句说银行对你还钱的能力做判断，“评估”正合适。", "忘记": "语义：银行不会“忘记”能力，此处应指对能力的判断。", "装饰": "搭配：“装饰”的对象是物品，不能说“装饰能力”。", "唱": "搭配：“唱”的对象是歌，不能说“唱能力”。"}, "sentence_index": 6, "correct_answer": "评估"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师评估了我一下，我马上笑了。", "explanation": "这里应该用〈逗〉。“评估”是对事物做判断，不能表示逗人开心，逗人要用“逗”。"}, {"text": "大家在车站评估客人。", "explanation": "这里应该用〈迎接〉。“评估”不表示到站接人，接站要用“迎接”。"}, {"text": "大家评估了春节的第一天。", "explanation": "这里应该用〈度过〉。“评估”是对事物做判断，不能用于度过时光，应说“度过”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司正在把评估这个新产品。", "corrected_sentence": "公司正在评估这个新产品。", "error_description": "“把”字句的语序是“把＋宾语＋动词”，“把评估这个新产品”颠倒了宾语和动词的位置。这里不需要“把”，应直接说“公司正在评估这个新产品”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们没评估了这次出差的风险。", "corrected_sentence": "他们没评估这次出差的风险。", "error_description": "“没”否定动作时不能带“了”，“没评估了”不对，应说“没评估”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25004, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "充足", "is_correct": true, "explanation": "正确答案。充足指数量足够，与“稀缺”构成反义。"}, {"text": "响亮", "is_correct": false, "explanation": "响亮描写声音，与稀缺没有反义关系。"}, {"text": "笔直", "is_correct": false, "explanation": "笔直描写形状或方向，与稀缺没有反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "潮湿描写环境的湿度，与稀缺没有反义关系。"}], "correct_answer": "充足", "explanations": {"充足": "正确答案。充足指数量足够，与“稀缺”构成反义。", "响亮": "响亮描写声音，与稀缺没有反义关系。", "笔直": "笔直描写形状或方向，与稀缺没有反义关系。", "潮湿": "潮湿描写环境的湿度，与稀缺没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25004, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "充足", "is_correct": true, "explanation": "正确答案。充足指数量足够，与“稀缺”构成反义。"}, {"text": "粗糙", "is_correct": false, "explanation": "粗糙描写表面质地，与稀缺没有反义关系。"}, {"text": "漫长", "is_correct": false, "explanation": "漫长描写时间的长度，与稀缺没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭描写地势，与稀缺没有反义关系。"}], "correct_answer": "充足", "explanations": {"充足": "正确答案。充足指数量足够，与“稀缺”构成反义。", "粗糙": "粗糙描写表面质地，与稀缺没有反义关系。", "漫长": "漫长描写时间的长度，与稀缺没有反义关系。", "陡峭": "陡峭描写地势，与稀缺没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25004, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很少，不够用。", "primary_collocate": null, "pronunciation": "xī quē", "ipa": "ɕi˥ tɕʰɥe˥", "syllable_count": 2, "sentences": [{"text": "山上的水很稀缺。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书现在很稀缺，书店里买不到。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，这里的雨水十分稀缺。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的工作机会越来越稀缺了。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在海边，淡水特别稀缺。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花很稀缺，只有山里才有。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时期，药品非常稀缺。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子里的医生很稀缺，病人要等很久。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物资稀缺的时候，大家都很节约。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在人才很稀缺，公司都在找人。", "target_word": "稀缺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稀缺性", "label": "复合"}, {"form": "稀缺资源", "label": "复合"}], "register": "中性", "sense_fingerprint": "很少，不够用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '04c1b86e-9912-47bf-a178-2800ffb4869e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25004, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稀缺", "is_correct": true, "explanation": "正确答案。“山上的水很稀缺”成立，表示水很少、不够用。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：水不能“热闹”，句子不成立。"}, {"text": "聪明", "is_correct": false, "explanation": "配价：“聪明”要求有智慧的主体作主语，水不能被说成聪明。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容人的神情或态度，不用来形容水。"}], "explanations": {"稀缺": "正确答案。“山上的水很稀缺”成立，表示水很少、不够用。", "热闹": "语义：水不能“热闹”，句子不成立。", "聪明": "配价：“聪明”要求有智慧的主体作主语，水不能被说成聪明。", "严肃": "语义：“严肃”形容人的神情或态度，不用来形容水。"}, "sentence_index": 0, "correct_answer": "稀缺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个孩子的脾气很稀缺，大家都怕他。", "explanation": "这里应该用〈暴躁〉。稀缺指东西很少、不够用，不能用来形容人的脾气，说脾气不好要用“暴躁”。"}, {"text": "这幅画的颜色很稀缺，看起来很暗。", "explanation": "这里应该用〈鲜艳〉。稀缺指东西很少、不够用，不能用来形容颜色的明暗，说颜色亮丽要用“鲜艳”。"}, {"text": "这个歌手的声音很稀缺，观众都很喜欢。", "explanation": "这里应该用〈动听〉。稀缺指东西很少、不够用，不能用来形容声音的好坏，说声音好听要用“动听”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀缺", "is_correct": true, "explanation": "正确答案。“战争时期，药品非常稀缺”成立，表示药品很少、不够用。"}, {"text": "幽默", "is_correct": false, "explanation": "语义：药品不能“幽默”，句子不成立。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“非常安静”多用于环境或人的状态，药品不说安静。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：药品没有情绪，不能说高兴，句子不成立。"}], "explanations": {"稀缺": "正确答案。“战争时期，药品非常稀缺”成立，表示药品很少、不够用。", "幽默": "语义：药品不能“幽默”，句子不成立。", "安静": "搭配：“非常安静”多用于环境或人的状态，药品不说安静。", "高兴": "语义：药品没有情绪，不能说高兴，句子不成立。"}, "sentence_index": 6, "correct_answer": "稀缺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子的温度很稀缺，大家都觉得很舒服。", "explanation": "这里应该用〈适宜〉。稀缺指东西很少、不够用，不能用来形容温度的高低，说温度合适要用“适宜”。"}, {"text": "这块玉的质地很稀缺，摸起来很舒服。", "explanation": "这里应该用〈细腻〉。稀缺指东西很少、不够用，不能用来形容质地的细密，说质地细密要用“细腻”。"}, {"text": "这把椅子的高度很稀缺，坐起来很舒服。", "explanation": "这里应该用〈合适〉。稀缺指东西很少、不够用，不能用来形容高度是否合适，说高度适宜要用“合适”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个地区的淡水被稀缺了。", "corrected_sentence": "这个地区的淡水稀缺了。", "error_description": "语态错误：形容词“稀缺”表示状态，不能用“被”构成被动句，应去掉“被”，说“这个地区的淡水稀缺了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里的雨水没稀缺。", "corrected_sentence": "这里的雨水不稀缺。", "error_description": "否定词错误：形容词“稀缺”表示状态，否定要用“不”，不能用“没”。应说“这里的雨水不稀缺”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceada015-636b-4b3a-b658-ac899e520e76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
