INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "开发商是盖房子、卖房子的人或公司。", "primary_collocate": null, "pronunciation": "kāi fā shāng", "ipa": "kʰai˥ fa˥ ʂɑŋ˥", "syllable_count": 3, "sentences": [{"text": "开发商正在这块地上盖新房子。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们向开发商买了一套小房子。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商说下个月就可以看房。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家开发商盖的房子又大又漂亮。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商把房子卖完以后就走了。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小区的水管坏了，业主去找开发商。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商在广告里说，小区旁边有地铁。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个开发商已经盖了二十年房子。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商花了两年时间才盖好这些楼。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开发商还没修好路，我们先不买房。", "target_word": "开发商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "房地产开发商", "label": "复合"}, {"form": "開發商", "label": "繁体"}], "register": "中性", "sense_fingerprint": "开发商：盖房子、卖房子的人或公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11855e5-45fd-4c04-9c51-cf5ccf93758f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开发商", "is_correct": true, "explanation": "正确。“开发商”指盖房、卖房的企业或个人，是这块地上盖新房子的主体。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生不会在这块地上盖房子，与“盖新房子”的语义不符。"}, {"text": "地铁", "is_correct": false, "explanation": "配价：“盖”的施事要能动，“地铁”是交通设施，不能作“盖新房子”的主语。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不能盖房子，整句无法成立。"}], "explanations": {"开发商": "正确。“开发商”指盖房、卖房的企业或个人，是这块地上盖新房子的主体。", "小学生": "语义：小学生不会在这块地上盖房子，与“盖新房子”的语义不符。", "地铁": "配价：“盖”的施事要能动，“地铁”是交通设施，不能作“盖新房子”的主语。", "水果": "语义：水果不能盖房子，整句无法成立。"}, "sentence_index": 0, "correct_answer": "开发商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这套房子的开发商每天早上都来开车接我上班。", "explanation": "这里应该用〈司机〉。开车接人上班是司机的工作，开发商指盖房、卖房的企业或个人。"}, {"text": "开发商在饭馆里给我们做了一桌菜。", "explanation": "这里应该用〈厨师〉。做菜是厨师的工作，开发商指盖房、卖房的企业或个人。"}, {"text": "开发商在医院里给病人打针。", "explanation": "这里应该用〈医生〉。给病人打针是医生的工作，开发商指盖房、卖房的企业或个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开发商", "is_correct": true, "explanation": "正确。“开发商”指盖房、卖房的企业或个人，能够在广告里发布信息。"}, {"text": "天气", "is_correct": false, "explanation": "配价：“说”要求能说话的言者，“天气”不能在广告里说话。"}, {"text": "冰箱", "is_correct": false, "explanation": "配价：“在广告里说”的主语需能发出言语，“冰箱”不能作言者。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机不是广告信息的发布者，“小区旁边有地铁”的信息与它无关。"}], "explanations": {"开发商": "正确。“开发商”指盖房、卖房的企业或个人，能够在广告里发布信息。", "天气": "配价：“说”要求能说话的言者，“天气”不能在广告里说话。", "冰箱": "配价：“在广告里说”的主语需能发出言语，“冰箱”不能作言者。", "洗衣机": "语义：洗衣机不是广告信息的发布者，“小区旁边有地铁”的信息与它无关。"}, "sentence_index": 6, "correct_answer": "开发商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "开发商把我的裤子改短了两寸。", "explanation": "这里应该用〈裁缝〉。改裤子是裁缝的工作，开发商指盖房、卖房的企业或个人。"}, {"text": "开发商给我剪了一个短发。", "explanation": "这里应该用〈理发师〉。剪头发是理发师的工作，开发商指盖房、卖房的企业或个人。"}, {"text": "开发商每天给学生上课。", "explanation": "这里应该用〈老师〉。给学生上课是老师的工作，开发商指盖房、卖房的企业或个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只开发商把新楼盘卖给了很多人。", "corrected_sentence": "这家开发商把新楼盘卖给了很多人。", "error_description": "量词错误。“开发商”多指企业，量词用“家”；“只”多用于动物等，不能用于企业。正确形式为“这家开发商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们的小区是一只大开发商盖的。", "corrected_sentence": "我们的小区是一家大开发商盖的。", "error_description": "量词错误。“开发商”多指企业，量词用“家”；“只”多用于动物等，不能用于企业。正确形式为“一家大开发商”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
