INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25008, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一根硬棍子，可以撬起很重的东西。", "primary_collocate": null, "pronunciation": "gàng gǎn", "ipa": "kɑŋ˥˩ kan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这根杠杆又硬又长。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿杠杆去撬那块大石头。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杠杆的一头压下去，石头就翘起来了。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用一根铁杠杆撬开了门。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头杠杆太细，会断的。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，我们用杠杆抬起了旧柜子。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杠杆放在石头下面，用力往下压。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友第一次见到杠杆，觉得很有意思。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根杠杆很重，一个人拿不动。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找来一根杠杆，想撬起地上的箱子。", "target_word": "杠杆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根", "label": "量词"}, {"form": "杠杆原理", "label": "复合"}, {"form": "槓桿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "杠杆：能撬起重物的硬棍子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11855e5-45fd-4c04-9c51-cf5ccf93758f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "杠杆", "is_correct": true, "explanation": "正确：“杠杆”是一根又硬又长的硬棍，与“又硬又长”的描述相符。"}, {"text": "歌声", "is_correct": false, "explanation": "语义：歌声是声音，没有形体，不能“又硬又长”。"}, {"text": "毛线", "is_correct": false, "explanation": "体貌：毛线柔软细长，不能形容为“又硬又长”。"}, {"text": "月光", "is_correct": false, "explanation": "语义：月光是光线，没有硬度，不能“又硬又长”。"}], "explanations": {"杠杆": "正确：“杠杆”是一根又硬又长的硬棍，与“又硬又长”的描述相符。", "歌声": "语义：歌声是声音，没有形体，不能“又硬又长”。", "毛线": "体貌：毛线柔软细长，不能形容为“又硬又长”。", "月光": "语义：月光是光线，没有硬度，不能“又硬又长”。"}, "sentence_index": 0, "correct_answer": "杠杆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人用杠杆拧紧了螺丝。", "explanation": "这里应该用〈扳手〉。拧螺丝要用扳手；杠杆是用来翘起重物的硬棍，不能拧螺丝。"}, {"text": "他用杠杆切开了一块蛋糕。", "explanation": "这里应该用〈刀〉。切蛋糕要用刀；杠杆是用来翘起重物的硬棍，不能用来切东西。"}, {"text": "他用杠杆煮好了一锅粥。", "explanation": "这里应该用〈锅〉。煮粥要用锅；杠杆是用来翘起重物的硬棍，不能用来煮东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杠杆", "is_correct": true, "explanation": "正确：“杠杆”放在石头下面、用力往下压，正是翘起重物的用法。"}, {"text": "窗帘", "is_correct": false, "explanation": "语义：窗帘不是工具，不能拿来翘起石头。"}, {"text": "羽毛", "is_correct": false, "explanation": "体貌：羽毛轻软，压不住石头，说不上“用力往下压”。"}, {"text": "棉花", "is_correct": false, "explanation": "体貌：棉花蓬松柔软，没有可以用力下压的硬着力点。"}], "explanations": {"杠杆": "正确：“杠杆”放在石头下面、用力往下压，正是翘起重物的用法。", "窗帘": "语义：窗帘不是工具，不能拿来翘起石头。", "羽毛": "体貌：羽毛轻软，压不住石头，说不上“用力往下压”。", "棉花": "体貌：棉花蓬松柔软，没有可以用力下压的硬着力点。"}, "sentence_index": 6, "correct_answer": "杠杆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用杠杆给手机充了电。", "explanation": "这里应该用〈充电器〉。给手机充电要用充电器；杠杆是用来翘起重物的硬棍，不能充电。"}, {"text": "妈妈用杠杆缝好了衣服上的破洞。", "explanation": "这里应该用〈针线〉。缝补破洞要用针线；杠杆是用来翘起重物的硬棍，不能用来缝补。"}, {"text": "他把杠杆当作雨伞撑开，走进了雨里。", "explanation": "这里应该用〈雨伞〉。遮雨要用雨伞；杠杆是用来翘起重物的硬棍，不能撑开遮雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只杠杆能把车轮抬起来。", "corrected_sentence": "这根杠杆能把车轮抬起来。", "error_description": "量词错误：长条硬棍的杠杆应该用量词“根”，说“这根杠杆”，不能用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用力把杠杆压去下了。", "corrected_sentence": "他用力把杠杆压下去了。", "error_description": "趋向补语语序错误：“压下去”中“下”在前、“去”在后，应说“压下去”，不能说“压去下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
