INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25010, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把植物的根泡在水里，让植物长大。", "primary_collocate": null, "pronunciation": "shuǐ péi", "ipa": "ʂweɪ̯˨˩ pʰeɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "我把绿萝放在瓶子里水培。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盆薄荷可以水培，也可以土培。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用玻璃杯水培大蒜。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水培的时候，水要经常换。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铜钱草很容易水培。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在窗台上水培了一盆风信子。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水培时不要让叶子泡在水里。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐喜欢水培，因为不会弄脏手。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以试着水培这棵红薯。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花水培比土培更容易活。", "target_word": "水培", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "水培了", "label": "体标"}, {"form": "水培过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把植物根部泡在水里养大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11855e5-45fd-4c04-9c51-cf5ccf93758f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水培", "is_correct": true, "explanation": "正确：“水培”是把植物根泡在水中养育，这里的动作正是把绿萝放在瓶子里养。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：绿萝不能冷冻处理，放进瓶子里冷冻说不通。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：烘干会让植物枯萎，与“放在瓶子里”的养护动作不符。"}, {"text": "腌", "is_correct": false, "explanation": "搭配：“腌”一般用于食物，不与“绿萝”搭配。"}], "explanations": {"水培": "正确：“水培”是把植物根泡在水中养育，这里的动作正是把绿萝放在瓶子里养。", "冷冻": "语义：绿萝不能冷冻处理，放进瓶子里冷冻说不通。", "烘干": "语义：烘干会让植物枯萎，与“放在瓶子里”的养护动作不符。", "腌": "搭配：“腌”一般用于食物，不与“绿萝”搭配。"}, "sentence_index": 0, "correct_answer": "水培"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这盆薄荷适合水培，根要埋进土里。", "explanation": "这里应该用〈土培〉。水培是让根泡在水中；根埋进土里的是土培，两者自相矛盾。"}, {"text": "妈妈用水培把白衬衫洗得很干净。", "explanation": "这里应该用〈洗〉。洗衣服是用水清洗衣物；水培是让植物根泡在水中养育的做法，不能用来洗衣服。"}, {"text": "妈妈把黄瓜放进盐水里水培一夜。", "explanation": "这里应该用〈腌〉。腌黄瓜要放进盐水里；水培是让植物根部浸在水中养育，不能用来处理食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水培", "is_correct": true, "explanation": "正确：“水培”指养植物的过程，这里作时间状语，与“叶子不要泡水”相符。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙是做面包点心的工序，与植物养护无关。"}, {"text": "煎炸", "is_correct": false, "explanation": "语义：煎炸是烹饪方法，不指植物的养护。"}, {"text": "打字", "is_correct": false, "explanation": "语义：打字是用键盘输入文字，与植物养护无关。"}], "explanations": {"水培": "正确：“水培”指养植物的过程，这里作时间状语，与“叶子不要泡水”相符。", "烘焙": "语义：烘焙是做面包点心的工序，与植物养护无关。", "煎炸": "语义：煎炸是烹饪方法，不指植物的养护。", "打字": "语义：打字是用键盘输入文字，与植物养护无关。"}, "sentence_index": 6, "correct_answer": "水培"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种茶叶要用开水水培。", "explanation": "这里应该用〈泡〉。泡茶是用热水冲泡饮品；水培是养植物的方法，不用于冲泡茶叶。"}, {"text": "妈妈用水培把花园里的草拔掉了。", "explanation": "这里应该用〈拔〉。除草要把草拔掉；水培是养育植物的方法，不能用来除草。"}, {"text": "给小狗水培一碗饭。", "explanation": "这里应该用〈喂〉。水培只用于养植物，不能用来给小狗喂食。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈以前水培了过一盆绿萝。", "corrected_sentence": "妈妈以前水培过一盆绿萝。", "error_description": "体标错误：“了”与“过”不能同时用在动词后，应去掉“了”，说“水培过一盆绿萝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把花水培很好。", "corrected_sentence": "她把花水培得很好。", "error_description": "程度补语错误：动词后的程度补语要用“得”，应说“水培得很好”，不能说“水培很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
