INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "别人或公司拥有的钱和东西。", "primary_collocate": null, "pronunciation": "zī chǎn", "ipa": "tsɹ̩˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "老板的资产有房子、车和一些钱。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的资产少了，工人的工资也发不出。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的资产不多，只有一套小房子。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的资产包括桌子、机器和存款。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王想知道公司现在有多少资产。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司卖掉一部分资产，还了银行的钱。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把自己的资产分给了三个孩子。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个人资产很多，可是生活很简单。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好公司会好好管理自己的资产。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "银行的人来检查了公司的资产。", "target_word": "资产", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "笔", "label": "量词"}, {"form": "固定资产", "label": "复合"}, {"form": "資產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "资产：别人或公司拥有的钱和东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11855e5-45fd-4c04-9c51-cf5ccf93758f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "资产", "is_correct": true, "explanation": "正确。“资产”指拥有的钱和东西，这里指老板拥有的房子、车和钱。"}, {"text": "收入", "is_correct": false, "explanation": "语义：收入是一段时间得到的钱，不是能拥有房子和车的东西。"}, {"text": "名字", "is_correct": false, "explanation": "搭配：“有”后接房子、车等拥有物时，“名字”不能这样搭配。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以拥有的东西，句子不成立。"}], "explanations": {"资产": "正确。“资产”指拥有的钱和东西，这里指老板拥有的房子、车和钱。", "收入": "语义：收入是一段时间得到的钱，不是能拥有房子和车的东西。", "名字": "搭配：“有”后接房子、车等拥有物时，“名字”不能这样搭配。", "天气": "语义：天气不是可以拥有的东西，句子不成立。"}, "sentence_index": 0, "correct_answer": "资产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月的资产不多，只够吃饭。", "explanation": "这里应该用〈工资〉。资产指拥有的钱和东西，按月领取的报酬才用“工资”。"}, {"text": "这间屋子的资产很便宜。", "explanation": "这里应该用〈房租〉。这里说的是租这间屋子要付的钱，是房租；资产指拥有的钱和东西，不能说“屋子的资产很便宜”。"}, {"text": "他的年终资产很高。", "explanation": "这里应该用〈奖金〉。年终发的额外报酬要说“奖金”，资产指拥有的钱和东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "资产", "is_correct": true, "explanation": "正确。“分给”的对象是爷爷拥有的财物，“资产”指拥有的钱和东西，语义吻合。"}, {"text": "地址", "is_correct": false, "explanation": "搭配：“分给”的对象是财物，不说“分给孩子地址”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是可以分给孩子的东西，句子不成立。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳无法被爷爷分给孩子，整句不合常识。"}], "explanations": {"资产": "正确。“分给”的对象是爷爷拥有的财物，“资产”指拥有的钱和东西，语义吻合。", "地址": "搭配：“分给”的对象是财物，不说“分给孩子地址”。", "天空": "语义：天空不是可以分给孩子的东西，句子不成立。", "太阳": "语义：太阳无法被爷爷分给孩子，整句不合常识。"}, "sentence_index": 6, "correct_answer": "资产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他欠了很多资产。", "explanation": "这里应该用〈债务〉。欠的是别人的钱，资产指拥有的钱和东西，两者意思相反。"}, {"text": "孩子每年都要交很多资产。", "explanation": "这里应该用〈学费〉。交的是上学的费用，资产指拥有的钱和东西，不能说“交资产”。"}, {"text": "他因为乱扔垃圾被罚了资产。", "explanation": "这里应该用〈罚款〉。罚款是违规后交的钱，资产指拥有的钱和东西，不能说“被罚资产”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他留下了一只可观的资产。", "corrected_sentence": "他留下了一笔可观的资产。", "error_description": "量词错误。“资产”的量词是“笔”，“只”不能用于资产。正确形式为“一笔可观的资产”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他卖掉了几只资产。", "corrected_sentence": "他卖掉了几笔资产。", "error_description": "量词错误。资产的量词是“笔”，“只”不能用于资产。正确形式为“几笔资产”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
