INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25014, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很高的级别或水平。", "primary_collocate": null, "pronunciation": "gāo jiē", "ipa": "kɑʊ̯˥ tɕje˥", "syllable_count": 2, "sentences": [{"text": "这所大学开设了高阶人才培训班。", "target_word": "高阶", "complexity_tier": "T3", "furigana": "zhè suǒ dà xué kāi shè le gāo jiē rén cái péi xùn bān", "sentence_source": "generated"}, {"text": "他想报名高阶研修班。", "target_word": "高阶", "complexity_tier": "T3", "furigana": "tā xiǎng bào míng gāo jiē yán xiū bān", "sentence_source": "generated"}, {"text": "该公司正在招聘高阶人才。", "target_word": "高阶", "complexity_tier": "T3", "furigana": "gāi gōng sī zhèng zài zhāo pìn gāo jiē rén cái", "sentence_source": "generated"}, {"text": "这家企业只录用高阶技术人员。", "target_word": "高阶", "complexity_tier": "T3", "furigana": "zhè jiā qǐ yè zhǐ lù yòng gāo jiē jì shù rén yuán", "sentence_source": "generated"}, {"text": "他已经晋升为高阶管理者。", "target_word": "高阶", "complexity_tier": "T3", "furigana": "tā yǐ jīng jìn shēng wéi gāo jiē guǎn lǐ zhě", "sentence_source": "generated"}, {"text": "这个团队需要多名高阶分析师。", "target_word": "高阶", "complexity_tier": "T3", "furigana": "zhè ge tuán duì xū yào duō míng gāo jiē fēn xī shī", "sentence_source": "generated"}, {"text": "这个高阶任务需要三个人完成。", "target_word": "高阶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她已经进入了公司的高阶管理层。", "target_word": "高阶", "complexity_tier": "T3", "furigana": "tā yǐ jīng jìn rù le gōng sī de gāo jiē guǎn lǐ céng", "sentence_source": "generated"}, {"text": "这位高阶人才的日程通常很满。", "target_word": "高阶", "complexity_tier": "T3", "furigana": "zhè wèi gāo jiē rén cái de rì chéng tōng cháng hěn mǎn", "sentence_source": "generated"}, {"text": "我们先学基础，再学高阶知识。", "target_word": "高阶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高階", "label": "繁体"}, {"form": "高阶思维", "label": "复合"}], "register": "书面", "sense_fingerprint": "级别或水平很高的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '45fe73ad-99b7-41e9-9b37-32d47e8af85e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高阶", "is_correct": true, "explanation": "填入“高阶”：这里指级别很高的人才培训班，与句意相符。"}, {"text": "圆形", "is_correct": false, "explanation": "语义：“圆形”描述外形，与培训班的级别无关，句意不通。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”形容场面冷落，不能说明培训班的级别。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能修饰“人才培训班”。"}], "explanations": {"高阶": "填入“高阶”：这里指级别很高的人才培训班，与句意相符。", "圆形": "语义：“圆形”描述外形，与培训班的级别无关，句意不通。", "冷清": "语义：“冷清”形容场面冷落，不能说明培训班的级别。", "咸": "搭配：“咸”形容味道，不能修饰“人才培训班”。"}, "sentence_index": 0, "correct_answer": "高阶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山很高阶，常年有积雪。", "explanation": "这里应该用〈高〉。“高阶”指级别或水平，不用来描写山的高矮。"}, {"text": "他是个高阶的男孩。", "explanation": "这里应该用〈高〉。“高阶”指级别或水平，不用来形容人的身高。"}, {"text": "他把行李放在了高阶的架子上。", "explanation": "这里应该用〈高〉。“高阶”指级别或水平，不用来描述架子的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高阶", "is_correct": true, "explanation": "填入“高阶”：这里指难度与级别很高的任务，需要多人完成，与句意一致。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能修饰“任务”。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：“温暖”形容温度或情感，与任务的级别无关。"}, {"text": "沉默", "is_correct": false, "explanation": "语义：“沉默”形容人的状态，不能说明任务的级别。"}], "explanations": {"高阶": "填入“高阶”：这里指难度与级别很高的任务，需要多人完成，与句意一致。", "甜": "搭配：“甜”形容味道，不能修饰“任务”。", "温暖": "语义：“温暖”形容温度或情感，与任务的级别无关。", "沉默": "语义：“沉默”形容人的状态，不能说明任务的级别。"}, "sentence_index": 6, "correct_answer": "高阶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只长颈鹿很高阶，能吃到树顶的叶子。", "explanation": "这里应该用〈高〉。“高阶”指级别或水平，不用来形容动物的身高。"}, {"text": "这位老人很高阶，已经活了九十岁。", "explanation": "这里应该用〈高〉。“高阶”指级别或水平，不用来形容年纪。"}, {"text": "这条路的海拔很高阶。", "explanation": "这里应该用〈高〉。“高阶”只指级别或水平，不用于描写海拔的高低。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是很高阶管理者。", "corrected_sentence": "她是高阶管理者。", "error_description": "程度副词位置错误：“高阶”作定语修饰名词时，前面不能加程度副词“很”，应说“高阶管理者”，不能说“很高阶管理者”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个高阶地任务要三个人才能完成。", "corrected_sentence": "这个高阶任务要三个人才能完成。", "error_description": "结构助词误用：“高阶”作定语修饰“任务”时，中间不能加状语助词“地”，应说“高阶任务”，不能说“高阶地任务”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7f482f0-5c2e-4bba-a3a5-9478eb6ee7ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
