INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25020, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25020, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "property", "definition": "一直不停，没有停下来的时候。", "primary_collocate": null, "pronunciation": "wú jiàn duàn", "ipa": "u˧˥ tɕjɛn˥˩ tuan˥˩", "syllable_count": 3, "sentences": [{"text": "他无间断地写了两个小时，中间一次也没停。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的泉水无间断地流着。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪无间断地下了一夜。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们无间断地工作了一天。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院无间断接待病人。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视无间断地播放着新闻。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子无间断地哭了半个小时，中间一次也没停。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他无间断地跑了十公里。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器无间断地转了两天。", "target_word": "无间断", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路灯夜里无间断地亮着。", "target_word": "无间断", "complexity_tier": "T3", "furigana": "lù dēng yè lǐ wú jiàn duàn de liàng zhe.", "sentence_source": "generated"}], "morphological_forms": [{"form": "无间断地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "一直不停，没有停下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71bd5a64-b9a1-4fbd-b417-527ab723f5e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "无间断", "is_correct": true, "explanation": "正确：“无间断”表示一直不停，与“写了两个小时”的持续意思相符。"}, {"text": "间或", "is_correct": false, "explanation": "语义：“间或”指偶尔出现，与连续写两个小时的情况相矛盾。"}, {"text": "时常", "is_correct": false, "explanation": "体貌：“时常”表示经常性的重复，与一次完成的“写了两个小时”不合。"}, {"text": "断断续续", "is_correct": false, "explanation": "语义：“断断续续”指时停时续，与“中间一次也没停”相矛盾。"}], "explanations": {"无间断": "正确：“无间断”表示一直不停，与“写了两个小时”的持续意思相符。", "间或": "语义：“间或”指偶尔出现，与连续写两个小时的情况相矛盾。", "时常": "体貌：“时常”表示经常性的重复，与一次完成的“写了两个小时”不合。", "断断续续": "语义：“断断续续”指时停时续，与“中间一次也没停”相矛盾。"}, "sentence_index": 0, "correct_answer": "无间断"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他无间断地眨了一下眼。", "explanation": "这里误把〈无间断〉当成〈频繁〉来用。“无间断”指持续不停，“眨一下”是瞬间的单次动作，不能持续进行，二者不搭配。"}, {"text": "这把伞无间断地打开了。", "explanation": "这里误把〈无间断〉当成〈突然〉来用。“无间断”强调动作持续不停，“打开”是瞬间完成的变化，二者不搭配。"}, {"text": "我无间断地忘了他的名字。", "explanation": "这里误把〈无间断〉当成〈彻底〉来用。“无间断”说的是持续不停，“忘了”是一次完成的状态变化，不能持续进行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无间断", "is_correct": true, "explanation": "正确：“无间断”表示哭个不停，与“哭了半个小时”的持续意思相符。"}, {"text": "不时", "is_correct": false, "explanation": "语义：“不时”指隔一段时间就出现一次，与持续哭半个小时的情况相矛盾。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”指间或出现，与连续哭半个小时的情况相矛盾。"}, {"text": "时而", "is_correct": false, "explanation": "搭配：“时而”多用于交替出现的情况，不能单独修饰“哭了半个小时”这种持续性行为。"}], "explanations": {"无间断": "正确：“无间断”表示哭个不停，与“哭了半个小时”的持续意思相符。", "不时": "语义：“不时”指隔一段时间就出现一次，与持续哭半个小时的情况相矛盾。", "偶尔": "语义：“偶尔”指间或出现，与连续哭半个小时的情况相矛盾。", "时而": "搭配：“时而”多用于交替出现的情况，不能单独修饰“哭了半个小时”这种持续性行为。"}, "sentence_index": 6, "correct_answer": "无间断"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他无间断地打了一个喷嚏。", "explanation": "这里误把〈无间断〉当成〈突然〉来用。“打一个喷嚏”是瞬间的单次动作，不能持续不停，不能用“无间断”修饰。"}, {"text": "这块布无间断地拼成了一个图案，中间却有空隙。", "explanation": "这里应该用〈无间隙〉。“无间断”只说时间上的连续，描写布面上没有缝隙要用“无间隙”。"}, {"text": "他无间断地每隔一天去一次医院。", "explanation": "这里误把〈无间断〉当成〈定时〉来用。“定时”指按固定间隔进行，恰恰有间隔；“无间断”不允许中间有间隔，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹无间断了地唱了一晚上歌。", "corrected_sentence": "妹妹无间断地唱了一晚上歌。", "error_description": "错误：“无间断”是状态副词，后面不能加“了”，“了”应放在动词后。正确形式：妹妹无间断地唱了一晚上歌。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店里的灯无间断的亮着。", "corrected_sentence": "店里的灯无间断地亮着。", "error_description": "“无间断”修饰动词时要用“地”，不用“的”。“的”连接定语，这里应说“无间断地亮着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
