INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25022, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数就是表示有多少个的数字。", "primary_collocate": null, "pronunciation": "shù", "ipa": "ʂu⁵¹", "syllable_count": 1, "sentences": [{"text": "数就是告诉你有几个。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你心里想一个数，我来猜。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数是五，那个数是八。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把最大的数写在这里。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有四口人，四就是一个数。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哪个数比九大？", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在纸上写了一个数。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数怎么读？", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小的数在前，大的数在后。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说出了一个很大的数。", "target_word": "数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "數", "label": "繁体"}], "register": "中性", "sense_fingerprint": "表示有多少个的数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71bd5a64-b9a1-4fbd-b417-527ab723f5e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25022, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数", "is_correct": true, "explanation": "数就是表示有多少个的数字。"}, {"text": "书", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是书。"}, {"text": "素", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是素、朴素。"}, {"text": "暑", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是暑热。"}], "explanations": {"数": "数就是表示有多少个的数字。", "书": "shū（第一声）与 shù（第四声）声调不同，意思是书。", "素": "sù 与 shù 声母不同（s 与 sh），意思是素、朴素。", "暑": "shǔ（第三声）与 shù（第四声）声调不同，意思是暑热。"}, "sentence_index": null, "correct_answer": "数"}, "level_3": {"options": [{"text": "数", "is_correct": true, "explanation": "数：表示有多少个的数字，正是句中“告诉你有几个”的意思。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不表示有几个，句子说的是数的定义。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“有几个”说的是可以计数的东西，颜色不能这样计数。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是表示数量的概念，“就是告诉你有几个”说不通。"}], "explanations": {"数": "数：表示有多少个的数字，正是句中“告诉你有几个”的意思。", "名字": "语义：名字不表示有几个，句子说的是数的定义。", "颜色": "搭配：“有几个”说的是可以计数的东西，颜色不能这样计数。", "桌子": "语义：桌子不是表示数量的概念，“就是告诉你有几个”说不通。"}, "sentence_index": 0, "correct_answer": "数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他唱歌的数很好听。", "explanation": "这里应该用〈声音〉。“好听”形容声音，“数”是表示有多少的数字，不能指歌声。"}, {"text": "这个花园的数很浓。", "explanation": "这里应该用〈香味〉。“浓”形容香味，“数”是数字，不能指气味。"}, {"text": "他这次的数很好。", "explanation": "这里应该用〈成绩〉。“好”形容成绩，“数”是数字，不能说“数很好”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25022, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "数", "is_correct": true, "explanation": "表示有多少个的数字。"}, {"text": "诉", "is_correct": false, "explanation": "sù 与 shù 声母不同（s 与 sh），意思是告诉、诉说。"}, {"text": "叔", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔。"}, {"text": "薯", "is_correct": false, "explanation": "shǔ（第三声）与 shù（第四声）声调不同，意思是薯类。"}], "explanations": {"数": "表示有多少个的数字。", "诉": "sù 与 shù 声母不同（s 与 sh），意思是告诉、诉说。", "叔": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔。", "薯": "shǔ（第三声）与 shù（第四声）声调不同，意思是薯类。"}, "sentence_index": null, "correct_answer": "数"}, "level_3": {"options": [{"text": "数", "is_correct": true, "explanation": "数：表示有多少个的数字，句中指纸上写的数字。"}, {"text": "河流", "is_correct": false, "explanation": "搭配：“写”后面不接“河流”，写的是数字，不是河流。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被写在纸上当数来用，句子意思说不通。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情不是可以计数的东西，“写了一个心情”说不通。"}], "explanations": {"数": "数：表示有多少个的数字，句中指纸上写的数字。", "河流": "搭配：“写”后面不接“河流”，写的是数字，不是河流。", "天气": "语义：天气不能被写在纸上当数来用，句子意思说不通。", "心情": "语义：心情不是可以计数的东西，“写了一个心情”说不通。"}, "sentence_index": 6, "correct_answer": "数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的数很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，“数”是数字，不能指颜色。"}, {"text": "这个故事的数很感人。", "explanation": "这里应该用〈情节〉。“感人”形容故事的情节，“数”是数字，不能用来形容故事。"}, {"text": "她的数很苗条。", "explanation": "这里应该用〈身材〉。“苗条”形容身材，“数”是数字，不能指人的身材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三只数的和是十二。", "corrected_sentence": "三个数的和是十二。", "error_description": "量词错误：“数”应该用“个”计数，“只”不能用来数数字。正确说法是“三个数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个数很重。", "corrected_sentence": "这个数很大。", "error_description": "搭配错误：“数”是数字，没有轻重，不能用“重”形容，应说“很大”。正确形式：这个数很大。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
