INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25024, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "立体就是有长、宽、高的东西，像积木一样。", "primary_collocate": null, "pronunciation": "lì tǐ", "ipa": "li⁵¹ tʰi²¹⁴", "syllable_count": 2, "sentences": [{"text": "立体就是有长、宽、高的东西。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "平面和立体有什么不同？", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "积木是立体，纸上的图是平面。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天学画平面，明天学画立体。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把平面的纸折成了立体。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球和盒子都是立体。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "立体比平面多一个高。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题要我们分清平面和立体。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纸是平面，纸盒是立体。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "影子是平面，苹果是立体。", "target_word": "立体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "立体图形", "label": "复合"}, {"form": "立體", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有长宽高的东西，如积木", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71bd5a64-b9a1-4fbd-b417-527ab723f5e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "立体", "is_correct": true, "explanation": "正确。立体（lì tǐ）指有长、宽、高的东西，如积木。"}, {"text": "例题", "is_correct": false, "explanation": "例题（lì tí）与立体（lì tǐ）第二个音节声调不同（tí 与 tǐ），意思是例子或习题。"}, {"text": "离题", "is_correct": false, "explanation": "离题（lí tí）与立体（lì tǐ）两个音节声调都不同，意思是偏离主题。"}, {"text": "离体", "is_correct": false, "explanation": "离体（lí tǐ）与立体（lì tǐ）第一个音节声调不同（lí 与 lì），意思是离开身体。"}], "explanations": {"立体": "正确。立体（lì tǐ）指有长、宽、高的东西，如积木。", "例题": "例题（lì tí）与立体（lì tǐ）第二个音节声调不同（tí 与 tǐ），意思是例子或习题。", "离题": "离题（lí tí）与立体（lì tǐ）两个音节声调都不同，意思是偏离主题。", "离体": "离体（lí tǐ）与立体（lì tǐ）第一个音节声调不同（lí 与 lì），意思是离开身体。"}, "sentence_index": null, "correct_answer": "立体"}, "level_3": {"options": [{"text": "立体", "is_correct": true, "explanation": "正确。“立体”指有长、宽、高的东西，与定义一致。"}, {"text": "平面", "is_correct": false, "explanation": "语义：平面只有长和宽，没有高，与“有长、宽、高”矛盾。"}, {"text": "影子", "is_correct": false, "explanation": "语义：影子是平面的投影，没有长、宽、高三个维度。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“香味”不能说有长、宽、高，搭配不当。"}], "explanations": {"立体": "正确。“立体”指有长、宽、高的东西，与定义一致。", "平面": "语义：平面只有长和宽，没有高，与“有长、宽、高”矛盾。", "影子": "语义：影子是平面的投影，没有长、宽、高三个维度。", "香味": "搭配：“香味”不能说有长、宽、高，搭配不当。"}, "sentence_index": 0, "correct_answer": "立体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个水箱能装五立体米的水。", "explanation": "这里应该用〈立方〉。容积的单位是立方米，立体是指有长、宽、高的物体，不能当单位用。"}, {"text": "这个仓库的立体很大。", "explanation": "这里应该用〈空间〉。仓库的大小要说空间，立体指有长、宽、高的物体，不指仓库的范围。"}, {"text": "这张纸是立体。", "explanation": "这里应该用〈平面〉。纸是平的，应说平面；立体指有长、宽、高的物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立体", "is_correct": true, "explanation": "正确。立体比平面多一个维度，即高。"}, {"text": "直线", "is_correct": false, "explanation": "语义：直线只有一维，比平面少一维，与“多一个高”矛盾。"}, {"text": "文字", "is_correct": false, "explanation": "语义：文字写在纸上，是平面的，不比平面多一个高。"}, {"text": "声音", "is_correct": false, "explanation": "搭配：“声音”不说比平面多一个高，搭配不当。"}], "explanations": {"立体": "正确。立体比平面多一个维度，即高。", "直线": "语义：直线只有一维，比平面少一维，与“多一个高”矛盾。", "文字": "语义：文字写在纸上，是平面的，不比平面多一个高。", "声音": "搭配：“声音”不说比平面多一个高，搭配不当。"}, "sentence_index": 6, "correct_answer": "立体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的立体有两厘米。", "explanation": "这里应该用〈厚度〉。书的厚薄要说厚度，立体指有体积的物体，不指厚度。"}, {"text": "这段录音的立体是三分钟。", "explanation": "这里应该用〈时长〉。录音的长度要说时长，立体指有体积的物体，不指时间。"}, {"text": "墙上有一个立体，指着三点。", "explanation": "这里应该用〈钟〉。指着三点的是钟表，立体指有长、宽、高的物体，不指钟表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一张立体，有六个面。", "corrected_sentence": "这是一个立体，有六个面。", "error_description": "错误：“立体”指有长、宽、高的物体，量词应用“个”，不用“张”（“张”多用于纸、床等有平面的东西）。正确形式：一个立体。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个魔方一个立体。", "corrected_sentence": "这个魔方是一个立体。", "error_description": "错误：“A是B”的判断句中不能省略“是”。正确形式：这个魔方是一个立体。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
