INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25026, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "种植物，帮助它长大。", "primary_collocate": null, "pronunciation": "zāi péi", "ipa": "tsaɪ̯˥ pʰeɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "爷爷在院子里栽培了很多花。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想在家栽培一些青菜。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种树不难栽培。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "栽培西红柿要常浇水。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她栽培的玫瑰开花了。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场里栽培着各种水果。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要栽培好花草，必须有耐心。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校后面有一块地，同学们在那里栽培蔬菜。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些苹果树是我叔叔栽培的。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "栽培这种草药需要凉爽的天气。", "target_word": "栽培", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "栽培了", "label": "体标"}, {"form": "栽培着", "label": "体标"}, {"form": "栽培过", "label": "体标"}], "register": "中性", "sense_fingerprint": "种植并照顾植物使其长大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f11855e5-45fd-4c04-9c51-cf5ccf93758f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "栽培", "is_correct": true, "explanation": "正确：“栽培”表示种植并培育，这里“爷爷在院子里栽培了很多花”成立，只能填“栽培”。"}, {"text": "装订", "is_correct": false, "explanation": "语义：装订是把纸张订在一起，与院子里的花无关。"}, {"text": "出版", "is_correct": false, "explanation": "语义：出版指印刷发行书籍，不能用于花。"}, {"text": "删除", "is_correct": false, "explanation": "搭配：“删除”的宾语通常是文件或数据，不能说“删除花”。"}], "explanations": {"栽培": "正确：“栽培”表示种植并培育，这里“爷爷在院子里栽培了很多花”成立，只能填“栽培”。", "装订": "语义：装订是把纸张订在一起，与院子里的花无关。", "出版": "语义：出版指印刷发行书籍，不能用于花。", "删除": "搭配：“删除”的宾语通常是文件或数据，不能说“删除花”。"}, "sentence_index": 0, "correct_answer": "栽培"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农民栽培鱼虾要定期换水。", "explanation": "这里应该用〈养殖〉。养殖用于饲养水产和动物，栽培只用于植物，鱼虾不能说“栽培”。"}, {"text": "栽培蛋糕要控制温度。", "explanation": "这里应该用〈烘焙〉。烘焙是用烤箱做点心，栽培指种植植物，不能用于蛋糕。"}, {"text": "栽培衣服要认真仔细。", "explanation": "这里应该用〈缝纫〉。缝纫是用针线做衣服，栽培指种植植物，不能用于衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "栽培", "is_correct": true, "explanation": "正确：“栽培好花草”指种植并照料，这里只能填“栽培”。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：翻译是转换语言，不能用于花草。"}, {"text": "上缴", "is_correct": false, "explanation": "语义：上缴是交出物品，不能用于照料花草。"}, {"text": "拆卸", "is_correct": false, "explanation": "搭配：“拆卸”的对象通常是机器或零件，不能说“拆卸花草”。"}], "explanations": {"栽培": "正确：“栽培好花草”指种植并照料，这里只能填“栽培”。", "翻译": "语义：翻译是转换语言，不能用于花草。", "上缴": "语义：上缴是交出物品，不能用于照料花草。", "拆卸": "搭配：“拆卸”的对象通常是机器或零件，不能说“拆卸花草”。"}, "sentence_index": 6, "correct_answer": "栽培"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "栽培房屋要打好地基。", "explanation": "这里应该用〈搭建〉。搭建是把构件组合成房屋结构，栽培指种植培育，不能用于房屋。"}, {"text": "栽培葡萄酒要选好葡萄。", "explanation": "这里应该用〈酿造〉。酿造是发酵制作酒类，栽培指种植培育，不能用于酒。"}, {"text": "栽培衬衫要调低温度。", "explanation": "这里应该用〈熨烫〉。熨烫是用熨斗烫平衣物，栽培指种植培育，不能用于衬衫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐以前在阳台上栽培了过兰花。", "corrected_sentence": "我姐姐以前在阳台上栽培过兰花。", "error_description": "体标错误：“过”表示曾经有过的经历，与“了”不能同时用在动词后。应说“栽培过”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把菜苗栽培很壮实。", "corrected_sentence": "他把菜苗栽培得很壮实。", "error_description": "补语错误：“栽培”后接程度补语须用“得”，应说“栽培得很壮实”，漏掉“得”是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f4a1ef-3e4a-4ea9-b4a0-3e4918616bf0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
