INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25028, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "农民伯伯用来种粮食的土。", "primary_collocate": null, "pronunciation": "gēng dì", "ipa": "kɤŋ˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷家有一块耕地。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块耕地里种着小麦。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民伯伯在耕地里种水稻。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，耕地里的玉米熟了。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片耕地很大，也很平。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，耕地变得很湿。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上去耕地里看看水。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能在耕地上盖房子。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的耕地都种了粮食。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在耕地旁边玩。", "target_word": "耕地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "片", "label": "量词"}, {"form": "耕地面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "农民种粮食的土地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71bd5a64-b9a1-4fbd-b417-527ab723f5e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25028, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "耕地", "is_correct": true, "explanation": "正确。耕地（gēng dì）指农民用来种粮食的土地。"}, {"text": "更替", "is_correct": false, "explanation": "更替（gēng tì）与耕地（gēng dì）第二个音节声母不同（t 与 d），意思是新旧交替。"}, {"text": "工地", "is_correct": false, "explanation": "工地（gōng dì）与耕地（gēng dì）第一个音节韵母不同（ong 与 eng），意思是施工的场地。"}, {"text": "更低", "is_correct": false, "explanation": "更低（gèng dī）与耕地（gēng dì）两个音节声调都不同，意思是比较低。"}], "explanations": {"耕地": "正确。耕地（gēng dì）指农民用来种粮食的土地。", "更替": "更替（gēng tì）与耕地（gēng dì）第二个音节声母不同（t 与 d），意思是新旧交替。", "工地": "工地（gōng dì）与耕地（gēng dì）第一个音节韵母不同（ong 与 eng），意思是施工的场地。", "更低": "更低（gèng dī）与耕地（gēng dì）两个音节声调都不同，意思是比较低。"}, "sentence_index": null, "correct_answer": "耕地"}, "level_3": {"options": [{"text": "耕地", "is_correct": true, "explanation": "正确。“爷爷家有一块耕地”，指家里用来种粮食的土地。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“块”不能用来计量“空气”，搭配不当。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“一块时间”不成立，时间不用“块”计量。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不是家庭的土地，“爷爷家有一块工厂”与家庭语境不符。"}], "explanations": {"耕地": "正确。“爷爷家有一块耕地”，指家里用来种粮食的土地。", "空气": "搭配：“块”不能用来计量“空气”，搭配不当。", "时间": "搭配：“一块时间”不成立，时间不用“块”计量。", "工厂": "语义：工厂不是家庭的土地，“爷爷家有一块工厂”与家庭语境不符。"}, "sentence_index": 0, "correct_answer": "耕地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的耕地很高，有五层。", "explanation": "这里应该用〈楼房〉。有几层的建筑要说楼房，耕地是用来种粮食的土地，不能说层数。"}, {"text": "每天有很多人在这片耕地等公共汽车。", "explanation": "这里应该用〈车站〉。等车的地方要说车站，耕地是用来种粮食的土地，不是交通设施。"}, {"text": "孩子们在耕地里上学。", "explanation": "这里应该用〈教室〉。上学要在教室，耕地是用来种粮食的土地，不能当教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "耕地", "is_correct": true, "explanation": "正确。“去耕地里看看水”指到种庄稼的土地里看水，符合语境。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是能进去的场所，“去天空里看看水”不合理。"}, {"text": "衣柜", "is_correct": false, "explanation": "语义：衣柜不是可以去看水的场所，“去衣柜里看看水”不合理。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“作业”不能说“去……里”，搭配不当。"}], "explanations": {"耕地": "正确。“去耕地里看看水”指到种庄稼的土地里看水，符合语境。", "天空": "语义：天空不是能进去的场所，“去天空里看看水”不合理。", "衣柜": "语义：衣柜不是可以去看水的场所，“去衣柜里看看水”不合理。", "作业": "搭配：“作业”不能说“去……里”，搭配不当。"}, "sentence_index": 6, "correct_answer": "耕地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村的耕地每天治病人。", "explanation": "这里应该用〈医院〉。治病的地方要说医院，耕地是用来种粮食的土地，不能治病。"}, {"text": "我们去耕地借书吧。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆，耕地是用来种粮食的土地，不能借书。"}, {"text": "这片耕地供游客住宿。", "explanation": "这里应该用〈宾馆〉。供人住宿的地方要说宾馆，耕地是用来种粮食的，不供游客住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家有一座耕地，每年种玉米。", "corrected_sentence": "我们家有一块耕地，每年种玉米。", "error_description": "错误：耕地（土地）的量词用“块”，不用“座”（“座”用于山、楼等大型建筑或山峰）。正确形式：一块耕地。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一条河把耕地们隔开了。", "corrected_sentence": "一条河把耕地隔开了。", "error_description": "错误：“耕地”是无生命的事物，一般不能加“们”（“们”通常只用于指人）。正确形式：一条河把耕地隔开了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
