INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25030, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "两个东西一样多、一样好。", "primary_collocate": null, "pronunciation": "xiāng dāng yú", "ipa": "ɕjɑŋ˥˥ tɑŋ˥˥ y˧˥", "syllable_count": 3, "sentences": [{"text": "这次出差的花费相当于他两个月的工资。", "target_word": "相当于", "complexity_tier": "T3", "furigana": "zhè cì chū chāi de huā fèi xiāng dāng yú tā liǎng gè yuè de gōng zī", "sentence_source": "generated"}, {"text": "他写的报告相当于一本小书的篇幅。", "target_word": "相当于", "complexity_tier": "T3", "furigana": "tā xiě de bào gào xiāng dāng yú yī běn xiǎo shū de piān fú", "sentence_source": "generated"}, {"text": "这点钱相当于我一天的饭钱。", "target_word": "相当于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛的时长相当于两节课。", "target_word": "相当于", "complexity_tier": "T3", "furigana": "zhè chǎng bǐ sài de shí cháng xiāng dāng yú liǎng jié kè", "sentence_source": "generated"}, {"text": "这件衣服的价格相当于一部手机。", "target_word": "相当于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间书房的面积相当于一间小客厅。", "target_word": "相当于", "complexity_tier": "T3", "furigana": "zhè jiān shū fáng de miàn jī xiāng dāng yú yī jiān xiǎo kè tīng", "sentence_source": "generated"}, {"text": "他每天的跑步量相当于走十公里。", "target_word": "相当于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的价格相当于三碗面。", "target_word": "相当于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一年的收入相当于我三年的工资。", "target_word": "相当于", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的人口相当于一所大学的学生人数。", "target_word": "相当于", "complexity_tier": "T3", "furigana": "zhè ge xiǎo zhèn de rén kǒu xiāng dāng yú yī suǒ dà xué de xué shēng rén shù", "sentence_source": "generated"}], "morphological_forms": [{"form": "相當於", "label": "繁体"}], "register": "书面", "sense_fingerprint": "在数量、价值或作用上等同于另一事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80ab50cd-4340-49f3-b7d1-188a43322068') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "相当于", "is_correct": true, "explanation": "正确：「相当于」表示在花费与工资的数量上等同。"}, {"text": "赚", "is_correct": false, "explanation": "语义：「赚」指获得收入，与「花费」的支出义相反。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：「参加」接活动、会议，不接「工资」作宾语。"}, {"text": "拍", "is_correct": false, "explanation": "搭配：「拍」不接「工资」作宾语。"}], "explanations": {"相当于": "正确：「相当于」表示在花费与工资的数量上等同。", "赚": "语义：「赚」指获得收入，与「花费」的支出义相反。", "参加": "搭配：「参加」接活动、会议，不接「工资」作宾语。", "拍": "搭配：「拍」不接「工资」作宾语。"}, "sentence_index": 0, "correct_answer": "相当于"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "二加三相当于五。", "explanation": "这里应该用〈等于〉。相当于只表示数量或价值大致相当，数学上的精确相等要用等于。"}, {"text": "他相当于他爸爸一样聪明。", "explanation": "这里应该用〈像〉。相当于比较的是数量或价值，描述人与人的相似要用像。"}, {"text": "我们相当于他是朋友，常常一起吃饭。", "explanation": "这里应该用〈当作〉。相当于表示数量或价值相当，把人看成朋友要用当作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相当于", "is_correct": true, "explanation": "正确：「相当于」表示跑步量与走路的距离在数量上等同。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：「讨厌」表示厌恶，跑步量与走路的距离之间不能用厌恶来表达。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：「打破」接纪录、记录，不接「走十公里」。"}, {"text": "厌恶", "is_correct": false, "explanation": "语义：「厌恶」表示不喜欢，与数量比较的意思不符。"}], "explanations": {"相当于": "正确：「相当于」表示跑步量与走路的距离在数量上等同。", "讨厌": "语义：「讨厌」表示厌恶，跑步量与走路的距离之间不能用厌恶来表达。", "打破": "搭配：「打破」接纪录、记录，不接「走十公里」。", "厌恶": "语义：「厌恶」表示不喜欢，与数量比较的意思不符。"}, "sentence_index": 6, "correct_answer": "相当于"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们相当于喜欢这部电影。", "explanation": "这里应该用〈同样〉。相当于表示数量或价值相当，表示做法相同要用同样。"}, {"text": "他相当于我一样高。", "explanation": "这里应该用〈和…一样〉。相当于比较的是数量或价值，比较身高要用和…一样高。"}, {"text": "他相当于生病了。", "explanation": "这里应该用〈好像〉。相当于比较的是数量或价值，表示推测他的状态要用好像。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套房子的面积相当于了三间教室。", "corrected_sentence": "这套房子的面积相当于三间教室。", "error_description": "错误：「相当于了」。正确：「相当于」。「相当于」是表示比较的动词，后面不能加「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动的费用很相当于一台新电脑。", "corrected_sentence": "这次活动的费用相当于一台新电脑。", "error_description": "错误：「很相当于」。正确：「相当于」。程度副词「很」不能修饰动词「相当于」，去掉「很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a064b18-cb72-4871-ba51-bc2dd5ad36d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
