INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25032, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25032, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主粮是人们每天主要吃的粮食，比如米饭和馒头。", "primary_collocate": null, "pronunciation": "zhǔ liáng", "ipa": "ʈʂu˨˩˦ liɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "米饭是我们家每天都吃的主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "馒头和面条也是北方人的主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，吃饭时不能只吃菜，也要吃主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大米和小麦是很多中国人的主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家的主粮是大米，邻居家的主粮是面粉。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的减肥菜单里，主粮只吃一小碗。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人家每天都要煮主粮，再炒两个菜。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人一天大概要吃多少主粮？", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长身体，主粮和蔬菜都不能少。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的大米和面粉都属于主粮。", "target_word": "主粮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "主粮产区", "label": "复合"}, {"form": "主糧", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人们每天主要吃的粮食，如米饭、馒头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a4ab504-b86b-4786-8d2f-75d08dca261d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25032, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主粮", "is_correct": true, "explanation": "正确。主粮 zhǔ liáng 指人们每天主要吃的粮食，如米饭、馒头。"}, {"text": "储粮", "is_correct": false, "explanation": "chǔ（第三声）与 zhǔ（第三声）声母不同，ch 与 zh 相混；储粮意思是储存粮食，不是主粮。"}, {"text": "猪粮", "is_correct": false, "explanation": "zhū（第一声）与 zhǔ（第三声）只有声调不同，意思是养猪用的粮食。"}, {"text": "出粮", "is_correct": false, "explanation": "chū（第一声）与 zhǔ（第三声）声母与声调不同，意思是产出粮食。"}], "explanations": {"主粮": "正确。主粮 zhǔ liáng 指人们每天主要吃的粮食，如米饭、馒头。", "储粮": "chǔ（第三声）与 zhǔ（第三声）声母不同，ch 与 zh 相混；储粮意思是储存粮食，不是主粮。", "猪粮": "zhū（第一声）与 zhǔ（第三声）只有声调不同，意思是养猪用的粮食。", "出粮": "chū（第一声）与 zhǔ（第三声）声母与声调不同，意思是产出粮食。"}, "sentence_index": null, "correct_answer": "主粮"}, "level_3": {"options": [{"text": "主粮", "is_correct": true, "explanation": "正确。“米饭是我们家每天都吃的主粮”中，“主粮”指每天吃的主食，句意通顺。"}, {"text": "零食", "is_correct": false, "explanation": "语义：米饭是正餐的主食，不是零食，与“每天都吃的”这一正餐语境相冲突。"}, {"text": "点心", "is_correct": false, "explanation": "语义：点心是小吃，不能说米饭是点心，句中的米饭指正餐。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“吃”不能搭配“饮料”，应说“喝饮料”，与“吃的”冲突。"}], "explanations": {"主粮": "正确。“米饭是我们家每天都吃的主粮”中，“主粮”指每天吃的主食，句意通顺。", "零食": "语义：米饭是正餐的主食，不是零食，与“每天都吃的”这一正餐语境相冲突。", "点心": "语义：点心是小吃，不能说米饭是点心，句中的米饭指正餐。", "饮料": "搭配：“吃”不能搭配“饮料”，应说“喝饮料”，与“吃的”冲突。"}, "sentence_index": 0, "correct_answer": "主粮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今晚的主粮是红烧肉。", "explanation": "这里应该用〈主菜〉。红烧肉是菜，主粮指米饭、馒头这类主食，不能用来指菜。"}, {"text": "他的主粮是教书，周末才画画。", "explanation": "这里应该用〈主业〉。主粮指每天主要吃的粮食，说工作要用主业，不能用主粮。"}, {"text": "我最爱吃的主粮是炸鸡。", "explanation": "这里应该用〈食物〉。炸鸡是食物，但不是每天主要吃的粮食，不能说成主粮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25032, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "主粮", "is_correct": true, "explanation": "正确。“煮主粮，再炒两个菜”指煮饭、炒菜，“主粮”符合句意。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“煮”用于食物，不能用来煮衣服，与“再炒两个菜”的饮食语境不符。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾不是可以煮来吃的东西，与句中的饮食语境相冲突。"}, {"text": "玩具", "is_correct": false, "explanation": "搭配：“煮”不搭配“玩具”，玩具不是用来煮的。"}], "explanations": {"主粮": "正确。“煮主粮，再炒两个菜”指煮饭、炒菜，“主粮”符合句意。", "衣服": "搭配：“煮”用于食物，不能用来煮衣服，与“再炒两个菜”的饮食语境不符。", "垃圾": "语义：垃圾不是可以煮来吃的东西，与句中的饮食语境相冲突。", "玩具": "搭配：“煮”不搭配“玩具”，玩具不是用来煮的。"}, "sentence_index": 6, "correct_answer": "主粮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这顿饭的主粮有鱼和豆腐。", "explanation": "这里应该用〈副食〉。鱼和豆腐是下饭的菜，不是主粮。"}, {"text": "孩子们最爱吃的主粮是薯片。", "explanation": "这里应该用〈零食〉。薯片是零食，不是每天主要吃的粮食。"}, {"text": "孩子们爱喝主粮，不爱吃饭。", "explanation": "这里应该用〈饮料〉。主粮是固体的粮食，不能用来喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天吃一只主粮。", "corrected_sentence": "他每天吃一碗主粮。", "error_description": "“主粮”指每天吃的饭食，量词应用“碗”或“顿”，不能用“只”。正确说法是“一碗主粮”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个村子只有一根主粮。", "corrected_sentence": "这个村子只有一种主粮。", "error_description": "“根”用于细长条状的东西，不能用来数主粮；主粮指一类食物，应用“种”。正确说法是“一种主粮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
