INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "东西慢慢变少或变坏。", "primary_collocate": null, "pronunciation": "sǔn hào", "ipa": "suən˨˩˦ xɑu˥˩", "syllable_count": 2, "sentences": [{"text": "天气太热，菜放久了会有损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长期开车，车的损耗很大。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋穿了两年，损耗很明显。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书放在潮湿的地方，损耗会更快。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家时，家具有一点损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米放得太久，损耗越来越多。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管老了，水的损耗也变大了。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想减少手机电池的损耗。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用心保养，东西的损耗就会小一些。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些水果运到这里，损耗不到一成。", "target_word": "损耗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自然损耗", "label": "复合"}, {"form": "损耗率", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西慢慢变少或变坏的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77085c74-6cb5-4c24-9776-6ad1cbffcff0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25034, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工资", "is_correct": false, "explanation": "语义：菜放久了不会产生“工资”，这里指的是东西变少或变坏。"}, {"text": "损耗", "is_correct": true, "explanation": "正确。“菜放久了会有损耗”指食物因放置时间变长而变少或变坏，符合语境。"}, {"text": "亏空", "is_correct": false, "explanation": "语义：“亏空”指钱款或账目的缺口，菜放久了不会产生亏空。"}, {"text": "脾气", "is_correct": false, "explanation": "配价：“脾气”需要有生命的主体，“菜”没有脾气。"}], "explanations": {"工资": "语义：菜放久了不会产生“工资”，这里指的是东西变少或变坏。", "损耗": "正确。“菜放久了会有损耗”指食物因放置时间变长而变少或变坏，符合语境。", "亏空": "语义：“亏空”指钱款或账目的缺口，菜放久了不会产生亏空。", "脾气": "配价：“脾气”需要有生命的主体，“菜”没有脾气。"}, "sentence_index": 0, "correct_answer": "损耗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次投资损耗了不少钱。", "explanation": "这里应该用〈损失〉。损耗多指物品因使用而变少或变坏，钱财亏掉要说损失。"}, {"text": "他的成绩损耗了，从第一名掉到了第十名。", "explanation": "这里应该用〈下降〉。损耗指东西因使用或时间慢慢变少、变坏，成绩变差要说下降。"}, {"text": "他在路上损耗了一把钥匙。", "explanation": "这里应该用〈丢失〉。损耗指东西因使用或时间慢慢变少、变坏，钥匙不见了要说丢失。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：水的“年龄”不会因水管老化而“变大”，这里说的是水量的流失。"}, {"text": "胃口", "is_correct": false, "explanation": "配价：“胃口”指人或动物的食欲，水没有胃口。"}, {"text": "体温", "is_correct": false, "explanation": "搭配：“变大”不搭配“体温”，体温一般说升高或降低。"}, {"text": "损耗", "is_correct": true, "explanation": "正确。水管老化后，水的损耗（流失）变大，符合语境。"}], "explanations": {"年龄": "语义：水的“年龄”不会因水管老化而“变大”，这里说的是水量的流失。", "胃口": "配价：“胃口”指人或动物的食欲，水没有胃口。", "体温": "搭配：“变大”不搭配“体温”，体温一般说升高或降低。", "损耗": "正确。水管老化后，水的损耗（流失）变大，符合语境。"}, "sentence_index": 6, "correct_answer": "损耗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的热情被工作损耗得越来越高涨。", "explanation": "这里应该用〈增长〉。损耗指东西慢慢变少或变坏，热情越来越多要说增长，不能说损耗。"}, {"text": "这个道理损耗了我的思想。", "explanation": "这里应该用〈影响〉。损耗指东西慢慢变少或变坏，道理改变人的想法要说影响。"}, {"text": "这场大风损耗了整座房子。", "explanation": "这里应该用〈毁坏〉。损耗指因使用、时间而慢慢减少，大风造成的突然破坏要说毁坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "运输途中难免会有一只的损耗。", "corrected_sentence": "运输途中难免会有一定的损耗。", "error_description": "量词误用：“损耗”前不能用“一只”，应改为“一定”，表示有一定数量的损耗。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批水果的损耗得很大。", "corrected_sentence": "这批水果的损耗很大。", "error_description": "多余的“得”：这里“损耗”是名词作主语，后面直接接“很大”，不能加“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3995bbd3-30f8-4c0f-9a78-6e3664693c5d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25036, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "反义：“隐藏”是不让人看见，与“展现出”让人看见的意思相反。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指把坏了的东西修好，与“展现出”没有近义或反义关系。"}, {"text": "煮", "is_correct": false, "explanation": "“煮”指用水加热食物，与“展现出”的意思无关。"}, {"text": "跑步", "is_correct": false, "explanation": "“跑步”是身体运动，与“展现出”的意思无关。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "反义：“隐藏”是不让人看见，与“展现出”让人看见的意思相反。", "修理": "“修理”指把坏了的东西修好，与“展现出”没有近义或反义关系。", "煮": "“煮”指用水加热食物，与“展现出”的意思无关。", "跑步": "“跑步”是身体运动，与“展现出”的意思无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25036, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "隐藏", "is_correct": true, "explanation": "反义：“隐藏”是不让人看见，与“展现出”让人看见的意思相反。"}, {"text": "洗", "is_correct": false, "explanation": "“洗”指用水去除污垢，与“展现出”的意思无关。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指发出歌声，与“展现出”没有近义或反义关系。"}, {"text": "搬", "is_correct": false, "explanation": "“搬”指移动物体的位置，与“展现出”的意思无关。"}], "correct_answer": "隐藏", "explanations": {"隐藏": "反义：“隐藏”是不让人看见，与“展现出”让人看见的意思相反。", "洗": "“洗”指用水去除污垢，与“展现出”的意思无关。", "唱": "“唱”指发出歌声，与“展现出”没有近义或反义关系。", "搬": "“搬”指移动物体的位置，与“展现出”的意思无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25036, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让人或事物清楚地出现在别人眼前或心里。", "primary_collocate": null, "pronunciation": "zhǎn xiàn chū", "ipa": "ʈʂan˨˩ ɕjɛn˥˩ ʈʂʰu˥", "syllable_count": 3, "sentences": [{"text": "这个孩子在比赛中展现出很大的勇气。", "target_word": "展现出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的作品展现出春天的美。", "target_word": "展现出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他唱歌时展现出很好的天分。", "target_word": "展现出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市的夜景展现出另一种美。", "target_word": "展现出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新来的老师展现出很好的耐心。", "target_word": "展现出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张照片展现出山里安静的生活。", "target_word": "展现出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个队在比赛里展现出了很强的力量。", "target_word": "展现出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王面对困难，展现出自己的聪明。", "target_word": "展现出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这部电影展现出一个家庭的真实生活。", "target_word": "展现出", "complexity_tier": "T3", "furigana": "zhè bù diàn yǐng zhǎn xiàn chū yí gè jiā tíng de zhēn shí shēng huó", "sentence_source": "generated"}, {"text": "秋天的公园展现出金黄的颜色。", "target_word": "展现出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "展现", "label": "原形"}, {"form": "展现出了", "label": "体标"}, {"form": "展现出来", "label": "复合"}], "register": "中性", "sense_fingerprint": "把能力、特点、样子清楚地表现出来，让人看见或感到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05710f7d-b7af-44a9-a7be-d2504441099b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25036, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "展现出", "is_correct": true, "explanation": "正确。“展现出”表示把勇气清楚地表现给人看，与“比赛中”“很大的勇气”搭配自然。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能带“勇气”作宾语，“吃很大的勇气”说不通。"}, {"text": "来", "is_correct": false, "explanation": "配价：“来”是不及物动词，不能带“很大的勇气”作宾语。"}, {"text": "放", "is_correct": false, "explanation": "搭配：“放”不能与“勇气”搭配，“放很大的勇气”不成话。"}], "explanations": {"展现出": "正确。“展现出”表示把勇气清楚地表现给人看，与“比赛中”“很大的勇气”搭配自然。", "吃": "搭配：“吃”不能带“勇气”作宾语，“吃很大的勇气”说不通。", "来": "配价：“来”是不及物动词，不能带“很大的勇气”作宾语。", "放": "搭配：“放”不能与“勇气”搭配，“放很大的勇气”不成话。"}, "sentence_index": 0, "correct_answer": "展现出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一口气展现出了三碗饭。", "explanation": "这里应该用〈吃〉。展现出指让人清楚看见或感到，不能用来说吃饭；吃下食物要用“吃”。"}, {"text": "孩子展现出了一场感冒。", "explanation": "这里应该用〈得〉。展现出不能用于疾病，患上感冒要用“得”。"}, {"text": "这场雨展现出了一整天。", "explanation": "这里应该用〈下〉。展现出不能用于说时间的长短，雨下了多久要用“下”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25036, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "展现出", "is_correct": true, "explanation": "正确。“展现出”与“比赛里”“很强的力量”搭配，表示力量被人看到。"}, {"text": "放弃", "is_correct": false, "explanation": "语义：“放弃”是不再要，与“很强的力量”自相矛盾，句子意思颠倒。"}, {"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，不能带“很强的力量”作宾语。"}, {"text": "掏", "is_correct": false, "explanation": "搭配：“掏”不能带“力量”作宾语，“掏了很强的力量”说不通。"}], "explanations": {"展现出": "正确。“展现出”与“比赛里”“很强的力量”搭配，表示力量被人看到。", "放弃": "语义：“放弃”是不再要，与“很强的力量”自相矛盾，句子意思颠倒。", "消失": "配价：“消失”是不及物动词，不能带“很强的力量”作宾语。", "掏": "搭配：“掏”不能带“力量”作宾语，“掏了很强的力量”说不通。"}, "sentence_index": 6, "correct_answer": "展现出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议展现出了三个小时。", "explanation": "这里应该用〈开〉。展现出不能用于说会议持续的时间，会议进行多久要用“开”。"}, {"text": "他展现出了一场考试，然后交了卷。", "explanation": "这里应该用〈参加〉。展现出不能用于考试，参加考试要用“参加”。"}, {"text": "她展现出了一封信，寄到了北京。", "explanation": "这里应该用〈寄〉。展现出不能用于把信送出去，寄信要用“寄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25036, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师在课堂上展现了出耐心。", "corrected_sentence": "老师在课堂上展现出了耐心。", "error_description": "“展现出”是一个词，“出”是补语，不能拆开。正确是“展现出了”，错误在于把“出”放到了“了”之后，写成“展现了出”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25036, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个队在训练中展现在了很强的团结。", "corrected_sentence": "这个队在训练中展现出了很强的团结。", "error_description": "“展现出”的“出”不能换成“在”。“展现在”后面接的是处所，如“展现在眼前”，不能接“很强的团结”，正确是“展现出了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '435200ee-fff5-4965-8391-ccfd57e61a1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
