INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生产东西的地方。", "primary_collocate": null, "pronunciation": "chǎn qū", "ipa": "tʂʰan˨˩˦ tɕʰy˥", "syllable_count": 2, "sentences": [{"text": "这里是有名的水果产区。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产区每天生产很多牛奶。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北方是小麦的主要产区。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边是盐的主要产区。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个产区离城市很远，运东西不方便。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要去产区看看那里怎么种菜。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛肉从产区送到商店要两天。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说这个产区的大米又香又好吃。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "产区的农民每年秋天最忙。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方是玉米产区，到处是玉米地。", "target_word": "产区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "主产区", "label": "复合"}, {"form": "產區", "label": "繁体"}], "register": "中性", "sense_fingerprint": "生产某种东西的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a4ab504-b86b-4786-8d2f-75d08dca261d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25038, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "产区", "is_correct": true, "explanation": "正确。产区 chǎn qū 指生产某种东西的地方。"}, {"text": "展区", "is_correct": false, "explanation": "zhǎn（第三声）与 chǎn（第三声）声母不同，zh 与 ch 相混；展区意思是展览的区域。"}, {"text": "厂区", "is_correct": false, "explanation": "chǎng（第三声）与 chǎn（第三声）韵母不同，ang 与 an 相混；厂区意思是工厂的区域。"}, {"text": "禅趣", "is_correct": false, "explanation": "禅趣 chánqū 与产区 chǎnqū 第一个音节声调不同（第二声与第三声），意思是禅意的趣味。"}], "explanations": {"产区": "正确。产区 chǎn qū 指生产某种东西的地方。", "展区": "zhǎn（第三声）与 chǎn（第三声）声母不同，zh 与 ch 相混；展区意思是展览的区域。", "厂区": "chǎng（第三声）与 chǎn（第三声）韵母不同，ang 与 an 相混；厂区意思是工厂的区域。", "禅趣": "禅趣 chánqū 与产区 chǎnqū 第一个音节声调不同（第二声与第三声），意思是禅意的趣味。"}, "sentence_index": null, "correct_answer": "产区"}, "level_3": {"options": [{"text": "产区", "is_correct": true, "explanation": "正确。“有名的水果产区”指盛产水果的地方，句意通顺。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院不生产水果，也不能说“水果医院”，与“有名的”语境冲突。"}, {"text": "电影", "is_correct": false, "explanation": "搭配：“水果电影”不成立，电影不能与“水果”构成一个可以生产的地方。"}, {"text": "机场", "is_correct": false, "explanation": "语义：机场是交通设施，不是生产水果的地方，与句中的语境不符。"}], "explanations": {"产区": "正确。“有名的水果产区”指盛产水果的地方，句意通顺。", "医院": "语义：医院不生产水果，也不能说“水果医院”，与“有名的”语境冲突。", "电影": "搭配：“水果电影”不成立，电影不能与“水果”构成一个可以生产的地方。", "机场": "语义：机场是交通设施，不是生产水果的地方，与句中的语境不符。"}, "sentence_index": 0, "correct_answer": "产区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个产区很甜，我每天都买来吃。", "explanation": "这里应该用〈水果〉。产区是生产东西的地方，不能吃，说水果很甜要用水果。"}, {"text": "种苹果是我们村的主要产区，全村都靠它生活。", "explanation": "这里应该用〈产业〉。产区指生产东西的地方，村里赖以生活的行业要说产业。"}, {"text": "这个产区有一千名员工，是一家大公司。", "explanation": "这里应该用〈公司〉。产区指生产东西的地方，不是企业；一家企业要说公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产区", "is_correct": true, "explanation": "正确。“牛肉从产区送到商店”指牛肉从产地运往商店，符合句意。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不生产牛肉，“牛肉从书包送到商店”没有货源的意义。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”不是地点，不能作牛肉的来源，与“送到商店”的物流语境不符。"}, {"text": "课本", "is_correct": false, "explanation": "配价：“从…送到”要求一个具体的来源地点，“课本”不能充当牛肉的来源。"}], "explanations": {"产区": "正确。“牛肉从产区送到商店”指牛肉从产地运往商店，符合句意。", "书包": "语义：书包不生产牛肉，“牛肉从书包送到商店”没有货源的意义。", "考试": "语义：“考试”不是地点，不能作牛肉的来源，与“送到商店”的物流语境不符。", "课本": "配价：“从…送到”要求一个具体的来源地点，“课本”不能充当牛肉的来源。"}, "sentence_index": 6, "correct_answer": "产区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学生每天早上都去产区上学，很辛苦。", "explanation": "这里应该用〈学校〉。产区是生产东西的地方，上学要去学校，不能说去产区。"}, {"text": "这个产区每天站在讲台上给我们上课。", "explanation": "这里应该用〈老师〉。产区是地方，不能站在讲台上给学生上课；上课的应是老师。"}, {"text": "这个产区很可爱，每天陪我玩。", "explanation": "这里应该用〈宠物〉。产区是地方或生产场所，不会可爱地陪人玩；陪人玩的是宠物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里是一只重要的稻米产区。", "corrected_sentence": "这里是一个重要的稻米产区。", "error_description": "“产区”是地方，量词应用“个”，“只”一般用于动物或成对物品之一，不能修饰产区。正确说法是“一个重要的稻米产区”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这一颗是有名的玉米产区。", "corrected_sentence": "这一片是有名的玉米产区。", "error_description": "“颗”用于粒状物，不能用来数产区；产区是一大片地方，应用“片”。正确说法是“这一片是有名的玉米产区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
