INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25040, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以当药用的植物。", "primary_collocate": null, "pronunciation": "yào yòng zhí wù", "ipa": "jɑʊ˥˩ jʊŋ˥˩ ʈʂɨ˧˥ u˥˩", "syllable_count": 4, "sentences": [{"text": "奶奶说这种草是药用植物，不能随便吃。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是中医，常去山里找药用植物。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花很漂亮，也是一种药用植物。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了几张药用植物的照片。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山区的农民靠种药用植物增加收入。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "药用植物的味道一般有点儿苦。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了一百种常见的药用植物。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天雨水多，药用植物长得特别好。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把采来的药用植物放在太阳下晒干。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些药用植物要先洗干净，再煮水喝。", "target_word": "药用植物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种药用植物", "label": "量词"}, {"form": "藥用植物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可以当药用的植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a4ab504-b86b-4786-8d2f-75d08dca261d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "药用植物", "is_correct": true, "explanation": "正确。“这种草”是植物，且“不能随便吃”提示它有药用价值。"}, {"text": "水果", "is_correct": false, "explanation": "语义：“这种草”是草本植物，不能说成水果。"}, {"text": "矿物", "is_correct": false, "explanation": "语义：矿物是无机物，不能说成“这种草”。"}, {"text": "宠物", "is_correct": false, "explanation": "搭配：“这种草”后一般不接“宠物”这类指动物的名词。"}], "explanations": {"药用植物": "正确。“这种草”是植物，且“不能随便吃”提示它有药用价值。", "水果": "语义：“这种草”是草本植物，不能说成水果。", "矿物": "语义：矿物是无机物，不能说成“这种草”。", "宠物": "搭配：“这种草”后一般不接“宠物”这类指动物的名词。"}, "sentence_index": 0, "correct_answer": "药用植物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他嗓子疼，吃了两颗药用植物就好了。", "explanation": "这里应该用〈药丸〉。药用植物指植物本身，不是制成的药粒，吃药粒要说“药丸”。"}, {"text": "他得了感冒，医生给他做了一次药用植物。", "explanation": "这里应该用〈检查〉。药用植物是植物，不是医生能“做”的事情。"}, {"text": "护士给她注射了一针药用植物。", "explanation": "这里应该用〈针剂〉。药用植物是植物，不能注射到身体里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "药用植物", "is_correct": true, "explanation": "正确。“常见的”说明这些是现实中常见的植物，且书的内容可以介绍它们。"}, {"text": "独角兽", "is_correct": false, "explanation": "语义：独角兽是传说中的动物，现实中不存在，与“常见的”矛盾。"}, {"text": "外星人", "is_correct": false, "explanation": "语义：外星人并不“常见”，与“一百种常见的”矛盾。"}, {"text": "彩虹", "is_correct": false, "explanation": "搭配：“一百种”后接的名词应能按种类计数，“彩虹”一般不这样计数。"}], "explanations": {"药用植物": "正确。“常见的”说明这些是现实中常见的植物，且书的内容可以介绍它们。", "独角兽": "语义：独角兽是传说中的动物，现实中不存在，与“常见的”矛盾。", "外星人": "语义：外星人并不“常见”，与“一百种常见的”矛盾。", "彩虹": "搭配：“一百种”后接的名词应能按种类计数，“彩虹”一般不这样计数。"}, "sentence_index": 6, "correct_answer": "药用植物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生给他开了三盒药用植物。", "explanation": "这里应该用〈中成药〉。药用植物是植物本身，不是包装好的成药，不能用“盒”来开。"}, {"text": "他每天早上都去公园里跑药用植物。", "explanation": "这里应该用〈步〉。药用植物是植物，不能“跑”。"}, {"text": "这家药店卖的药用植物都是机器压成的药片。", "explanation": "这里应该用〈中成药〉。药用植物是植物本身，不是机器压制成的成药，应该说“中成药”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师教我们认识了几只药用植物。", "corrected_sentence": "老师教我们认识了几种药用植物。", "error_description": "量词错误：这里应该用“种”（或“株”）。“只”用于动物，不能用来数药用植物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把采来的药用植物们晒干了。", "corrected_sentence": "他把采来的药用植物晒干了。", "error_description": "“植物”不能加“们”表示复数，“们”一般只用于人，这里应直接说“药用植物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25042, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25042, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25042, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "快要到了，比如时间或地方快到了。", "primary_collocate": null, "pronunciation": "lín jìn", "ipa": "lin˧˥ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "临近年底，公司里的工作越来越忙。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临近下课，学生们开始收拾书包。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子临近终点站，大家都站了起来。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临近生日，妈妈给我买了一块蛋糕。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机临近机场时，天气突然变坏了。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临近期末，图书馆里坐满了学生。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天快黑了，我们临近目的地，心里很高兴。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛临近结束，场上的气氛越来越紧张。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临近冬天，商店里的外套卖得很好。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "临近假期，火车票特别难买。", "target_word": "临近", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "临近了", "label": "体标"}, {"form": "臨近", "label": "繁体"}], "register": "中性", "sense_fingerprint": "时间或地点快要到了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a4ab504-b86b-4786-8d2f-75d08dca261d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "临近", "is_correct": true, "explanation": "正确。“临近”表示时间快到，与“年底”搭配，符合句意。"}, {"text": "离开", "is_correct": false, "explanation": "搭配：“离开”接地点或人，不接时间，不说“离开年底”。"}, {"text": "远离", "is_correct": false, "explanation": "语义：“远离”表示距离遥远，不能用来说时间快要到了。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”的对象是事物，不能用于时间，句子无法成立。"}], "explanations": {"临近": "正确。“临近”表示时间快到，与“年底”搭配，符合句意。", "离开": "搭配：“离开”接地点或人，不接时间，不说“离开年底”。", "远离": "语义：“远离”表示距离遥远，不能用来说时间快要到了。", "发明": "语义：“发明”的对象是事物，不能用于时间，句子无法成立。"}, "sentence_index": 0, "correct_answer": "临近"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很临近地笑了笑，大家都很喜欢他。", "explanation": "这里应该用〈亲切〉。临近是动词，不能修饰“笑”，也不表示态度。"}, {"text": "这个消息让我临近了快乐，一整天都很开心。", "explanation": "这里应该用〈带来〉。临近指快到某个时间或地点，不接“快乐”这类情感宾语。"}, {"text": "他对我临近，总是耐心地解答问题。", "explanation": "这里应该用〈亲切〉。临近指快到某个时间或地点，不用来形容人对人的态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "临近", "is_correct": true, "explanation": "正确。“临近”表示快到某个地点，与“目的地”搭配，符合句意。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：“逃离”表示躲避、逃走，与“快到目的地”的语境不合。"}, {"text": "挖掘", "is_correct": false, "explanation": "搭配：“挖掘”的对象是矿藏、潜力，不说“挖掘目的地”。"}, {"text": "制造", "is_correct": false, "explanation": "语义：“制造”指生产物品，不能用于“目的地”这样的地点。"}], "explanations": {"临近": "正确。“临近”表示快到某个地点，与“目的地”搭配，符合句意。", "逃离": "语义：“逃离”表示躲避、逃走，与“快到目的地”的语境不合。", "挖掘": "搭配：“挖掘”的对象是矿藏、潜力，不说“挖掘目的地”。", "制造": "语义：“制造”指生产物品，不能用于“目的地”这样的地点。"}, "sentence_index": 6, "correct_answer": "临近"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "两个小朋友的关系临近，一起拉着手走进教室。", "explanation": "这里应该用〈亲热〉。临近指快到某个时间或地点，不用来说两个人的关系亲热。"}, {"text": "这篇文章临近学生的生活，大家都很喜欢。", "explanation": "这里应该用〈贴近〉。临近只用于时间和地点，不用于说文章与生活的联系。"}, {"text": "这个节日的气氛临近，大家都很开心。", "explanation": "这里应该用〈热烈〉。临近描述时间或地点，不用来形容气氛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "临近到元旦，超市里的人越来越多。", "corrected_sentence": "临近元旦，超市里的人越来越多。", "error_description": "多余的补语：“临近”后直接接时间名词，不说“临近到”，应去掉“到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天快亮了，火车把临近站台。", "corrected_sentence": "天快亮了，火车临近站台。", "error_description": "用法错误：“临近”是不及物动词，不能接“把”字结构，应说“火车临近站台”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
