INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25044, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "叶菜是可以吃的菜，它的叶子很好吃。", "primary_collocate": null, "pronunciation": "yè cài", "ipa": "jɛ˥˩ tsʰaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢吃叶菜。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘叶菜很好吃。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈买了一把叶菜。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不爱吃叶菜。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把叶菜又绿又嫩。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店里有三种叶菜。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把叶菜洗干净。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子最爱吃叶菜。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天中午我们吃了炒叶菜。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些叶菜是爷爷种的。", "target_word": "叶菜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "把", "label": "量词"}, {"form": "盘", "label": "量词"}, {"form": "葉菜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "吃叶子的蔬菜", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71bd5a64-b9a1-4fbd-b417-527ab723f5e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叶菜", "is_correct": true, "explanation": "正确：“叶菜”是可以吃的蔬菜，与“我喜欢吃”的意思相符。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：“吃”的对象应是食物，书籍不可食用。"}, {"text": "木材", "is_correct": false, "explanation": "搭配：“吃”不能搭配木材，二者搭配不当。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔不可食用，句意与“吃”的动作冲突。"}], "explanations": {"叶菜": "正确：“叶菜”是可以吃的蔬菜，与“我喜欢吃”的意思相符。", "书籍": "语义：“吃”的对象应是食物，书籍不可食用。", "木材": "搭配：“吃”不能搭配木材，二者搭配不当。", "粉笔": "语义：粉笔不可食用，句意与“吃”的动作冲突。"}, "sentence_index": 0, "correct_answer": "叶菜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用叶菜写了一封信。", "explanation": "这里误把〈叶菜〉当成〈纸张〉来用。叶菜是可以吃的蔬菜，不能拿来写字。"}, {"text": "我把叶菜戴在头上。", "explanation": "这里误把〈叶菜〉当成〈帽子〉来用。叶菜是食物，不是可以戴在头上的东西。"}, {"text": "妈妈用叶菜盖房子。", "explanation": "这里误把〈叶菜〉当成〈建材〉来用。叶菜是食物，不能作为盖房子的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叶菜", "is_correct": true, "explanation": "正确：“叶菜”是可以洗的食物，与“请把……洗干净”的搭配相符。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“洗干净”的对象应是能清洗的东西，天空不能这样处理。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无形，不能用“洗干净”来处理。"}, {"text": "闪电", "is_correct": false, "explanation": "语义：闪电是瞬间的天象，无法洗干净，句意与动作冲突。"}], "explanations": {"叶菜": "正确：“叶菜”是可以洗的食物，与“请把……洗干净”的搭配相符。", "天空": "搭配：“洗干净”的对象应是能清洗的东西，天空不能这样处理。", "空气": "语义：空气无形，不能用“洗干净”来处理。", "闪电": "语义：闪电是瞬间的天象，无法洗干净，句意与动作冲突。"}, "sentence_index": 6, "correct_answer": "叶菜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "樱花的叶菜落了一地。", "explanation": "这里应该用〈花瓣〉。樱花落下的是花瓣，叶菜指可以吃的蔬菜，不能用来指花瓣。"}, {"text": "这棵大树的叶菜掉光了。", "explanation": "这里应该用〈叶子〉。大树的叶子掉光了，叶菜指可以吃的蔬菜，不能用来指树叶。"}, {"text": "这只鸟的叶菜很漂亮。", "explanation": "这里应该用〈羽毛〉。鸟的羽毛漂亮，叶菜指可以吃的蔬菜，不能用来指羽毛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25044, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了两只叶菜。", "corrected_sentence": "我昨天买了两斤叶菜。", "error_description": "叶菜应用“斤”或“把”计量，“只”用于动物，不能用来数叶菜。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25044, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些叶菜们很新鲜。", "corrected_sentence": "这些叶菜很新鲜。", "error_description": "“叶菜”是指蔬菜的名词，一般不加“们”。“们”通常只加在指人的名词后面，不能加在这里。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1c90382-2627-4b84-8811-99ab147004ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
