INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25046, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "东西可以怎么用。", "primary_collocate": null, "pronunciation": "yòng tú", "ipa": "jʊŋ˥˩ tʰu˧˥", "syllable_count": 2, "sentences": [{"text": "这个东西的用途我不清楚。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请告诉我这瓶药的用途。", "target_word": "用途", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个小工具有三种用途。", "target_word": "用途", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想知道这把钥匙的用途。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子问我这个按钮的用途。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块布的用途是擦桌子。", "target_word": "用途", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在店里问了咖啡壶的用途。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包的用途很简单，就是装书。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "箱子里有一些不知道用途的东西。", "target_word": "用途", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张卡的用途写在背面。", "target_word": "用途", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "多用途", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西可以怎么用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c031e5-ef73-4c3e-80a2-d044d0cc24bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25046, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "用途", "is_correct": true, "explanation": "正确：「这个东西的用途我不清楚」指不知道东西能怎么用。"}, {"text": "人品", "is_correct": false, "explanation": "搭配：「人品」只用于人，不说东西的人品。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：「身高」只用于人或动物，东西不说身高。"}, {"text": "国籍", "is_correct": false, "explanation": "语义：国籍属于人，东西没有国籍。"}], "explanations": {"用途": "正确：「这个东西的用途我不清楚」指不知道东西能怎么用。", "人品": "搭配：「人品」只用于人，不说东西的人品。", "身高": "搭配：「身高」只用于人或动物，东西不说身高。", "国籍": "语义：国籍属于人，东西没有国籍。"}, "sentence_index": 0, "correct_answer": "用途"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些零件派上了用途。", "explanation": "这里应该用〈用场〉。「派上用场」是固定说法，不说「派上用途」。"}, {"text": "这次活动的用途很大。", "explanation": "这里应该用〈收获〉。收获指做事后得到的好处，活动不是东西，不说用途。"}, {"text": "写这篇作文的用途是三十分钟。", "explanation": "这里应该用〈用时〉。用途指东西可以怎么用，写作文花费的时间要说用时。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25046, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "用途", "is_correct": true, "explanation": "正确：「问了咖啡壶的用途」指问咖啡壶能做什么。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：「身高」只说人或动物，咖啡壶不说身高。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历属于人，咖啡壶没有学历。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」用于人或动物，咖啡壶不说体重。"}], "explanations": {"用途": "正确：「问了咖啡壶的用途」指问咖啡壶能做什么。", "身高": "搭配：「身高」只说人或动物，咖啡壶不说身高。", "学历": "语义：学历属于人，咖啡壶没有学历。", "体重": "搭配：「体重」用于人或动物，咖啡壶不说体重。"}, "sentence_index": 6, "correct_answer": "用途"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这把剪刀的用途很强大。", "explanation": "这里应该用〈功能〉。用途说的是用处的范围，形容能力强弱要说功能。"}, {"text": "这瓶药的用途是每天三次。", "explanation": "这里应该用〈用量〉。用途指药能治什么，每次或每天吃多少要说用量。"}, {"text": "他学习的用途是提高水平。", "explanation": "这里应该用〈目的〉。用途指事物能发挥的作用，人做事的意图要说目的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25046, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台仪器的主要用途测量温度。", "corrected_sentence": "这台仪器的主要用途是测量温度。", "error_description": "错误：「用途」后缺少引出说明的「是」，应说「主要用途是测量温度」，不能直接接动词短语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25046, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把钳子是两种用途。", "corrected_sentence": "这把钳子有两种用途。", "error_description": "动词错误：表示事物具有几种作用要用「有」，不能用「是」。应说「这把钳子有两种用途」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
