INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25048, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做相反方向的事情来减少风险。", "primary_collocate": null, "pronunciation": "duì chōng", "ipa": "twei˥˩ tʂʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他同时做两份工作来对冲失业风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民种了几种菜，对冲天气带来的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店既卖冷饮又卖热茶，对冲天气变化的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板用多个供应商来对冲缺货风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了保险，对冲生病带来的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司在两个国家开店，对冲单一市场的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了对冲风险，她把钱放在不同的地方。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行社提前订酒店，对冲旺季涨价的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们多准备一个方案，对冲计划失败的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小店同时卖两种商品，对冲其中一种卖不好的风险。", "target_word": "对冲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "对冲了", "label": "体标"}, {"form": "对冲过", "label": "体标"}, {"form": "对冲基金", "label": "复合"}, {"form": "對沖", "label": "繁体"}], "register": "书面", "sense_fingerprint": "做方向相反的安排来抵消、减少风险", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5a4ab504-b86b-4786-8d2f-75d08dca261d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25048, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对冲", "is_correct": true, "explanation": "对冲：用反向安排抵消风险，符合“做两份工作”减少失业风险的意思。"}, {"text": "加剧", "is_correct": false, "explanation": "语义：同时做两份工作是为了减少失业风险，说“加剧”与句意相反。"}, {"text": "体验", "is_correct": false, "explanation": "搭配：“体验”通常接感受、生活，不能说“体验失业风险”。"}, {"text": "宣传", "is_correct": false, "explanation": "语义：做两份工作不是为了宣传失业风险，这样说与句意不合。"}], "explanations": {"对冲": "对冲：用反向安排抵消风险，符合“做两份工作”减少失业风险的意思。", "加剧": "语义：同时做两份工作是为了减少失业风险，说“加剧”与句意相反。", "体验": "搭配：“体验”通常接感受、生活，不能说“体验失业风险”。", "宣传": "语义：做两份工作不是为了宣传失业风险，这样说与句意不合。"}, "sentence_index": 0, "correct_answer": "对冲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老板用多个供应商来对冲员工的笑容。", "explanation": "这里应该用〈保持〉。对冲针对的是风险，不能用于“笑容”。"}, {"text": "老板用多个供应商来对冲原料的质量。", "explanation": "这里应该用〈检验〉。对冲用于抵消风险，不用于检验原料质量。"}, {"text": "老板用多个供应商来对冲订单的数量。", "explanation": "这里应该用〈增加〉。对冲是抵消风险，不能用来增加订单数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25048, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对冲", "is_correct": true, "explanation": "对冲：用分散的方式抵消风险，与“放在不同的地方”一致。"}, {"text": "集中", "is_correct": false, "explanation": "语义：“集中”与“放在不同的地方”的分散做法相反。"}, {"text": "放大", "is_correct": false, "explanation": "语义：把钱分散放置是为了降低风险，说“放大风险”与句意矛盾。"}, {"text": "推迟", "is_correct": false, "explanation": "搭配：“推迟”不能与“风险”组合，说“为了推迟风险”不成立。"}], "explanations": {"对冲": "对冲：用分散的方式抵消风险，与“放在不同的地方”一致。", "集中": "语义：“集中”与“放在不同的地方”的分散做法相反。", "放大": "语义：把钱分散放置是为了降低风险，说“放大风险”与句意矛盾。", "推迟": "搭配：“推迟”不能与“风险”组合，说“为了推迟风险”不成立。"}, "sentence_index": 6, "correct_answer": "对冲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小店同时卖两种商品，对冲了顾客的满意度。", "explanation": "这里应该用〈提高〉。对冲针对的是风险，不用于提高顾客满意度。"}, {"text": "小店同时卖两种商品，对冲了每天的阳光。", "explanation": "这里应该用〈享受〉。对冲针对的是风险，不能用于“阳光”。"}, {"text": "小店同时卖两种商品，对冲了老板的脾气。", "explanation": "这里应该用〈控制〉。对冲针对的是风险，不能用于“脾气”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25048, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了保险，对冲了生病。", "corrected_sentence": "他买了保险，对冲了生病带来的风险。", "error_description": "宾语错误：“对冲”的对象应是风险或损失，不能直接说“对冲生病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25048, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车间新增一条生产线，对冲订单。", "corrected_sentence": "车间新增一条生产线，对冲订单减少的风险。", "error_description": "宾语错误：“对冲”针对的是风险，不能直接说“对冲订单”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '433c21c7-465e-4968-b2c3-3320d1051764') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25050, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排斥", "is_correct": true, "explanation": "正确答案。“吸引”与“排斥”在“把人或东西引到自己这边”这一义项上构成反义。"}, {"text": "搬运", "is_correct": false, "explanation": "“搬运”指把东西从一处移到另一处，与“吸引”的义项没有反义关系。"}, {"text": "清洗", "is_correct": false, "explanation": "“清洗”指用水去除污物，与“吸引”的义项没有反义关系。"}, {"text": "修理", "is_correct": false, "explanation": "“修理”指修复损坏之物，与“吸引”的义项没有反义关系。"}], "correct_answer": "排斥", "explanations": {"排斥": "正确答案。“吸引”与“排斥”在“把人或东西引到自己这边”这一义项上构成反义。", "搬运": "“搬运”指把东西从一处移到另一处，与“吸引”的义项没有反义关系。", "清洗": "“清洗”指用水去除污物，与“吸引”的义项没有反义关系。", "修理": "“修理”指修复损坏之物，与“吸引”的义项没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25050, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "排斥", "is_correct": true, "explanation": "正确答案。“吸引”与“排斥”在“把人或东西引到自己这边”这一义项上构成反义。"}, {"text": "砍伐", "is_correct": false, "explanation": "“砍伐”指砍倒树木，与“吸引”的义项没有反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "“翻译”指把一种语言转换成另一种语言，与“吸引”的义项没有反义关系。"}, {"text": "批改", "is_correct": false, "explanation": "“批改”指评阅作业或文章，与“吸引”的义项没有反义关系。"}], "correct_answer": "排斥", "explanations": {"排斥": "正确答案。“吸引”与“排斥”在“把人或东西引到自己这边”这一义项上构成反义。", "砍伐": "“砍伐”指砍倒树木，与“吸引”的义项没有反义关系。", "翻译": "“翻译”指把一种语言转换成另一种语言，与“吸引”的义项没有反义关系。", "批改": "“批改”指评阅作业或文章，与“吸引”的义项没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25050, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让别人或东西到自己这边来。", "primary_collocate": null, "pronunciation": "xī yǐn", "ipa": "ɕi˥ in˨˩˦", "syllable_count": 2, "sentences": [{"text": "花香吸引蜜蜂。", "target_word": "吸引", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "磁铁能吸引铁钉。", "target_word": "吸引", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "牛奶的香味吸引小猫。", "target_word": "吸引", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌上的糖吸引了很多蚂蚁。", "target_word": "吸引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鱼饵吸引了河里的鱼。", "target_word": "吸引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "垃圾桶里的剩饭吸引了老鼠。", "target_word": "吸引", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块大磁铁吸引着桌上所有的铁钉。", "target_word": "吸引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里的面包屑吸引了一群鸽子飞过来。", "target_word": "吸引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用香甜的花蜜吸引蝴蝶飞到花园里来。", "target_word": "吸引", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小灯会吸引很多晚上出来的虫子。", "target_word": "吸引", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "吸引着", "label": "体标（着）"}, {"form": "吸引了", "label": "体标（了）"}, {"form": "吸引过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "吸引：磁力、气味、光等把人或东西引到自己这边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19c031e5-ef73-4c3e-80a2-d044d0cc24bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (25050, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吸引", "is_correct": true, "explanation": "正确答案。“吸引”表示花香把蜜蜂引过来，符合句意。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“喜欢”的主语通常是人或有意识的动物，花香不能“喜欢”蜜蜂。"}, {"text": "追逐", "is_correct": false, "explanation": "语义：花香不会主动“追逐”蜜蜂，这与“花香”的被动性质矛盾。"}, {"text": "躲避", "is_correct": false, "explanation": "搭配：“躲避”需要有行动能力的主体，花香不能“躲避”蜜蜂。"}], "explanations": {"吸引": "正确答案。“吸引”表示花香把蜜蜂引过来，符合句意。", "喜欢": "搭配：“喜欢”的主语通常是人或有意识的动物，花香不能“喜欢”蜜蜂。", "追逐": "语义：花香不会主动“追逐”蜜蜂，这与“花香”的被动性质矛盾。", "躲避": "搭配：“躲避”需要有行动能力的主体，花香不能“躲避”蜜蜂。"}, "sentence_index": 0, "correct_answer": "吸引"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "干布吸引了地上的水。", "explanation": "这里应该用〈吸收〉。干布吸收液体用“吸收”，“吸引”指用好的特点让人或东西靠近。"}, {"text": "他用吸管吸引了一口果汁。", "explanation": "这里应该用〈吸〉。用吸管把果汁吸进嘴里说「吸」，「吸引」指把人或东西引到自己这边。"}, {"text": "老师的声音吸引了大家的睡意。", "explanation": "这里应该用〈引起〉。“吸引”指让人或东西靠近，睡意不能被拉过来，应说“引起大家的睡意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dd5964e-632d-4483-a6e7-d4947da2e08c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
